const PHOTO_METADATA_BY_RECORD_ID = Object.freeze({
  "print-decals-45": {"descriptionVi":"In tranh canvas theo bộ, phối hai màu khung, hợp với nhà hàng, văn phòng, sảnh khách sạn muốn trang trí tường theo đúng tông nội thất có sẵn.\n\n• Chất liệu: vải canvas in UV độ phân giải cao, mực bền màu trong nhà\n• Khung: gỗ sồi tự nhiên hoặc composite sơn đen, kiểu khung nổi\n• Kích thước thường làm: 40x60, 50x70, 60x80 cm\n• Lưu ý: nên in thử một mẫu nhỏ để duyệt màu, vì màu trên màn hình thường tươi hơn màu in trên vải\n\nTrường Thịnh thiết kế, in, đóng khung và giao tận nơi trọn gói.","descriptionEn":"Canvas printing in sets with two frame finishes suits restaurants, offices and hotel lobbies that want wall art matched to an existing interior.\n\n• Material: high-resolution UV print on canvas, fade-resistant indoors\n• Frames: natural oak or black composite floater frames\n• Typical size: 40x60, 50x70 or 60x80 cm\n• Tip: approve a small test print first, as colours on screen usually look brighter than on canvas\n\nTrường Thịnh designs, prints, frames and delivers the set.","altVi":"Bốn tranh canvas phối khung gỗ và khung đen trên vách trắng","altEn":"Four canvas prints in mixed timber and black frames on a white wall","source":"/assets/content/projects/advertising/print-decals/in-tranh-canvas-khung-go-den.webp","sha256":"d4e2f5279963db102c8526c577ec67cbfe56711f4d2e1780e68b9b7444f7e90a","provenance":"AI-generated illustration; Codex gpt-6-sol; source ID codex:2026-11-22:print-decals-45; original PNG SHA256 66a05555d13ddf1b52904adc6eeb7301502e32e8554cd40d34faeccff14716b7; 1k master, owner approved 2026-11-21."},
  "print-decals-44": {"descriptionVi":"Tranh canvas tràn viền là tranh in trùm qua mép khung căng, không cần khung ngoài, hợp với phòng homestay, spa, góc đọc sách muốn treo nhanh với chi phí thấp hơn tranh đóng khung.\n\n• Chất liệu: vải canvas in UV hoặc mực gốc dầu, phủ lớp bảo vệ mờ chống ẩm\n• Khung căng: gỗ thông dày 2-4 cm, khung càng dày nhìn nghiêng càng có khối\n• Kích thước thường làm: 40x60, 50x70, 60x90 cm\n• Lưu ý: ảnh cần dư 3-5 cm mỗi cạnh để gấp qua mép, nên báo trước chi tiết nào không được mất\n\nTrường Thịnh in, căng khung tại xưởng và giao tận nơi.","descriptionEn":"Gallery-wrapped canvas prints are printed around the edges of the stretcher with no outer frame, suiting homestay rooms, spas and reading corners that want art up quickly for less than framed pieces.\n\n• Material: canvas printed with UV or solvent inks, finished with a matt moisture-resistant coat\n• Stretcher: 2-4 cm pine bars, and deeper bars give more presence from the side\n• Typical size: 40x60, 50x70 or 60x90 cm\n• Tip: the image needs 3-5 cm extra on each edge to wrap, so flag any detail that must not be lost\n\nTrường Thịnh prints, stretches and delivers to your door.","altVi":"Bốn tranh canvas tràn viền không khung treo tường","altEn":"Four frameless gallery-wrapped canvas prints on a white wall","source":"/assets/content/projects/advertising/print-decals/tranh-canvas-tran-vien-tinh-vat.webp","sha256":"6453b5ecfde92f6274f743697a8254d1314eeaa72415ea97b19031cb8de3d6d8","provenance":"AI-generated illustration; Codex gpt-6-sol; source ID codex:2026-11-22:print-decals-44; original PNG SHA256 3f6c2b6b295fe959663352008ee416df4827eade32404c7bdd5b5e2a6bedecc5; 1k master, owner approved 2026-11-21."},
  "mobile-retail-27": {"descriptionVi":"Xe cafe lưu động dạng rơ moóc hợp với chủ quán bán ở phố đi bộ, chợ đêm, sự kiện cuối tuần, cần một quầy có mái, có nước, có điện mà di chuyển được giữa nhiều điểm.\n\n• Khung gầm: thép hộp mạ kẽm, một trục bánh, móc kéo và chân chống\n• Thân xe: tôn hoặc composite cách nhiệt, nội thất inox và gạch men dễ vệ sinh\n• Kích thước thường làm: dài 2,5-3,5 m, rộng 1,6-1,8 m\n• Lưu ý: hỏi trước quy định đỗ xe và công suất điện ở điểm bán để chọn máy pha, máy phát cho vừa\n\nTrường Thịnh thiết kế, đóng xe tại xưởng và bàn giao trọn gói.","descriptionEn":"A mobile coffee trailer suits owners trading at walking streets, night markets and weekend events who need a covered counter with water and power that moves between pitches.\n\n• Chassis: galvanised steel box section, single axle, tow hitch and jockey wheel\n• Body: insulated steel sheet or composite, with a stainless and tiled interior that's easy to clean\n• Typical size: 2.5-3.5 m long, 1.6-1.8 m wide\n• Tip: check parking rules and available power at each pitch first so the machine or generator is sized to match\n\nTrường Thịnh designs, builds the trailer in its workshop and hands it over ready to trade.","altVi":"Xe cafe lưu động dạng rơ moóc có biển neon ven sông","altEn":"Mobile coffee trailer with a neon roof sign by a river at night","source":"/assets/content/projects/advertising/mobile-retail/xe-cafe-luu-dong-ro-mooc.webp","sha256":"ea5504087901b097a7c171a3638e9af9b4b2e8ba26416bbbed188cf47ee84c0b","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd119-c174-83ec-b69c-0c08da7c248f); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-27 01:07Z; master PNG SHA256 47ddc2bf76782995ec43ad63b337283c931562d280c124659a1c13ed7a4b0055."},
  "kiosk-posm-41": {"descriptionVi":"Quầy lễ tân sự kiện dạng module hợp với hội thảo, hội nghị chuyên ngành ở khách sạn, nơi ban tổ chức cần chỗ đón khách, phát tài liệu và thẻ đeo ngay ở sảnh.\n\n• Kết cấu: khung gỗ hoặc MDF chống ẩm ốp laminate trắng, tháo lắp bằng vít cấy\n• Hộp đèn đầu quầy: mica sữa in UV, thay logo theo từng chương trình\n• Kích thước thường làm: dài 2,4-3,6 m, cao 1-1,1 m\n• Lưu ý: quầy chia 2-3 khối rời thì lọt thang hàng khách sạn và dùng lại được cho sự kiện sau\n\nTrường Thịnh thiết kế, sản xuất tại xưởng, vận chuyển và lắp đặt trọn gói.","descriptionEn":"A modular event reception counter suits seminars and industry conferences in hotels, where organisers need a place in the foyer to greet guests and hand out documents and badges.\n\n• Build: timber or moisture-resistant MDF frame in white laminate, assembled with threaded inserts\n• End lightbox: opal acrylic with UV print, logo swapped for each event\n• Typical size: 2.4-3.6 m long, 1-1.1 m high\n• Tip: a counter split into 2-3 blocks fits hotel service lifts and can be reused for the next event\n\nTrường Thịnh designs, builds, delivers and installs the counter.","altVi":"Quầy lễ tân trắng hắt đèn chân, đặt trước backdrop hội thảo y khoa","altEn":"White reception counter with base lighting before a medical conference backdrop","source":"/assets/content/projects/advertising/kiosk-posm/quay-le-tan-su-kien.webp","sha256":"f9427c6f3f8f26de991bd747b07a13debdc431314ab28a2879cf1c6d90fd7a20","provenance":"AI-generated illustration; source ID imagegen:2026-10-15:kiosk-posm-08-x1; original SHA256 1bc7290a5439864b3adcb49ce2cfe84b67113ea7ab0c3a37a81ff3381ff45832; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-42": {"descriptionVi":"Bàn đón khách tiệc cưới thân mica trong hợp với nhà hàng tiệc cưới, wedding planner cần một quầy ký sổ, nhận phong bì mà đổi được hoa theo tông từng tiệc.\n\n• Kết cấu: mặt gỗ công nghiệp phủ veneer óc chó, thân mica trong 8-10 mm ghép khung inox\n• Đèn: LED dây âm đế, nguồn 12V\n• Kích thước thường làm: dài 1,8-2,4 m, cao 0,9-1 m\n• Lưu ý: mica dễ trầy, nên lau bằng khăn mềm và không dùng cồn để mặt mica không bị rạn\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và giao lắp tận sảnh tiệc.","descriptionEn":"A clear acrylic wedding welcome table suits wedding venues and planners who need a guestbook and gift counter whose flowers can change to match each party.\n\n• Build: engineered wood top in walnut veneer, 8-10 mm clear acrylic body on a stainless frame\n• Lighting: LED strip recessed in the base, 12V supply\n• Typical size: 1.8-2.4 m long, 0.9-1 m high\n• Tip: acrylic scratches easily, so clean it with a soft cloth and never with alcohol, which causes crazing\n\nTrường Thịnh designs, builds the table in its workshop and sets it up at the venue.","altVi":"Bàn đón khách mặt gỗ, thân mica trong cắm hoa trắng ở sảnh cưới","altEn":"Wedding welcome table with a timber top and a flower-filled clear acrylic base","source":"/assets/content/projects/advertising/kiosk-posm/ban-don-khach-tiec-cuoi.webp","sha256":"3b40903de721758973f8e212e9261d6f6565e37336860e1950c4ed002b72275e","provenance":"AI-generated illustration; source ID imagegen:2026-10-15:kiosk-posm-08-x3; original SHA256 2a1a725b8533cd4d1825c070032b8bd05c39fef55692aab59d15df5173bfbd83; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-43": {"descriptionVi":"Quầy đăng ký sự kiện ốp vân gỗ dừa hợp với hội thảo chủ đề xanh, hội chợ nông sản, OCOP, khi ban tổ chức muốn chất liệu quầy nói luôn tinh thần chương trình.\n\n• Kết cấu: khung MDF chống ẩm, ốp gỗ dừa lạng hoặc laminate vân dừa, mặt trước in UV hoặc decal\n• Vách sau: tấm MDF in lá, tách rời khỏi quầy để dựng làm góc chụp ảnh\n• Kích thước thường làm: dài 1,8-2,4 m, vách cao 2-2,4 m\n• Lưu ý: gỗ dừa thật đẹp nhưng nặng và đắt, laminate vân dừa nhẹ hơn, hợp quầy phải chở đi nhiều lần\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"An event registration desk in coconut-grain timber suits green-themed seminars, farm produce fairs and regional product shows, where organisers want the desk material to reflect the event.\n\n• Build: moisture-resistant MDF frame, coconut wood veneer or coconut-grain laminate, front UV printed or in vinyl\n• Back panel: printed MDF, freestanding so it can double as a photo backdrop\n• Typical size: 1.8-2.4 m long, back panel 2-2.4 m high\n• Tip: real coconut wood looks great but is heavy and costly, while the laminate is lighter for desks that travel often\n\nTrường Thịnh designs, builds in its own workshop and installs it.","altVi":"Quầy đăng ký ốp gỗ vân dừa, vách sau in lá cọ","altEn":"Registration desk clad in coconut-grain timber with a palm leaf back panel","source":"/assets/content/projects/advertising/kiosk-posm/quay-dang-ky-su-kien.webp","sha256":"c60a25778edd6858ad2fbc39ef37527c1d868364978df946a6d3f7b9c32d6351","provenance":"AI-generated illustration; source ID imagegen:2026-10-17:kiosk-posm-08-x2; original SHA256 48c74cefc857062198f2e55e86c9b596f56f7361bf96df09067bea1221200eb3; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-25": {"descriptionVi":"Màn hình LED sự kiện hợp với hội nghị khách hàng, tri ân đại lý tổ chức ở phòng tiệc khách sạn, nơi chương trình chuyển liên tục giữa phần phát biểu và phần tiệc.\n\n• Module: LED trong nhà P2.5-P3, độ sáng 800-1.200 nit, đủ dùng cả khi phòng có vách kính lớn\n• Kích thước thường làm: ngang 5-10 m theo sân khấu\n• Lắp đặt: dựng từ tối hôm trước hoặc vài giờ trước giờ đón khách, tháo ngay sau tiệc\n• Lưu ý: gửi file nội dung đúng tỷ lệ màn trước một ngày để kỹ thuật chạy thử\n\nTrường Thịnh khảo sát sảnh, lắp đặt và cử kỹ thuật trực suốt buổi.","descriptionEn":"An event LED screen suits customer conferences and dealer appreciation nights held in hotel ballrooms, where the programme keeps switching between speeches and dinner.\n\n• Modules: indoor LED, P2.5-P3, 800-1,200 nits, bright enough even in rooms with large windows\n• Typical size: 5-10 m wide, to match the stage\n• Installation: set up the night before or a few hours ahead, taken down straight after\n• Tip: send content at the screen's exact aspect ratio a day early so the technician can test it\n\nTrường Thịnh surveys the venue, installs the screen and keeps a technician on hand throughout.","altVi":"Màn hình LED sự kiện trên sân khấu phòng tiệc hội nghị khách hàng","altEn":"Event LED screen on a ballroom stage set for a customer conference","source":"/assets/content/projects/advertising/led-displays-lightboxes/man-hinh-led-su-kien-tiec.webp","sha256":"336b21834ad67e780a7b6eb1d41678643ac939703d5afb336fbd6b5aac423aab","provenance":"AI-generated illustration; source ID imagegen:2026-10-17:led-man-hoi-nghi; original SHA256 8e940b125fc19290d91f1a74ebd14585eb34359b2df8af6c568596865afcf31a; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-26": {"descriptionVi":"Màn hình LED hội trường lắp cố định hợp với trường học, cơ quan, nhà văn hóa có lễ và họp quanh năm, tiết kiệm khoản in phông cho từng dịp.\n\n• Module: LED trong nhà full màu P2-P3\n• Lắp đặt: khung thép bắt vào tường, chọn module bảo trì mặt trước nếu sau màn không có lối đi\n• Kích thước thường làm: ngang 4-8 m, tỷ lệ 16:9 để chiếu slide và video không méo\n• Lưu ý: nên có aptomat và ổn áp riêng cho màn, đồng thời hướng dẫn nhân viên tự đổi nội dung\n\nTrường Thịnh khảo sát hội trường, làm khung và lắp đặt màn trọn gói.","descriptionEn":"A permanently installed hall LED screen suits schools, public offices and community halls with ceremonies and meetings all year, saving the cost of a new backdrop for every occasion.\n\n• Modules: full-colour indoor LED, P2-P3\n• Installation: steel frame fixed to the wall, with front-serviceable modules if there is no access behind\n• Typical size: 4-8 m wide in 16:9, so slides and video fit without distortion\n• Tip: give the screen its own breaker and voltage stabiliser, and have staff trained to update content\n\nTrường Thịnh surveys the hall, builds the frame and installs the screen.","altVi":"Màn hình LED hội trường trường học gắn trên vách ốp gỗ","altEn":"School hall LED screen fixed to a timber-panelled stage wall","source":"/assets/content/projects/advertising/led-displays-lightboxes/man-hinh-led-hoi-truong.webp","sha256":"8eec776c219f989eb84b04022e24e5009d11811c461223ead8c281109b085347","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:led-man-hoi-truong; original SHA256 ab7fe2aea7cdbe46e169cdb6c166abde18f863a86beac7685c4ef468b501a7a4; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-27": {"descriptionVi":"Chữ nổi trên mái hợp với trung tâm hội nghị, nhà hàng tiệc cưới, khách sạn nhiều tầng muốn tên công trình được thấy từ xa khi mặt dựng đã kín cửa kính và lam trang trí.\n\n• Chữ: mica hoặc alu chấn mặt mica, LED module chống nước; logo có thể cắm LED ruồi tạo điểm sáng\n• Kết cấu: khung thép hộp mạ kẽm trên sân thượng, giằng chéo chống gió, tiếp địa chống sét\n• Kích thước thường làm: chữ cao 60-120 cm\n• Lưu ý: chữ trên mái chịu gió mạnh, nên có bản tính kết cấu khung trước khi chốt kích thước chữ\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và thi công trọn gói trên mái.","descriptionEn":"Rooftop letters suit conference centres, wedding venues and multi-storey hotels that want the building's name seen from afar when the facade is already full of glazing and fins.\n\n• Letters: acrylic or folded aluminium with acrylic faces and waterproof LED modules; the logo can use LED dots for sparkle\n• Structure: galvanised steel box frame on the roof deck, cross-braced against wind and earthed for lightning\n• Typical size: letters 60-120 cm high\n• Tip: rooftop letters take strong wind, so get a structural check of the frame before fixing the letter height\n\nTrường Thịnh designs, builds in its workshop and handles the full rooftop installation.","altVi":"Chữ nổi LED và logo tròn trên khung thép mái tòa nhà buổi tối","altEn":"Illuminated rooftop letters and a round logo on a steel frame at dusk","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-27-imagegen-20261018.webp","sha256":"1eeccb25da108360c05d831468b4f94d64f2fb2d9e7e6aa667da3f2ca7433849","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:led-chu-diem-nong; original SHA256 f71b98ac97735464567d84cec164b9426ce3a664bb4abce962a8e61f9c97549d; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-28": {"descriptionVi":"Chữ nổi đèn LED gắn bóng tròn kiểu marquee hợp với quán cà phê, nhà hàng phong cách cổ điển muốn mặt tiền có điểm nhấn ấm mà vẫn đọc rõ tên quán.\n\n• Chữ: alu hoặc inox sơn tĩnh điện, khoan lỗ cắm bóng LED tròn chống nước\n• Logo: hộp đèn tròn mặt mica, khắc hình hoặc in UV\n• Kích thước thường làm: chữ cao 50-80 cm\n• Lưu ý: bóng ánh vàng 2700-3000K hợp mặt tiền tông kem, ánh trắng dễ làm chữ trông lạnh\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"LED marquee-style raised letters with round bulbs suit cafés and restaurants with a vintage look that want a warm feature on the frontage while keeping the name easy to read.\n\n• Letters: powder-coated aluminium or stainless, drilled for waterproof round LED bulbs\n• Logo: round acrylic-faced lightbox, engraved or UV printed\n• Typical size: letters 50-80 cm high\n• Tip: 2700-3000K warm bulbs suit cream facades, while cool white tends to make the letters look cold\n\nTrường Thịnh designs, builds in its own workshop and installs the letters.","altVi":"Chữ nổi gắn bóng LED vàng và logo ly cà phê trên mặt tiền","altEn":"Bulb-lit raised letters and a coffee cup logo on a café frontage","source":"/assets/content/projects/advertising/led-displays-lightboxes/chu-noi-den-led-mat-tien.webp","sha256":"ef359877ae2bedd780214c94719ac5ece63d695aebb6a8c467ef2fbf49720d3a","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 3050157fc62f6aa8c0cb3fa921f5d21e32e9d1acef64b0bc6ba53c2957f0f18d."},
  "led-displays-lightboxes-29": {"descriptionVi":"Bảng vẫy LED viền chạy đuổi hợp với tiệm sửa xe, vá vỏ, rửa xe ven đường, cần liệt kê dịch vụ để người chạy xe ngang qua quyết định ghé ngay.\n\n• Cấu tạo: hộp nhôm định hình, mặt alu hoặc mica khoan lỗ CNC, cắm LED ruồi chống nước\n• Điều khiển: mạch chạy viền, nháy chữ theo từng dòng\n• Kích thước thường làm: ngang 1-1,5 m, cao 50-70 cm, một hoặc hai mặt\n• Lưu ý: tay vẫy vươn ra lề đường nên giữ mép dưới cao trên 2,5 m để xe tải nhỏ không va\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"An LED projecting sign with a chasing border suits roadside motorbike repair, tyre and wash shops that need to list their services so passing riders decide to pull in.\n\n• Build: aluminium profile case, CNC-drilled aluminium composite or acrylic face, waterproof LED dots\n• Control: chasing border and line-by-line flashing text\n• Typical size: 1-1.5 m wide, 50-70 cm high, single or double-sided\n• Tip: an arm reaching over the pavement should keep the bottom edge above 2.5 m so small trucks don't clip it\n\nTrường Thịnh designs, builds in its own workshop and installs the sign.","altVi":"Bảng vẫy LED ruồi viền nhiều màu trước tiệm sửa xe máy","altEn":"Multi-colour LED-dot projecting sign outside a motorbike repair shop","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-29-imagegen-20261018.webp","sha256":"611779680e318905418c08e6a80953b93b5d31d63422e9b8984bd29e0722dabe","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:led-bang-vay-sua-xe; original SHA256 de2e80159d32df89b423f70c24efae12ddd35afaab12db8f63729daa7b4833ee; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-30": {"descriptionVi":"Bảng LED chân đứng hợp với xe bánh mì, quán ăn sáng, tiệm nhỏ không có chỗ treo biển, đặt ra vỉa hè lúc bán và cất vào trong khi dọn hàng.\n\n• Cấu tạo: mặt alu khoan lỗ cắm LED ruồi, hộp nhôm kín nước, chân sắt hộp sơn tĩnh điện\n• Nguồn: điện 220V qua ổ cắm, hoặc nguồn 12V chạy ắc quy cho điểm bán không có điện\n• Kích thước thường làm: 60x90 cm hoặc 80x120 cm\n• Lưu ý: chân đế nên rộng và có dằn tạ, bảng đứng ngoài trời dễ ngã khi gió giật\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và giao tận nơi.","descriptionEn":"A free-standing LED sign suits bánh mì carts, breakfast stalls and small shops with nowhere to hang a sign, set out on the pavement while trading and brought in at closing.\n\n• Build: drilled aluminium face with LED dots, sealed aluminium case, powder-coated steel stand\n• Power: 220V from a socket, or a 12V battery supply where there is no power point\n• Typical size: 60x90 cm or 80x120 cm\n• Tip: choose a wide, weighted base, as a free-standing sign outdoors tips over easily in gusts\n\nTrường Thịnh designs, builds the sign in its workshop and delivers it.","altVi":"Bảng LED ruồi chân sắt đặt trên vỉa hè cạnh tủ bánh mì","altEn":"Free-standing LED-dot sign on a steel stand beside a bánh mì cart","source":"/assets/content/projects/advertising/led-displays-lightboxes/bang-led-chan-dung-via-he.webp","sha256":"d996d5ccf33b96abedb0d18555c8ffecf4ebcc23bcad92e4f938a0eef627e017","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:led-bang-vay-banh-mi; original SHA256 2435727590731d7d2a195f27dd3d656d623a698d468de6522e07fcee3a5e452c; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-33": {"descriptionVi":"Kỷ niệm chương vinh danh là quà trao cho nhân viên, đối tác, nhà tài trợ trong lễ tổng kết, hội nghị khách hàng, kỷ niệm thành lập, chọn chất liệu theo mức trang trọng của từng hạng mục.\n\n• Chất liệu: gỗ hương hoặc gỗ đỏ gắn đồng ăn mòn, pha lê K9, kim loại in UV\n• Gia công: khắc laser hoặc ăn mòn chữ, in UV màu logo, đế gỗ hoặc đế pha lê\n• Kích thước thường làm: cao 18-25 cm\n• Lưu ý: chốt danh sách tên người nhận sớm 7-10 ngày, pha lê khắc sai không sửa được\n\nTrường Thịnh thiết kế, gia công và giao tận nơi trọn gói.","descriptionEn":"Honour plaques are presented to staff, partners and sponsors at year-end ceremonies, customer conferences and anniversaries, with the material chosen to match the weight of each award.\n\n• Material: rosewood or red timber with etched brass, K9 crystal, UV-printed metal\n• Fabrication: laser-engraved or etched lettering, full-colour UV logo, timber or crystal base\n• Typical size: 18-25 cm tall\n• Tip: confirm the list of recipients' names 7-10 days ahead, because a mistake engraved in crystal can't be fixed\n\nTrường Thịnh designs, makes and delivers the plaques.","altVi":"Ba kỷ niệm chương hình khiên bằng kim loại, gỗ đồng và pha lê","altEn":"Three shield-shaped plaques in metal, timber with brass, and crystal","source":"/assets/content/projects/advertising/office-signs-wayfinding/ky-niem-chuong-go-pha-le.webp","sha256":"dcaf9b2ee58d97bd4db7d15854f66f0be5d2b81fe4631412edb40ebbb9949325","provenance":"AI-generated illustration; owner approved 2026-10-12; original SHA256 1be51ed9a12dd456abc7a1d54077c068fa7eca1d009583d187237f13d49f1e41; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-34": {"descriptionVi":"Kỷ niệm chương in màu hợp với doanh nghiệp, cơ quan muốn phần thưởng mang đúng màu nhận diện, logo và họa tiết riêng thay vì chỉ khắc chữ một màu.\n\n• Chất liệu: mica dày 10-15 mm phủ nhũ bạc mặt sau, hoặc inox xước 1,5-2 mm\n• Gia công: cắt laser theo dáng, in UV màu trực tiếp, đế mica đen hoặc đá\n• Kích thước thường làm: cao 20-28 cm\n• Lưu ý: gửi file logo dạng vector để màu in khớp bộ nhận diện, nhất là màu đỏ và vàng\n\nTrường Thịnh thiết kế mẫu, gia công tại xưởng và giao tận nơi.","descriptionEn":"Colour-printed award plaques suit companies and public bodies that want awards in their own brand colours, logo and artwork rather than single-colour engraving.\n\n• Material: 10-15 mm acrylic with a silver backing, or 1.5-2 mm brushed stainless\n• Fabrication: laser-cut to shape, direct UV colour print, black acrylic or stone base\n• Typical size: 20-28 cm tall\n• Tip: supply the logo as a vector file so the print matches your brand colours, especially reds and golds\n\nTrường Thịnh designs the award, makes it in its workshop and delivers it.","altVi":"Kỷ niệm chương ngọn lửa in màu đỏ xanh, đế đen trên bàn họp","altEn":"Flame-shaped colour-printed award plaque on a black base on a boardroom table","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-34-owner-20261012.webp","sha256":"bde62af54755c8d0f13783d278333982d8b099f943be72d81b3494830f09fd6c","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 3480c197a7bc764b2397ec64abd2491c73c7a49138a65b1fadc91d42a7b74c6d."},
  "office-signs-wayfinding-35": {"descriptionVi":"Kỷ niệm chương gỗ đỏ hình khiên là mẫu truyền thống cho cơ quan, hiệp hội, doanh nghiệp trao danh hiệu, vinh danh tập thể, cá nhân trong lễ tổng kết.\n\n• Chất liệu: gỗ tự nhiên hoặc MDF phủ sơn PU bóng màu gỗ đỏ\n• Mặt: tấm đồng hoặc alu mạ vàng xước, khắc laser hay ăn mòn đổ sơn\n• Kích thước thường làm: 20x25 cm, 25x30 cm, có chân dựng và móc treo tường\n• Lưu ý: viền hoa văn đúc hợp kim mạ vàng nặng tay hơn viền in, nhìn sang hơn khi trao trên sân khấu\n\nTrường Thịnh thiết kế, gia công tại xưởng và giao tận nơi trọn gói.","descriptionEn":"A red timber shield plaque is the traditional choice for public bodies, associations and companies honouring teams and individuals at year-end ceremonies.\n\n• Material: solid timber or MDF in a glossy red-wood PU lacquer\n• Face: brushed gold-tone brass or aluminium plate, laser-engraved or etched and paint-filled\n• Typical size: 20x25 cm or 25x30 cm, with a stand and a wall hook\n• Tip: a cast gold-plated ornamental border feels weightier than a printed one and looks better when presented on stage\n\nTrường Thịnh designs, makes the plaque in its workshop and delivers it.","altVi":"Kỷ niệm chương gỗ đỏ hình khiên, tấm đồng vàng viền hoa văn nổi","altEn":"Red timber shield plaque with a brass-tone plate and raised ornamental border","source":"/assets/content/projects/advertising/office-signs-wayfinding/ky-niem-chuong-go-do.webp","sha256":"1967275f462327c73798ee628a316d9b3ebb9d4514ac01b00810dcefefbba1cc","provenance":"AI-generated illustration; owner approved 2026-10-12; original SHA256 7f4f07d1522a254a4b7ed299a25254d55427e6877fea4ec9063ed1d14d14764e; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-36": {"descriptionVi":"Kỷ niệm chương pha lê dáng ngọn lửa hợp với lễ vinh danh của doanh nghiệp, trường học, cơ quan, khi muốn giải thưởng trong trẻo, sang mà vẫn có điểm màu riêng.\n\n• Chất liệu: pha lê K9 cắt cạnh, dày 15-20 mm\n• Gia công: khắc laser chữ và biểu tượng, phun màu chuyển sắc ở phần chân\n• Đế: gỗ óc chó hoặc gỗ sồi phủ dầu\n• Lưu ý: in tên từng người nhận thì nên chọn khắc laser, nét mảnh vẫn rõ và không bong như in dán\n\nTrường Thịnh thiết kế, khắc tại xưởng và giao tận nơi trọn gói.","descriptionEn":"A flame-shaped crystal award suits recognition ceremonies at companies, schools and public bodies that want a clear, elegant piece with a touch of its own colour.\n\n• Material: 15-20 mm K9 crystal with cut edges\n• Fabrication: laser-engraved text and emblem, with a graduated colour tint at the foot\n• Base: oiled walnut or oak\n• Tip: for individual recipient names, choose laser engraving, which keeps fine strokes sharp and never peels like an applied print\n\nTrường Thịnh designs, engraves in its workshop and delivers the awards.","altVi":"Kỷ niệm chương pha lê hình ngọn lửa, chân phủ màu xanh, đế gỗ","altEn":"Flame-shaped crystal award with a blue-tinted lower edge on a timber base","source":"/assets/content/projects/advertising/office-signs-wayfinding/ky-niem-chuong-pha-le.webp","sha256":"bc6c745f86afee306f175bf13feec7651002887a4caf827de3bdc78f5b48b01c","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 65943c8db20627b28dba9535786cc1ff53f12ad7ca7a11db42a0bc86088a0dd8."},
  "office-signs-wayfinding-37": {"descriptionVi":"Kỷ niệm chương pha lê đế gỗ làm nhiều dáng trong một lần đặt hợp với lễ vinh danh có nhiều hạng mục, mỗi giải một kiểu nhưng cùng chất liệu nên vẫn đồng bộ.\n\n• Chất liệu: pha lê K9 dày 15-20 mm, đế gỗ sồi hoặc gỗ tần bì phủ dầu mờ\n• Gia công: in UV màu mặt sau, khắc laser chữ, mạ nhũ vàng chi tiết nhỏ\n• Kích thước thường làm: cao 18-24 cm\n• Lưu ý: đế gỗ sáng dễ lộ vết tay, nên phủ dầu hoặc lacquer mờ trước khi giao\n\nTrường Thịnh thiết kế từng mẫu, gia công tại xưởng và giao tận nơi.","descriptionEn":"Crystal awards on timber bases, made in several shapes in one order, suit ceremonies with many categories: each prize has its own form, while the shared materials keep the set consistent.\n\n• Material: 15-20 mm K9 crystal on oak or ash bases with a matt oil finish\n• Fabrication: reverse UV colour print, laser-engraved text, gold foil on small details\n• Typical size: 18-24 cm tall\n• Tip: pale timber shows fingerprints easily, so have the bases oiled or matt-lacquered before delivery\n\nTrường Thịnh designs each piece, makes them in its workshop and delivers the set.","altVi":"Năm kỷ niệm chương pha lê nhiều dáng in màu trên đế gỗ sáng","altEn":"Five crystal awards in different shapes with colour print on light timber bases","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-37-owner-20261012.webp","sha256":"cd17e8277c42d4bd9886d121db4a9a4628131eaece49ccd89be861a602da4245","provenance":"AI-generated illustration; owner approved 2026-10-12; original SHA256 c140e21b768459efdce0f4553cc1e44dc6f40d1df1e1dbb5222ffe7d4f9aa00c; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-38": {"descriptionVi":"Kỷ niệm chương mạ vàng bằng kim loại hợp với giải thưởng cấp cao của doanh nghiệp, hiệp hội, khi cần một phần thưởng nặng tay, đứng vững và không sợ vỡ khi vận chuyển.\n\n• Chất liệu: inox 304 dày 3-5 mm mạ PVD vàng, dải màu sơn tĩnh điện hoặc sơn men\n• Gia công: cắt laser theo dáng, khắc hoặc in UV nội dung\n• Đế: đá granite đen, cao 5-6 cm để cân phần thân\n• Lưu ý: mạ PVD giữ màu vàng lâu hơn nhiều so với sơn nhũ vàng, đáng chọn cho giải trưng bày lâu năm\n\nTrường Thịnh thiết kế, gia công tại xưởng và giao tận nơi trọn gói.","descriptionEn":"A gold-plated metal award suits top-tier company or association prizes that need real weight, stand firm and won't break in transit.\n\n• Material: 3-5 mm 304 stainless with gold PVD plating, colour bands in powder coat or enamel paint\n• Fabrication: laser-cut to shape, with engraved or UV-printed wording\n• Base: black granite, 5-6 cm high to balance the body\n• Tip: PVD plating keeps its gold far longer than metallic gold paint, so it is worth it for awards kept on display for years\n\nTrường Thịnh designs, makes the award in its workshop and delivers it.","altVi":"Kỷ niệm chương kim loại mạ vàng dáng ngọn lửa, đế đá đen","altEn":"Gold-plated metal flame award with teal and navy bands on a stone base","source":"/assets/content/projects/advertising/office-signs-wayfinding/ky-niem-chuong-ma-vang.webp","sha256":"d6ba0b1792a46a2e7b6b7ec14879f234a7e70a3dff33b597c8a5db9c9336f8a1","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 79dd72a9cb49343f8037c03cfcf086708214abbbe2f75300d362d15d17094a9b."},
  "office-signs-wayfinding-39": {"descriptionVi":"Kỷ niệm chương pha lê màu hợp với lễ vinh danh đại lý, nhân viên xuất sắc, giải thưởng nhiều hạng, khi cần phân biệt hạng mục bằng màu mà vẫn cùng một bộ.\n\n• Chất liệu: pha lê K9 nguyên khối, đế pha lê trong hoặc màu\n• Gia công: in UV màu lên mặt pha lê, khắc laser chữ hoặc logo\n• Kích thước thường làm: cao 20-25 cm, dày 1,5-2 cm\n• Lưu ý: in UV màu lên pha lê nên duyệt mẫu thật trước, màu dưới đèn sân khấu khác màu trên màn hình\n\nTrường Thịnh thiết kế, gia công và giao tận nơi trọn gói.","descriptionEn":"Coloured crystal plaques suit dealer awards, staff excellence awards and multi-tier prizes, when each category needs its own colour within one matching set.\n\n• Material: solid K9 crystal, clear or coloured crystal base\n• Fabrication: full-colour UV print on the crystal, laser-engraved text or logo\n• Typical size: 20-25 cm tall, 1.5-2 cm thick\n• Tip: approve a real sample of the UV colours first, as they look different under stage lights than on screen\n\nTrường Thịnh designs, makes and delivers the plaques.","altVi":"Ba kỷ niệm chương pha lê màu đỏ, xanh, lục in chữ vinh danh","altEn":"Three coloured crystal award plaques in red, blue and green","source":"/assets/content/projects/advertising/office-signs-wayfinding/ky-niem-chuong-pha-le-mau.webp","sha256":"f34e5acb9bd0b2b77fefbfe49bffbeda611900457bdd14615a40ac425ddc2ead","provenance":"AI-generated illustration; owner approved 2026-10-12; original SHA256 9af21b2824ea33a3301775ee82464dc83ab3d12e2dcd06c81e28425f2b71d317; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-40": {"descriptionVi":"Kỷ niệm chương pha lê mài giác hợp với lễ kỷ niệm thành lập, tri ân nhân viên lâu năm, khi phần thưởng cần trang trọng và trưng bày được nhiều năm.\n\n• Chất liệu: pha lê K9 dày 15-20 mm, cạnh mài nhiều giác bắt sáng\n• Gia công: khắc laser mặt sau hoặc phun cát, chữ trắng mờ không phai\n• Đế: gỗ tự nhiên sơn PU hoặc pha lê đen, kèm hộp nhung\n• Lưu ý: đặt trước 7-10 ngày khi làm số lượng lớn, vì pha lê mài giác phải mài tay từng cạnh\n\nTrường Thịnh thiết kế nội dung, khắc tại xưởng và giao tận nơi.","descriptionEn":"A faceted crystal plaque suits company anniversaries and long-service awards, where the piece needs to feel formal and stay on display for years.\n\n• Material: 15-20 mm K9 crystal with multi-faceted edges that catch the light\n• Fabrication: laser-engraved from the back or sandblasted, leaving a frosted text that never fades\n• Base: lacquered solid timber or black crystal, supplied in a velvet box\n• Tip: order 7-10 days ahead for larger runs, as each faceted edge is ground by hand\n\nTrường Thịnh lays out the wording, engraves in its workshop and delivers to your door.","altVi":"Kỷ niệm chương pha lê mài giác khắc laser trên đế gỗ đỏ","altEn":"Faceted crystal anniversary plaque, laser-engraved, on a red timber base","source":"/assets/content/projects/advertising/office-signs-wayfinding/ky-niem-chuong-mai-giac.webp","sha256":"1d3bf559c5b12b4d68c62af3764b549a5f00f33311e0a22e2bc98de0b5baa7d1","provenance":"AI-generated illustration; owner approved 2026-10-12; original SHA256 ceaff512305ac5a321caf7d8d7d1432ebff3d5fc53b41798ae9d5c1845989529; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "print-decals-22": {"descriptionVi":"In túi giấy kraft kèm hộp cùng mẫu hợp với tiệm bánh mì, tiệm bánh, quán bán mang đi cần đồ đựng chắc tay, in tên tiệm một màu cho tiết kiệm.\n\n• Chất liệu: kraft nâu 120-150 gsm cho túi, kraft 300-350 gsm cho hộp\n• In: flexo hoặc offset một màu, mực gốc nước an toàn khi đựng bánh\n• Quy cách: túi quai giấy xoắn, hộp gấp nắp gài không cần keo\n• Lưu ý: túi in riêng thường đặt từ vài nghìn cái, tiệm nhỏ có thể in tem dán lên túi trơn\n\nTrường Thịnh thiết kế, in và giao tận nơi trọn gói.","descriptionEn":"Printed kraft paper bags with matching boxes suit bánh mì shops, bakeries and takeaway counters that need sturdy packaging, with the shop name in one colour to keep costs down.\n\n• Material: 120-150 gsm brown kraft for bags, 300-350 gsm kraft for boxes\n• Print: one-colour flexo or offset with water-based ink, safe for food contact\n• Format: twisted paper handle bags, tuck-flap boxes with no glue needed\n• Tip: custom-printed bags usually start at a few thousand, so small shops can put printed stickers on plain bags\n\nTrường Thịnh designs, prints and delivers to your door.","altVi":"Túi quai giấy kraft và hộp in chữ BÁNH MÌ NƯỚNG trên quầy","altEn":"Kraft handle bags and boxes printed BÁNH MÌ NƯỚNG on a bakery counter","source":"/assets/content/projects/advertising/print-decals/in-tui-giay-kraft-tiem-banh.webp","sha256":"ad0aadbd8cdca026c6c99cccd108b87d0207a8987d5b071b1d1d55045a402392","provenance":"AI-generated illustration; owner approved 2026-10-12; original SHA256 88d3486d4883426d5bf5e533a500e497c2d62008247df20ff6d116fc02186fb6; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "print-decals-23": {"descriptionVi":"In thẻ thành viên ép nhũ hợp với spa, cửa hàng, câu lạc bộ, nhà hàng muốn tặng khách quen một tấm thẻ có cảm giác quý, phát kèm bao thư in logo.\n\n• Chất liệu: nhựa PVC 0,76 mm như thẻ ngân hàng, hoặc giấy mỹ thuật bồi dày\n• Gia công: ép nhũ vàng logo và chữ, bo góc, viền nhũ quanh cạnh thẻ\n• Đi kèm: phong bì giấy mỹ thuật in logo, vừa thẻ 86x54 mm\n• Lưu ý: cần quẹt thẻ hay quét mã thì báo trước để in mã vạch, QR hoặc gắn chip\n\nTrường Thịnh thiết kế, in và giao tận nơi trọn gói.","descriptionEn":"Foil-stamped member cards suit spas, shops, clubs and restaurants that want regulars to receive a card that feels valuable, presented in a logo envelope.\n\n• Material: 0.76 mm PVC like a bank card, or thick laminated art paper\n• Finishing: gold foil logo and text, rounded corners, foil-edged sides\n• Supplied with: logo-printed art-paper envelopes sized for 86x54 mm cards\n• Tip: if cards will be swiped or scanned, say so early to add a barcode, QR code or chip\n\nTrường Thịnh designs, prints and delivers to your door.","altVi":"Thẻ thành viên xanh navy ép nhũ vàng xếp trên bao thư kem","altEn":"Navy member cards with gold foil stacked on cream logo envelopes","source":"/assets/content/projects/advertising/print-decals/the-thanh-vien-ep-nhu.webp","sha256":"09323f8329b36d0bd9718f1cb75a8bb829a46108e6e4362103230b0acd6aefe6","provenance":"AI-generated illustration; Codex gpt-6-sol; source ID codex:2026-11-22:print-decals-23; original PNG SHA256 81ce2d799b69106392428b42a9e729789da558a266d823a066b46abd59725d6e; 1k master, owner approved 2026-11-21."},
  "print-decals-24": {"descriptionVi":"In vé vào cổng đánh số hợp với ban tổ chức hội chợ, triển lãm, đêm nhạc, khu vui chơi cần đếm khách và hạn chế vé giả mà không cần máy quét.\n\n• Giấy: couché hoặc giấy mỹ thuật 250-300 gsm\n• Gia công: nhảy số từng vé, cấn răng cưa xé cuống, ép nhũ để khó làm giả\n• Quy cách: 7x20 cm hoặc 6x18 cm, cuống chiếm khoảng một phần tư\n• Lưu ý: số nhảy in kỹ thuật số nên mỗi lô có thể đổi màu theo ngày hoặc theo khu\n\nTrường Thịnh thiết kế, in và giao tận nơi trọn gói.","descriptionEn":"Numbered entry ticket printing suits organisers of fairs, exhibitions, concerts and amusement parks who need to count visitors and deter fakes without scanners.\n\n• Paper: 250-300 gsm coated or art paper\n• Finishing: sequential numbering, perforated tear-off stub, foil to make copying harder\n• Format: 7x20 cm or 6x18 cm, with the stub about a quarter of the length\n• Tip: numbers are printed digitally, so each batch can change colour by day or zone\n\nTrường Thịnh designs, prints and delivers to your door.","altVi":"Ba vé vào cổng xanh navy họa tiết vàng có số thứ tự","altEn":"Three numbered navy and gold entry tickets with tear-off stubs","source":"/assets/content/projects/advertising/print-decals/in-ve-vao-cong-danh-so.webp","sha256":"b7eb7e3aefe11dd845d9a0c7403d3e5eb7e8874751bfa50bfa17caecc8626dbd","provenance":"AI-generated illustration; owner approved 2026-10-12; original SHA256 2fa8a114b32e9f3a6fb4a803cdc8708bf68112a56dc688164ac66a2308020f3b; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-27": {"descriptionVi":"Chữ nổi inox xước đèn hắt hợp với cửa hàng thời trang, văn phòng luật, quán cà phê tối giản muốn chữ kim loại sang mà không cần bảng nền.\n\n• Chất liệu: inox 304 xước dày 0,8-1 mm, lưng mica trong hoặc sữa\n• Đèn: LED module ánh vàng 3000K, chân ty giữ chữ cách tường 3-4 cm\n• Kích thước thường làm: chữ cao 20-60 cm\n• Lưu ý: dấu tiếng Việt cần chân gắn riêng chắc chắn, dấu nhỏ gắn hờ dễ lệch khi lau chùi\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"Brushed stainless halo-lit letters suit fashion stores, law offices and minimalist cafés that want refined metal lettering without a backing panel.\n\n• Material: 0.8-1 mm brushed 304 stainless, clear or opal acrylic backs\n• Lighting: 3000K warm LED modules, letters held 3-4 cm off the wall on studs\n• Typical size: letters 20-60 cm tall\n• Tip: Vietnamese accents need their own solid fixings, as small loosely set marks shift during cleaning\n\nTrường Thịnh designs, builds in its own workshop and installs the sign.","altVi":"Cận chữ Ê inox xước hắt sáng vàng ấm trên tường trắng","altEn":"Close-up of a brushed stainless letter with warm halo lighting on a white wall","source":"/assets/content/projects/advertising/signage-raised-letters/chu-noi-inox-xuoc-den-hat.webp","sha256":"98cb8efa5834f9fd48ff1827260cd31e9c52979e3754f3fa99faec9dbae9dfb6","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 446ebdda39ce59857913591a40f862218c6e0089e37b0c1ee329614b64121374."},
  "signage-raised-letters-28": {"descriptionVi":"Chữ nổi mica đỏ đèn LED là loại chữ sáng mặt phổ biến cho quán ăn, cửa hàng điện thoại, siêu thị mini muốn màu thương hiệu giữ đúng tông cả ngày lẫn tối.\n\n• Chất liệu: mica đỏ xuyên sáng 3 mm, viền inox hoặc alu chấn cao 5-8 cm\n• Đèn: LED module 12V xếp dày trong lòng chữ để mặt sáng đều, không lộ chấm\n• Kích thước thường làm: chữ cao 30-100 cm\n• Lưu ý: mica đỏ giá rẻ phai sang hồng sau 1-2 năm nắng, nên dùng loại chống UV\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"Red LED acrylic letters are the most common face-lit letter for eateries, phone shops and mini-marts that want their brand colour true by day and at night.\n\n• Material: 3 mm translucent red acrylic, stainless or folded aluminium returns 5-8 cm deep\n• Lighting: 12V LED modules packed closely so the face lights evenly with no hot spots\n• Typical size: letters 30-100 cm tall\n• Tip: cheap red acrylic fades to pink after 1-2 years of sun, so use a UV-stabilised grade\n\nTrường Thịnh designs, builds in its own workshop and installs the sign.","altVi":"Cận chữ nổi mica đỏ sáng mặt, viền kim loại trên mặt dựng trắng","altEn":"Close-up of a red face-lit acrylic letter with metal returns on white cladding","source":"/assets/content/projects/advertising/signage-raised-letters/chu-noi-mica-do-den-led.webp","sha256":"08843c54915040f0908905f7514ec9ea7d8b7db95c00248cd2e6c470bca678ae","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 2079a09a85c3f75b0dcf1869379a8ff932a9b63d5b23e40a8eb26df53d3db8ef."},
  "signage-raised-letters-29": {"descriptionVi":"Chữ nổi inox vàng xước hợp với tiệm vàng bạc, cửa hàng trang sức, showroom nội thất cần chữ kim loại màu vàng mà không chói như vàng gương.\n\n• Chất liệu: inox 304 mạ PVD màu vàng, mặt xước sợi dọc, dày 0,8-1,2 mm\n• Gia công: cắt laser, chấn viền, hàn kín và đánh mờ mối hàn\n• Kích thước thường làm: chữ cao 20-60 cm, viền dày 3-5 cm\n• Lưu ý: inox mạ màu kém chất lượng bong sau vài năm, hỏi rõ là mạ PVD hay sơn giả vàng\n\nTrường Thịnh thiết kế, gia công tại xưởng và lắp đặt trọn gói.","descriptionEn":"Gold brushed stainless letters suit gold and jewellery shops and furniture showrooms that want gold-toned metal lettering without the glare of a mirror finish.\n\n• Material: 0.8-1.2 mm 304 stainless with gold PVD coating, vertical brushed grain\n• Fabrication: laser cut, folded returns, welded and dressed seams\n• Typical size: letters 20-60 cm tall, returns 3-5 cm deep\n• Tip: poor-quality colour plating peels within a few years, so ask whether it is PVD or gold paint\n\nTrường Thịnh designs, fabricates in its workshop and installs the letters.","altVi":"Bộ chữ inox vàng xước hoàn thiện đặt trên bàn xưởng","altEn":"Finished gold brushed stainless letters laid out on a workshop table","source":"/assets/content/projects/advertising/signage-raised-letters/chu-noi-inox-vang-xuoc.webp","sha256":"d920748eecc234d08ebcbc49e5bc32b417a553d0ce9c026447309b0730ccfdf6","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:signage-detail-x1-xuong-a; original SHA256 4b16f7c196a4d2eaee2113df7cc35981c2ea85496e67cafb11a724d64ff87536; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-30": {"descriptionVi":"Chữ nổi inox vàng hắt chân được lắp đèn và chạy thử tại xưởng trước khi mang đi lắp, hợp với tiệm vàng, spa, khách sạn cần mặt tiền chỉn chu ngay từ ngày khai trương.\n\n• Chất liệu: inox 304 mạ PVD vàng xước, lưng mica, chân ty inox\n• Đèn: LED module 3000K, nguồn 12V chống nước\n• Kiểm tra: chạy thử đèn tại xưởng để thay bóng lỗi trước khi giao\n• Lưu ý: xưởng gửi kèm bản mẫu khoan tỷ lệ thật, thợ bắt chân ty đúng vị trí trên tường\n\nTrường Thịnh sản xuất, chạy thử tại xưởng và lắp đặt trọn gói.","descriptionEn":"Gold stainless halo-lit letters are wired and test-lit in the workshop before going to site, suiting gold shops, spas and hotels that need a polished frontage from opening day.\n\n• Material: brushed gold PVD 304 stainless, acrylic backs, stainless studs\n• Lighting: 3000K LED modules on a waterproof 12V supply\n• Testing: lights run in the workshop so faulty modules are replaced before delivery\n• Tip: a full-size drilling template comes with the letters, so the studs go exactly where they should\n\nTrường Thịnh builds and tests the letters in its workshop and installs them.","altVi":"Chữ inox vàng hắt chân đang thử đèn trên tấm panel trong xưởng","altEn":"Gold stainless halo-lit letters being light-tested on a workshop panel","source":"/assets/content/projects/advertising/signage-raised-letters/chu-noi-inox-vang-hat-chan.webp","sha256":"72933ebaa09cf1c613136ad5307dea77d8eb356ab600b56692a375710c10428d","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:signage-detail-x1-xuong-b; original SHA256 271892d0d4094b540c925888fde58188334ea2dc492255ab19a57a4c4adeddd1; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-31": {"descriptionVi":"Chữ nổi đèn LED mặt mica đỏ viền trắng hợp với quán cơm, quán ăn gia đình, tiệm ăn nhanh cần bảng tên rõ ràng với chi phí vừa phải.\n\n• Chất liệu: mặt mica đỏ 3 mm, viền mica trắng hoặc alu sơn trắng cao 8-10 cm\n• Đèn: LED module 12V, chạy thử tại xưởng trước khi giao\n• Kích thước thường làm: chữ cao 40-80 cm\n• Lưu ý: viền mica dán keo cần đủ thời gian khô, chữ làm vội dễ hở mép và vào nước sau mùa mưa\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"LED letters with red acrylic faces and white returns suit rice eateries, family restaurants and fast-food shops that want a clear name sign at a moderate cost.\n\n• Material: 3 mm red acrylic faces, white acrylic or painted aluminium returns 8-10 cm deep\n• Lighting: 12V LED modules, test-lit in the workshop before delivery\n• Typical size: letters 40-80 cm tall\n• Tip: glued acrylic returns need full curing time; rushed letters open at the seams and let water in after the rains\n\nTrường Thịnh designs, builds in its own workshop and installs the sign.","altVi":"Chữ nổi mặt mica đỏ viền trắng sáng đèn trên bàn xưởng","altEn":"Red-faced lit letters with white returns on a workshop bench","source":"/assets/content/projects/advertising/signage-raised-letters/chu-noi-den-led-quan-com.webp","sha256":"a7995de4c2a9b7917bfc93986c11e1bf2084366bd85fae9c4e6a1e8564961edf","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:signage-detail-x2-xuong-a; original SHA256 7195f21c740eb5c18a3aedfa5e6eab97b3ee7f9150e6a72fdb146e6dc6c79cf3; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-32": {"descriptionVi":"Gia công chữ nổi mica tại xưởng gồm cắt CNC mặt chữ, dán viền, lắp đèn rồi chạy thử, phù hợp cho chủ cửa hàng và cả đơn vị quảng cáo cần đặt chữ đúng mẫu thiết kế.\n\n• Cắt: CNC router hoặc laser theo file vector, sai số dưới 1 mm\n• Viền: mica hoặc alu chấn máy, dán keo chuyên dụng kín nước\n• Đèn: LED module 12V, đi dây gọn, chừa lỗ thoát nước dưới chân chữ\n• Lưu ý: gửi file vector (AI, PDF, DXF) để giữ đúng nét logo; file ảnh JPG phải vẽ lại, mất thêm thời gian\n\nTrường Thịnh nhận gia công chữ nổi tại xưởng và lắp đặt trọn gói.","descriptionEn":"Acrylic letter fabrication in the workshop covers CNC-cutting the faces, fitting returns, wiring the lights and test-running them, for shop owners and sign companies that need letters exactly to design.\n\n• Cutting: CNC router or laser from vector files, within 1 mm tolerance\n• Returns: acrylic or machine-folded aluminium, bonded with waterproof adhesive\n• Lighting: 12V LED modules, tidy wiring, drain holes at the base of each letter\n• Tip: send vector files (AI, PDF, DXF) to keep the logo exact; a JPG has to be redrawn, which takes longer\n\nTrường Thịnh fabricates letters to order in its workshop and installs them.","altVi":"Thợ ráp chữ nổi mica đỏ viền trắng trên bàn xưởng","altEn":"Worker assembling red acrylic letters with white returns at a workshop bench","source":"/assets/content/projects/advertising/signage-raised-letters/gia-cong-chu-noi-mica.webp","sha256":"c34982e47d026ecc18934594ac756e9ecdb47836a30db69986fc55ed9b0c0a36","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 f06e41cfab3af538f1c612037009d0a1b04082984087983981b95687c09b3bd2."},
  "signage-raised-letters-33": {"descriptionVi":"Bảng mica LED neon treo dây cáp hợp với quầy bar quán cà phê, tiệm bánh có tường gạch hoặc tường tối màu, cần biển tên trong nhà nhẹ mà không phải khoan nhiều vào tường.\n\n• Chất liệu: mica trong 5-8 mm cắt CNC, dây LED neon silicon uốn theo nét chữ\n• Đèn: nguồn 12V kèm dimmer chỉnh độ sáng, tốn điện ít hơn đèn neon thủy tinh nhiều lần\n• Kích thước thường làm: ngang 60-120 cm\n• Lưu ý: chữ viết tay nét liền uốn LED neon đẹp hơn font có chân, nét nhỏ dưới 3 cm khó uốn gọn\n\nTrường Thịnh thiết kế, uốn LED tại xưởng và treo lắp tận nơi.","descriptionEn":"A cable-hung acrylic LED neon sign suits café bars and bakeries with brick or dark walls that want a light indoor name sign without drilling much into the wall.\n\n• Material: 5-8 mm clear acrylic cut by CNC, silicone LED neon flex bent to the lettering\n• Lighting: 12V supply with a dimmer, using far less power than glass neon\n• Typical size: 60-120 cm wide\n• Tip: joined-up script lettering bends better in LED neon than serif fonts, and strokes under 3 cm are hard to form cleanly\n\nTrường Thịnh designs the sign, bends the LED in its workshop and hangs it on site.","altVi":"Bảng mica trong uốn LED neon hình tách cà phê trên quầy pha chế","altEn":"Clear acrylic panel with an LED neon coffee cup hung above a café bar","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-33-imagegen-20261018.webp","sha256":"aa6d4deee95a5be8d91f893e21d50fb519ae908c98ec876ae02a831ad550f28b","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:signage-raised-letters-33-1; original SHA256 836cf541752a3801d9fea68a82c000aa5b27b3991575706e0fd0201da6f80fa9; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-34": {"descriptionVi":"Bảng hiệu nhà hàng kết hợp ốp lam gỗ mặt tiền hợp với nhà hàng gia đình, quán ăn ven sông muốn cả tòa nhà thành bảng hiệu chứ không chỉ một tấm biển.\n\n• Lam: gỗ nhựa composite hoặc nhôm vân gỗ, bền mưa nắng hơn gỗ tự nhiên\n• Bảng chữ: alu sơn tối, chữ inox mạ vàng hoặc mica vàng, đèn hắt\n• Đèn: LED dây chống nước âm trong lam, bật tắt theo giờ\n• Lưu ý: gỗ tự nhiên ngoài trời phải sơn dầu lại hằng năm, composite gần như không cần bảo dưỡng\n\nTrường Thịnh thiết kế mặt tiền, sản xuất tại xưởng và thi công trọn gói.","descriptionEn":"A restaurant sign combined with timber-slat cladding suits family restaurants and riverside eateries that want the whole building to act as the sign, not just one panel.\n\n• Slats: wood-plastic composite or wood-grain aluminium, more weatherproof than real timber\n• Sign panel: dark painted aluminium composite, gold-plated stainless or gold acrylic letters, halo-lit\n• Lighting: waterproof LED strip recessed in the slats, on a timer\n• Tip: real timber outdoors needs re-oiling every year, while composite needs almost no upkeep\n\nTrường Thịnh designs the frontage, builds in its workshop and handles the installation.","altVi":"Mặt tiền nhà hàng ốp lam gỗ, bảng chữ vàng và dải LED","altEn":"Restaurant frontage clad in timber slats with gold letters and LED strip","source":"/assets/content/projects/advertising/signage-raised-letters/bang-hieu-nha-hang-op-go.webp","sha256":"9efb63286f36857d0017cf5aa2935bf7b2b3805139e03f37127386132918fb41","provenance":"AI-generated illustration; owner selected A270-v1 in HTML audit and confirmed in chat 2026-10-22; ChatGPT web gpt-image; original SHA256 9d1b0167aeeabadb36d0d8f8295c85516780d92fa54c9c633166c2c54af52e57; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-38": {"descriptionVi":"Vách trưng bày hương liệu có khoang tròn hợp với thương hiệu trầm hương, tinh dầu, nước hoa làm điểm bán trong trung tâm thương mại, cần một mảng tường đủ sang để bày ít mà bán giá cao.\n\n• Vách: khung gỗ ốp MDF sơn đen mờ, lam gỗ dọc, chữ in UV hoặc chữ nổi mica\n• Khoang tròn: vòng gỗ uốn, kệ đợt âm LED, tủ thấp có cánh trữ hàng\n• Bục: trụ tròn ốp lam, cao lệch nhau để bày mẫu thử\n• Lưu ý: nền tối làm sản phẩm nổi nhưng cần thêm đèn rọi, thiếu sáng khách khó đọc nhãn\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A fragrance display wall with a circular niche suits agarwood, essential oil and perfume brands selling from a mall pitch, giving them a wall refined enough to show a few high-value pieces.\n\n• Wall: timber frame with matt black MDF, vertical timber slats, UV-printed or raised acrylic lettering\n• Niche: bent timber ring, LED-lit shelves, low cabinet with doors for stock\n• Plinths: round slatted columns at staggered heights for testers\n• Tip: a dark backdrop makes products stand out but needs extra spotlights, or labels become hard to read\n\nTrường Thịnh designs, builds in its workshop and installs the wall.","altVi":"Vách trưng bày lam gỗ, khoang tròn hắt sáng và bục gỗ tròn","altEn":"Slatted timber display wall with a lit circular niche and round timber plinths","source":"/assets/content/projects/advertising/kiosk-posm/vach-trung-bay-huong-lieu.webp","sha256":"03341ea5b459ac298c407b25979e6d171b06f49dd4c441e76b88d1e474452fb3","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd3c3-f4e0-83ec-b65e-ec700ba3d93f); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-27 01:07Z; master PNG SHA256 4cd3cb2b16015f49da0c34667169bfab2ba1dd8cef33c2e14603848c4c3a52fd."},
  "office-signs-wayfinding-32": {"descriptionVi":"Biển tên khách sạn inox gắn trụ cổng hợp với khách sạn nhỏ, nhà nghỉ, villa cho thuê và văn phòng công ty có cổng riêng, cần một bảng tên gọn, bền và trang nhã.\n\n• Chất liệu: inox 304 xước 1,2-1,5 mm, chân đinh inox\n• Gia công: chữ ăn mòn đổ sơn hoặc in UV, viền chỉ ăn mòn quanh mép\n• Kích thước thường làm: 40x30 cm đến 60x40 cm\n• Lưu ý: gắn nơi nắng trực tiếp thì chọn ăn mòn đổ sơn, chữ bền màu hơn in UV sau vài năm\n\nTrường Thịnh thiết kế, gia công tại xưởng và lắp đặt trọn gói.","descriptionEn":"A stainless hotel name plate for a gate pillar suits small hotels, guesthouses, rental villas and company offices with their own gate, needing a neat, durable and understated name plate.\n\n• Material: 1.2-1.5 mm brushed 304 stainless, stainless stand-offs\n• Fabrication: etched and paint-filled or UV-printed lettering, etched border line\n• Typical size: 40x30 cm to 60x40 cm\n• Tip: in direct sun choose etched and paint-filled lettering, which keeps its colour longer than UV print\n\nTrường Thịnh designs, makes the plate in its workshop and installs it.","altVi":"Biển tên khách sạn inox xước chân đinh trên trụ cổng trắng","altEn":"Brushed stainless hotel name plate on stand-offs on a white gate pillar","source":"/assets/content/projects/advertising/office-signs-wayfinding/bien-ten-khach-san-inox.webp","sha256":"338b567e59c749b23e5f568bd4401a57edde1f2ec35de8011055ce39594ef1b0","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:new-bang-ten-cong-ty-x1; original SHA256 c050e9578fa849ae430d95ad47db2fa01340b2fc77cb152256eebfccaa30bd36; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-19": {"descriptionVi":"Hộp đèn quầy trà sữa dạng mỏng đặt ngang hợp với tiệm trà sữa, cà phê mang đi muốn giới thiệu món mới ngay chỗ khách gọi và trả tiền.\n\n• Cấu tạo: khung nhôm dày 2-3 cm, tấm dẫn sáng LED viền, chân đế nhôm nặng chống đổ\n• Mặt tranh: film in UV, thay qua khe trên khung\n• Nguồn: adapter 12V cắm ổ quầy, hoặc pin sạc cho quầy không có ổ điện\n• Kích thước thường làm: A3, A2 ngang hoặc 40x60 cm\n\nTrường Thịnh thiết kế ảnh món, sản xuất tại xưởng và giao tận nơi.","descriptionEn":"A slim landscape counter lightbox suits milk tea and takeaway coffee shops that want to push new drinks right where customers order and pay.\n\n• Build: 2-3 cm aluminium frame, edge-lit LED panel, weighted aluminium base that won't tip\n• Graphic: UV-printed film, slid in through a slot in the frame\n• Power: 12V adapter from a counter socket, or a rechargeable battery where there is none\n• Typical size: A3 or A2 landscape, or 40x60 cm\n\nTrường Thịnh designs the drink artwork, builds the box in its workshop and delivers it.","altVi":"Hộp đèn mỏng ngang chân nhôm đặt trên quầy gỗ trà sữa","altEn":"Slim landscape lightbox on an aluminium base on a milk tea counter","source":"/assets/content/projects/advertising/led-displays-lightboxes/hop-den-quay-tra-sua.webp","sha256":"1bb415230a5bd26d1b53a0c5c9faeb21fdee9688fa4378cd6af0124424012c89","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:led-displays-lightboxes-c1; original SHA256 65f6d421e1852500b1b13a4e33e0f33b930226ad3448ee5b16985aad08cf66c3; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-20": {"descriptionVi":"Hộp đèn để bàn hai mặt hợp với tiệm bánh mì, xe bánh, quầy đồ ăn sáng, đặt ở mép quầy hướng ra đường và đổi ảnh khi có món mới.\n\n• Cấu tạo: khung nhôm viền bo, chân đế nhôm đúc, tấm dẫn sáng LED\n• Mặt tranh: film in UV hai mặt, ép giữa hai tấm mica trong\n• Kích thước thường làm: A4, A3 hoặc 30x45 cm\n• Lưu ý: quầy ngoài trời nên dùng adapter vỏ kín, dây đủ dài để giấu sau quầy, tránh nước rửa bắn vào\n\nTrường Thịnh thiết kế, in và giao tận nơi trọn gói.","descriptionEn":"A double-sided tabletop lightbox suits bánh mì shops, food carts and breakfast counters, set at the edge of the counter facing the street and updated when the menu changes.\n\n• Build: rounded aluminium frame, cast aluminium base, LED light-guide panel\n• Graphic: double-sided UV-printed film between two clear acrylic sheets\n• Typical size: A4, A3 or 30x45 cm\n• Tip: on an outdoor counter use a sealed adapter with a cable long enough to hide behind the counter, away from washing water\n\nTrường Thịnh designs, prints and delivers to your door.","altVi":"Hộp đèn để bàn đứng dọc in ảnh bánh mì trên quầy","altEn":"Portrait tabletop lightbox with a bánh mì photo on a bakery counter","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-20-imagegen-20261014.webp","sha256":"e5800b57f1fbc4cc59216155983da705634f4c20e5b9985025b3ab6a30825fa8","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:led-displays-lightboxes-c2; original SHA256 bf895132855e1501be62e2fb76b9e32e54211bacd28ba62ce9f43e7250cdeeb1; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-21": {"descriptionVi":"Hộp đèn treo tường khổ đứng hợp với quán gà rán, quán ăn nhanh, tiệm đồ uống có mảng tường hẹp cạnh quầy, dùng như tấm menu ảnh lớn cho món bán chạy.\n\n• Cấu tạo: khung nhôm định hình dày 4-8 cm, LED module hoặc tấm dẫn sáng\n• Mặt tranh: vải hoặc bạt xuyên sáng in UV, viền silicon thay nhanh\n• Kích thước thường làm: 80x120 cm hoặc 100x150 cm\n• Lưu ý: chừa ổ điện đúng vị trí treo trước khi hoàn thiện tường, tránh dây đi nổi\n\nTrường Thịnh thiết kế ảnh, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A portrait wall lightbox suits fried chicken shops, fast-food outlets and drinks shops with a narrow wall beside the counter, working as one big photo menu for the best seller.\n\n• Build: 4-8 cm extruded aluminium frame, LED modules or light-guide panel\n• Graphic: UV-printed backlit fabric or banner with a silicone edge for quick changes\n• Typical size: 80x120 cm or 100x150 cm\n• Tip: put a socket at the hanging point before the wall is finished, so no cable runs on the surface\n\nTrường Thịnh designs the artwork, builds the box in its workshop and installs it.","altVi":"Hộp đèn treo tường đứng dọc ảnh gà rán trên vách lam gỗ","altEn":"Portrait wall lightbox of fried chicken on a timber-slatted wall","source":"/assets/content/projects/advertising/led-displays-lightboxes/hop-den-treo-tuong-ga-ran.webp","sha256":"b1ec465d603d6f7f0b96770055b5a8704bf7ff50b69168c2cbc56a7513f64dc4","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:led-displays-lightboxes-c3; original SHA256 490c15ef8bee1b92a351c4034bffe5b7559026a5ad2818d9e7f608908b507142; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-22": {"descriptionVi":"Khung poster treo tường hợp với tiệm bánh, quán cà phê nhỏ muốn trang trí bằng ảnh món của chính quán, rẻ hơn hộp đèn và dễ đổi ảnh theo mùa.\n\n• Khung: gỗ hoặc nhôm sơn đen, mặt mica trong hoặc kính, lưng ván ép\n• In: giấy ảnh hoặc giấy mỹ thuật in phun, màu bền trong nhà\n• Kích thước thường làm: A2, A1 hoặc 50x70 cm\n• Lưu ý: mặt mica nhẹ và an toàn hơn kính ở quán đông khách, nhưng nên chọn loại chống trầy\n\nTrường Thịnh thiết kế, in, đóng khung và giao tận nơi trọn gói.","descriptionEn":"Framed wall posters suit bakeries and small cafés that want to decorate with photos of their own products, for less than a lightbox and easy to change with the seasons.\n\n• Frame: timber or black aluminium, clear acrylic or glass front, plywood back\n• Print: inkjet on photo or fine-art paper, colourfast indoors\n• Typical size: A2, A1 or 50x70 cm\n• Tip: acrylic is lighter and safer than glass in a busy café, but choose a scratch-resistant grade\n\nTrường Thịnh designs, prints, frames and delivers the set.","altVi":"Hai khung poster ảnh bánh ngọt treo trên tường vàng quán","altEn":"Two framed pastry posters on a yellow café wall","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-22-imagegen-20261014.webp","sha256":"a01f1714ebefa85e6085526b8bfd427d97835e9eac7fb4d7041ffba2b3b768c7","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:led-displays-lightboxes-c4; original SHA256 c0523aaec955c3bf6bee0b7eabe0ea40d78c230537728d58294b5ea5f888acba; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-23": {"descriptionVi":"Hộp đèn vải căng khổ lớn hợp với cửa hàng giày, thời trang, mỹ phẩm cần một mảng ảnh sản phẩm sáng đều cả tường mà không lộ khung dày.\n\n• Cấu tạo: khung nhôm định hình có rãnh, LED module chiếu ngược, dày 8-12 cm\n• Mặt tranh: vải polyester in UV hoặc in chuyển nhiệt, viền silicon nhét rãnh\n• Kích thước thường làm: 1x2 m đến 2x3 m\n• Lưu ý: vải gấp gọn gửi được qua bưu điện, chuỗi cửa hàng đổi chiến dịch chỉ cần in vải mới\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A large fabric lightbox suits shoe, fashion and cosmetics stores that want an evenly lit product image across a wall without a bulky frame.\n\n• Build: grooved extruded aluminium frame, backlit LED modules, 8-12 cm deep\n• Graphic: UV or dye-sublimation printed polyester with a silicone edge pressed into the groove\n• Typical size: 1x2 m to 2x3 m\n• Tip: the fabric folds up for posting, so a chain changing campaigns only needs new prints\n\nTrường Thịnh designs, builds the frame in its workshop and installs it.","altVi":"Hộp đèn vải căng khổ đứng nền cam trong cửa hàng giày","altEn":"Tall orange fabric lightbox on the wall of a shoe shop","source":"/assets/content/projects/advertising/led-displays-lightboxes/hop-den-vai-cang.webp","sha256":"2a8dcb35b9798a1dbb98520ffccf94b5e262df3816c2cbdd381e63bc189e5a2c","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:led-displays-lightboxes-c5; original SHA256 98b747ddba57d4f06f2fcf6a3fc7d698acc89eeed3a7bdb143b73f5facc07208; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-39": {"descriptionVi":"Tranh sắt cắt CNC hắt đèn là món trang trí hợp với quán cà phê sân vườn, nhà hàng có mảng tường trống ngoài trời, vừa làm điểm chụp ảnh vừa nhắc chủ đề quán mà không cần hộp đèn.\n\n• Chất liệu: thép tấm 2-3 mm cắt laser hoặc CNC plasma, sơn tĩnh điện đen mờ\n• Đèn: LED dây hoặc LED module gắn sau hình, cách tường 3-5 cm bằng chân đinh\n• Kích thước thường làm: ngang 80-150 cm\n• Lưu ý: đặt ngoài trời nên dùng thép mạ kẽm rồi mới sơn, mép cắt không xử lý sẽ gỉ sau vài mùa mưa\n\nTrường Thịnh vẽ hình, cắt tại xưởng và lắp đặt trọn gói.","descriptionEn":"A CNC-cut steel wall artwork with halo lighting suits garden cafés and restaurants with a bare outdoor wall, giving a photo spot and a nod to the theme without a lightbox.\n\n• Material: 2-3 mm steel plate, laser or CNC plasma cut, matt black powder coat\n• Lighting: LED strip or modules behind the shape, held 3-5 cm off the wall on stand-offs\n• Typical size: 80-150 cm wide\n• Tip: outdoors, use galvanised steel before painting, because untreated cut edges rust within a few rainy seasons\n\nTrường Thịnh draws the design, cuts it in its workshop and installs it.","altVi":"Hình tách cà phê cắt sắt đen hắt đèn trên tường sân vườn","altEn":"Black steel coffee cup cut-out with halo lighting on a garden wall","source":"/assets/content/projects/advertising/kiosk-posm/tranh-sat-hat-den-ca-phe.webp","sha256":"018cdd09ed5d58bc942f2445e1c7f90f5aca50fc5049eb5365f091c172a23cd4","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:new-led-decor-c6; original SHA256 531e6ac18c78379de0482798db983fc6264008898b4bf93c18d1ce2e926ea07d; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-40": {"descriptionVi":"LED neon chữ treo tường hợp với tiệm hoa, shop quà tặng, studio nhỏ muốn có một góc nhận diện riêng để khách chụp ảnh và đăng mạng.\n\n• Chất liệu: dây LED neon silicon 6-8 mm, đế mica trong 5 mm cắt laser theo chữ\n• Nguồn: adapter 12V kèm dimmer chỉnh độ sáng, tốn điện ít hơn neon thủy tinh\n• Kích thước thường làm: ngang 60-120 cm\n• Lưu ý: chữ viết tay nét quá nhỏ khó uốn, nên duyệt bản vẽ đường dây trước khi làm\n\nTrường Thịnh thiết kế, uốn neon tại xưởng và lắp đặt trọn gói.","descriptionEn":"A wall-mounted LED neon word sign suits florists, gift shops and small studios that want a signature corner customers like to photograph and share.\n\n• Material: 6-8 mm silicone LED neon flex on 5 mm clear acrylic, laser cut to the lettering\n• Power: 12V adapter with a dimmer, using less power than glass neon\n• Typical size: 60-120 cm wide\n• Tip: very fine handwritten strokes are hard to bend, so approve the line drawing before production\n\nTrường Thịnh designs, bends the neon in its workshop and installs it.","altVi":"Chữ LED neon đỏ trên tấm mica trong, gắn tường tiệm hoa","altEn":"Red LED neon lettering on clear acrylic on a florist's wall","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-40-imagegen-20261018.webp","sha256":"cbd9dfd65b390b749b1cb9c7f4165830e0b27ae958c88f27dc2d8c9155c863cf","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 eda3ec59633daa9ada59f843b4656d2970da80b9c3dffee1a34b59542c435284."},
  "signage-raised-letters-35": {"descriptionVi":"Bảng vẫy hộp đèn gắn tường là lựa chọn hợp cho quán cà phê, tiệm trà mặt tiền hẹp, khi bảng hiệu ngang không đủ chỗ hoặc bị cây che.\n\n• Cấu tạo: viền tôn sơn tĩnh điện, mặt mica sữa, logo in UV hoặc ghép mica màu nổi\n• Đèn: LED module ánh trắng ấm, bộ nguồn đặt trong nhà để dễ thay\n• Kích thước thường làm: đường kính 60-80 cm, hai mặt\n• Lưu ý: hộp trên 70 cm nên dùng tay đỡ hai thanh và bu lông hóa chất để không rung khi gió lớn\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A wall-mounted lightbox projecting sign suits cafés and tea shops with narrow frontages, where a fascia sign has no room or is hidden by trees.\n\n• Build: powder-coated steel rim, opal acrylic face, logo UV printed or built up in coloured acrylic\n• Lighting: warm white LED modules, with the power supply kept indoors for easy replacement\n• Typical size: 60-80 cm diameter, double-sided\n• Tip: boxes over 70 cm need a twin-arm bracket and chemical anchors so they don't shake in strong wind\n\nTrường Thịnh designs, builds in its own workshop and installs the sign.","altVi":"Bảng vẫy hộp đèn tròn mica chữ BREWTIFUL, gắn tay thép trên tường","altEn":"Round acrylic lightbox sign reading BREWTIFUL on a wall-mounted steel bracket","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-35-brewtiful-20261115.webp","sha256":"874507ec96a9e96851bad05f69fd0812b0d162dbd5c5bb84164f6e41764b307c","provenance":"AI-generated illustration; ChatGPT web gpt-image edit (chat 6af9c15b-99f4-83ec-8aab-6e4dcbebdff7); owner approved 2026-11-15; original PNG SHA256 12ec53c629a0ef147994fc59266eb861d23eae2352f4de2463aca30f6328ced2."},
  "signage-raised-letters-36": {"descriptionVi":"Hộp đèn dọc gắn vuông góc tường hợp với quán cà phê, tiệm trà trên phố nhỏ có hàng cây, nơi bảng ngang song song mặt tiền khó thấy từ đầu đường.\n\n• Cấu tạo: hộp nhôm hoặc tôn sơn tĩnh điện, hai mặt mica sữa, chữ ghép mica hoặc decal; bản tiết kiệm dùng bạt 3M in chữ\n• Đèn: LED module ánh trắng ấm 3000-4000K\n• Kích thước thường làm: rộng 30-50 cm, cao 1,5-3 m\n• Lưu ý: hộp cao trên 2 m cần ba điểm tay đỡ bắt vào dầm hoặc cột, không bắt vào tường gạch đơn\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A vertical lightbox mounted at right angles to the wall suits cafés and tea shops on small tree-lined streets, where a fascia sign parallel to the front is hard to spot from the corner.\n\n• Build: powder-coated aluminium or steel case, opal acrylic on both faces, inlaid acrylic or vinyl lettering, or printed 3M flex faces on a tighter budget\n• Lighting: warm white LED modules at 3000-4000K\n• Typical size: 30-50 cm wide, 1.5-3 m tall\n• Tip: boxes over 2 m need three bracket points into a beam or column, never into a single-skin brick wall\n\nTrường Thịnh designs, builds in its own workshop and installs the sign.","altVi":"Hộp đèn dọc chữ cà phê gắn vuông góc tường mặt tiền","altEn":"Tall vertical café lightbox mounted at right angles to the facade","source":"/assets/content/projects/advertising/signage-raised-letters/hop-den-doc-quan-ca-phe.webp","sha256":"136f160f81565a358564d4b79f00b00360dbec825189baffd33eab1d5971c05e","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:signage-raised-letters-c9; original SHA256 69fd78f15f870a32e42fd24d57e3abca4013b95ac654c4eadbd83e575ec32f6d; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-24": {"descriptionVi":"Bảng hiệu mô hình 3D cắt theo hình món ăn hợp với quán bún, quán phở, quán lẩu ven đường muốn khách nhận ra món bán mà không cần đọc chữ.\n\n• Chất liệu: Formex hoặc alu cắt CNC theo đường viền, in UV ảnh món trực tiếp lên tấm\n• Chân đế: sắt hộp sơn tĩnh điện, đế rộng hoặc bắt bu lông xuống nền\n• Kích thước thường làm: cao 1,5-2 m, ngang 1-1,4 m\n• Lưu ý: nên đặt trong phần đất nhà mình và neo chân chắc, biển trên vỉa hè dễ bị nhắc nhở và gió quật\n\nTrường Thịnh thiết kế hình, sản xuất tại xưởng và giao lắp trọn gói.","descriptionEn":"A 3D cut-out sign shaped like the dish suits noodle, pho and hotpot eateries by the road that want passers-by to recognise the food without reading a word.\n\n• Material: CNC contour-cut Formex or aluminium composite, dish photo UV printed directly onto the panel\n• Stand: powder-coated steel box section, wide base or bolted to the ground\n• Typical size: 1.5-2 m tall, 1-1.4 m wide\n• Tip: keep it on your own frontage and anchor it well, as signs on the pavement draw complaints and catch the wind\n\nTrường Thịnh draws the shape, builds the sign in its workshop and delivers it.","altVi":"Bảng hiệu mô hình tô bún và đũa trên chân sắt ven đường","altEn":"Cut-out noodle bowl sign with chopsticks on a steel stand by the road","source":"/assets/content/projects/advertising/led-displays-lightboxes/bang-hieu-mo-hinh-to-bun.webp","sha256":"d18a07a6f781a392bfed73ef3a6db19e099a6f278434fe3b71692850c6d36702","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:led-displays-lightboxes-c10; original SHA256 b505af2475dcbcbd6e34c56642ad283f59009ef75f30ebd6302c973742a9888e; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "mobile-retail-22": {"descriptionVi":"Xe nước mía khung gỗ hợp với người bán nước mía, nước ép ở bờ kè, công viên, phố đi bộ, cần xe gọn, chở được máy ép và mía cây mà một người vẫn đẩy được.\n\n• Thân xe: gỗ dầu hoặc gỗ thông xử lý chống mối, sơn PU ngoài trời\n• Mặt quầy: lót inox chỗ đặt máy ép, cánh gỗ gấp hai bên để mía và ly\n• Kích thước thường làm: dài 1,4-1,6 m, rộng 0,6-0,7 m, cao tổng khoảng 2,2 m\n• Lưu ý: máy ép mía khá nặng, nên đặt gần trục bánh xe và gia cố khung đáy\n\nTrường Thịnh thiết kế, đóng xe tại xưởng và giao tận nơi trọn gói.","descriptionEn":"A timber sugarcane juice cart suits juice sellers on riverside walks, in parks and on walking streets who need a compact cart that carries the press and cane yet one person can still push.\n\n• Body: termite-treated dầu hardwood or pine in an exterior PU finish\n• Counter: stainless lining under the press, fold-out timber leaves for cane and cups\n• Typical size: 1.4-1.6 m long, 0.6-0.7 m deep, about 2.2 m tall overall\n• Tip: a cane press is heavy, so mount it near the axle and reinforce the base frame\n\nTrường Thịnh designs, builds the cart in its workshop and delivers it ready to use.","altVi":"Xe nước mía khung gỗ mái tôn, máy ép inox, đặt bên bờ kè","altEn":"Timber sugarcane juice cart with a white roof and stainless press by a river","source":"/assets/content/projects/advertising/mobile-retail/xe-nuoc-mia-khung-go.webp","sha256":"bb7ec390f77600a08686105f26a61355d37257622ab8f1b09b848c8abb557190","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:mobile-retail-22-1; original SHA256 38c0a74a55cb71c34a37ef2f8b4e14b12219bf837ed8e8ca3a308a4effa0f3b2; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "mobile-retail-23": {"descriptionVi":"Xe đẩy kem xôi kiểu cổ điển hợp với tiệc cưới ngoài trời, tiệc sân vườn, nhà hàng tiệc muốn có quầy tráng miệng riêng, vừa phục vụ món vừa làm góc chụp ảnh cho khách.\n\n• Khung xe: thép hộp sơn tĩnh điện đen mờ, mặt quầy và cánh bàn gỗ sồi hoặc gỗ cao su\n• Bánh xe: bánh căm lớn phía trước, bánh xoay có khóa phía sau, đẩy được trên sân cỏ\n• Kích thước thường làm: dài 1,4-1,8 m, rộng 0,6-0,7 m\n• Lưu ý: đơn vị tổ chức tiệc nên chọn bảng tên treo móc, thay được theo món và theo từng tiệc\n\nTrường Thịnh thiết kế, đóng xe tại xưởng và giao tận nơi trọn gói.","descriptionEn":"A vintage-style sticky rice ice cream cart suits outdoor weddings, garden parties and banquet venues that want their own dessert station, serving guests and doubling as a photo spot.\n\n• Frame: matt black powder-coated steel, counter and side leaves in oak or rubberwood\n• Wheels: large spoked wheels at the front, lockable swivel casters at the back, fine on lawns\n• Typical size: 1.4-1.8 m long, 0.6-0.7 m deep\n• Tip: caterers should go for a hook-on name board that changes with the menu and each event\n\nTrường Thịnh designs, builds the cart in its workshop and delivers it ready to use.","altVi":"Xe đẩy kem xôi bánh căm lớn, mái bạt đen, tiệc cưới sân vườn","altEn":"Black sticky rice ice cream cart with spoked wheels at a garden wedding","source":"/assets/content/projects/advertising/mobile-retail/xe-day-kem-xoi-tiec-cuoi.webp","sha256":"6540ef003c270b016c47e0fc0a67cf4932f2163f6e0082285fbf17bcb7498831","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:mobile-retail-23-1; original SHA256 0d92f866e54606452c402b27cb626690db7776b727a4b2ac795046d245fba64e; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "mobile-retail-24": {"descriptionVi":"Xe bán trà lưu động khung sắt hợp với tiệm trà sen, trà thảo mộc bán mang đi ở cổng trường, phố cổ, vỉa hè rộng, cần xe nhẹ để một người đẩy ra vào mỗi ngày.\n\n• Khung xe: sắt hộp sơn tĩnh điện, mái tôn phẳng, bánh xe xoay có khóa\n• Mặt quầy: gỗ cao su phủ dầu chịu nước, cánh gập hai bên\n• Kích thước thường làm: dài 1,2-1,5 m\n• Lưu ý: xe để ngoài trời qua đêm nên chọn sơn tĩnh điện ngoài trời và ốc vít inox để chân xe không gỉ\n\nTrường Thịnh thiết kế, đóng xe tại xưởng và giao tận nơi trọn gói.","descriptionEn":"A steel-framed mobile tea cart suits lotus and herbal tea sellers trading takeaway outside schools, in old quarters or on wide pavements, and is light enough for one person to wheel out every day.\n\n• Frame: powder-coated steel box section, flat steel roof, lockable swivel casters\n• Counter: oiled rubberwood that handles spills, fold-down leaves on both sides\n• Typical size: 1.2-1.5 m long\n• Tip: if the cart stays outdoors overnight, specify exterior-grade powder coat and stainless fixings so it doesn't rust\n\nTrường Thịnh designs, builds the cart in its workshop and delivers it to your door.","altVi":"Xe bán trà lưu động khung sắt đen mái trắng trước cổng trường","altEn":"Black steel tea cart with a white roof outside a school gate","source":"/assets/content/projects/advertising/mobile-retail/xe-ban-tra-luu-dong.webp","sha256":"5eb0e9b3cf23c418ec8641e2fe8112259c4e1825015599dde440a28ee4f1b0db","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 c03398b387cd1a8d87b16709c0868fe06abd76ad9e1259943e23495fd1482c28."},
  "mobile-retail-25": {"descriptionVi":"Ki-ốt trà chanh ngoài trời hợp với quán trà chanh, đồ uống mang đi ở bờ sông, phố đi bộ, khu vui chơi, cần một quầy có mái, có cửa khóa, đứng cố định nhiều tháng mà vẫn dời được bằng xe cẩu.\n\n• Khung: thép hộp mạ kẽm, ốp tôn sóng sơn tĩnh điện, viền gỗ ngoài trời\n• Chữ nổi: mica hoặc inox, LED 12V chống nước, gắn trên nóc ki-ốt\n• Kích thước thường làm: rộng 2,0-2,4 m, sâu 1,2-1,5 m, cao 2,4-2,6 m\n• Lưu ý: tôn sóng hấp nhiệt, nên lót tấm cách nhiệt bên trong và chừa ô thoáng khí sau quầy\n\nTrường Thịnh thiết kế, đóng ki-ốt tại xưởng và lắp đặt trọn gói.","descriptionEn":"An outdoor lemon tea kiosk suits tea and takeaway drink stalls on riverbanks, walking streets and leisure areas that need a roofed, lockable unit standing for months yet movable by crane truck.\n\n• Frame: galvanised steel box section, powder-coated corrugated sheet cladding, exterior timber trim\n• Letters: acrylic or stainless raised letters with waterproof 12V LEDs, mounted on the roof\n• Typical size: 2.0-2.4 m wide, 1.2-1.5 m deep, 2.4-2.6 m tall\n• Tip: corrugated sheet traps heat, so line the inside with insulation and leave a vent behind the counter\n\nTrường Thịnh designs, builds the kiosk in its workshop and installs it on site.","altVi":"Ki-ốt trà chanh ốp tôn trắng, chữ nổi đèn trên nóc, chụp buổi tối","altEn":"White corrugated lemon tea kiosk with lit raised letters on the roof at dusk","source":"/assets/content/projects/advertising/mobile-retail/kiot-tra-chanh-op-ton.webp","sha256":"06608206d7e6802dcb42bd8ef7ec0d866797c10824f4900d01dee69edb98618b","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 df208bc7322a4aedf278c7d20a15694df7f11a77033c4a5c2dc12fb66a3ce3c5."},
  "mobile-retail-26": {"descriptionVi":"Xe bán trà đào lưu động có biển LED neon hợp với quán trà, nước ép bán buổi tối ở bờ sông, phố đi bộ, chợ đêm, nơi khách hay dừng chụp ảnh trước khi gọi món.\n\n• Khung xe: thép hộp sơn tĩnh điện, thân alu hoặc PVC dán decal, mặt gỗ phủ PU\n• Biển neon: LED neon silicon uốn chữ, gắn lên khung lưới sắt, tháo rời khi chở xe\n• Kích thước thường làm: dài 1,4-1,6 m, rộng 0,6 m, cao tổng 2,2-2,4 m\n• Lưu ý: neon silicon chịu mưa tốt hơn neon thủy tinh, bộ nguồn 12V nên đặt kín trong thân xe\n\nTrường Thịnh thiết kế, đóng xe tại xưởng và giao tận nơi trọn gói.","descriptionEn":"A mobile peach tea cart with an LED neon sign suits tea and juice stalls trading in the evening on riverbanks, walking streets and night markets, where people stop for a photo before they order.\n\n• Frame: powder-coated steel box section, aluminium composite or PVC body with vinyl, PU-finished timber top\n• Neon sign: bent silicone LED neon on a steel mesh frame, removable for transport\n• Typical size: 1.4-1.6 m long, 0.6 m deep, 2.2-2.4 m tall overall\n• Tip: silicone neon handles rain far better than glass neon, and the 12V supply belongs sealed inside the body\n\nTrường Thịnh designs, builds the cart in its workshop and delivers it ready to use.","altVi":"Xe bán trà đào khung thép đen, biển LED neon trên lưới, ven sông","altEn":"Peach tea cart with LED neon lettering on a black mesh frame","source":"/assets/content/projects/advertising/mobile-retail/xe-ban-tra-dao-bien-neon.webp","sha256":"0cc75e8137414966b6990c019306130f22c04f595d556d2bdca06801dde7ea8b","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:mobile-retail-c6; original SHA256 fec2ad4f78a61e9885b245ef547ed9b4ae393d9f56824e15c9a9fe953757b892; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "mobile-retail-21": {"descriptionVi":"Quầy nước dừa di động dạng tủ hợp với thương hiệu nước dừa, nông sản, đồ uống bán ở chợ phiên, phố đi bộ, sự kiện ngoài trời, cần mặt bày rộng và chỗ cất hàng khóa lại được qua đêm.\n\n• Thân tủ: tôn sơn tĩnh điện, cửa bản lề có khóa, mặt gỗ cao su ghép phủ PU\n• Bánh xe: bánh cao su đặc có phanh, đi được trên sân lát đá\n• Kích thước thường làm: dài 1,4-1,8 m, rộng 0,6-0,7 m, cao quầy 0,9 m\n• Lưu ý: nên thêm khung biển tên hoặc dán decal mặt tủ, tủ trơn đứng giữa chợ khó gắn với thương hiệu\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và giao tận nơi trọn gói.","descriptionEn":"A cabinet-style mobile coconut water counter suits coconut water, farm produce and drink brands at weekend markets, walking streets and outdoor events that need a wide display top and lockable storage overnight.\n\n• Cabinet: powder-coated steel sheet, lockable hinged doors, PU-finished finger-jointed rubberwood top\n• Wheels: solid rubber casters with brakes that handle paved squares\n• Typical size: 1.4-1.8 m long, 0.6-0.7 m deep, 0.9 m counter height\n• Tip: add a name board or a vinyl wrap, because a plain cabinet in a busy market says nothing about the brand\n\nTrường Thịnh designs, builds the counter in its workshop and delivers it ready to use.","altVi":"Quầy nước dừa di động tủ thép trắng, mặt gỗ, đặt ở chợ phiên","altEn":"White steel coconut water counter on casters with a timber top at a market","source":"/assets/content/projects/advertising/mobile-retail/quay-nuoc-dua-di-dong.webp","sha256":"d418b4db4ce0d3f88e0781e186abd1c8c9c9114ca3df02134d6138f1332f2854","provenance":"AI-generated illustration; owner approved 2026-09-24; original SHA256 aaa5b58ce7c4d1d257b557250ec61c26d326047914010feda5c304185c09c6bf; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "print-decals-21": {"descriptionVi":"Decal mờ dán kính hợp với phòng họp, phòng giám đốc, phòng khám có vách kính, che bớt tầm nhìn từ hành lang mà phòng vẫn đủ sáng.\n\n• Chất liệu: decal mờ (decal sand) cắt chữ, hoặc in màu họa tiết lên decal mờ\n• Quy cách: dải ngang cao 30-60 cm, che vùng ngang tầm mắt người ngồi và đứng\n• Gia công: cắt chữ bằng máy, dán ướt trên kính sạch để không còn bọt\n• Lưu ý: decal mờ bóc ra không để lại keo, đổi tên phòng hay họa tiết chỉ mất vài giờ\n\nTrường Thịnh thiết kế, cắt decal và dán tận nơi trọn gói.","descriptionEn":"Frosted window film suits meeting rooms, directors' offices and clinics with glass partitions, cutting the view from the corridor while keeping the room bright.\n\n• Material: frosted vinyl with cut lettering, or colour motifs printed onto frosted film\n• Format: a 30-60 cm band covering eye level for both seated and standing people\n• Finishing: machine-cut lettering, applied wet on clean glass so no bubbles remain\n• Tip: frosted film peels off without residue, so renaming a room or changing the motif takes only hours\n\nTrường Thịnh designs, cuts and applies the film on site.","altVi":"Decal mờ chữ PHÒNG HỌP và họa tiết lá trên vách kính văn phòng","altEn":"Frosted PHÒNG HỌP decal with leaf motifs on an office glass partition","source":"/assets/content/projects/advertising/print-decals/print-decals-21-owner-20260924.webp","sha256":"de9fad1d893ffaf62567f79a1d096c00b3a0caf397545d3e3dd5f81c009f4041","provenance":"AI-generated illustration; owner approved 2026-09-24; original SHA256 f68bceaa3940ae9723950d49cf0387f3d52849adab01a64eeda8f15316c5b84a; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-31": {"descriptionVi":"Bảng bản đồ khu du lịch sinh thái làm khung gỗ mái lá hợp với khu vườn, homestay, điểm du lịch miệt vườn muốn biển chỉ dẫn hòa vào cảnh quan sông nước.\n\n• Kết cấu: cột gỗ dầu hoặc căm xe, mái lá dừa nước hoặc lá giả nhựa bền hơn\n• Mặt bảng: alu in UV cán màng chống tia cực tím, bản đồ vẽ minh họa theo lối đi thực tế\n• Kích thước thường làm: mặt bảng 1,2x0,8 m đến 2x1,2 m\n• Lưu ý: chân cột gỗ nên bọc bê tông hoặc ống thép, đất ven sông ẩm làm gỗ mục sau vài mùa mưa\n\nTrường Thịnh vẽ bản đồ, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A timber map board with a thatched roof suits eco-tourism gardens, homestays and orchard attractions that want their wayfinding to blend into a riverside landscape.\n\n• Structure: dipterocarp or other hardwood posts, nipa palm thatch or longer-lasting synthetic thatch\n• Face: UV-resistant laminated print on aluminium composite, with an illustrated map drawn from the real paths\n• Typical size: face 1.2x0.8 m to 2x1.2 m\n• Tip: sleeve the post feet in concrete or steel, because damp riverside soil rots timber within a few rainy seasons\n\nTrường Thịnh draws the map, builds the board in its workshop and installs it.","altVi":"Bảng bản đồ khu du lịch sinh thái mái lá khung gỗ","altEn":"Timber eco-park map board with a thatched roof beside a brick path","source":"/assets/content/projects/advertising/office-signs-wayfinding/bang-ban-do-khu-du-lich.webp","sha256":"b9e3b1ec3517dc24d57ba7b4048bba5ee8089f8df8c17c0ae9a690c24524687c","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adf826e-ad58-83ec-a342-7d8fda687896, card #873); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-26 18:24Z; master PNG SHA256 c38ba183fe9f61cf394b30ef8d59a5591e49714cefc1c4c13afd1e8c8c7170a3."},
  "office-signs-wayfinding-30": {"descriptionVi":"Biển tên đường hợp với khu công nghiệp, khu đô thị, khu dân cư mới khi bàn giao hạ tầng, giúp xe tải, xe cứu thương và bưu tá tìm đúng tuyến.\n\n• Mặt biển: alu 2-3 mm dán decal phản quang, nền xanh chữ trắng theo kiểu biển chỉ dẫn đường bộ\n• Cột: thép ống mạ kẽm nhúng nóng, đế bích bắt bu lông neo\n• Kích thước thường làm: mặt biển 50x30 cm đến 80x40 cm, cột cao 2,5-3 m\n• Lưu ý: hỏi rõ loại decal phản quang, loại kỹ thuật cao bền ngoài nắng hơn hẳn loại thường\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"Street name signs suit industrial estates, townships and new residential areas at infrastructure handover, helping trucks, ambulances and postal workers find the right road.\n\n• Face: 2-3 mm aluminium with reflective vinyl, white on blue in road-sign style\n• Pole: hot-dip galvanised steel tube, flanged base on anchor bolts\n• Typical size: face 50x30 cm to 80x40 cm, pole 2.5-3 m tall\n• Tip: ask which reflective grade is quoted, as high-intensity sheeting lasts far longer in the sun than the standard grade\n\nTrường Thịnh designs, makes the signs in its workshop and installs them.","altVi":"Biển tên đường nền xanh chữ trắng trên cột thép mạ kẽm","altEn":"Blue street name sign on a galvanised steel pole in an industrial estate","source":"/assets/content/projects/advertising/office-signs-wayfinding/bien-ten-duong-khu-cong-nghiep.webp","sha256":"39665f0c2baba7cf323e064a52a47875ed7331b68ace2b65f251e902073b6f1c","provenance":"AI-generated illustration; owner approved 2026-09-24; original SHA256 c2aff88e9b41268d56e8fc8ee2d08577570557af0c924b7fe0029eac1629652d; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-37": {"descriptionVi":"Standee chữ X là cách quảng cáo gọn nhất cho quầy đồ uống, gian hội chợ, chợ phiên cuối tuần: dựng trong một phút, gấp vào túi mang theo xe máy được.\n\n• Chất liệu: chân thép sơn tĩnh điện, bạt hiflex hoặc PP in UV\n• Kích thước thường làm: 60x160 cm hoặc 80x180 cm\n• Độ bền: bạt in UV ngoài trời giữ màu được vài tháng nắng, hỏng bạt chỉ cần in tấm mới\n• Lưu ý: chân X nhẹ nên dễ đổ khi gió mạnh, đặt ngoài trời nên chèn bao cát hoặc dựa vào vật cố định\n\nTrường Thịnh thiết kế, in và giao tận nơi trọn gói.","descriptionEn":"An X-banner stand is the most compact way to advertise a drinks stall, fair booth or weekend market pitch: it goes up in a minute and folds into a bag that fits on a motorbike.\n\n• Material: powder-coated steel legs, hiflex or PP banner with UV print\n• Typical size: 60x160 cm or 80x180 cm\n• Durability: a UV-printed banner holds its colour for a few months outdoors, and a worn one only needs a new print\n• Tip: the X frame is light and tips over in strong wind, so weigh it with sandbags or lean it against something fixed outdoors\n\nTrường Thịnh designs, prints and delivers to your door.","altVi":"Standee chữ X in hình trái dừa đặt trên lối đi chợ phiên","altEn":"X-banner stand printed with coconuts on a market walkway","source":"/assets/content/projects/advertising/kiosk-posm/standee-chu-x-nuoc-dua.webp","sha256":"b38041557622d29d87cb67316b99cb26aec365f4792d2e0f4630ac547bcaf169","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile, edited by owner; owner approved to site 2026-10-27; master PNG SHA256 38e6120d02791c54f37cd0067d37209bfac51878ea0352001c587dc3104387ab."},
  "kiosk-posm-36": {"descriptionVi":"Standee cửa hàng thời trang khung ống chân chữ H hợp với shop váy, váy cưới, cửa hàng trong trung tâm thương mại cần giới thiệu bộ sưu tập mới ngay lối đi chung.\n\n• Khung: ống thép sơn tĩnh điện trắng, chân chữ H vững trên sàn đá bóng\n• Mặt in: bạt hoặc vải in UV, luồn ống trên dưới, thay mẫu trong vài phút\n• Kích thước thường làm: 80x180 cm đến 100x200 cm\n• Lưu ý: nhiều trung tâm thương mại chỉ cho đặt standee trong ranh ô thuê, nên hỏi ban quản lý trước khi in\n\nTrường Thịnh thiết kế, in và giao standee tận nơi trọn gói.","descriptionEn":"A fashion shop standee on an H-base tube frame suits dress and bridal boutiques and mall stores introducing a new collection on the shared walkway.\n\n• Frame: white powder-coated steel tube with H-feet, stable on polished stone floors\n• Print: UV-printed banner or fabric with top and bottom pole pockets, swapped in minutes\n• Typical size: 80x180 cm to 100x200 cm\n• Tip: many malls only allow standees inside the leased line, so check with management before printing\n\nTrường Thịnh designs, prints and delivers the standee.","altVi":"Standee bạt khung trắng in hình cô gái mặc váy trước cửa hàng","altEn":"White-frame fabric standee illustrated with a woman in a dress outside a boutique","source":"/assets/content/projects/advertising/kiosk-posm/standee-cua-hang-thoi-trang.webp","sha256":"7a646ff46ca20164472705c6d1a19b4ec0c1a170a817c4868388ca3198eac089","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd461-3fac-83ec-8784-a4ded59b03ca); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-27 01:07Z; master PNG SHA256 6a2dae3033da006aae4e7503e15126bbd1155e40ee3b6de3b57f3302be0e30e4."},
  "kiosk-posm-35": {"descriptionVi":"Standee bạt khung ống hợp với shop thời trang, cửa hàng phụ kiện cần báo bộ sưu tập mới, mùa giảm giá với chi phí thấp và cất gọn sau chiến dịch.\n\n• Khung: ống thép hoặc nhôm sơn trắng, chân chữ T tháo rời\n• Mặt in: bạt hiflex hoặc vải canvas in UV, may viền luồn ống\n• Kích thước thường làm: 80x180 cm hoặc 100x200 cm\n• Lưu ý: chọn vải canvas thay bạt nếu muốn mặt in mờ, không bóng loáng dưới đèn rọi cửa hàng\n\nTrường Thịnh thiết kế, in và giao standee tận nơi trọn gói.","descriptionEn":"A banner standee on a tube frame suits fashion and accessory shops announcing a new collection or sale on a small budget, and packs away after the campaign.\n\n• Frame: white-painted steel or aluminium tube on detachable T-feet\n• Print: hiflex banner or UV-printed canvas, hemmed with pole pockets\n• Typical size: 80x180 cm or 100x200 cm\n• Tip: pick canvas over banner for a matt print that doesn't glare under shop spotlights\n\nTrường Thịnh designs, prints and delivers the standee.","altVi":"Standee bạt khung ống trắng chân chữ T trong shop thời trang","altEn":"White tube-frame fabric standee on T-feet inside a fashion boutique","source":"/assets/content/projects/advertising/kiosk-posm/standee-bat-shop-thoi-trang.webp","sha256":"4c0a4ceb22cf4dddaf268e84e1c83c575905a6a7ade62db4d25084e7f2669c4e","provenance":"AI-generated illustration; owner approved 2026-09-24; original SHA256 6702c522fd825b58be45ea1eecb094ff2237107b96b1b77089738d63b24f3aed; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-34": {"descriptionVi":"Standee chân sắt khung đen hợp với quán trà trái cây, nhà hàng, cửa hàng có hiên rộng, bền và đứng vững hơn hẳn standee nhựa chữ X khi để ngoài cửa cả ngày.\n\n• Khung: sắt hộp 20x20 hoặc 25x25 mm sơn tĩnh điện, đế khung chữ nhật\n• Mặt: lồng poster hoặc bạt in, có nẹp mở để thay nội dung\n• Kích thước thường làm: 60x160 cm, 80x180 cm, một hoặc hai mặt\n• Lưu ý: chân đế nên bọc nút cao su để không trầy sàn gạch và không trượt khi trời mưa\n\nTrường Thịnh thiết kế, in và gia công standee tại xưởng, giao tận nơi.","descriptionEn":"A black steel-base standee suits fruit tea shops, restaurants and stores with a wide porch, lasting far longer and standing steadier than a plastic X-banner left out all day.\n\n• Frame: 20x20 or 25x25 mm powder-coated steel box section on a rectangular base\n• Face: slide-in poster or printed banner behind an opening trim\n• Typical size: 60x160 cm or 80x180 cm, single or double-sided\n• Tip: fit rubber feet so the base doesn't scratch tiles or slide in the rain\n\nTrường Thịnh designs, prints, makes the frame in its workshop and delivers it.","altVi":"Standee chân sắt khung đen, poster trà trái cây trước hiên quán","altEn":"Black steel-base standee with a fruit tea poster on a café porch","source":"/assets/content/projects/advertising/kiosk-posm/standee-chan-sat-khung-den.webp","sha256":"a888e334fc87438bffe309e09d1521adfa4581612e4c46423b7abdbea00c15ec","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 46be69d3976e5d1341bc0c174365f7d7ad73d33d3da3f66202bbb1958825c30f."},
  "kiosk-posm-33": {"descriptionVi":"Standee chân nước khung ống bo tròn hợp với quán trà sữa, cà phê đặt trước cửa hoặc vỉa hè, nơi có gió mà vẫn cần đổi poster món mới hằng tháng.\n\n• Khung: ống thép sơn tĩnh điện, hai mặt kẹp poster bằng ngàm\n• Đế: nhựa HDPE rỗng đổ nước hoặc cát, có bánh xe để kéo ra vào\n• Kích thước thường làm: poster 60x160 cm hoặc 80x180 cm\n• Lưu ý: poster ngoài trời nên in PP hoặc bạt hiflex cán màng, giấy thường phai sau vài tuần nắng\n\nTrường Thịnh thiết kế poster, in và giao standee tận nơi.","descriptionEn":"A water-base standee with a rounded tube frame suits milk tea shops and cafés placing it at the door or on the pavement, where there is wind but posters still change monthly.\n\n• Frame: powder-coated steel tube, posters clipped in on both sides\n• Base: hollow HDPE filled with water or sand, with wheels for moving it in and out\n• Typical size: 60x160 cm or 80x180 cm posters\n• Tip: outdoor posters should be PP or laminated hiflex banner, since paper fades within weeks of sun\n\nTrường Thịnh designs the poster, prints it and delivers the standee.","altVi":"Standee khung ống trắng bo tròn, đế nhựa đổ nước, poster trà sữa","altEn":"Round-cornered white tube standee on a water-filled base with a milk tea poster","source":"/assets/content/projects/advertising/kiosk-posm/standee-chan-nuoc-tra-sua.webp","sha256":"a4d6bb1e22cfe2295ee164c542eb4644b0ed5e4dcf498d52f7ae793799bf3858","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 6e3f8e0c7e7246044ae2b02123a5446366efc5dbe36a31b592814e7f22a3d423."},
  "signage-raised-letters-26": {"descriptionVi":"Chữ nổi Formex đặt đứng hợp với studio ảnh, showroom, quầy lễ tân muốn bảng tên dời chỗ được hoặc đặt trên kệ, không phải khoan tường.\n\n• Chất liệu: Formex (PVC foam) dày 1-3 cm, cắt CNC\n• Hoàn thiện: chà mịn cạnh, sơn trắng mờ hoặc dán mica màu lên mặt chữ\n• Kích thước thường làm: chữ cao 15-40 cm\n• Lưu ý: Formex nhẹ và rẻ nhưng chỉ hợp trong nhà; ra ngoài trời nên chuyển sang alu hoặc inox\n\nTrường Thịnh thiết kế, cắt CNC tại xưởng và giao lắp trọn gói.","descriptionEn":"Freestanding Formex letters suit photo studios, showrooms and reception desks that want a name sign they can move or set on a shelf, with no drilling.\n\n• Material: 1-3 cm Formex (PVC foam), CNC cut\n• Finish: sanded edges, matt white paint or coloured acrylic faces\n• Typical size: letters 15-40 cm tall\n• Tip: Formex is light and inexpensive but for indoor use only; outdoors, switch to aluminium or stainless\n\nTrường Thịnh designs, CNC cuts in its workshop and delivers and sets up the letters.","altVi":"Chữ nổi Formex trắng đứng trên bệ bê tông cạnh chậu cây","altEn":"White Formex raised letters standing on a concrete ledge beside a plant","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-26-owner-20260924.webp","sha256":"6f34ac8241b1538d58b1bdf790751366076934b823383ad0363287b9c3034e0d","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 b749d1b56cebccf56b53b4074b1edab320a8d04e4029c80dd054e228e2c5d1f3."},
  "signage-raised-letters-25": {"descriptionVi":"Chữ nổi mica sáng mặt hợp với quán cà phê, tiệm trà, nhà hàng nhỏ có tường mặt tiền phẳng, gắn thẳng lên tường mà không cần bảng nền.\n\n• Chất liệu: mặt mica màu xuyên sáng 3 mm, viền alu chấn hoặc mica cao 5-8 cm\n• Đèn: LED module 12V, nguồn đặt trong nhà để dễ thay\n• Lắp đặt: chân ty inox giữ chữ cách tường 1-2 cm, nước mưa thoát được và dễ lau\n• Lưu ý: với nhà phố mặt tiền 4-6 m, chữ cao 40-60 cm là vừa, làm to hơn dễ chật tường\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"Face-lit acrylic letters suit cafés, tea shops and small restaurants with a flat front wall, fixed straight on without a backing panel.\n\n• Material: 3 mm translucent coloured acrylic faces, folded aluminium or acrylic returns 5-8 cm deep\n• Lighting: 12V LED modules, power supply kept indoors for easy replacement\n• Installation: stainless stand-offs hold the letters 1-2 cm off the wall so rain drains and cleaning is easy\n• Tip: on a 4-6 m shophouse frontage, letters 40-60 cm tall are right; bigger ones crowd the wall\n\nTrường Thịnh designs, builds in its own workshop and installs the sign.","altVi":"Chữ nổi mica vàng sáng mặt gắn chân ty trên tường trắng quán","altEn":"Yellow face-lit acrylic letters on stand-offs above a café entrance","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-25-owner-20260924-audit-a261-v1.webp","sha256":"653fc0cdedbcee613875ef995f364063ad5df9296be676ca0c08b166092fe9a6","provenance":"AI-generated illustration; owner selected A261-v1 in HTML audit and confirmed in chat 2026-10-22; ChatGPT web gpt-image; original SHA256 9ea2e1cd527c7b7e1e4f8099b8b19508270f9d03d8ad0a6da410896bdb770928; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "print-decals-20": {"descriptionVi":"Tem nhãn decal in theo tờ hợp với cơ sở làm nước ép, trà, nông sản đóng gói cần nhãn đẹp cho từng mẻ mà chưa đủ số lượng để in bao bì riêng.\n\n• Chất liệu: decal giấy, decal nhựa trắng sữa hoặc decal trong\n• Quy cách: tròn hoặc vuông bo góc, đường kính hay cạnh 3-8 cm\n• Gia công: in kỹ thuật số rồi bế bằng máy cắt, giao theo tờ để bóc dán tay\n• Lưu ý: in từ vài chục tờ vẫn được, thêm hương vị mới hay đổi mẫu không tốn khuôn\n\nTrường Thịnh thiết kế, in và cắt tem nhãn tại xưởng, giao tận nơi.","descriptionEn":"Sheet-printed decal labels suit juice, tea and packaged farm-produce makers who want good labels for each batch but don't yet sell enough to print custom packaging.\n\n• Material: paper, white plastic or clear vinyl\n• Format: round or rounded square, 3-8 cm across\n• Finishing: digitally printed then plotter-cut, supplied on sheets for hand application\n• Tip: runs of a few dozen sheets are fine, and new flavours or design changes need no cutting die\n\nTrường Thịnh designs, prints and cuts the labels in its own workshop, then delivers them.","altVi":"Máy cắt decal đang chạy tem cam, cạnh tờ tem trà xanh","altEn":"Vinyl cutter running orange labels next to a sheet of green tea stickers","source":"/assets/content/projects/advertising/print-decals/print-decals-20-owner-20260924.webp","sha256":"8102fa0b38a47d2055daf94f0089f5b6f2dbe91c58ac576450c0171584027dbd","provenance":"AI-generated illustration; owner approved 2026-09-24; original SHA256 ae0e791a292804e6c91dc994ed1d96fff625cd1c98587d2928a8a762f282fda6; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-24": {"descriptionVi":"Biển quảng cáo trên mái nhà hợp với vựa trái cây, nhà xe, đại lý ở ngã tư hoặc đường lớn, tận dụng chính mái nhà mình thay cho thuê vị trí billboard.\n\n• Kết cấu: khung thép hộp mạ kẽm bắt vào sàn mái, giằng chéo chống gió bão\n• Mặt biển: bạt 3M hoặc bạt hiflex in dầu căng khung, đèn pha LED rọi từ trên\n• Kích thước thường làm: 3x6 m đến 4x12 m\n• Lưu ý: xử lý chống thấm quanh chân khung sau khi khoan sàn mái, và hỏi quy định chiều cao ở địa phương\n\nTrường Thịnh khảo sát mái, gia công tại xưởng và lắp đặt trọn gói.","descriptionEn":"A rooftop billboard suits fruit wholesalers, coach operators and dealers on junctions or main roads, using their own roof instead of renting a billboard site.\n\n• Structure: galvanised steel box frame bolted to the roof slab, cross-braced against storms\n• Face: 3M or hiflex banner with solvent print on the frame, LED floodlights above\n• Typical size: 3x6 m to 4x12 m\n• Tip: re-waterproof around the frame feet after drilling the slab, and check local height limits\n\nTrường Thịnh surveys the roof, fabricates in its workshop and installs the billboard.","altVi":"Biển quảng cáo bạt in trái cây dựng trên mái tòa nhà trắng","altEn":"Printed fruit billboard on a steel frame atop a white building","source":"/assets/content/projects/advertising/signage-raised-letters/bien-quang-cao-tren-mai-nha.webp","sha256":"9e0e64574995218495f220b21d534ac34379929edb9fa2f267946e1dda94a53a","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 e394f8051362eec75f550fab7fc882e19c7d437817acb8e6e4eeafeec66bd2bd."},
  "mobile-retail-20": {"descriptionVi":"Xe bánh mì inox là loại xe bền nhất cho người bán bánh mì, đồ ăn sáng ở vỉa hè, chợ, khu ẩm thực, vì chịu dầu mỡ, nước rửa và nắng mưa hằng ngày mà không mục.\n\n• Chất liệu: inox 304 cho mặt quầy và khay nhân, khung inox hộp hoặc sắt sơn tĩnh điện\n• Tủ kính: hai tầng, kính cường lực, có đèn giữ ấm bánh\n• Kích thước thường làm: dài 1,4-1,8 m, rộng 0,6-0,7 m\n• Lưu ý: khay nhân nên là khay inox rời theo cỡ tiêu chuẩn, dễ mua thay và tháo ra rửa mỗi tối\n\nTrường Thịnh thiết kế, đóng xe tại xưởng và giao tận nơi trọn gói.","descriptionEn":"A stainless banh mi cart is the most durable choice for banh mi and breakfast sellers on pavements, at markets and in food courts, standing up to grease, washing and daily sun and rain without rotting.\n\n• Material: 304 stainless for the top and filling trays, stainless box or powder-coated steel frame\n• Display: two-tier toughened glass case with a bread-warming lamp\n• Typical size: 1.4-1.8 m long, 0.6-0.7 m deep\n• Tip: use standard-size loose stainless trays, easy to replace and to lift out for washing every night\n\nTrường Thịnh designs, builds the cart in its workshop and delivers it ready to use.","altVi":"Xe bánh mì inox, tủ kính hai tầng, mái bạt sọc vàng trắng","altEn":"Stainless banh mi cart with a two-tier glass case and yellow striped awning","source":"/assets/content/projects/advertising/mobile-retail/xe-banh-mi-inox-mai-bat.webp","sha256":"aae0a07aacb81f50f86faf6f54c12e184691dfe3e421ba65238e0db2a8750375","provenance":"AI-generated illustration; owner approved 2026-09-24; original SHA256 e88f3a2376eb6703308a623915f98105c309d8c57d1233ed3d7bed4fcfa64402; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "mobile-retail-19": {"descriptionVi":"Quầy trà sữa di động khung nhôm hợp với quán trà sữa mở điểm bán ở trung tâm thương mại, hội chợ, sự kiện, cần đủ chỗ cho máy móc pha chế và khay topping trên một mặt quầy.\n\n• Khung: nhôm định hình hoặc sắt hộp sơn tĩnh điện, mặt quầy inox 304\n• Mặt tranh: decal in UV dán alu, hộp đèn LED tên quán trên nóc, mặt bạt hiflex hoặc bạt 3M\n• Kích thước thường làm: dài 1,4-1,8 m, rộng 0,6-0,7 m, cao tổng 2,2-2,4 m\n• Lưu ý: cộng trước công suất nồi ủ, máy dập nắp, tủ mát, vì nhiều sảnh hội chợ chỉ cấp một ổ điện nhỏ\n\nTrường Thịnh thiết kế, đóng quầy tại xưởng và giao tận nơi trọn gói.","descriptionEn":"An aluminium-framed mobile bubble tea counter suits tea shops opening points in malls, fairs and events, with room for the brewing kit and topping trays on a single top.\n\n• Frame: aluminium profile or powder-coated steel, 304 stainless counter top\n• Graphics: UV-printed vinyl on aluminium composite, LED header lightbox with the shop name on translucent or 3M flex\n• Typical size: 1.4-1.8 m long, 0.6-0.7 m deep, 2.2-2.4 m tall overall\n• Tip: add up the load of urns, cup sealer and fridge first, since many fair halls supply only one small socket\n\nTrường Thịnh designs, builds the counter in its workshop and delivers it ready to use.","altVi":"Quầy trà sữa di động khung đen, mặt inox, hộp đèn tên trên nóc","altEn":"Mobile bubble tea counter with a black frame, stainless top and header lightbox","source":"/assets/content/projects/advertising/mobile-retail/quay-tra-sua-di-dong.webp","sha256":"8e7ad357214551549b869dc2d22d8a10841f9f6afeced101887e2552509e3d97","provenance":"AI-generated illustration; owner approved 2026-09-24; original SHA256 8390376e92834f068e85ef01876132fffea3a46e6ba62200e64cbb7b7017094a; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "mobile-retail-18": {"descriptionVi":"Xe bán kem inox có tủ đông hợp với thương hiệu kem, quán tráng miệng bán ở khu vui chơi, chợ đêm, sự kiện, nơi kem phải giữ lạnh nhiều giờ liền xa cửa hàng.\n\n• Chất liệu: inox 304 cho khung và mặt quầy, thân dán decal in UV cán màng\n• Tủ đông: loại nằm ngang lắp âm thân xe, khay múc kem có nắp\n• Kích thước thường làm: dài 1,6-2,0 m, rộng 0,7-0,8 m\n• Lưu ý: tủ đông cần điện ổn định suốt ca bán; điểm bán xa ổ cắm nên tính trước máy phát hoặc bộ lưu điện\n\nTrường Thịnh thiết kế, đóng xe tại xưởng và giao tận nơi trọn gói.","descriptionEn":"A stainless ice cream cart with a built-in freezer suits ice cream brands and dessert shops at play areas, night markets and events, where stock must stay frozen for hours away from the shop.\n\n• Material: 304 stainless frame and top, body in laminated UV-printed vinyl\n• Freezer: chest type built into the body, with lidded scoop trays\n• Typical size: 1.6-2.0 m long, 0.7-0.8 m deep\n• Tip: the freezer needs steady power for the whole shift, so plan a generator or backup unit for pitches far from a socket\n\nTrường Thịnh designs, builds the cart in its workshop and delivers it ready to use.","altVi":"Xe bán kem inox mái bạt sọc hồng, tủ đông, tủ kính ốc quế","altEn":"Stainless ice cream cart with a pink striped awning, freezer and cone case","source":"/assets/content/projects/advertising/mobile-retail/xe-ban-kem-inox-mai-bat.webp","sha256":"68c69fee07f022c4990e515ec6493d6e046bb2f6c6c722b421ef36bac2982c83","provenance":"AI-generated illustration; owner approved 2026-09-24; original SHA256 7338594e3a32b58e0c06984456cb6e1310d85f56d45dbcfb7a9e18612c6d5e53; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-29": {"descriptionVi":"Bảng bản đồ phân lô dùng ở cổng khu công nghiệp, dự án đất nền, khu dân cư mới, giúp nhà đầu tư và khách xem đất nắm vị trí từng lô ngay tại hiện trường.\n\n• Kết cấu: khung sắt hộp mạ kẽm, hai trụ thép trên móng bê tông, mặt alu hoặc tôn\n• In: bạt hoặc decal in UV cán màng chống tia cực tím, mỗi nhóm lô một màu\n• Kích thước thường làm: 3x2 m đến 5x3 m\n• Lưu ý: tình trạng lô thay đổi liên tục, nên in mặt bạt căng khung để cập nhật nhanh và rẻ\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A plot map board stands at the gate of industrial parks, land subdivisions and new residential projects, letting investors and buyers see where each plot sits while on site.\n\n• Structure: galvanised steel box frame, two steel posts on concrete footings, aluminium composite or steel face\n• Print: UV-resistant laminated banner or vinyl, one colour per plot group\n• Typical size: 3x2 m to 5x3 m\n• Tip: plot status changes constantly, so a stretched banner face is the quickest and cheapest to update\n\nTrường Thịnh designs, builds the board in its workshop and installs it.","altVi":"Bảng bản đồ phân lô in màu trên hai trụ thép cổng dự án","altEn":"Colour-printed plot map billboard on two steel posts at a project gate","source":"/assets/content/projects/advertising/office-signs-wayfinding/bang-ban-do-phan-lo.webp","sha256":"2ebf6bf51e33eeefedfc6e86d9e06da5b13e160c8bee368eb1f6fb056448f1b6","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:office-signs-wayfinding-29-1; original SHA256 2c3b0fc6dedd293ace2228236509592f889e75bc09b382acdd3ccb5b0fd88e7f; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-28": {"descriptionVi":"Biển số nhà phát sáng với chữ nổi đèn LED hợp với biệt thự, nhà phố hiện đại có trụ cổng ốp đá hoặc sơn tối màu, khi chủ nhà muốn biển số kiêm luôn đèn trang trí cổng.\n\n• Cấu tạo: nền alu hoặc inox sơn đen, chữ mica trắng sữa dày 2-3 cm, LED module bên trong\n• Đèn: LED 12V chống nước, nối công tắc cảm biến ánh sáng để tự bật tắt\n• Kích thước thường làm: 40x25 cm đến 60x35 cm\n• Lưu ý: chừa ống luồn dây từ lúc xây hoặc trát trụ, bộ nguồn đặt chỗ khô để dễ thay\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A raised-numeral LED house number suits villas and modern townhouses with stone-clad or dark gate pillars, when the owner wants the number to double as gate lighting.\n\n• Build: black-painted aluminium or stainless backplate, 2-3 cm deep opal acrylic numerals with LED modules inside\n• Lighting: waterproof 12V LEDs wired to a photocell so they switch on and off by themselves\n• Typical size: 40x25 cm to 60x35 cm\n• Tip: leave a cable conduit when building or rendering the pillar, and put the power supply somewhere dry for easy replacement\n\nTrường Thịnh designs, makes the plate in its workshop and installs it.","altVi":"Biển số nhà nền đen chữ nổi đèn LED hắt sáng trên trụ đá","altEn":"Black house number plate with halo-lit raised numerals on a stone pillar","source":"/assets/content/projects/advertising/office-signs-wayfinding/bien-so-nha-phat-sang.webp","sha256":"5a62420c95009d643e30c2e38d110678a9e4ca7a152ca1baa7fde1d70cea2885","provenance":"AI-generated illustration; owner approved 2026-09-24; original SHA256 35596237a12705f0edb66a8ed5bb78da5c85f656f31cab5710b41f87eb688b3c; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "mobile-retail-17": {"descriptionVi":"Quầy bán hàng gấp gọn khung nhôm hợp với thương hiệu mỹ phẩm, đồ uống đi hội chợ, sự kiện, roadshow nhiều điểm, cần dựng quầy trong vài phút mà không phải thuê xe tải chở.\n\n• Khung: nhôm xếp kiểu cắt kéo, mặt bàn nhựa hoặc MDF tháo rời\n• Bạt in: vải căng in chuyển nhiệt, bọc khít khung, giặt được và thay theo chiến dịch\n• Kích thước thường làm: mặt 1,6-1,8 m x 0,5 m, cao 0,9-1,0 m, kèm khung banner tên\n• Lưu ý: vải in chuyển nhiệt ít nhăn và ít nứt mực hơn bạt hiflex khi gấp đi gấp lại nhiều lần\n\nTrường Thịnh thiết kế, in bạt, gia công khung và giao tận nơi trọn gói.","descriptionEn":"A folding aluminium promo counter suits cosmetics and drink brands doing fairs, events and multi-stop roadshows, where the counter has to go up in minutes without hiring a truck.\n\n• Frame: scissor-fold aluminium with a removable plastic or MDF top\n• Graphic: stretch fabric with dye-sublimation print, a snug fit, washable and swapped per campaign\n• Typical size: 1.6-1.8 m x 0.5 m top, 0.9-1.0 m high, with a header banner frame\n• Tip: sublimated fabric creases and cracks far less than PVC banner when folded again and again\n\nTrường Thịnh designs, prints the fabric, builds the frame and delivers the counter ready to use.","altVi":"Quầy gấp khung nhôm bọc bạt in, bên cạnh khung xếp và túi đựng","altEn":"Folding aluminium promo counter with printed fabric, beside its folded frame and carry bag","source":"/assets/content/projects/advertising/mobile-retail/quay-ban-hang-gap-gon.webp","sha256":"3eb6c5222ee9b669b5fc7618e657c738c5f0d393b6be4461212099cb95abd44f","provenance":"AI-generated illustration; ChatGPT web image edit with owner mask (chat 6ae5c7a4-9430-83ec-b818-abc5d473266f); upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-27; master PNG SHA256 4de4dd6e1d6ce7dded777aef1daa7ab7f13d4a5c04a0905735d09fef75191144."},
  "print-decals-19": {"descriptionVi":"In ly giấy, ly nhựa cùng túi và hộp kraft hợp với quán cà phê kiêm bán mứt, đặc sản, cần cả bộ đồ đựng mang đi chung nét vẽ nhưng tách màu từng dòng sản phẩm.\n\n• Ly giấy: giấy tráng PE, in offset, dung tích 8-16 oz\n• Ly nhựa: PET trong in quanh thân, 360-700 ml\n• Hộp và túi: kraft in 2-4 màu, hộp nắp gài đựng mứt và bánh\n• Lưu ý: giữ chung một nét vẽ, đổi màu theo dòng sản phẩm để nhân viên lấy đúng ly, đúng hộp\n\nTrường Thịnh thiết kế bộ bao bì, in và giao tận nơi.","descriptionEn":"Printed paper and plastic cups with kraft bags and boxes suit cafés that also sell jams and local specialties, needing a full takeaway set in one illustration style with a colour per product line.\n\n• Paper cups: PE-lined board, offset printed, 8-16 oz\n• Plastic cups: clear PET printed around the body, 360-700 ml\n• Boxes and bags: kraft printed in 2-4 colours, tuck-flap boxes for jam and pastries\n• Tip: keep one drawing style and change colour by product line, so staff grab the right cup and box\n\nTrường Thịnh designs the packaging set, prints it and delivers to your door.","altVi":"Ly giấy, ly nhựa, túi kraft và hộp in cà phê, mứt trái cây","altEn":"Printed paper cups, plastic cups, kraft bags and boxes for coffee and fruit jam","source":"/assets/content/projects/advertising/print-decals/in-ly-giay-ly-nhua.webp","sha256":"303f34e783859069731980a4744737366b0a1c3d03470df67f85020a25bee603","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd27c-fe40-83ec-871a-be181f952768); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-27 01:07Z; master PNG SHA256 ab3e45b55f1a7f46c1ce7891b2a12a46da9202b940b2677160ba88edf5c89873."},
  "office-signs-wayfinding-27": {"descriptionVi":"Bảng bản đồ nhà máy đặt ở cổng chính giúp tài xế giao hàng, nhà thầu và khách tham quan tìm đúng xưởng, kho, bãi xe mà không cần bảo vệ dẫn đường.\n\n• Kết cấu: khung sắt hộp sơn tĩnh điện theo màu nhận diện, hai chân thép trên bệ bê tông\n• Mặt bảng: alu ngoài trời in UV cán màng, chịu nắng mưa nhiều năm\n• Kích thước thường làm: 2x1,2 m đến 3x2 m\n• Lưu ý: nên ghi thêm luồng xe tải, điểm tập kết khi có sự cố và số điện thoại bảo vệ\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A factory site map at the main gate helps delivery drivers, contractors and visitors find the right workshop, warehouse or car park without a guard showing them the way.\n\n• Structure: steel box frame powder-coated in brand colours, two steel legs on concrete bases\n• Face: exterior aluminium composite with laminated UV print that stands up to years of sun and rain\n• Typical size: 2x1.2 m to 3x2 m\n• Tip: add truck routes, the emergency assembly point and the gatehouse phone number\n\nTrường Thịnh designs, builds the board in its workshop and installs it.","altVi":"Bảng bản đồ khu nhà máy khung xanh, hai chân thép cạnh cổng","altEn":"Factory site map board in a green frame on steel legs by the gate","source":"/assets/content/projects/advertising/office-signs-wayfinding/bang-ban-do-nha-may.webp","sha256":"9ea52017bbb32337e65b76ef036fbc5a7b2d0fdb5d68b1fdf5839740adf724b0","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:office-signs-wayfinding-27-2; original SHA256 1ffed7c355b6b63dace0ccaddd743056f048fa7fd8539163e3fe0705293830e8; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-23": {"descriptionVi":"Biển chỉ dẫn nhà máy ngoài trời hợp với khu công nghiệp, kho bãi, xưởng chế biến có nhiều khu và xe hàng ra vào liên tục, giúp tài xế tự tìm đúng cổng nhập xuất.\n\n• Mặt biển: alu ngoài trời 3-4 mm, chữ decal phản quang hoặc in UV\n• Kết cấu: viền nhôm định hình, trụ thép mạ kẽm, chân đế bê tông\n• Kích thước thường làm: 60x120 cm đến 100x200 cm\n• Lưu ý: biển ở lối xe nên dùng decal phản quang, ca đêm đèn xe chiếu vào vẫn đọc được\n\nTrường Thịnh khảo sát luồng xe, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"Outdoor factory wayfinding signs suit industrial parks, warehouses and processing plants with several zones and constant truck traffic, so drivers find the right loading bay on their own.\n\n• Face: 3-4 mm exterior aluminium composite, reflective vinyl or UV-printed lettering\n• Structure: extruded aluminium edge, galvanised steel posts, concrete bases\n• Typical size: 60x120 cm to 100x200 cm\n• Tip: use reflective vinyl on signs along vehicle routes so they stay readable in headlights on night shifts\n\nTrường Thịnh maps the traffic flow, makes the signs in its workshop and installs them.","altVi":"Biển chỉ dẫn khu sản xuất mặt alu, hai trụ thép trong nhà máy","altEn":"Aluminium production-area direction sign on two steel posts in a factory yard","source":"/assets/content/projects/advertising/signage-raised-letters/bien-chi-dan-nha-may.webp","sha256":"97df347854168d225b8529215223f0d318a4d4791ebbc6951d7aadf146ff5eb3","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:signage-raised-letters-23-1; original SHA256 3092d67cb620777cf038a545d86ac387b2bc1a745a2330ca814e9ca15401b08c; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "print-decals-18": {"descriptionVi":"In tem decal cắt bế hợp với quán nước, cơ sở đóng chai trà, sữa dừa, nước sâm cần nhãn riêng cho từng loại để dán lên ly, chai và nắp.\n\n• Chất liệu: decal giấy cho hàng khô, decal nhựa PVC hoặc PP chống nước cho chai lạnh\n• In: kỹ thuật số, cán màng bóng hoặc mờ để tem không lem khi đọng nước\n• Gia công: máy cắt bế theo viền, tròn, oval hay theo dáng hình\n• Lưu ý: chai để tủ lạnh nên dùng decal nhựa keo chịu lạnh, decal giấy dễ bong mép\n\nTrường Thịnh thiết kế, in, cắt bế và giao tem theo tờ tận nơi.","descriptionEn":"Die-cut decal printing suits drink shops and small bottlers of tea, coconut milk and herbal drinks that need a separate label for each flavour on cups, bottles and lids.\n\n• Material: paper vinyl for dry goods, waterproof PVC or PP vinyl for chilled bottles\n• Print: digital, gloss or matt laminated so labels don't smear with condensation\n• Finishing: plotter die-cut to round, oval or custom shapes\n• Tip: bottles kept in the fridge need plastic vinyl with cold-rated adhesive, as paper labels peel at the edges\n\nTrường Thịnh designs, prints, die-cuts and delivers the labels on sheets.","altVi":"Máy cắt bế tem decal trà sen, bên cạnh tem sữa dừa, nước sâm","altEn":"Cutting plotter die-cutting lotus tea decals beside coconut milk and herbal drink labels","source":"/assets/content/projects/advertising/print-decals/in-tem-decal-cat-be.webp","sha256":"28d708e29ff13e5fc335489ee6c92922f6ecf1fbfb42b3f72ba5029aa237cf37","provenance":"AI-generated illustration; ChatGPT web (chat 6ae651a8-4a9c-83ec-81e0-c981c6a2a390); upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 4c1ac8013ade5a32d45682094452fdd7567c05bcae05628a0458e94ea5026b98."},
  "kiosk-posm-32": {"descriptionVi":"Kệ carton trưng bày để quầy hợp với nhãn hàng mỹ phẩm, mặt nạ, dược mỹ phẩm phân phối qua nhà thuốc, siêu thị, cần POSM giá thấp gửi đi hàng loạt điểm bán.\n\n• Chất liệu: carton sóng E hoặc B in offset, cán màng, bế theo khuôn\n• Bộ đi kèm: kệ để bàn, kệ tầng khay mica, wobbler, standee mini, dải dán mép kệ\n• Đóng gói: giao dạng tấm phẳng, nhân viên gấp dựng tại điểm bán không cần keo\n• Lưu ý: làm mẫu trắng và thử tải với sản phẩm thật trước khi in số lượng lớn\n\nTrường Thịnh thiết kế, in và giao tận nơi trọn gói.","descriptionEn":"Cardboard counter displays suit cosmetics, sheet mask and dermocosmetic brands sold through pharmacies and supermarkets that need low-cost POSM shipped to many outlets.\n\n• Material: E- or B-flute corrugated board, offset printed, laminated and die cut\n• Kit: counter unit, tiered unit with acrylic trays, wobbler, mini standee and shelf strip\n• Packing: shipped flat and folded up in store without glue\n• Tip: make a plain prototype and load-test it with real product before the full print run\n\nTrường Thịnh designs, prints and delivers to your door.","altVi":"Kệ carton in mặt nạ dừa, wobbler treo và standee mini trên kệ","altEn":"Printed cardboard displays for coconut sheet masks with a wobbler and mini standee","source":"/assets/content/projects/advertising/kiosk-posm/ke-carton-trung-bay-my-pham.webp","sha256":"e255ea6bf683a5e82b9c553a478b60d9850d914a3885fdb06718fbb974275651","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd47d-66f8-83ec-a335-672fa602cbac); upscaled RunningHub SeedVR2 tile to 3072; owner approved incl. design system 2026-10-27 01:54Z; master PNG SHA256 3e40fc46c79977bbd8f99a027128962bfdd06b4b74f901a34c42cbcc49797025."},
  "office-signs-wayfinding-26": {"descriptionVi":"Bảng sơ đồ tầng hợp với tòa văn phòng, nhà xưởng, trường học cần chỉ rõ vị trí phòng và lối thoát nạn, đồng thời đáp ứng yêu cầu treo sơ đồ thoát hiểm khi kiểm tra phòng cháy.\n\n• Chất liệu: mica trong 5-8 mm in UV mặt sau, hoặc alu in UV cán màng\n• Lắp đặt: chân đinh inox, đặt ở sảnh thang máy và đầu cầu thang mỗi tầng\n• Kích thước thường làm: A2, A1 hoặc 60x100 cm\n• Lưu ý: gửi bản vẽ mặt bằng thực tế để xưởng vẽ lại, chấm vị trí đứng phải đúng theo từng bảng\n\nTrường Thịnh vẽ sơ đồ, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A floor plan board suits office buildings, factories and schools that need to show room locations and escape routes, and it meets the requirement to display an evacuation plan at fire inspections.\n\n• Material: 5-8 mm clear acrylic with reverse UV print, or laminated UV-printed aluminium composite\n• Installation: stainless stand-offs, at the lift lobby and stair head on every floor\n• Typical size: A2, A1 or 60x100 cm\n• Tip: send the as-built floor plan for redrawing, and make sure each board's you-are-here dot matches where it hangs\n\nTrường Thịnh draws the plan, makes the boards in its workshop and installs them.","altVi":"Bảng sơ đồ tầng mica có điểm bạn ở đây, gắn sảnh văn phòng","altEn":"Acrylic floor plan board with a you-are-here dot in an office lobby","source":"/assets/content/projects/advertising/office-signs-wayfinding/bang-so-do-tang-mica.webp","sha256":"2ac9c90eb767383b4fb78ec46bc7e5a316626570bd2b628d4285c71214190c66","provenance":"AI-generated illustration; owner approved 2026-09-24; original SHA256 fe412b6b8630b97c84471c16624af40d0f5371d3c57b5b1633a5fdb9d0ea81ab; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-31": {"descriptionVi":"Kiosk màn hình cảm ứng hợp với thương hiệu đồ uống, thực phẩm đi hội chợ, sự kiện, cho khách tự xem thông tin sản phẩm trong lúc nhân viên bận rót mẫu thử.\n\n• Khung: sắt hộp sơn tĩnh điện, thân MDF dán decal in UV, mái cong in tên chương trình\n• Màn hình: cảm ứng 21-32 inch đặt nghiêng, khung khóa chống tháo\n• Kích thước thường làm: dài 1,8-2,4 m, sâu 0,7-0,8 m\n• Lưu ý: chuẩn bị nội dung chạy không cần mạng, wifi hội chợ thường chập chờn giờ đông khách\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và giao lắp tận nơi trọn gói.","descriptionEn":"A touch screen kiosk suits drink and food brands at fairs and events, letting visitors browse product information while staff are busy pouring samples.\n\n• Frame: powder-coated steel box section, MDF body with UV-printed vinyl, curved canopy with the campaign name\n• Screen: 21-32 inch touch display set at an angle in a lockable surround\n• Typical size: 1.8-2.4 m long, 0.7-0.8 m deep\n• Tip: prepare content that runs offline, since fair wifi tends to drop at peak hours\n\nTrường Thịnh designs, builds in its workshop and delivers and installs the kiosk.","altVi":"Kiosk hội chợ mái cong có màn hình cảm ứng, kệ nước dừa","altEn":"Curved-roof trade show kiosk with a touch screen and shelves of coconut drinks","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-man-hinh-cam-ung.webp","sha256":"82b5371a01ea9f286ae05a76437273de9b5d5935d4cd71e81e9bfcdb94794aca","provenance":"AI-generated illustration; owner approved 2026-09-24; original SHA256 fcff2bf7b424b9b83a3af01181a1744953f9c30ca4679439ffc4c8db4b7592a6; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "print-decals-17": {"descriptionVi":"Kệ menu mica chữ T hợp với quán cà phê, tiệm bánh, quán trà muốn đặt menu trên bàn khách hay quầy order, đổi giá chỉ cần in lại tờ giấy kẹp bên trong.\n\n• Chất liệu: mica trong 2-3 mm, uốn chữ T liền đế, không mối dán\n• Ruột: giấy couché in hai mặt, cán màng để lau được\n• Kích thước thường làm: A5, A6 hoặc 10x21 cm\n• Lưu ý: đặt ngoài sân nên chọn mica 3 mm, mica mỏng dễ đổ khi có gió\n\nTrường Thịnh thiết kế, in menu và giao kệ mica tận nơi.","descriptionEn":"Acrylic T-stand menus suit cafés, bakeries and tea shops that want menus on tables or at the order counter, where a price change only means reprinting the sheet inside.\n\n• Material: 2-3 mm clear acrylic bent into a one-piece T with no glued joints\n• Insert: coated paper printed both sides, laminated to wipe clean\n• Typical size: A5, A6 or 10x21 cm\n• Tip: for outdoor tables choose 3 mm acrylic, as thinner stands tip over in the wind\n\nTrường Thịnh designs and prints the menus and delivers them with the stands.","altVi":"Ba kệ menu mica chữ T in thực đơn cà phê, trà, bánh ngọt","altEn":"Three clear acrylic T-stand menus for coffee, tea and pastries on a counter","source":"/assets/content/projects/advertising/print-decals/ke-menu-mica-chu-t.webp","sha256":"5e0059dc9044466240831f47e5c0b3ec6ec63efd2aedffc6b3f4fbbf41812786","provenance":"AI-generated illustration; owner approved 2026-09-24; original SHA256 97bf80cb3404f34bf1ca902841c6a2245af947a482f9d87de5f40a64b3b36c5a; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-14": {"descriptionVi":"Biển phòng họp inox xước hợp với văn phòng công ty, tòa nhà cho thuê cần biển cửa bền, sạch, dùng chung một mẫu cho cả dãy phòng.\n\n• Chất liệu: inox 304 xước dày 1-1,2 mm, chân đinh inox hoặc keo 3M\n• Gia công: chữ và biểu tượng in UV hoặc ăn mòn đổ sơn\n• Kích thước thường làm: 30x10 cm đến 40x15 cm\n• Lưu ý: đặt cùng lúc cho cả tầng, mỗi biển chỉ đổi tên phòng, giá theo bộ rẻ hơn đặt lẻ\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A brushed stainless meeting room sign suits company offices and rented office buildings that need durable, clean door signs in one design for a whole corridor.\n\n• Material: 1-1.2 mm brushed 304 stainless, stainless stand-offs or 3M tape\n• Fabrication: text and icons UV printed, or etched and paint-filled\n• Typical size: 30x10 cm to 40x15 cm\n• Tip: order a whole floor at once with only the room name changing, since a set costs less than single signs\n\nTrường Thịnh designs, makes the signs in its workshop and installs them.","altVi":"Biển phòng họp inox xước song ngữ gắn trên khung cửa gỗ","altEn":"Bilingual brushed stainless meeting room sign above a timber door","source":"/assets/content/projects/advertising/office-signs-wayfinding/bien-phong-hop-inox-xuoc.webp","sha256":"2fba8a439ccc9600112e46638118de5c666022a7b57273c1ec38af6d2a66dc3b","provenance":"AI-generated illustration; ChatGPT web image generation 2026-10-24; owner approved audit #789 in chat; original SHA256 32b2f047df331c70ec6a29e4829ad1d09db278b9ab9873bdddc572c7f4cb5aef; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-15": {"descriptionVi":"Biển phòng họp mica trong hợp với văn phòng có vách kính, cửa kính khung nhôm, nơi biển dán thẳng lên cửa sẽ lẫn vào cảnh phía sau.\n\n• Chất liệu: mica trong 5-8 mm, chân đinh inox 304\n• In: UV mặt sau mica, lớp in nằm dưới mica nên lau chùi không trầy\n• Kích thước thường làm: 20x20 cm đến 25x25 cm\n• Lưu ý: mica trong chỉ rõ chữ trên mảng tường trơn sáng màu, tường hoa văn nên chọn mica trắng sữa\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A clear acrylic meeting room sign suits offices with glass partitions and aluminium-framed glass doors, where a sign stuck on the door gets lost against the room behind.\n\n• Material: 5-8 mm clear acrylic, 304 stainless stand-offs\n• Print: reverse UV print, so the graphic sits under the acrylic and won't scratch with cleaning\n• Typical size: 20x20 cm to 25x25 cm\n• Tip: clear acrylic reads well only on a plain light wall; on patterned walls choose opal acrylic\n\nTrường Thịnh designs, makes the signs in its workshop and installs them.","altVi":"Biển phòng họp mica trong chân đinh inox cạnh cửa kính","altEn":"Clear acrylic meeting room sign on stainless stand-offs beside a glass door","source":"/assets/content/projects/advertising/office-signs-wayfinding/bien-phong-hop-mica-trong.webp","sha256":"0bc58f81ead03d1b5bde065e9f04be8430e24516755418ed901b35f472e7f554","provenance":"AI-generated illustration; KIE gpt-image-2-5-flare-image-to-image; task 8a76af7091c7cd088293887ddfaacf1a; owner approved A149-v1 in chat; original SHA256 5db89eb2f7c5c847a90d8bbb4c93777fe7fc43276e2e40a4f4580f1dc3963661; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-16": {"descriptionVi":"Biển phòng họp gỗ khắc laser hợp với văn phòng startup, coworking, quán cà phê có phòng họp riêng, nơi nội thất dùng nhiều gỗ và cây xanh.\n\n• Chất liệu: gỗ sồi ghép hoặc MDF phủ veneer sồi dày 8-10 mm\n• Gia công: khắc laser chữ âm, phủ dầu hoặc PU mờ chống bám bẩn\n• Kích thước thường làm: 30x10 cm đến 40x12 cm\n• Lưu ý: gỗ thật ngả màu theo thời gian, muốn cả dãy biển đều tông thì chọn veneer phủ PU\n\nTrường Thịnh thiết kế, gia công tại xưởng và lắp đặt trọn gói.","descriptionEn":"A laser-engraved timber meeting room sign suits startups, coworking spaces and cafés with private meeting rooms, where the interior already uses plenty of wood and greenery.\n\n• Material: 8-10 mm finger-jointed oak or oak-veneered MDF\n• Fabrication: laser-engraved recessed lettering, oil or matt PU finish against marks\n• Typical size: 30x10 cm to 40x12 cm\n• Tip: solid timber darkens with age, so for a row of signs that stay one tone choose PU-coated veneer\n\nTrường Thịnh designs, makes the signs in its workshop and installs them.","altVi":"Biển phòng họp gỗ sồi khắc chữ, gắn tường cạnh cửa","altEn":"Engraved oak meeting room sign on the wall beside an open door","source":"/assets/content/projects/advertising/office-signs-wayfinding/bien-phong-hop-go-soi.webp","sha256":"d1ded95f8d7355b92ebe145780d58d4459ba1142cc89f099b1f925b621ba360a","provenance":"AI-generated illustration; ChatGPT web image generation 2026-11-11, version q2, chat 6af43e13-c79c-83ec-9a16-0d296de0c4f8; original PNG SHA256 dbdeccf501bc9984a75c4a47b85b7df1a7781a7f6c21e3e7afc8c55cd340149c; 1024x1536, not upscaled yet; owner approved to site 2026-11-11."},
  "office-signs-wayfinding-17": {"descriptionVi":"Biển tên phòng inox chân đinh hợp với cơ quan, trường học, doanh nghiệp sản xuất có nhiều phòng ban, cần biển bền, dễ vệ sinh và cùng một mẫu cho cả tòa nhà.\n\n• Chất liệu: inox 304 xước 1-1,5 mm, chân đinh inox cách tường 1,5-2 cm\n• Gia công: chữ và biểu tượng in UV theo màu nhận diện hoặc ăn mòn đổ sơn\n• Kích thước thường làm: 40x20 cm đến 50x25 cm\n• Lưu ý: gửi trước đủ danh sách phòng ban để xưởng dàn chữ cùng cỡ, tránh tên dài bị ép nhỏ\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A stainless room name sign on stand-offs suits public offices, schools and manufacturers with many departments that need durable, easy-clean signs in one design across the building.\n\n• Material: 1-1.5 mm brushed 304 stainless, stainless stand-offs 1.5-2 cm off the wall\n• Fabrication: text and icons UV printed in brand colours, or etched and paint-filled\n• Typical size: 40x20 cm to 50x25 cm\n• Tip: send the full list of departments first so the workshop sets every name at one size, rather than squeezing long ones\n\nTrường Thịnh designs, makes the signs in its workshop and installs them.","altVi":"Biển tên phòng inox xước chữ xanh, chân đinh cạnh cửa","altEn":"Brushed stainless room name sign with blue lettering on stand-offs","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-planning-01.webp","sha256":"b3b2abbe7eb393b7740b2faa31669157dc375ba2bdd6d4af841818bc07df734f","provenance":"AI-generated illustration; ChatGPT web image generation 2026-11-11, version r3, chat 6af443b7-74bc-83ec-88cc-45c664c00eaf; original PNG SHA256 c5c11b7b1f725f8096364fbff9098bb1444e7d647d9fabdfa4c9afd144764a75; 1024x1536, not upscaled yet; owner approved to site 2026-11-11."},
  "office-signs-wayfinding-18": {"descriptionVi":"Biển phòng họp mica đen chữ vàng hợp với văn phòng luật, ngân hàng, công ty có nội thất gỗ ấm, muốn biển cửa trang trọng hơn inox mà chi phí vẫn thấp.\n\n• Chất liệu: mica đen bóng 3-5 mm hoặc alu đen, chữ decal nhũ vàng hay in UV vàng kim\n• Gia công: cắt laser bo góc, thêm viền chỉ hoặc logo tùy nhận diện\n• Kích thước thường làm: 30x10 cm đến 35x12 cm\n• Lắp đặt: keo 3M hai mặt dán thẳng lên cánh cửa, không phải khoan\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A black acrylic meeting room sign with gold lettering suits law firms, banks and companies with warm timber interiors that want a more formal door sign than stainless at a low cost.\n\n• Material: 3-5 mm gloss black acrylic or black aluminium composite, gold foil vinyl or gold UV print\n• Fabrication: laser cut with rounded corners, optional keyline or logo to suit the brand\n• Typical size: 30x10 cm to 35x12 cm\n• Installation: double-sided 3M tape straight onto the door, no drilling\n\nTrường Thịnh designs, makes the signs in its workshop and installs them.","altVi":"Biển mica đen chữ vàng phòng họp gắn giữa cánh cửa gỗ","altEn":"Black acrylic meeting room sign with gold text on a timber door","source":"/assets/content/projects/advertising/office-signs-wayfinding/bien-phong-hop-mica-den-vang.webp","sha256":"834c480e95374c8bb0e39efa9b464465c7162cacde2fb8cc0c2234d36d713f62","provenance":"AI-generated illustration; KIE gpt-image-2-5-flare-image-to-image; task c64c3f682146dca4b010c7737e075274; owner approved A152-v1 in chat; original SHA256 baad7b9d493e0410cc94ec39fa6bdf6f9aa9f1b3da655cddaa681c269afa703d; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-19": {"descriptionVi":"Biển phòng kỹ thuật hợp với tầng hầm, phòng điện, phòng bơm của tòa nhà và nhà xưởng, nơi biển phải chịu được ẩm, bụi dầu và va chạm.\n\n• Chất liệu: alu 3 mm hoặc tôn sơn tĩnh điện, decal in UV cán màng\n• Màu sắc: nền tối chữ trắng kèm dải vàng, cùng màu vạch sơn sàn khu kỹ thuật\n• Kích thước thường làm: 30x15 cm đến 40x20 cm\n• Lắp đặt: keo VHB chuyên dụng cho cửa thép chống cháy, hạn chế khoan làm hỏng cánh cửa\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A technical room sign suits basements, electrical rooms and pump rooms in buildings and factories, where the sign has to cope with damp, oily dust and knocks.\n\n• Material: 3 mm aluminium composite or powder-coated steel, UV-printed laminated vinyl\n• Colour: dark background, white text and a yellow band to match the plant-area floor markings\n• Typical size: 30x15 cm to 40x20 cm\n• Installation: VHB tape rated for steel fire doors, avoiding drilling that could damage the door\n\nTrường Thịnh designs, makes the signs in its workshop and installs them.","altVi":"Biển phòng kỹ thuật nền xanh đen viền vàng trên cửa thép","altEn":"Navy technical room sign with a yellow stripe on a steel door","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-technical-room-door.webp","sha256":"e201b082a42527c9acfb061618c97ad66877eb3547abf552974340a718d3f9d4","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adf74ca-c558-83ec-a8a6-ff556b2b35c0, card #861); upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-26 19:32Z; master PNG SHA256 da47bf8dc1de766b18533f961033bfae0dcad4c00191e5cc63ddfdf63e32a52e."},
  "office-signs-wayfinding-20": {"descriptionVi":"Biển tên công viên dạng trụ đứng hợp với công viên khu đô thị, khu dân cư, khuôn viên trường và bệnh viện, nơi biển vừa đánh dấu lối vào vừa là điểm nhấn cảnh quan.\n\n• Kết cấu: khung thép mạ kẽm ốp alu hoặc tôn sơn tĩnh điện, bồn cây và đế ốp đá granite\n• Chữ: alu hoặc inox sơn tĩnh điện cắt CNC, gắn nổi 1-2 cm\n• Kích thước thường làm: cao 1,8-2,5 m, rộng 0,8-1,2 m\n• Lưu ý: đế granite nên cao hơn mặt cỏ, nước tưới và máy cắt cỏ không làm ố, mẻ chân biển\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A free-standing park name sign suits parks in new townships, residential estates, school and hospital grounds, marking the entrance and adding a feature to the landscape.\n\n• Structure: galvanised steel frame clad in aluminium composite or powder-coated steel, planter and plinth faced in granite\n• Letters: CNC-cut aluminium or stainless, powder-coated, standing 1-2 cm proud\n• Typical size: 1.8-2.5 m tall, 0.8-1.2 m wide\n• Tip: raise the granite plinth above the lawn so sprinklers and mowers don't stain or chip the base\n\nTrường Thịnh designs, builds the sign in its workshop and installs it.","altVi":"Trụ biển tên công viên chữ nổi xanh, đế đá granite giữa thảm cỏ","altEn":"Park name monolith with raised green letters on a granite plinth","source":"/assets/content/projects/advertising/office-signs-wayfinding/bien-ten-cong-vien-de-granite.webp","sha256":"91d5c9f91830cdb433a58491dd202e6851f206ee85cbfc3003ca610f92e3d340","provenance":"AI-generated illustration; ChatGPT web image generation 2026-11-11, owner-edited image in the ChatGPT chat, chat 6af4602a-e4ec-83ec-b725-137f861849f8; original PNG SHA256 428b1b850c23e0f1e4606b0326c6d7cf37ae54986185dc3b95131495525e73d3; 1024x1536, not upscaled yet; owner approved to site 2026-11-11."},
  "office-signs-wayfinding-21": {"descriptionVi":"Cột biển chỉ dẫn mũi tên hợp với phố đi bộ, khu chợ, khu dân cư mới muốn chỉ đường đến nhiều điểm trên một cột, gọn hơn dựng từng biển riêng.\n\n• Kết cấu: cột thép ống sơn tĩnh điện, đế bắt bu lông neo, mũi tên alu hai mặt\n• Màu sắc: mỗi nhóm điểm đến giữ một màu trên mọi cột trong khu\n• Kích thước thường làm: cột cao 2,8-3,2 m, mũi tên dài 60-90 cm\n• Lưu ý: mũi tên bắt bằng cùm xoay, khi thêm điểm đến hay đổi hướng chỉ cần tháo một thanh\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"An arrow fingerpost suits walking streets, markets and new residential areas that want to point to several places from one post, tidier than putting up separate signs.\n\n• Structure: powder-coated steel tube post on an anchor-bolted base, double-sided aluminium arrows\n• Colour: each group of destinations keeps one colour on every post in the area\n• Typical size: post 2.8-3.2 m tall, arrows 60-90 cm long\n• Tip: arrows fixed with swivel clamps mean a new destination or direction needs only one blade changed\n\nTrường Thịnh designs, builds the post in its workshop and installs it.","altVi":"Cột biển chỉ dẫn mũi tên nhiều màu ở khu phố ven sông","altEn":"Multicoloured arrow fingerpost sign on a riverside neighbourhood street","source":"/assets/content/projects/advertising/office-signs-wayfinding/cot-bien-chi-dan-mui-ten.webp","sha256":"1e328409e82a13a18bb6a735338e3539cbc7a8ea5b3e0727178b9e8339e85c17","provenance":"AI-generated illustration; source ID imagegen:2026-10-19:office-signs-wayfinding-21-a-2; original SHA256 19db2e575683c6d2fe13a84291e7b1152b649bd095d17956df669f1a0ef6ceef; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-22": {"descriptionVi":"Biển tên hai chân thép hợp với nhà văn hóa, nhà sinh hoạt khu dân cư, trường học, cơ quan cần biển đứng ngoài sân bền, dễ thay nội dung và chi phí vừa phải.\n\n• Kết cấu: hai chân thép hộp sơn tĩnh điện, khung viền sắt, mặt alu ngoài trời\n• Chữ: decal cắt hoặc in UV cán màng chống phai\n• Kích thước thường làm: mặt biển 1,2x0,6 m đến 2x0,8 m, cao tổng 1,8-2,2 m\n• Lưu ý: chân thép chôn khối bê tông sâu 40-50 cm, biển rộng trên 1,5 m nên tăng tiết diện chân để chịu gió\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A two-post steel name sign suits community halls, neighbourhood centres, schools and public offices that need a durable yard sign with replaceable content at a moderate cost.\n\n• Structure: two powder-coated steel box posts, steel edge frame, exterior aluminium composite face\n• Lettering: cut vinyl or laminated UV print that resists fading\n• Typical size: face 1.2x0.6 m to 2x0.8 m, 1.8-2.2 m tall overall\n• Tip: set the posts 40-50 cm into concrete, and use heavier posts for signs over 1.5 m wide to handle wind\n\nTrường Thịnh designs, builds the sign in its workshop and installs it.","altVi":"Biển tên nhà sinh hoạt khung thép đen trên hai chân","altEn":"Community hall name sign on two black steel posts in a flowerbed","source":"/assets/content/projects/advertising/office-signs-wayfinding/bien-ten-hai-chan-thep.webp","sha256":"a85c8c9d544cc42d50d74e2d327743b681881b1819d2a270611b2b969a9a57d6","provenance":"AI-generated illustration; ChatGPT web image generation 2026-11-11, version r2, chat 6af442ca-5618-83ec-926b-eabad9dae7c9; original PNG SHA256 321ed368e0e95a77271e4708e7c144eb7bd1558a2b384a5c298a5338f586142f; 1024x1536, not upscaled yet; owner approved to site 2026-11-11."},
  "office-signs-wayfinding-23": {"descriptionVi":"Biển WC bằng đồng xước hợp với khách sạn, nhà hàng, văn phòng có cửa gỗ tối màu và nội thất tông ấm. Cùng chất liệu có thể làm đồng bộ biển số phòng, biển lối thoát.\n\n• Chất liệu: đồng thau 1-2 mm hoặc inox mạ PVD màu đồng, phủ lớp chống oxy hóa\n• Gia công: ăn mòn hoặc khắc laser, đổ sơn, bo cạnh\n• Kích thước thường làm: 15x15 cm hoặc 20x20 cm\n• Lưu ý: đồng thau thật sẽ xỉn dần nếu không phủ lớp bảo vệ, inox mạ PVD giữ màu lâu hơn và rẻ hơn\n\nTrường Thịnh thiết kế, gia công tại xưởng và lắp đặt trọn gói.","descriptionEn":"Brushed brass toilet signs suit hotels, restaurants and offices with dark timber doors and warm-toned interiors. Room numbers and exit signs can be made in the same finish for a matching set.\n\n• Material: 1-2 mm brass or brass-tone PVD-coated stainless, sealed against tarnish\n• Fabrication: etched or laser-engraved, paint-filled, edges rounded\n• Typical size: 15x15 cm or 20x20 cm\n• Tip: solid brass dulls over time without a protective coat, while PVD stainless holds its colour longer and costs less\n\nTrường Thịnh designs, makes the signs in its workshop and installs them.","altVi":"Biển WC bằng đồng xước hình nam nữ trên cửa gỗ","altEn":"Brushed brass male and female toilet signs on dark timber doors","source":"/assets/content/projects/advertising/office-signs-wayfinding/bien-wc-dong-gan-cua-go.webp","sha256":"c5948bd4bba9b46aec84f7c7ba3a9a11f2f8cf3b5323a5a1875c5c352d979dfd","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adf74fb-0894-83ec-8fee-bbfa5df0d286, card #862); upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-26 19:32Z; master PNG SHA256 7eff6a87ccaabe53965ae7ebaea291d043c6badd95c3ec3a0385f58f91ae913f."},
  "office-signs-wayfinding-24": {"descriptionVi":"Biển cảnh báo điện là biển an toàn cần có ở tủ điện, trạm biến áp, phòng máy của nhà xưởng và tòa nhà, thường được kiểm tra khi nghiệm thu an toàn lao động.\n\n• Chất liệu: alu 2-3 mm hoặc tôn sơn tĩnh điện, decal phản quang hoặc in UV cán màng\n• Quy cách: màu và hình dạng theo mẫu biển báo an toàn TCVN\n• Kích thước thường làm: 20x30 cm, 30x40 cm\n• Lưu ý: tủ điện ngoài trời nên dùng decal phản quang và đinh rive inox để không bong mép, không gỉ\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"An electrical hazard sign is a required safety sign on switchboards, substations and plant rooms in factories and buildings, and is usually checked during safety inspections.\n\n• Material: 2-3 mm aluminium composite or powder-coated steel, reflective vinyl or laminated UV print\n• Specification: colours and shapes following the Vietnamese TCVN safety sign standard\n• Typical size: 20x30 cm or 30x40 cm\n• Tip: on outdoor cabinets use reflective vinyl and stainless rivets so edges don't lift or rust\n\nTrường Thịnh designs, makes the signs in its workshop and installs them.","altVi":"Biển cảnh báo điện nền vàng hình tia sét gắn cửa tủ điện","altEn":"Yellow electrical hazard sign with a lightning symbol on a switchboard door","source":"/assets/content/projects/advertising/office-signs-wayfinding/bien-canh-bao-dien-tu-dien.webp","sha256":"2ad92f18bd880ed85b45008761061541b0c73f5da8c62fcd7e816f5008646359","provenance":"AI-generated illustration; ChatGPT web image generation 2026-11-11, version v2, chat 6af4264c-6060-83ec-a149-15964d3e6178; original PNG SHA256 0d6ecd25c2e5b1864af7ffb48f9deacb073fbfd14e8d86984b8f1789334db3df; 1536x1024, not upscaled yet; owner approved to site 2026-11-11."},
  "office-signs-wayfinding-25": {"descriptionVi":"Biển nhà vệ sinh dạng hộp gắn vuông góc hợp với hành lang dài của nhà hàng, khách sạn, văn phòng, nơi biển dán phẳng trên cửa chỉ thấy khi đã đến gần.\n\n• Cấu tạo: hộp alu hoặc tôn sơn tĩnh điện dày 5-8 cm, hai mặt in UV hoặc decal cắt\n• Kích thước thường làm: 25x25 cm đến 30x30 cm\n• Lắp đặt: pát thép bắt tắc kê, đáy biển cao từ 2,1 m trở lên để không vướng đầu\n• Lưu ý: muốn có đèn thì làm thành hộp đèn LED mặt mica, dây nguồn đi âm tường từ trước\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A projecting box washroom sign suits long corridors in restaurants, hotels and offices, where a flat sign on the door is only visible once you're close.\n\n• Build: 5-8 cm deep aluminium or powder-coated steel box, both faces UV printed or cut vinyl\n• Typical size: 25x25 cm to 30x30 cm\n• Installation: steel bracket on wall anchors, with the bottom edge at least 2.1 m up for head clearance\n• Tip: for a lit version, build it as an LED lightbox with an acrylic face and run the cable inside the wall beforehand\n\nTrường Thịnh designs, makes it in its own workshop and installs it.","altVi":"Biển WC hộp vuông đen hai mặt gắn vuông góc hành lang","altEn":"Double-sided black box washroom sign projecting from a corridor wall","source":"/assets/content/projects/advertising/office-signs-wayfinding/bien-nha-ve-sinh-hop-vuong.webp","sha256":"e436624498599feb2efb96f5f5d06685c6181cdcfef809150de574b2ac5bc9db","provenance":"AI-generated illustration; ChatGPT web image generation 2026-11-11, version s3, chat 6af443d3-248c-83ec-9423-d0fe073d0d84; original PNG SHA256 193a6984da755a679ca1b34e67ad694495f7d9e9b13d470ed05e0aa3dfe2f86a; 1024x1536, not upscaled yet; owner approved to site 2026-11-11."},
  "kiosk-posm-01": {"descriptionVi":"Gian hàng hội chợ khung gỗ hợp với khu du lịch, hợp tác xã, công ty lữ hành tham gia hội chợ du lịch hay triển lãm OCOP, cần một gian có bản sắc riêng thay vì gian khung nhôm tiêu chuẩn.\n\n• Kết cấu: khung gỗ hoặc sắt hộp ốp MDF, lam giả tre, sàn nâng\n• Phông nền: in bạt hoặc decal khổ lớn, thay được cho kỳ hội chợ sau\n• Kích thước thường làm: 3x3 m, 3x6 m, 6x6 m theo ô ban tổ chức\n• Lưu ý: làm khung dạng module bắt vít thì dùng lại được nhiều kỳ, chỉ cần in lại phông\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và thi công trọn gói từ lúc dựng đến khi tháo gian hàng.","descriptionEn":"A timber-framed trade fair booth suits resorts, cooperatives and tour operators at tourism fairs and regional product shows who want a stand with its own character rather than a standard aluminium shell.\n\n• Structure: timber or steel box frame clad in MDF, bamboo-look slats, raised floor\n• Backdrop: large-format banner or vinyl, replaceable for the next show\n• Typical size: 3x3 m, 3x6 m or 6x6 m to suit the organiser's plot\n• Tip: a bolted modular frame can be reused for several shows, with only the graphics reprinted\n\nTrường Thịnh designs, builds and handles the booth from set-up to take-down.","altVi":"Gian hàng hội chợ du lịch khung gỗ ốp lam, phông nền xanh rêu","altEn":"Tourism fair booth with a slatted timber frame and deep green backdrop","source":"/assets/content/projects/advertising/kiosk-posm/gian-hang-hoi-cho-du-lich.webp","sha256":"813285a78066be19f2dc8ab8208857eb5a9b4cf26d84920381c6e30a528a3133","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adf7528-510c-83ec-8d67-bc7773648b99, card #854); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-26 18:24Z; master PNG SHA256 219e784bd19392f94ff226b0a364e502328b6b2b59e3998630c6f79217a034ad."},
  "kiosk-posm-02": {"descriptionVi":"Quầy bar quán nước ép có tủ kính lạnh ghép liền hợp với quán sinh tố, trà trái cây cần vừa pha chế vừa giữ lạnh trái cây ngay tại quầy order.\n\n• Thân quầy: khung gỗ hoặc sắt hộp, ốp MDF chống ẩm phủ laminate, lam gỗ cắt CNC\n• Mặt quầy: gỗ cao su phủ PU hoặc đá nhân tạo, chịu nước và axit trái cây\n• Tủ kính: tủ lạnh trưng bày mua theo hãng, xưởng đóng vỏ gỗ bao ngoài cho đồng bộ với quầy\n• Lưu ý: chừa khe thoát nhiệt cho tủ lạnh và máy nén, đóng kín quá sẽ nhanh hỏng máy\n\nTrường Thịnh thiết kế theo mặt bằng, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A juice bar counter with a built-in chilled display case suits smoothie and fruit tea shops that need to make drinks and keep fruit cold at the same counter where customers order.\n\n• Body: timber or steel box frame clad in moisture-resistant MDF with laminate, CNC-cut timber slats\n• Top: PU-finished rubberwood or engineered stone that stands up to water and fruit acid\n• Display case: a branded chilled cabinet, boxed in timber at the workshop to match the counter\n• Tip: leave ventilation gaps for the fridge and compressor, since a fully enclosed unit wears out fast\n\nTrường Thịnh designs to your floor plan, builds in its workshop and installs the counter.","altVi":"Quầy bar gỗ ốp lam sóng kèm tủ kính lạnh bày trái cây","altEn":"Timber juice bar counter with wave-cut slats and a chilled fruit display case","source":"/assets/content/projects/advertising/kiosk-posm/quay-bar-quan-nuoc-ep.webp","sha256":"7f9da4b88cb86f9c615a7175d3a520ec1671b9b4f88703a51a83469eecba7fdb","provenance":"AI-generated illustration; owner explicitly approved latest chat image A021-v3 on 2026-10-23; ChatGPT web; model unknown; original SHA256 c6bd887c8d81cd06a39559d2a49e79f9a45f7f8bd88dbe9984206580314610b1; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-03": {"descriptionVi":"Tủ trưng bày kính mắt dạng tủ tường kèm tủ dưới là cấu hình chuẩn của cửa hàng mắt kính: phần trên để khách xem mẫu, phần dưới trữ hàng có khóa.\n\n• Khung tủ: nhôm định hình sơn tĩnh điện, kính cường lực, kệ kính 8-10 mm\n• Đèn: LED thanh sau mica tán quang 3000-4000K, giữ đúng màu gọng và tròng\n• Tủ dưới: MDF chống ẩm phủ laminate, ray giảm chấn\n• Kích thước thường làm: cao 2,2-2,4 m, mỗi khoang 60-90 cm\n\nTrường Thịnh đo mặt bằng, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"An eyewear display cabinet with a wall unit over a base unit is the standard optical-shop setup: frames on show above, lockable stock storage below.\n\n• Frame: powder-coated aluminium profiles, toughened glass, 8-10 mm glass shelves\n• Lighting: LED bars behind diffuser acrylic at 3000-4000K, so frame and lens colours look true\n• Base: moisture-resistant MDF with laminate, soft-close runners\n• Typical size: 2.2-2.4 m tall, bays 60-90 cm wide\n\nTrường Thịnh measures the shop, builds the cabinets in its workshop and installs them.","altVi":"Tủ trưng bày kính mắt khung nhôm đen, kệ kính hắt đèn","altEn":"Black aluminium eyewear display cabinets with lit glass shelves in an optical shop","source":"/assets/content/projects/advertising/kiosk-posm/tu-trung-bay-kinh-mat.webp","sha256":"1b1f73c52393740fee61c81ca62959f2849c29416029019e7da0c3e76f735689","provenance":"AI-generated illustration; ChatGPT web image edit with owner mask (chat 6ae5c729-5f14-83ec-a2e4-163bde88716c); upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-27; master PNG SHA256 091b159645c6cb2c4fb48d26ee8945466f556c5bea281303e9a82fbf975ce4ae."},
  "kiosk-posm-04": {"descriptionVi":"Kệ trưng bày đặc sản dạng quầy đảo hợp với cửa hàng đặc sản, quầy quà biếu trong siêu thị hay trạm dừng chân, cần bày nhiều loại bánh kẹo đóng gói trên một khối gọn.\n\n• Chất liệu: gỗ cao su ghép hoặc MDF chống ẩm phủ laminate vân gỗ, khung sắt sơn tĩnh điện\n• Kệ: mặt kệ nghiêng nhẹ có nẹp chặn, LED dây âm dưới từng tầng\n• Kích thước thường làm: dài 1,8-2,4 m, cao 1,8-2,2 m tính cả bảng tên\n• Lưu ý: làm sẵn ray gắn thẻ giá ở mép kệ, sau này đổi giá chỉ cần thay thẻ\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"Island-style specialty food shelving suits local-speciality shops, gift counters in supermarkets and highway rest stops that need to show many packaged sweets in one compact unit.\n\n• Material: finger-jointed rubberwood or moisture-resistant MDF with woodgrain laminate, powder-coated steel frame\n• Shelves: slightly tilted with a lip rail, LED strip recessed under each tier\n• Typical size: 1.8-2.4 m long, 1.8-2.2 m tall including the header\n• Tip: build price-tag rails into the shelf edges from the start, so a price change means swapping a tag\n\nTrường Thịnh designs, builds in its workshop and installs the unit.","altVi":"Kệ gỗ nhiều tầng bày bánh kẹo dừa, bảng tên trên khung cong","altEn":"Tiered timber shelving of coconut sweets under a curved name header","source":"/assets/content/projects/advertising/kiosk-posm/ke-trung-bay-dac-san-go.webp","sha256":"35f4451b6dc2521cf29c503a7f4e9bb4de42536f6482a2dd9166c0b0fdddd50a","provenance":"AI-generated illustration; owner approved A023-v3 in chat 2026-10-23; ChatGPT web; model unknown; original SHA256 4d6195df504fb32532516022167173c62df92ac7b0542663e20e96803bda38ec; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-05": {"descriptionVi":"Kiosk kính mắt khung thép hợp với thương hiệu mắt kính, đồng hồ, phụ kiện thuê ô giữa sảnh trung tâm thương mại, bán được bốn phía mà vẫn khóa hàng an toàn khi đóng ca.\n\n• Khung: thép hộp sơn tĩnh điện đen mờ, mái hộp đèn bạt xuyên sáng (bạt 3M, bạt Hàn Quốc) in hình, thay được theo mùa\n• Tủ kính: kính cường lực, đế MDF chống ẩm phủ laminate, cửa lùa có khóa\n• Đèn: rọi ray trên mái và LED thanh trong tủ, ánh trung tính giữ đúng màu gọng\n• Kích thước thường làm: 2,5x2,5 m đến 3x3 m theo ô thuê\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói trong khung giờ trung tâm cho phép.","descriptionEn":"A steel-framed eyewear kiosk suits optical, watch and accessory brands renting an atrium plot in a shopping mall, selling on all four sides while locking stock away safely at closing.\n\n• Frame: matt black powder-coated steel box section, translucent flex lightbox canopy (3M or Korean flex) with graphics swapped by season\n• Cases: toughened glass on moisture-resistant MDF bases with laminate, lockable sliding doors\n• Lighting: track spots on the canopy and LED bars in the cases, neutral white to keep frame colours true\n• Typical size: 2.5x2.5 m to 3x3 m to suit the plot\n\nTrường Thịnh designs, builds in its workshop and installs within the mall's permitted hours.","altVi":"Kiosk kính mắt khung thép đen, tủ kính đế gỗ giữa sảnh thương mại","altEn":"Black steel eyewear kiosk with timber-based glass cases in a mall atrium","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-kinh-mat-khung-thep.webp","sha256":"64dc0e70fce8d368127b6db59269bf5ada6135269bf6eb45dddf4f5b6c7a52a1","provenance":"AI-generated illustration; owner selected A024-v1 in HTML audit and confirmed in chat 2026-10-22; ChatGPT web gpt-image; original SHA256 4e8f7a271de3f239f60587b90ee588b897e8564659f9c8e0fe58010fdb03eb29; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-06": {"descriptionVi":"Kiosk mỹ phẩm gỗ mái cong hợp với thương hiệu mỹ phẩm thiên nhiên, chăm sóc da thuê điểm giữa sảnh, muốn có một không gian riêng mang đúng chất thương hiệu.\n\n• Kết cấu: khung sắt hộp bọc MDF chống ẩm, lam gỗ và mái cong uốn tại xưởng\n• Kệ: bục tròn nhiều tầng mặt solid surface, LED dây hắt dưới từng tầng\n• Kích thước thường làm: 3x3 m đến 4x6 m, có quầy thu ngân và tủ trữ hàng phía trong\n• Lưu ý: mái và cây trang trí phải nằm trong chiều cao ban quản lý cho phép, nên gửi bản vẽ duyệt trước\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A curved timber cosmetics kiosk suits natural beauty and skincare brands renting an atrium plot that want a space of their own with the brand's character built in.\n\n• Structure: steel box frame clad in moisture-resistant MDF, timber slats and a canopy curved in the workshop\n• Display: round multi-tier plinths with solid-surface tops, LED strip under each tier\n• Typical size: 3x3 m to 4x6 m, with a cash counter and stock storage inside\n• Tip: the canopy and planting must stay under the mall's height limit, so send drawings for approval first\n\nTrường Thịnh designs, builds in its workshop and installs the kiosk.","altVi":"Kiosk gỗ mái cong bày mỹ phẩm dừa giữa sảnh trung tâm thương mại","altEn":"Curved-canopy timber kiosk showing coconut cosmetics in a mall atrium","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-my-pham-go-cong.webp","sha256":"b6df6e1b0ee096b966cd15251ff0995f9fe288f1829c1aefcaf659d4699a0406","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 a27da3b9df61ce02fab48d3de30377367d04872e95470d1948f59fb117a10ab8."},
  "kiosk-posm-07": {"descriptionVi":"Quầy sampling bày đặc sản dừa hợp với cơ sở kẹo dừa, bánh kẹo, đồ khô đặt điểm bán lâu dài trong trung tâm thương mại, vừa mời nếm thử vừa bán tại chỗ.\n\n• Thân quầy: MDF chống ẩm ốp lam, mặt trước hộp đèn bạt hiflex hoặc bạt 3M xuyên sáng in hình sản phẩm\n• Khung trên: sắt hộp sơn tĩnh điện, treo đèn mây và đồ trang trí theo chủ đề\n• Kích thước thường làm: dài 2,4-3 m, có ngăn trữ hàng và kệ phụ phía sau\n• Lưu ý: tấm in mặt quầy nên làm dạng lồng rời, đổi chiến dịch chỉ in lại tấm này\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A sampling counter for coconut specialities suits coconut candy, sweet and dried-goods makers running a long-term pitch in a shopping mall, offering tastings and selling on the spot.\n\n• Body: moisture-resistant MDF with slatted cladding, front lightbox in translucent or 3M flex printed with the products\n• Overhead frame: powder-coated steel box section carrying rattan pendants and themed decor\n• Typical size: 2.4-3 m long, with stock storage and a back shelf\n• Tip: make the front graphic a slide-in panel, so a new campaign only needs that panel reprinted\n\nTrường Thịnh designs, builds in its workshop and installs the counter.","altVi":"Quầy sampling gỗ bo cong bày bánh kẹo dừa trong trung tâm thương mại","altEn":"Curved timber sampling counter with coconut sweets in a shopping mall","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-07-sampling-counters-v2-audit-a026-v2.webp","sha256":"55e583cb845918cad13895d3ace4807a3f54f9175743c74a54b6ffdb28a01d5c","provenance":"AI-generated illustration; owner selected A026-v2 in HTML audit and confirmed in chat 2026-10-22; ChatGPT web gpt-image; original SHA256 7967a4b5a3e09187aae31e8074efd5f814d72f2e284e042ea6994832b38837da; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-08": {"descriptionVi":"Quầy lễ tân cong ốp nan sóng hợp với spa, phòng khám thẩm mỹ, văn phòng có sảnh nhỏ, nơi quầy cần mềm mại và không chiếm lối đi như quầy chữ L.\n\n• Kết cấu: khung MDF cắt CNC theo cung, ốp nan sóng sơn PU\n• Mặt quầy: đá nhân tạo solid surface uốn liền, không lộ đường nối\n• Kích thước thường làm: dài cung 2-3 m, cao 1-1,1 m\n• Lưu ý: quầy cong phải làm dưỡng theo bán kính thực tế, nên đo sảnh kỹ trước khi chốt bản vẽ\n\nTrường Thịnh đo mặt bằng, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A curved fluted reception desk suits spas, aesthetic clinics and offices with small lobbies, where the desk should feel soft and take less walkway than an L-shaped counter.\n\n• Build: CNC-cut MDF frame following the arc, fluted cladding in PU paint\n• Top: thermoformed solid surface in one piece with no visible joints\n• Typical size: 2-3 m along the arc, 1-1.1 m high\n• Tip: a curved desk is built on a template of the real radius, so measure the lobby carefully before signing off drawings\n\nTrường Thịnh measures the space, builds the desk in its workshop and installs it.","altVi":"Quầy lễ tân cong ốp nan sóng màu kem, chụp từ trên cao","altEn":"Cream curved reception desk with fluted cladding, seen from above","source":"/assets/content/projects/advertising/kiosk-posm/quay-le-tan-cong-nan-song.webp","sha256":"eed1e44c261f0af7d29f1971ba37e5674670b76c9ccdfcb9cd0d9b95183e280e","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adf7558-6a64-83ec-9b2a-081319dd5fe7, card #869); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-26 18:24Z; master PNG SHA256 422abeacb72b6272141c3f2430c24659693eeb944b9725f5d96e8e2468f69cec."},
  "kiosk-posm-09": {"descriptionVi":"Bục trưng bày sản phẩm có hộp mica úp hợp với showroom đồ uống, mỹ phẩm, nước hoa muốn đặt hàng mẫu gần cửa kính mà không lo bụi và tay khách.\n\n• Bục: MDF chống ẩm sơn PU nhiều lớp, chân âm sơn đen tạo khe hở với sàn\n• Hộp mica: mica trong 5 mm dán keo UV, mối dán không bọt khí\n• Kích thước thường làm: mặt 40x40 đến 50x50 cm, cao 70-110 cm, đặt so le theo bộ\n• Lưu ý: bục sát cửa kính hứng nắng chiều nên dùng sơn PU kháng UV để không ố vàng\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và giao lắp tận nơi.","descriptionEn":"Product display plinths with acrylic covers suit drinks, cosmetics and fragrance showrooms that want samples near the window without dust or handling.\n\n• Plinths: moisture-resistant MDF in several coats of PU paint, recessed black kick base\n• Covers: 5 mm clear acrylic bonded with UV adhesive for bubble-free joints\n• Typical size: tops 40x40 to 50x50 cm, 70-110 cm tall, staggered as a set\n• Tip: plinths by a sunny window need UV-resistant PU paint so they don't yellow\n\nTrường Thịnh designs, builds in its workshop and delivers and places the set.","altVi":"Ba bục MDF sơn màu cao thấp, mỗi bục úp hộp mica trong","altEn":"Three painted MDF plinths of varied height, each topped with a clear acrylic case","source":"/assets/content/projects/advertising/kiosk-posm/buc-trung-bay-hop-mica.webp","sha256":"c147b90851691cd85a4b057604f2daf7118e3feeffeabfcd78c403588d8434d1","provenance":"AI-generated illustration; source ID imagegen:2026-10-15:kiosk-posm-09-a; original SHA256 012fc271dc886ccceb8b50e1f7bcddba322e0eb542e3175e5c7b2b8ab2a05d95; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-10": {"descriptionVi":"Đảo trưng bày cửa hàng dạng tủ thấp có mặt đá hợp với cửa hàng gốm, mây tre, quà tặng có mặt bằng dài, cần chia lối đi và có thêm chỗ trữ hàng ngay dưới mặt bày.\n\n• Thân tủ: MDF chống ẩm sơn PU theo màu nhận diện, cánh mở nhấn không tay nắm\n• Mặt: đá nhân tạo hoặc solid surface, chịu va đập của đồ gốm\n• Viền: nẹp inox mạ vàng ở chân và mép mặt, LED dây âm dưới chân tủ\n• Kích thước thường làm: dài 2,4-3,6 m, sâu 0,8-1 m, cao 0,8-0,9 m\n\nTrường Thịnh thiết kế đồng bộ với kệ tường, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A low cabinet-style island display with a stone top suits ceramics, rattan and gift shops with long floor plans, dividing the aisle and adding storage right under the display surface.\n\n• Body: moisture-resistant MDF in PU paint matched to the brand colour, push-to-open doors\n• Top: engineered stone or solid surface that takes knocks from ceramics\n• Trim: gold-tone stainless at the plinth and top edge, LED strip recessed under the base\n• Typical size: 2.4-3.6 m long, 0.8-1 m deep, 0.8-0.9 m high\n\nTrường Thịnh designs it to match the wall shelving, builds in its workshop and installs it.","altVi":"Đảo trưng bày MDF sơn xanh, mặt đá trắng, LED hắt chân","altEn":"Green MDF island display with a white stone top and LED base light","source":"/assets/content/projects/advertising/kiosk-posm/dao-trung-bay-mat-da.webp","sha256":"45aca1bdf52282620f233c8b1ef090bf912b8b98ba1f97d35cd6a346290cba8f","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 9ffc62b352955b6001239a6cf625ff39a1c5eb9835db2fa1445521dead3e9db9."},
  "kiosk-posm-11": {"descriptionVi":"Vách trưng bày nến thơm dạng vòm cong hợp với thương hiệu nến, tinh dầu, quà tặng thuê ô nhỏ trong trung tâm thương mại, gom kệ, quầy và mảng thương hiệu vào một khối.\n\n• Vách: khung gỗ ốp MDF uốn, mảng tranh in UV trực tiếp lên tấm hoặc dán decal\n• Kệ: đợt gỗ veneer âm LED dây phía trên, ánh 2700-3000K hợp tông nến\n• Quầy trước: ốp lam gỗ, mặt đá terrazzo hoặc solid surface\n• Lưu ý: nến dễ mềm khi gần nguồn nóng, chọn LED dây có máng nhôm tản nhiệt và đặt cách mặt kệ vài cm\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"An arched display wall for scented candles suits candle, essential oil and gift brands renting a small mall unit, bringing shelving, counter and brand wall together in one piece.\n\n• Wall: timber frame with bent MDF, artwork UV printed directly on the board or applied as vinyl\n• Shelves: veneered timber with LED strip recessed above, 2700-3000K to suit candle tones\n• Front counter: slatted timber with a terrazzo or solid-surface top\n• Tip: candles soften near heat, so use LED strip in aluminium heat-sink channels set a few cm off the shelf\n\nTrường Thịnh designs, builds in its workshop and installs the unit.","altVi":"Vách trưng bày cong có kệ hắt sáng, quầy lam gỗ bày nến thơm","altEn":"Curved display wall with lit shelves and a slatted timber counter of scented candles","source":"/assets/content/projects/advertising/kiosk-posm/vach-trung-bay-nen-thom.webp","sha256":"9cfb560a10a9f0260bf4ee3f37eb58b279f86b2a6eb810cfb2018e52f06409ac","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adf757d-8878-83ec-8d44-59066c923cbe, card #870); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-26 18:24Z; master PNG SHA256 f248be8dc4882d00667c5d0ff81e61f964954abb2721731991847ebef584e71f."},
  "kiosk-posm-12": {"descriptionVi":"Gian hàng khuyến mãi siêu thị làm thành bộ POSM gỗ đồng bộ hợp với thương hiệu thực phẩm sạch, trái cây sấy, đồ ăn vặt chạy chương trình dùng thử, cần xe mời thử, kệ bán và standee cùng một phong cách.\n\n• Thành phần: xe đẩy mái gỗ, kệ tầng, bục, standee cắt hình, bảng treo\n• Chất liệu: gỗ thông, MDF chống ẩm in UV, cắt CNC theo hình\n• Kích thước thường làm: cụm ngang 3-4 m, kệ chính cao 2-2,4 m\n• Lưu ý: mỗi món nên tháo rời được và có chân chỉnh, vì sàn siêu thị thường không phẳng tuyệt đối\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A supermarket promotion stand built as a matching timber POSM set suits clean-food, dried-fruit and snack brands running tasting campaigns that need a sampling cart, sales shelving and standees in one style.\n\n• Components: canopied push cart, tiered shelving, plinths, shaped standees and hanging boards\n• Material: pine and moisture-resistant MDF, UV printed and CNC cut to shape\n• Typical size: 3-4 m wide as a group, main shelving 2-2.4 m tall\n• Tip: make every piece demountable with levelling feet, since supermarket floors are rarely perfectly flat\n\nTrường Thịnh designs, builds in its workshop and installs the set.","altVi":"Bộ POSM gỗ gồm xe đẩy, kệ tầng và standee lá trong siêu thị","altEn":"Timber POSM set with a cart, tiered shelves and leaf standee in a supermarket","source":"/assets/content/projects/advertising/kiosk-posm/gian-hang-khuyen-mai-sieu-thi.webp","sha256":"add347407290f73a8473208d2a5e723593ff1d1c709d86b6016e594a2a52b4db","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adf75a7-86b8-83ec-b6d4-e2d7b78a2951, card #856); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-26 18:24Z; master PNG SHA256 a1dff5abe9e3a01fb157f3487355e7f3e396d163d7a80c446402308347d8c604."},
  "kiosk-posm-13": {"descriptionVi":"Gian hàng triển lãm nội thất dạng mở hai mặt hợp với thương hiệu ván gỗ, vải rèm, gạch ốp đi hội chợ vật liệu xây dựng, nơi khách cần sờ mẫu thật và ngồi trao đổi đơn hàng.\n\n• Kết cấu: khung gỗ hoặc sắt hộp ốp MDF sơn đen mờ, sàn nâng phủ sàn gỗ công nghiệp\n• Vách mẫu: tấm mẫu treo trên ray, thay được theo bộ sưu tập\n• Kích thước thường làm: 6x6 m đến 9x9 m, có quầy bar và khu ngồi\n• Lưu ý: dùng chính vật liệu của hãng để ốp vách gian, vừa là mẫu trưng bày vừa bớt chi phí in\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và thi công trọn gói từ lúc dựng đến khi tháo gian hàng.","descriptionEn":"An open two-sided interior design exhibition booth suits board, curtain fabric and tile brands at building materials fairs, where buyers need to touch real samples and sit down to talk orders.\n\n• Structure: timber or steel box frame clad in matt black MDF, raised floor finished in laminate flooring\n• Sample walls: panels hung on rails, swapped with each collection\n• Typical size: 6x6 m to 9x9 m, with a bar counter and seating area\n• Tip: clad the booth walls in the brand's own materials, which doubles as a display and cuts print costs\n\nTrường Thịnh designs, builds and handles the booth from set-up to take-down.","altVi":"Gian triển lãm vách gỗ tối, kệ mẫu vật liệu và quầy tư vấn","altEn":"Dark timber exhibition booth with material sample walls and a consultation bar","source":"/assets/content/projects/advertising/kiosk-posm/gian-hang-trien-lam-noi-that.webp","sha256":"760a1908e500a58e3e3acedc403aac7df553083ca358d72167ba85e0126f4af0","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adf75db-880c-83ec-b429-016ab7ca2ad4, card #871); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-26 18:24Z; master PNG SHA256 0a7c16a280155b8b6bfadd5a889e5ed4a9bac3cd8581e1469e2d70e79bf8df39."},
  "kiosk-posm-14": {"descriptionVi":"Kệ trưng bày đồ thủ công gồm đảo giữa và kệ tường hợp với cửa hàng đồ gáo dừa, gốm, mây tre, nơi khách thích đi vòng và cầm từng món lên xem.\n\n• Đảo giữa: MDF chống ẩm bo cong, ốp lam gỗ, mặt veneer sồi phủ PU\n• Kệ tường: khung sắt sơn đen, đợt gỗ dày 25-30 mm chịu được đồ nặng\n• Đèn: LED dây hắt chân và âm dưới đợt kệ, ánh 3000K hợp tông gỗ\n• Lưu ý: đợt kệ dài trên 90 cm nên có ke đỡ giữa, đồ thủ công nặng dễ làm võng ván\n\nTrường Thịnh thiết kế theo mặt bằng, đóng kệ tại xưởng và lắp đặt trọn gói.","descriptionEn":"Handicraft display shelving with a central island and wall units suits shops selling coconut-shell ware, ceramics and rattan, where customers like to walk around and pick pieces up.\n\n• Island: curved moisture-resistant MDF, slatted timber cladding, PU-finished oak veneer top\n• Wall units: black steel frame with 25-30 mm timber shelves for heavy pieces\n• Lighting: LED strip at the base and under each shelf, 3000K to suit the wood tones\n• Tip: shelves over 90 cm long need a centre bracket, because heavy handicrafts make boards sag\n\nTrường Thịnh designs to your floor plan, builds the shelving in its workshop and installs it.","altVi":"Đảo kệ gỗ hai tầng chân lam bày chén bát gáo dừa","altEn":"Two-tier timber island with a slatted base displaying coconut-shell bowls","source":"/assets/content/projects/advertising/kiosk-posm/ke-trung-bay-do-thu-cong.webp","sha256":"9442b0bc5b8b6fa681b6335ed833571213a7d83599dd013c4863b073153fcb2a","provenance":"AI-generated illustration; owner explicitly approved latest chat image A033-v3 on 2026-10-23; ChatGPT web; model unknown; original SHA256 fbd0e2bb81c0872464d33f664ecafba947a697d4aa1ff0b405e9e051f4003282; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-15": {"descriptionVi":"Tủ kính trưng bày có hộp đèn tên hợp với cửa hàng lưu niệm, đồ mỹ nghệ, quầy đặc sản cần bày hàng nhỏ, dễ vỡ mà vẫn đặt tên thương hiệu ngay trên tủ.\n\n• Khung tủ: MDF chống ẩm phủ veneer hoặc laminate, cửa kính lùa có khóa\n• Kệ: kính cường lực 8 mm, chịu được đồ gốm, đồ gỗ nặng\n• Kích thước thường làm: ngang 1,6-2,4 m, cao 2-2,2 m\n• Lưu ý: tủ đặt gần lối ra vào nên dùng kính cường lực cho cả cánh để an toàn khi va chạm\n\nTrường Thịnh thiết kế theo sản phẩm, đóng tủ tại xưởng và lắp đặt trọn gói.","descriptionEn":"A glass display cabinet with a lit name header suits souvenir, handicraft and local-speciality shops that need to show small, fragile pieces with the brand right above them.\n\n• Body: moisture-resistant MDF with veneer or laminate, lockable sliding glass doors\n• Shelves: 8 mm toughened glass that carries heavy ceramics and woodwork\n• Typical size: 1.6-2.4 m wide, 2-2.2 m tall\n• Tip: for cabinets near the entrance, use toughened glass in the doors too in case of knocks\n\nTrường Thịnh designs around the products, builds the cabinet in its workshop and installs it.","altVi":"Tủ kính bày đồ mỹ nghệ dừa, đầu tủ có hộp đèn tên","altEn":"Glass display cabinet of coconut handicrafts with a lightbox name header","source":"/assets/content/projects/advertising/kiosk-posm/tu-kinh-trung-bay-my-nghe.webp","sha256":"20f6b7b0b72c92fc25f59ad50afda771a6826e6ab2a87fda5c0f0d0b92992f39","provenance":"AI-generated illustration; owner selected A034-v2 in HTML audit and confirmed in chat 2026-10-22; ChatGPT web gpt-image; original SHA256 bf960aa701ed1a2d91cebb9a542494c719c16b1fa6d8f52d49026fe26408a012; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-16": {"descriptionVi":"Kệ trưng bày hội chợ kèm vách cong in tranh hợp với thương hiệu mỹ nghệ, quà lưu niệm đi hội chợ, triển lãm, cần một góc bày hàng có câu chuyện riêng giữa nhiều gian giống nhau.\n\n• Bục: MDF bo cong ốp lam, tháo rời thành từng khối để chở\n• Kệ: khung thép hộp sơn tĩnh điện, đợt gỗ dày\n• Vách cong: khung gỗ uốn, in UV hoặc dán decal, thay tranh được cho kỳ sau\n• Lưu ý: hỏi trước ban tổ chức giới hạn chiều cao vách và giờ được vào dựng gian\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và thi công trọn gói tại hội chợ.","descriptionEn":"Trade fair display shelving with a curved printed wall suits handicraft and souvenir brands at fairs and exhibitions that want a corner with its own story among rows of similar booths.\n\n• Plinths: curved MDF with slatted cladding, splitting into separate blocks for transport\n• Shelf: powder-coated steel box frame with thick timber boards\n• Curved wall: bent timber frame, UV printed or vinyl-wrapped, with artwork replaceable for the next show\n• Tip: check the organiser's wall height limit and build-up hours before finalising the design\n\nTrường Thịnh designs, builds in its workshop and sets everything up at the fair.","altVi":"Bục gỗ nhiều bậc bày bình gáo dừa trước vách cong in tranh","altEn":"Stepped timber plinths of coconut-shell vases before a curved printed wall","source":"/assets/content/projects/advertising/kiosk-posm/ke-trung-bay-hoi-cho.webp","sha256":"ed0bae062ded6879f42db46c5e56e2f244e33f0c7d7f30c5171de46a55662403","provenance":"AI-generated illustration; owner explicitly approved latest chat image A035-v3 on 2026-10-23; ChatGPT web; model unknown; original SHA256 9d15e1bdfa2ed8f2ca8fde8278ceb8885ffed737e6eba364e340cfe2bcf34990; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-17": {"descriptionVi":"Kiosk mỹ phẩm có bàn trang điểm hợp với thương hiệu son, nước hoa, chăm sóc da thuê ô trong trung tâm thương mại, cần chỗ cho khách ngồi thử và nhân viên tư vấn tại quầy.\n\n• Khung: sắt hộp hoặc nhôm bọc inox mạ vàng, ốp MDF sơn PU\n• Kệ tường: đợt kính hoặc mica, LED thanh âm 4000K giữ đúng màu son phấn\n• Quầy: mặt đá nhân tạo vân marble, thân lam bo cong\n• Lưu ý: gương trang điểm nên dùng LED có chỉ số hoàn màu CRI trên 90, ánh lệch màu thì khách chọn sai tông\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A cosmetics kiosk with a make-up station suits lipstick, fragrance and skincare brands renting a mall plot that need somewhere for customers to sit and try products with staff advice.\n\n• Frame: steel or aluminium wrapped in gold-tone stainless, PU-painted MDF cladding\n• Wall shelves: glass or acrylic, recessed 4000K LED bars that keep make-up colours true\n• Counter: marble-look engineered stone top on a curved slatted base\n• Tip: use LED with a CRI above 90 for the vanity mirror, or customers pick the wrong shade\n\nTrường Thịnh designs, builds in its workshop and installs the kiosk.","altVi":"Kiosk mỹ phẩm tông hồng viền vàng, gương tròn có đèn và quầy đá","altEn":"Pink and gold cosmetics kiosk with a lit round mirror and marble-look counter","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-my-pham-ban-trang-diem.webp","sha256":"5b9eacab54f409b622f5b4b45df7a29a64738c8c02befd180709720d20ee73d3","provenance":"AI-generated illustration; owner approved A036-v3 in chat 2026-10-23; ChatGPT web; model unknown; original SHA256 f1bd50f039546c9646ced73c4bd3c32c008ee991e400723b29c82fba4554407e; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-18": {"descriptionVi":"Kiosk tư vấn du lịch hợp với công ty lữ hành, khu du lịch, điểm đến địa phương quảng bá tour trong trung tâm thương mại, gói quầy ngồi tư vấn và kệ tờ rơi trong một ô nhỏ.\n\n• Khung: gỗ uốn cong hoặc sắt hộp ốp lam gỗ, mái bạt căng\n• Tranh: bạt hoặc vải in UV căng khung, thay theo mùa tour\n• Kích thước thường làm: 3x3 m đến 3x4 m\n• Lưu ý: kệ tờ rơi nên đặt sát lối đi, khách thường lấy tài liệu trước rồi mới ngồi hỏi\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A travel consultation kiosk suits tour operators, resorts and local destinations promoting tours in a shopping mall, fitting a seated advice counter and brochure racks into a small plot.\n\n• Frame: bent timber or steel box section with timber slats, tensioned fabric canopy\n• Graphics: UV-printed banner or fabric on frames, changed with the tour season\n• Typical size: 3x3 m to 3x4 m\n• Tip: put the brochure rack right on the walkway, as visitors usually grab a leaflet before sitting down to ask\n\nTrường Thịnh designs, builds in its workshop and installs the kiosk.","altVi":"Kiosk du lịch khung gỗ cong, tranh in sông nước, quầy và đôn mây","altEn":"Curved timber travel kiosk with river-scene prints, a counter and rattan stools","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-tu-van-du-lich.webp","sha256":"49a2549c585e12ea70328a926f9a656b255a1a3043deec16cef0e6778aceef53","provenance":"AI-generated illustration; edited by owner in ChatGPT web; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-27; master PNG SHA256 5553915cc337c10558a9170a93739ff0249e6aaf9872bd2659d0b9f8e586e130."},
  "kiosk-posm-19": {"descriptionVi":"Quầy dùng thử sản phẩm ốp nan tre hợp với chương trình sampling ngắn ngày trong siêu thị, hội chợ đặc sản, khi thương hiệu cần một quầy dựng nhanh mà vẫn mang chất miệt vườn.\n\n• Khung: gỗ thông hoặc sắt hộp, ốp nan tre thật hoặc lam nhựa giả tre\n• Mái: khung gỗ lợp lá giả, bảng tên cắt CNC treo trên khung\n• Kích thước thường làm: dài 2-3 m, chia khu rót thử và khu bán\n• Lưu ý: nan tre thật cần quét dầu chống mốc, nhất là khi quầy chở đi nhiều điểm\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và giao lắp tận nơi trọn gói.","descriptionEn":"A bamboo-clad product tasting counter suits short in-store sampling runs in supermarkets and speciality fairs, when a brand needs a counter that goes up quickly and still feels countryside-made.\n\n• Frame: pine or steel box section, clad in real bamboo or bamboo-look PVC slats\n• Canopy: timber frame with faux thatch, CNC-cut name boards hung from the frame\n• Typical size: 2-3 m long, split into a tasting area and a sales area\n• Tip: real bamboo needs an anti-mould oil, especially if the counter travels between sites\n\nTrường Thịnh designs, builds in its workshop and delivers and installs on site.","altVi":"Quầy dùng thử ốp nan tre mái lá bày sản phẩm dừa","altEn":"Bamboo-clad tasting counter with a thatch canopy, coconut drinks and snacks","source":"/assets/content/projects/advertising/kiosk-posm/quay-dung-thu-san-pham-tre.webp","sha256":"b8024114f8c7c164c5ce9e421883e393bc0c613c427550377ecb494d9fe8ea66","provenance":"AI-generated illustration; edited by owner in ChatGPT web; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-27; master PNG SHA256 92026a1616da2edb425fceec4ce60e501c225157ae48a0c2befbf188308cce9b."},
  "kiosk-posm-20": {"descriptionVi":"Quầy lễ tân sự kiện bo cong hợp với ban tổ chức triển lãm, hội nghị, lễ khai mạc, cần một điểm đón khách và đăng ký tại lối vào đúng chủ đề chương trình.\n\n• Thân quầy: khung gỗ ốp lam dọc, mặt MDF sơn trắng hoặc đá nhân tạo\n• Chữ: in UV hoặc decal cắt dán mặt quầy, thay theo từng sự kiện\n• Kích thước thường làm: dài 2,4-3,6 m, cao 1,05-1,1 m\n• Lưu ý: chừa lỗ đi dây cho laptop, máy in thẻ và đèn hắt chân ngay từ bản vẽ\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và thi công trọn gói tại địa điểm sự kiện.","descriptionEn":"A curved event reception counter suits exhibition, conference and opening ceremony organisers who need a welcome and registration point at the entrance that fits the event theme.\n\n• Body: timber frame with vertical slats, white-painted MDF or engineered stone top\n• Lettering: UV print or cut vinyl on the counter face, changed for each event\n• Typical size: 2.4-3.6 m long, 1.05-1.1 m high\n• Tip: plan cable holes for laptops, badge printers and base lighting at the drawing stage\n\nTrường Thịnh designs, builds in its workshop and installs at the venue.","altVi":"Quầy lễ tân cong ốp lam gỗ, mặt trắng, vách sau in tán dừa","altEn":"Curved slatted reception counter with a white top and a coconut-palm print behind","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-20-event-reception-counters-audit-a039-v2.webp","sha256":"1ca8b97e3e3a6935ddb87c3ffd16f8ff7be9fe111642396e84b357f6ca7aa180","provenance":"AI-generated illustration; edited by owner in ChatGPT web; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-27; master PNG SHA256 fcec895c16c8652ac3fd694862e2464f1dab43aa62d4c083ee653235e52f1c7c."},
  "kiosk-posm-21": {"descriptionVi":"Bục trưng bày nhiều bậc bo cong hợp với cửa hàng, gian hàng đồ mỹ nghệ, gốm, quà lưu niệm, bày được nhiều món cao thấp trên một cụm mà món nào cũng có chỗ riêng.\n\n• Chất liệu: MDF chống ẩm uốn cong sơn PU trắng, khối lam gỗ xen giữa\n• Đèn: LED dây âm dưới mép từng bậc, nguồn giấu trong lòng bục\n• Kích thước thường làm: dài 2-3 m, mỗi bậc cao 20-30 cm, ghép thành cụm 3-4 khối\n• Lưu ý: sơn PU trắng dễ lộ vết xước, nên phủ thêm lớp bóng mờ chịu mài mòn\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"Curved stepped display plinths suit handicraft, ceramics and souvenir shops and booths, holding pieces of many heights in one group while giving each its own spot.\n\n• Material: curved moisture-resistant MDF in white PU paint, with slatted timber blocks between\n• Lighting: LED strip recessed under each step, power supply hidden inside\n• Typical size: 2-3 m long, steps 20-30 cm high, grouped from 3-4 blocks\n• Tip: white PU shows scratches, so add a hard-wearing satin topcoat\n\nTrường Thịnh designs, builds in its workshop and installs the set.","altVi":"Bục trưng bày nhiều bậc sơn trắng phối lam gỗ, bày đồ gáo dừa","altEn":"Stepped white plinths with slatted timber, holding coconut-shell crafts","source":"/assets/content/projects/advertising/kiosk-posm/buc-trung-bay-nhieu-bac.webp","sha256":"98a2b1a5a21dc06404fe5b7c1b2b085e3b3e51a3f161b4395f9f569ea33df194","provenance":"AI-generated illustration; owner selected A040-v2 in HTML audit and confirmed in chat 2026-10-22; ChatGPT web gpt-image; original SHA256 7492121998bfcd05f2535c46023c1f3d86819ca70edb63c0c6b925582b723f81; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-22": {"descriptionVi":"Đảo trưng bày nhiều tầng đặt giữa sảnh hợp với thương hiệu đồ gia dụng thủ công thuê điểm ngắn hạn trong trung tâm thương mại, khi ô thuê không có tường để dựa kệ.\n\n• Chất liệu: MDF chống ẩm uốn cong, veneer hai tông phủ PU\n• Đèn: LED dây hắt dưới từng tầng, dây điện đi trong lòng khối\n• Kích thước thường làm: dài 2,4-3,6 m, tầng trên cùng cao 1,2-1,5 m\n• Lưu ý: làm từng khối rời có bánh xe giấu, tiện xoay hướng hoặc chuyển sang điểm khác\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A multi-tier island display suits handcrafted homeware brands taking a short-term atrium plot in a mall, where there is no wall to stand shelving against.\n\n• Material: curved moisture-resistant MDF with two-tone veneer and PU finish\n• Lighting: LED strip under each tier, wiring run inside the blocks\n• Typical size: 2.4-3.6 m long, top tier 1.2-1.5 m high\n• Tip: build it as separate blocks on hidden castors, easy to re-angle or move to another site\n\nTrường Thịnh designs, builds in its workshop and installs the display.","altVi":"Đảo trưng bày nhiều tầng ốp gỗ hai tông giữa sảnh thương mại","altEn":"Multi-tier two-tone timber island display in a mall concourse","source":"/assets/content/projects/advertising/kiosk-posm/dao-trung-bay-nhieu-tang.webp","sha256":"07d48fbe914ed0eae00d6de4c99f003c5250f08c802e563297d8828f47215508","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 d701cc517afb4afcce227a932ca4b1ef191e3c8e6f51747339ce0c5c95f1c862."},
  "kiosk-posm-23": {"descriptionVi":"Kệ trưng bày mỹ phẩm gắn vách cong hợp với thương hiệu mỹ phẩm thiên nhiên mở điểm bán trong trung tâm thương mại, bày đủ cả dòng sản phẩm trên một mảng tường.\n\n• Vách: khung gỗ, MDF uốn cong, mảng in UV hoặc dán decal\n• Kệ: đợt gỗ veneer âm LED, sâu 20-25 cm vừa chai lọ mỹ phẩm\n• Quầy và bục: trụ tròn ốp lam, mặt solid surface dễ lau\n• Lưu ý: chai lọ cao thấp khác nhau nên làm đợt kệ chỉnh được khoảng cách trên ray\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"Cosmetics display shelving built into a curved wall suits natural beauty brands opening a mall pitch, holding the whole product range on a single wall.\n\n• Wall: timber frame with bent MDF, UV printed or vinyl-wrapped panels\n• Shelves: veneered timber with recessed LED, 20-25 cm deep to fit bottles and jars\n• Counter and plinths: round slatted bases with easy-wipe solid-surface tops\n• Tip: with bottles of different heights, mount the shelves on rails so spacing can be adjusted\n\nTrường Thịnh designs, builds in its workshop and installs the display.","altVi":"Kệ mỹ phẩm dừa âm vách cong in hình, quầy lam gỗ","altEn":"Coconut cosmetics on shelves set into a curved printed wall, slatted counter in front","source":"/assets/content/projects/advertising/kiosk-posm/ke-trung-bay-my-pham-vach-cong.webp","sha256":"a2334b6c948d1070d36801af3fb95833e08d1be89b7d630f078ad9ed50b50b97","provenance":"AI-generated illustration; edited by owner in ChatGPT web; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-27; master PNG SHA256 57782bd636340d686e1259fc49ddd217af67662b05a33bdf59a3211e82c1ce66."},
  "kiosk-posm-24": {"descriptionVi":"Bộ trưng bày mỹ phẩm theo chiến dịch (POSM) hợp với nhãn hàng chạy chương trình ngắn ngày ở trung tâm thương mại, siêu thị, dựng xong trong một đêm và tháo mang đi điểm khác.\n\n• Thành phần: standee bo góc, vách vòm in, bục tròn, kệ đứng nhiều tầng\n• Chất liệu: MDF hoặc formex in UV, bục ốp lam gỗ, chân đế có ốc chỉnh\n• Kích thước thường làm: cụm ngang 2-3 m, standee cao 1,8-2 m\n• Lưu ý: làm khung cố định, mặt in dạng lắp ghép thì chiến dịch sau chỉ cần in lại mặt\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói tại điểm bán.","descriptionEn":"A campaign cosmetics display set (POSM) suits brands running short promotions in malls and supermarkets, going up overnight and moving on to the next location afterwards.\n\n• Components: round-cornered standees, a printed arch wall, round plinths and a tiered shelf unit\n• Material: UV-printed MDF or foam PVC board, slatted plinths, adjustable feet\n• Typical size: 2-3 m wide as a group, standees 1.8-2 m tall\n• Tip: keep the frames fixed and the printed faces modular, so the next campaign only needs new faces\n\nTrường Thịnh designs, builds in its workshop and installs the set in store.","altVi":"Standee, bục tròn và kệ tầng gỗ bày mỹ phẩm dừa chủ đề biển","altEn":"Beach-themed standees, round plinths and a timber shelf unit for coconut cosmetics","source":"/assets/content/projects/advertising/kiosk-posm/bo-trung-bay-my-pham.webp","sha256":"250de996cabeb7b80a3020a7376f05f81ce124c32c138d5daca886091001c3ab","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd49c-b338-83ec-96c8-430ba0b1639c); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-27 01:07Z; master PNG SHA256 c75e25a96630001175181584355a92b00dcfa9700287d41bc3141d40a192a335."},
  "kiosk-posm-25": {"descriptionVi":"Gian hàng hội chợ khung nhôm định hình là lựa chọn tiết kiệm cho hợp tác xã, doanh nghiệp nông sản đi hội chợ, vì khung thuê theo kỳ, chỉ phần in và đồ gỗ là làm mới.\n\n• Kết cấu: khung nhôm định hình tiêu chuẩn, vách panel trắng hoặc bạt căng in UV\n• Đồ gỗ: quầy ốp lam, kệ gỗ có đèn, làm rời để dùng lại kỳ sau\n• Kích thước thường làm: 3x3 m, 3x6 m theo ô tiêu chuẩn của ban tổ chức\n• Lưu ý: gửi file in sớm 5-7 ngày, bạt in gấp dễ lệch màu so với bao bì sản phẩm\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và thi công trọn gói từ lúc dựng đến khi tháo gian hàng.","descriptionEn":"An aluminium-frame trade fair booth is the budget choice for cooperatives and farm-produce companies, since the frame is hired per show and only the graphics and joinery are new.\n\n• Structure: standard aluminium system frame, white panels or UV-printed tension fabric\n• Joinery: slatted counter and lit timber shelves, demountable for reuse\n• Typical size: 3x3 m or 3x6 m to the organiser's standard plot\n• Tip: send print files 5-7 days ahead, as rushed banners often drift in colour from the packaging\n\nTrường Thịnh designs, builds and handles the booth from set-up to take-down.","altVi":"Gian hàng hội chợ khung nhôm, vách in vườn dừa và kệ sản phẩm","altEn":"Aluminium-frame trade fair booth with coconut grove graphics and product shelves","source":"/assets/content/projects/advertising/kiosk-posm/gian-hang-hoi-cho-khung-nhom.webp","sha256":"d3f11d8a7f308fb26e48849cb6b0422d7f7550d9d3470292378ac8d10135c3c5","provenance":"Derivative of accepted source SHA-256 67c25939a98a3659b7f5d8b47c3f8687828a9b551de15e7630c0f659373cda93; source-assets/projects/advertising/taxonomy-20260910-review/acceptance.json; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-26": {"descriptionVi":"Gian hàng triển lãm dạng đảo bốn mặt hợp với thương hiệu thực phẩm, đồ uống đi hội chợ lớn, cần quầy pha chế để khách nếm tại chỗ và đủ chỗ cho nhiều nhân viên đứng quầy.\n\n• Kết cấu: khung sắt hộp ốp MDF chống ẩm, mái bảng tên in UV bốn mặt\n• Quầy: bo cong ốp lam, mặt solid surface chịu nước, có bồn rửa và ổ điện riêng\n• Kích thước thường làm: 6x6 m đến 9x12 m\n• Lưu ý: đăng ký trước với ban tổ chức điện ba pha và cấp nước nếu có máy pha cà phê, bếp nấu\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và thi công trọn gói từ lúc dựng đến khi tháo gian hàng.","descriptionEn":"An island exhibition booth open on four sides suits food and drink brands at major fairs that need a bar for on-the-spot tastings and room for several staff at the counters.\n\n• Structure: steel box frame clad in moisture-resistant MDF, canopy fascia UV printed on all four sides\n• Counters: curved and slatted, water-resistant solid-surface tops, with a sink and dedicated power\n• Typical size: 6x6 m to 9x12 m\n• Tip: book three-phase power and a water supply with the organiser early if there is an espresso machine or cooking\n\nTrường Thịnh designs, builds and handles the booth from set-up to take-down.","altVi":"Gian hàng đảo có mái bảng tên, quầy pha chế và quầy bày dừa","altEn":"Island exhibition booth with a branded canopy, coffee bar and coconut product counters","source":"/assets/content/projects/advertising/kiosk-posm/gian-hang-trien-lam-dang-dao.webp","sha256":"ad70c869435f448a5c13cf56f98e77257cb79426335daf1776ab5c33df5e29b4","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:kiosk-posm-26-1; original SHA256 aa959c5254b2ed5b574aa08e238913bade0b59131b552a2ea4d177d20f90f060; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-27": {"descriptionVi":"Gian hàng triển lãm tiêu chuẩn nâng cấp bằng đồ gỗ hợp với thương hiệu mỹ phẩm nhỏ lần đầu đi hội chợ, giữ chi phí của gian khung nhôm mà vẫn có chỗ làm mẫu và tư vấn.\n\n• Kết cấu: khung nhôm định hình của ban tổ chức, ốp thêm tranh in và bảng tên\n• Đồ gỗ: kệ nhiều tầng, quầy giới thiệu ốp lam, kệ góc cho mẫu thử\n• Kích thước thường làm: 3x3 m hoặc 3x6 m, sàn trải thảm\n• Lưu ý: đo lại ô gian thực tế trước khi đóng kệ, khung nhôm chiếm vài cm mỗi cạnh\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và thi công trọn gói tại hội chợ.","descriptionEn":"A standard shell-scheme exhibition booth upgraded with timber joinery suits small cosmetics brands at their first fair, keeping shell-scheme costs while making room for demos and consultations.\n\n• Structure: the organiser's aluminium system frame, with added printed panels and a name fascia\n• Joinery: tiered shelving, a slatted product counter and a corner unit for testers\n• Typical size: 3x3 m or 3x6 m, carpeted floor\n• Tip: measure the actual plot before the shelves are built, as the frame takes a few cm on each side\n\nTrường Thịnh designs, builds in its workshop and sets up the booth at the fair.","altVi":"Gian khung nhôm bày mặt nạ dừa, kệ gỗ và bàn tiếp khách","altEn":"Aluminium shell-scheme booth with coconut face masks, timber shelves and a meeting table","source":"/assets/content/projects/advertising/kiosk-posm/gian-hang-trien-lam-tieu-chuan.webp","sha256":"d0bf57e79844c6baaa827c7a5680bb810726641d44981cb13f8bd8595f9f6425","provenance":"Derivative of accepted source SHA-256 5c0a654a71025f6b1870b657429c5e4e5010ac4f929cf709849da3ce62be7f21; source-assets/projects/advertising/taxonomy-20260910-review/acceptance.json; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-28": {"descriptionVi":"Gian hàng triển lãm mỹ phẩm thiết kế riêng hợp với thương hiệu làm đẹp đi hội chợ, triển lãm chuyên ngành, cần khác hẳn các gian khung nhôm và có chỗ ngồi tiếp đại lý.\n\n• Kết cấu: khung gỗ, sắt hộp, ốp MDF uốn cong sơn PU, lam nhôm vân gỗ\n• Quầy: đá nhân tạo vân marble, chân bọc inox mạ vàng hồng\n• Kích thước thường làm: 6x6 m đến 9x9 m, có kho nhỏ phía sau\n• Lưu ý: mái vòng cung cần bản vẽ kết cấu, nhiều ban tổ chức yêu cầu nộp trước để duyệt\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và thi công trọn gói từ lúc dựng đến khi tháo gian hàng.","descriptionEn":"A custom cosmetics exhibition booth suits beauty brands at trade fairs and industry shows that want to stand apart from the shell-scheme rows and have seating for meeting distributors.\n\n• Structure: timber and steel box frame, bent MDF in PU paint, woodgrain aluminium slats\n• Counter: marble-look engineered stone on a rose-gold stainless base\n• Typical size: 6x6 m to 9x9 m, with a small store room behind\n• Tip: curved overhead rings need structural drawings, and many organisers require them for approval in advance\n\nTrường Thịnh designs, builds and handles the booth from set-up to take-down.","altVi":"Gian triển lãm mỹ phẩm bo cong hồng đất, quầy đá, góc tiếp khách","altEn":"Curved terracotta-pink cosmetics exhibition booth with a stone counter and lounge corner","source":"/assets/content/projects/advertising/kiosk-posm/gian-hang-trien-lam-my-pham.webp","sha256":"ccea7de9c6bcbac119217eefd4ac53abf64e4673ccc2236ede596266bf0c9fdc","provenance":"Derivative of accepted source SHA-256 6f6b2bda8a0a1b9d1feaf67be3e874f4125b792275088a738713db1f19c216cf; source-assets/projects/advertising/taxonomy-20260910-review/acceptance.json; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-29": {"descriptionVi":"Gian hàng triển lãm thời trang khung nhôm sơn đen hợp với thương hiệu quần áo, vải lanh, đồ thiết kế đi hội chợ, tuần lễ thời trang, cần trình bày cả bộ sưu tập như một cửa hàng thu nhỏ.\n\n• Kết cấu: khung nhôm sơn tĩnh điện đen, vách MDF sơn trắng, bảng tên chữ nổi\n• Trưng bày: giá treo thép, bục và kệ gỗ xếp đồ gấp, gương đứng\n• Đèn: rọi ray 3000-4000K, chỉnh hướng theo từng giá treo\n• Kích thước thường làm: 6x6 m đến 6x9 m\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và thi công trọn gói từ lúc dựng đến khi tháo gian hàng.","descriptionEn":"A black-frame fashion exhibition booth suits clothing, linen and designer labels at trade fairs and fashion weeks that want to present a full collection like a small shop.\n\n• Structure: black powder-coated aluminium frame, white-painted MDF walls, raised-letter fascia\n• Display: steel garment rails, timber plinths and folding shelves, a floor mirror\n• Lighting: 3000-4000K track spots, aimed at each rail\n• Typical size: 6x6 m to 6x9 m\n\nTrường Thịnh designs, builds and handles the booth from set-up to take-down.","altVi":"Gian triển lãm thời trang khung đen, giá treo thép và ma-nơ-canh","altEn":"Black-frame fashion exhibition booth with steel garment rails and mannequins","source":"/assets/content/projects/advertising/kiosk-posm/gian-hang-trien-lam-thoi-trang.webp","sha256":"aca3b04fedab2382eb885a498b2bdc1807667018e94ec627a131bf97a968c367","provenance":"Derivative of accepted source SHA-256 30fad3bc843b5c6d2b880ec84ff699310a6a4f3d440d1b1d4171c3b218d92d11; source-assets/projects/advertising/taxonomy-20260910-review/acceptance.json; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-30": {"descriptionVi":"Gian hàng hội chợ nông sản dạng giao thương hợp với doanh nghiệp nguyên liệu, hàng xuất khẩu, nơi khách mua sỉ cần xem mẫu thật, quy cách đóng bao và ngồi bàn đơn hàng.\n\n• Kết cấu: khung nhôm định hình, vách in UV hình nguyên liệu và tên công ty\n• Trưng bày: kệ thép tải nặng cho bao mẫu, quầy mẫu nhỏ chia theo loại hàng\n• Kích thước thường làm: 3x6 m hoặc 6x6 m, có góc bàn tiếp khách\n• Lưu ý: in quy cách, chứng nhận và mã QR liên hệ lên vách, khách mua sỉ hay chụp lại để gửi về công ty\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và thi công trọn gói tại hội chợ.","descriptionEn":"A B2B agricultural trade fair booth suits ingredient suppliers and exporters, where wholesale buyers need to see real samples and bag specs and sit down to discuss orders.\n\n• Structure: aluminium system frame, UV-printed walls showing the raw materials and company name\n• Display: heavy-duty steel racking for sample sacks, small sample counter split by grade\n• Typical size: 3x6 m or 6x6 m, with a meeting table\n• Tip: print specs, certifications and a contact QR code on the walls, since buyers photograph them to send back to the office\n\nTrường Thịnh designs, builds in its workshop and sets up the booth at the fair.","altVi":"Gian hội chợ khung nhôm có kệ thép xếp bao nguyên liệu dừa","altEn":"Aluminium-frame fair booth with steel racks of coconut ingredient sacks","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-30-trade-fair-coconut-ingredients.webp","sha256":"28d9187e6b012434e7710f5c41284fcb5b971c3bdb3ae321c94f87410b5c0edb","provenance":"Derivative of accepted source SHA-256 3e0fe6a7e1059a8d864edea3fdb09f611fc017d11486d9ded0970139fe637067; source-assets/projects/advertising/taxonomy-20260910-review/acceptance.json; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "mobile-retail-01": {"descriptionVi":"Xe đẩy nước dừa khung sắt hợp với thương hiệu nước dừa, nước đóng chai mở điểm bán trong trung tâm thương mại, sảnh siêu thị, nơi mặt bằng thuê theo mét vuông và hay phải đổi vị trí.\n\n• Khung xe: sắt hộp sơn tĩnh điện, kệ gỗ thông hoặc gỗ cao su phủ PU chống nước\n• Bánh xe: bánh PU giảm ồn có khóa, không để vệt trên sàn đá\n• Kích thước thường làm: dài 1,0-1,4 m, rộng 0,6-0,7 m, cao tổng 1,8-2,0 m\n• Lưu ý: chỗ để đá trên mặt gỗ cần khay inox có gờ chặn nước, tránh gỗ ngấm nước nở mặt\n\nTrường Thịnh thiết kế, đóng xe tại xưởng và giao tận nơi trọn gói.","descriptionEn":"A steel coconut water cart suits coconut water and bottled drink brands selling in shopping centres and supermarket lobbies, where floor space is rented by the square metre and the pitch often moves.\n\n• Frame: powder-coated steel box section, pine or rubberwood shelves with a waterproof PU finish\n• Wheels: quiet PU casters with brakes that leave no marks on stone floors\n• Typical size: 1.0-1.4 m long, 0.6-0.7 m deep, 1.8-2.0 m tall overall\n• Tip: ice on a timber top needs a stainless tray with a drip lip, or the wood swells\n\nTrường Thịnh designs, builds the cart in its workshop and delivers it ready to use.","altVi":"Xe đẩy nước dừa khung sắt xanh, kệ gỗ, giữa sảnh thương mại","altEn":"Green steel coconut water cart with three timber shelves in a shopping centre","source":"/assets/content/projects/advertising/mobile-retail/xe-day-nuoc-dua-ke-go.webp","sha256":"0bf24c40a8d0b440c609734b2190756655a0318732bfff1f7c806f1d06442f9d","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:mobile-retail-01-a; original SHA256 9a1dbf8610a5bc93a7d595d3b1e9858de6adfd39ef8d44ea1f7cbffcaa5771ef; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "mobile-retail-02": {"descriptionVi":"Xe bán cà phê mang đi hợp với mô hình bán buổi sáng trước tòa văn phòng, cổng khu công nghiệp, bệnh viện, nơi khách mua nhanh và không cần chỗ ngồi.\n\n• Khung xe: sắt hộp sơn tĩnh điện, mặt quầy inox 304, bánh xe có khóa\n• Thân xe: alu dán decal, dễ lau và dễ thay mẫu khi đổi thương hiệu\n• Kích thước thường làm: dài 1,2-1,6 m, cao tổng khoảng 2,2 m\n• Lưu ý: điểm bán không có ổ điện gần thì chọn hộp đèn 12V chạy bình và bình giữ nhiệt thay cho máy pha\n\nTrường Thịnh thiết kế, đóng xe tại xưởng và giao tận nơi trọn gói.","descriptionEn":"A takeaway coffee cart suits a morning trade outside office blocks, industrial-park gates and hospitals, where customers buy quickly and need no seating.\n\n• Frame: powder-coated steel box section, 304 stainless top, lockable casters\n• Body: aluminium composite with printed vinyl, easy to wipe and to rebrand\n• Typical size: 1.2-1.6 m long, about 2.2 m tall overall\n• Tip: with no socket nearby, go for a 12V battery-run lightbox and insulated urns instead of an espresso machine\n\nTrường Thịnh designs, builds the cart in its workshop and delivers it ready to use.","altVi":"Xe bán cà phê mang đi có hộp đèn, đặt trước tòa văn phòng","altEn":"Takeaway coffee cart with a lightbox header outside an office building","source":"/assets/content/projects/advertising/mobile-retail/xe-ban-ca-phe-mang-di.webp","sha256":"c60361ea82b8e079720ac1c54e34665f83816044b66d113ec4993e99ff153582","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:mobile-retail-02-a; original SHA256 86f5c817b577295beac18ea55321cf668cbc521c5c84cd8158eee4adf14ce15d; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "mobile-retail-03": {"descriptionVi":"Xe bán thức ăn khung thép ốp gỗ hợp với quán ăn, thương hiệu đồ ăn nhanh mở thêm điểm bán ở sảnh tòa nhà, khu ẩm thực, cần quầy trông như cửa hàng cố định mà vẫn đẩy đi được.\n\n• Khung xe: thép hộp sơn tĩnh điện, lam gỗ ngoài trời hoặc nhựa giả gỗ chịu ẩm\n• Mặt quầy: inox 304, tủ kính giữ nhiệt hoặc tủ mát tùy món\n• Kích thước thường làm: dài 1,6-2,2 m, rộng 0,8-1,0 m\n• Lưu ý: món chiên, nướng cần chừa chỗ cho máy hút khói; bán trong nhà nên dùng bếp điện thay bếp gas\n\nTrường Thịnh thiết kế, đóng xe tại xưởng và giao tận nơi trọn gói.","descriptionEn":"A steel and timber food cart suits eateries and fast-food brands adding a sales point in building lobbies and food courts, where the counter should look like a fixed shop yet still roll away.\n\n• Frame: powder-coated steel box section, exterior timber slats or moisture-proof wood-look composite\n• Counter: 304 stainless top, with a heated or chilled glass case to suit the menu\n• Typical size: 1.6-2.2 m long, 0.8-1.0 m deep\n• Tip: fried or grilled food needs room for an extractor, and indoor sites call for electric hobs rather than gas\n\nTrường Thịnh designs, builds the cart in its workshop and delivers it ready to use.","altVi":"Xe bán thức ăn khung thép đen, ốp lam gỗ, mái lật có đèn","altEn":"Black steel food cart with timber slat cladding and a lift-up lit canopy","source":"/assets/content/projects/advertising/mobile-retail/xe-ban-thuc-an-op-go.webp","sha256":"b379765fb0b73d47b4760b9c14a70ed7644b6e43b064f2427258b72c466d69c4","provenance":"AI-generated illustration; source ID imagegen:2026-09-01:mobile-retail:03; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "mobile-retail-04": {"descriptionVi":"Quầy cà phê di động gắn hộp đèn hợp với thương hiệu cà phê, đồ uống chạy chương trình dùng thử trong siêu thị, nơi quầy phải gọn trong một ô lối đi và dời đi theo từng đợt khuyến mãi.\n\n• Thân quầy: MDF chống ẩm hoặc khung sắt ốp alu, mặt trước dán decal in UV thay được theo chiến dịch\n• Hộp đèn: bạt 3M hoặc mica, LED module 12V, dùng chung ổ điện với ấm pha\n• Kích thước thường làm: dài 0,9-1,2 m, rộng 0,5-0,6 m, cao tổng 2,0-2,2 m\n• Lưu ý: hỏi trước quy định chiều cao quầy và vị trí ổ điện, mỗi chuỗi siêu thị một khác\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và giao tận nơi trọn gói.","descriptionEn":"A mobile coffee counter with a lightbox suits coffee and drink brands running tasting promotions in supermarkets, where the unit has to fit one aisle bay and move with each campaign.\n\n• Body: moisture-resistant MDF or a steel frame clad in aluminium composite, with a UV-printed vinyl front that swaps per campaign\n• Lightbox: 3M flex or acrylic, with 12V LED modules, sharing one socket with the urn\n• Typical size: 0.9-1.2 m long, 0.5-0.6 m deep, 2.0-2.2 m tall overall\n• Tip: check height limits and socket positions first, since every supermarket chain has its own rules\n\nTrường Thịnh designs, builds the counter in its workshop and delivers it ready to use.","altVi":"Quầy cà phê di động gắn hộp đèn, đặt giữa lối đi siêu thị","altEn":"Mobile coffee counter with an overhead lightbox in a supermarket aisle","source":"/assets/content/projects/advertising/mobile-retail/quay-ca-phe-di-dong.webp","sha256":"5fef77116cc38e7abe82ae2b9ac8d87b42b27f5fc5c48fea706f08b077653557","provenance":"AI-generated illustration; owner selected A125-v1 in HTML audit and confirmed in chat 2026-10-22; ChatGPT web gpt-image; original SHA256 2d9e65683017216339741970bbedc467d7fa8d8b0abb23821249c6660b029474; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "mobile-retail-05": {"descriptionVi":"Quầy trưng bày di động hai đầu kệ hợp với nhãn hàng đồ uống, thực phẩm đóng gói chạy khuyến mãi trong siêu thị, vừa chứa đủ hàng cho một ca bán vừa có chỗ đặt máy tính tiền.\n\n• Khung quầy: sắt hộp sơn tĩnh điện, kệ và mặt quầy MDF phủ melamine\n• Mặt tranh: decal in UV dán tấm alu hoặc PVC, đổi chiến dịch chỉ cần thay tranh\n• Kích thước thường làm: dài 1,4-1,8 m, rộng 0,6 m, cao quầy 0,9-1,0 m\n• Lưu ý: kệ chất nước đóng hộp rất nặng, cần tính tải từng tầng và chọn bánh xe chịu tải tốt\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và giao tận nơi trọn gói.","descriptionEn":"A double-ended mobile display counter suits drink and packaged food brands running supermarket promotions, holding a full shift of stock with room on top for a till.\n\n• Frame: powder-coated steel box section, shelves and top in melamine-faced MDF\n• Graphic panel: UV-printed vinyl on aluminium composite or PVC, so a new campaign only needs a new panel\n• Typical size: 1.4-1.8 m long, 0.6 m deep, 0.9-1.0 m counter height\n• Tip: boxed drinks are heavy, so rate each shelf for the load and choose heavy-duty casters\n\nTrường Thịnh designs, builds the counter in its workshop and delivers it ready to use.","altVi":"Quầy trưng bày di động khung sắt đen, kệ gỗ xếp nước dừa hộp","altEn":"Black steel mobile display counter with timber shelves of boxed coconut water","source":"/assets/content/projects/advertising/mobile-retail/quay-trung-bay-di-dong.webp","sha256":"cee6d7de08a35ab9546abb9a2156a5bcd8e9ad25c2d8ba11d17674b778b54e6e","provenance":"AI-generated illustration; owner approved 2026-09-24; original SHA256 c9cafc6aae2e4de29c028f770996b7846c4c75cbae205fc530f64fd5480384b4; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "mobile-retail-06": {"descriptionVi":"Quầy bán hàng di động khung sắt hợp với tiệm cà phê, bánh ngọt đặt thêm điểm bán trước trung tâm thương mại, tòa văn phòng, nhẹ hơn xe gỗ mà vẫn đủ chỗ cho máy pha và tủ bánh.\n\n• Khung: sắt hộp sơn tĩnh điện, mái phẳng có đèn rọi\n• Thân: ván ép phủ laminate hoặc alu dán decal\n• Kích thước thường làm: dài 1,4-1,8 m, bánh xe xoay có khóa\n• Lưu ý: bảng menu nên làm tấm rời gắn vào khung, đổi món chỉ cần in lại tấm menu\n\nTrường Thịnh thiết kế, đóng quầy tại xưởng và giao tận nơi trọn gói.","descriptionEn":"A steel-framed mobile sales counter suits coffee and pastry shops adding a pitch outside a mall or office block, lighter than a timber cart but with room for a coffee machine and pastry case.\n\n• Frame: powder-coated steel box section, flat roof with downlights\n• Body: laminated plywood or aluminium composite with vinyl graphics\n• Typical size: 1.4-1.8 m long, lockable swivel casters\n• Tip: make the menu a separate panel fixed to the frame, so a menu change means reprinting one board\n\nTrường Thịnh designs, builds the counter in its workshop and delivers it to your door.","altVi":"Quầy bán hàng di động khung sắt đen bán cà phê và bánh ngọt","altEn":"Black steel mobile counter for coffee and pastries outside a shop","source":"/assets/content/projects/advertising/mobile-retail/quay-ban-hang-di-dong.webp","sha256":"8820b9ae9898e45908da17b4a58cc88b774b28504a0b8b8b3573b290d92c3362","provenance":"AI-generated illustration; ChatGPT web image edit with owner mask (chat 6ae5c766-1ecc-83ec-9240-11f009cc1ac2); upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-27; master PNG SHA256 58a40dbf8526314f72a9a8aaba494607bfc05be7bf195521b2a4396c6c994f8a."},
  "mobile-retail-07": {"descriptionVi":"Xe đẩy trưng bày mỹ phẩm bằng gỗ hợp với thương hiệu mỹ phẩm thiên nhiên, đồ chăm sóc da mở quầy tạm ở trung tâm thương mại, hội chợ, cần bày đủ dòng sản phẩm trên chưa tới hai mét vuông.\n\n• Chất liệu: gỗ cao su hoặc MDF dán veneer, sơn PU mờ, khung đỡ sắt sơn cùng tông gỗ\n• Đèn: LED thanh 3000-4000K dưới từng tầng kệ, giữ đúng màu bao bì\n• Kích thước thường làm: dài 1,2-1,6 m, rộng 0,6 m, cao tổng 2,0-2,3 m\n• Lưu ý: nên chừa ngăn tủ có khóa dưới quầy để cất hàng mẫu và hàng giá trị qua đêm\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và giao tận nơi trọn gói.","descriptionEn":"A timber cosmetics display cart suits natural beauty and skincare brands opening pop-up counters in malls and fairs, where the whole range has to fit on less than two square metres.\n\n• Material: rubberwood or veneered MDF in a matt PU finish, with a steel support frame painted to match\n• Lighting: 3000-4000K LED bars under each shelf, so packaging colours read true\n• Typical size: 1.2-1.6 m long, 0.6 m deep, 2.0-2.3 m tall overall\n• Tip: add a lockable cupboard under the counter for testers and high-value stock overnight\n\nTrường Thịnh designs, builds the cart in its workshop and delivers it ready to use.","altVi":"Xe đẩy gỗ trưng bày mỹ phẩm, kệ hắt đèn, hộp đèn trên khung","altEn":"Timber cosmetics display cart with lit shelves and a lightbox header in a mall","source":"/assets/content/projects/advertising/mobile-retail/xe-day-trung-bay-my-pham.webp","sha256":"e4a0f8687695ef80f90dc76a3679f607e4cc0ed203271d9167239b55ea7cf169","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd1a2-094c-83ec-9a07-d00ebab66898); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-27 01:07Z; master PNG SHA256 8c6347bc2a43943032b46a49986be47d86b3ad01f5f92148cf3a297802066470."},
  "mobile-retail-08": {"descriptionVi":"Quầy bán nước bằng gỗ có bánh xe hợp với quán cà phê, tiệm trà muốn mở thêm quầy mang đi trước cửa hoặc mang đi sự kiện, ban ngày đẩy ra vỉa hè, tối đẩy vào trong.\n\n• Thân quầy: gỗ thông hoặc gỗ cao su sơn PU, tranh in UV trực tiếp lên gỗ\n• Cánh bàn: bản lề và tay đỡ sắt gấp hai bên, xếp gọn khi đẩy qua cửa\n• Kích thước thường làm: dài 1,2-1,5 m khi gấp cánh, rộng 0,6 m\n• Lưu ý: đo bề ngang cửa quán trước khi chốt kích thước, xe gấp cánh vẫn phải lọt cửa\n\nTrường Thịnh thiết kế, đóng quầy tại xưởng và giao tận nơi trọn gói.","descriptionEn":"A timber mobile drinks counter suits cafés and tea shops adding a takeaway point outside the door or at events, rolled onto the pavement by day and back inside at night.\n\n• Body: pine or rubberwood in a PU finish, artwork UV printed straight onto the timber\n• Side leaves: hinged with folding steel brackets, tucked away to pass through the door\n• Typical size: 1.2-1.5 m long with leaves folded, 0.6 m deep\n• Tip: measure the shop door before fixing the size, as the cart must fit through with its leaves down\n\nTrường Thịnh designs, builds the counter in its workshop and delivers it ready to use.","altVi":"Quầy bán nước bằng gỗ, mái in họa tiết lá, bình thủy tinh","altEn":"Timber drinks cart with a leaf-print roof, glass jars and fold-out side tables","source":"/assets/content/projects/advertising/mobile-retail/quay-ban-nuoc-bang-go.webp","sha256":"0878432fe93525f90a58073337d64b8643860319d92b6dc8dec2cb656c04b48c","provenance":"AI-generated illustration; owner approved A129-v3 in chat 2026-10-22; ChatGPT web; model unknown; original SHA256 29e2b444757fc573afc01704541fbbd50c350803cbdbbb81694b97c2c4bdf696; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "mobile-retail-09": {"descriptionVi":"Quầy bán hàng ngoài trời có mái tôn và bánh xe hợp với quầy kem, bánh ngọt, đồ ăn vặt ở công viên, sân trường, khu du lịch, nơi quầy đứng cả ngày dưới nắng mưa.\n\n• Khung quầy: thép hộp mạ kẽm, thân composite hoặc alu, ốp lam gỗ nhựa ngoài trời\n• Tủ kính: kính cong cường lực, loại tủ mát hoặc tủ thường tùy món\n• Kích thước thường làm: dài 1,8-2,4 m, rộng 0,8-1,0 m\n• Lưu ý: mặt dưới mái tôn nên dán lớp cách nhiệt, không thì trưa nắng rất nóng ngay chỗ người bán đứng\n\nTrường Thịnh thiết kế, đóng quầy tại xưởng và giao tận nơi trọn gói.","descriptionEn":"An outdoor mobile counter with a metal roof suits ice cream, pastry and snack sellers in parks, schools and resorts, where the counter stands all day in sun and rain.\n\n• Frame: galvanised steel box section, composite or aluminium body, exterior wood-plastic slats\n• Display: curved toughened glass cases, chilled or ambient to suit the product\n• Typical size: 1.8-2.4 m long, 0.8-1.0 m deep\n• Tip: line the underside of the metal roof with insulation, or the seller's spot gets very hot at midday\n\nTrường Thịnh designs, builds the counter in its workshop and delivers it ready to use.","altVi":"Quầy bán hàng ngoài trời mái tôn, tủ kính cong, thân trắng ốp gỗ","altEn":"Outdoor sales counter with a corrugated roof, curved glass cases and timber panels","source":"/assets/content/projects/advertising/mobile-retail/quay-ban-hang-ngoai-troi.webp","sha256":"fd9d6712966f712bf29e577a12adb55eb4b7528887026c009b27b848e4335209","provenance":"AI-generated illustration; owner selected A130-v1 in HTML audit and confirmed in chat 2026-10-22; ChatGPT web gpt-image; original SHA256 c828fcd8deb72ec28ad650e776d7a533942d0ee1484a3e1f82dc4d7a86e7b3ab; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "mobile-retail-10": {"descriptionVi":"Quầy pha chế di động có bồn rửa và tủ lạnh âm hợp với quán nước ép, trà trái cây, góc bar ngoài sân, cần pha nhiều món ngay tại quầy rồi đẩy vào trong khi đóng cửa.\n\n• Khung: thép hộp sơn tĩnh điện, mặt quầy inox 304 liền bồn\n• Nước: vòi nối can nước sạch có bơm hoặc đường ống, can nước thải riêng\n• Kích thước thường làm: dài 1,8-2,2 m, sâu 0,6-0,7 m\n• Lưu ý: chọn tủ lạnh âm quầy loại thoát nhiệt mặt trước, đặt kín trong quầy vẫn không nóng máy\n\nTrường Thịnh thiết kế theo thực đơn, đóng quầy tại xưởng và giao tận nơi trọn gói.","descriptionEn":"A mobile bar counter with a sink and under-counter fridge suits juice bars, fruit tea shops and outdoor bar corners that make a wide menu at the counter and wheel inside at closing.\n\n• Frame: powder-coated steel box section, 304 stainless top with an integrated sink\n• Water: tap fed from a clean water tank with a pump or from mains, plus a separate waste tank\n• Typical size: 1.8-2.2 m long, 0.6-0.7 m deep\n• Tip: choose a front-venting under-counter fridge so it doesn't overheat when built in\n\nTrường Thịnh designs around your menu, builds the counter in its workshop and delivers it.","altVi":"Quầy pha chế di động khung thép có bồn rửa và tủ lạnh inox","altEn":"Mobile bar counter on a steel frame with a sink and stainless fridge","source":"/assets/content/projects/advertising/mobile-retail/mobile-retail-10-mobile-beverage-counters-v2-audit-a131-v2.webp","sha256":"1724fbfc72a063b7e5872686e93da20c04441d335f8c577d09ff47488265d034","provenance":"AI-generated illustration; ChatGPT web image edit with owner mask (chat 6ae5c784-5d64-83ec-b366-e809693038cb); upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-27; master PNG SHA256 5c761343fa2e808c2b711285781ee84a21ef9f118dd677989e39456e526e91bf."},
  "mobile-retail-11": {"descriptionVi":"Xe bán hàng lưu động bằng gỗ hợp với tiệm bánh ngọt, bánh mì mở thêm điểm bán ở chợ phiên, sân trung tâm thương mại, khu ẩm thực, nơi chiếc xe vừa là quầy vừa là bảng hiệu.\n\n• Thân xe: gỗ thông hoặc MDF chống ẩm phủ veneer, sơn PU, lam cắt CNC\n• Tủ bánh: kính cường lực, lắp thêm quạt hoặc ngăn giữ lạnh tùy loại bánh\n• Kích thước thường làm: dài 1,8-2,2 m, mái bạt tháo rời khi chở\n• Lưu ý: xe gỗ dùng ngoài trời cần sơn PU ngoài trời và bọc chân nhôm để không mục khi gặp nước\n\nTrường Thịnh thiết kế, đóng xe tại xưởng và giao tận nơi trọn gói.","descriptionEn":"A timber mobile vending cart suits bakeries and cake shops opening an extra pitch at weekend markets, mall courtyards or food halls, where the cart is both counter and sign.\n\n• Body: pine or moisture-resistant MDF with veneer, PU finish, CNC-cut slats\n• Display case: toughened glass, with an optional fan or chilled section depending on the products\n• Typical size: 1.8-2.2 m long, with a removable awning for transport\n• Tip: for outdoor use specify exterior PU and aluminium-capped feet so the timber doesn't rot where it meets water\n\nTrường Thịnh designs, builds the cart in its workshop and delivers it to your door.","altVi":"Xe bán hàng lưu động bằng gỗ có mái bạt và tủ kính bánh","altEn":"Timber mobile vending cart with a canvas awning and pastry display case","source":"/assets/content/projects/advertising/mobile-retail/mobile-retail-11-imagegen-20261018-audit-a132-v2.webp","sha256":"9e9fbadc60d453baa51b85c48a9e7bdee387d8249310ac0a99d03cdb1c2e4417","provenance":"AI-generated illustration; owner selected A132-v2 in HTML audit and confirmed in chat 2026-10-22; ChatGPT web gpt-image; original SHA256 556b96b7bbb67c6ab603c5f47a25ada90d1823358d7c644c14b2fa350c79940c; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "mobile-retail-12": {"descriptionVi":"Xe bán hàng gỗ veneer khung sắt hợp với thương hiệu đồ uống, đặc sản, phụ kiện đặt quầy ở sảnh tòa nhà, khu ẩm thực trong nhà, nơi quầy cần trông như đồ nội thất hơn là xe đẩy vỉa hè.\n\n• Thân xe: MDF chống ẩm dán veneer óc chó hoặc sồi, sơn PU mờ\n• Khung: sắt hộp sơn tĩnh điện, cánh bàn gấp hai bên khi cần thêm mặt bày\n• Kích thước thường làm: dài 1,4-1,8 m, rộng 0,7 m, cao tổng 2,2-2,4 m\n• Lưu ý: veneer chỉ hợp đặt trong nhà; bán ngoài trời nên đổi sang gỗ nhựa hoặc alu vân gỗ\n\nTrường Thịnh thiết kế, đóng xe tại xưởng và giao tận nơi trọn gói.","descriptionEn":"A timber veneer sales cart on a steel frame suits drink, specialty food and accessory brands trading in building lobbies and indoor food courts, where the counter should read as furniture rather than a street cart.\n\n• Body: moisture-resistant MDF with walnut or oak veneer in a matt PU finish\n• Frame: powder-coated steel box section, with fold-out side leaves for extra display space\n• Typical size: 1.4-1.8 m long, 0.7 m deep, 2.2-2.4 m tall overall\n• Tip: veneer is for indoor use only; outdoors, switch to wood-plastic composite or wood-grain aluminium\n\nTrường Thịnh designs, builds the cart in its workshop and delivers it ready to use.","altVi":"Xe bán hàng gỗ veneer khung sắt đen, mái phẳng có đèn rọi","altEn":"Walnut veneer sales cart with a black steel frame and spotlit flat roof","source":"/assets/content/projects/advertising/mobile-retail/xe-ban-hang-go-veneer.webp","sha256":"82805d295c0a7650c22ea118cf3918a0b8aa385d5426caa08a161dd655818c9f","provenance":"AI-generated illustration; source ID imagegen:2026-09-01:mobile-retail:12; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "mobile-retail-13": {"descriptionVi":"Xe bán bánh ngọt bằng gỗ có mái bạt hợp với tiệm bánh, quán cà phê nhỏ bán thêm ở sân vườn, chợ phiên cuối tuần, cần một quầy có nét riêng mà cuối ngày vẫn khóa cửa tủ được.\n\n• Thân xe: gỗ thông hoặc gỗ tràm sơn PU ngoài trời, mặt tranh in UV trên alu\n• Mái: bạt căng trên khung sắt uốn, tháo được khi chở xe đi xa\n• Kích thước thường làm: dài 1,6-2,0 m, rộng 0,7-0,8 m\n• Lưu ý: tủ bánh ngoài trời nên có nắp kín và đặt tránh hướng nắng chiều\n\nTrường Thịnh thiết kế, đóng xe tại xưởng và giao tận nơi trọn gói.","descriptionEn":"A timber pastry cart with a canvas roof suits bakeries and small cafés selling in gardens and weekend markets, giving the stall its own character while the cupboards still lock at closing time.\n\n• Body: pine or acacia in an exterior PU finish, artwork UV printed on aluminium composite\n• Roof: canvas stretched over a bent steel frame, removable for longer trips\n• Typical size: 1.6-2.0 m long, 0.7-0.8 m deep\n• Tip: an outdoor cake case needs a sealed lid and should face away from the afternoon sun\n\nTrường Thịnh designs, builds the cart in its workshop and delivers it ready to use.","altVi":"Xe bán bánh ngọt gỗ mái bạt cong, tủ kính bánh và đèn thả","altEn":"Timber pastry cart with a curved canvas roof, glass cake case and pendant lamps","source":"/assets/content/projects/advertising/mobile-retail/xe-ban-banh-ngot-mai-bat.webp","sha256":"2ebb45daa052c3a6212bc210c27b83167d61bb597e3f66bea32eb16dee066ce7","provenance":"AI-generated illustration; owner selected A134-v1 in HTML audit and confirmed in chat 2026-10-22; ChatGPT web gpt-image; original SHA256 bee632893acb226a8fc6f08bdc3797190d161ebaa977c87479cd9b6c51e01f7b; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "mobile-retail-14": {"descriptionVi":"Xe cafe sự kiện hợp với hội nghị, hội thảo, tiệc cưới, ngày hội nhân viên muốn có cà phê pha máy tại chỗ, đồng thời là chỗ đặt logo nhà tài trợ.\n\n• Khung xe: sắt hộp sơn tĩnh điện, mặt quầy inox, bánh cao su có phanh không hằn thảm\n• Thân xe: alu dán decal, thay mẫu theo từng chương trình\n• Kích thước thường làm: dài 1,4-1,8 m, sâu 0,6-0,7 m để lọt thang hàng\n• Lưu ý: máy espresso hai group cần nguồn riêng khoảng 3-5 kW, nên báo khách sạn chừa điện trước\n\nTrường Thịnh thiết kế, đóng xe tại xưởng và giao đến tận nơi tổ chức sự kiện.","descriptionEn":"An event coffee cart suits conferences, seminars, weddings and staff days that want espresso made on the spot, and it doubles as a place for sponsor branding.\n\n• Frame: powder-coated steel, stainless top, braked rubber casters that won't mark carpet\n• Body: aluminium composite with vinyl graphics, swapped for each event\n• Typical size: 1.4-1.8 m long, 0.6-0.7 m deep to fit service lifts\n• Tip: a two-group espresso machine needs its own 3-5 kW supply, so ask the venue to set power aside in advance\n\nTrường Thịnh designs, builds the cart in its workshop and delivers it to the venue.","altVi":"Xe cafe sự kiện có máy pha espresso tại sảnh hội nghị","altEn":"Event coffee cart with an espresso machine in a conference foyer","source":"/assets/content/projects/advertising/mobile-retail/xe-cafe-su-kien-hoi-nghi.webp","sha256":"d1a8ebe1944c36f661d75ef33ee705bf08536964e72f0f52de9a2159dd7ed403","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:mobile-retail-14-1; original SHA256 f9d931a0855f22da97d955d8a6d697f34ace6cebbeab7c31242cd5a135b6e980; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "mobile-retail-15": {"descriptionVi":"Xe bánh mì gỗ khung thép hợp với tiệm bánh mì, quán ăn sáng muốn đặt quầy trước cửa hàng hoặc trong sân quán, nơi cần chỗ hâm bánh, bày nhân và gói ngay trên một mặt xe.\n\n• Khung xe: thép hộp sơn tĩnh điện, thân gỗ dầu hoặc gỗ nhựa ngoài trời\n• Mặt quầy: inox 304 ở khu bày nhân, phần gỗ dùng để gói và bày bánh\n• Kích thước thường làm: dài 1,6-2,0 m, rộng 0,7-0,8 m\n• Lưu ý: khay nhân nên có nắp kính hoặc tủ kính nhỏ để đạt yêu cầu an toàn thực phẩm khi bán vỉa hè\n\nTrường Thịnh thiết kế, đóng xe tại xưởng và giao tận nơi trọn gói.","descriptionEn":"A timber banh mi cart on a steel frame suits banh mi shops and breakfast stalls setting up outside the shop or in a courtyard, with room to warm bread, lay out fillings and wrap on one top.\n\n• Frame: powder-coated steel box section, body in dầu hardwood or exterior wood-plastic composite\n• Counter: 304 stainless over the filling area, timber for wrapping and bread display\n• Typical size: 1.6-2.0 m long, 0.7-0.8 m deep\n• Tip: fillings need a glass lid or a small glass case to meet food safety rules for pavement trading\n\nTrường Thịnh designs, builds the cart in its workshop and delivers it ready to use.","altVi":"Xe bánh mì gỗ khung thép đen, mái có đèn, quầy bày nhân","altEn":"Timber banh mi cart with a black steel frame, lit roof and filling counter","source":"/assets/content/projects/advertising/mobile-retail/xe-banh-mi-go-mai-phang.webp","sha256":"69f5eaf4a0b32f466071a96d3dc67b004070199f6575a6e763a2000f6b898f71","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd151-60a4-83ec-99a6-b6764d902042); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-27 01:07Z; master PNG SHA256 51274db5cbe78ddd0565a9eabb1e760676359bd13305172af14cc5b7c7974fa8."},
  "mobile-retail-16": {"descriptionVi":"Xe bán nước dừa lưu động mái bạt hợp với thương hiệu nước dừa, nước giải khát bán sáng sớm ở công viên, đường chạy bộ, giải chạy, nơi điểm bán đổi theo ngày và thường không có điện.\n\n• Khung xe: sắt hộp sơn tĩnh điện, mặt quầy inox, bánh xe cỡ lớn nếu phải đẩy trên đường đất\n• Thân xe: alu dán decal in UV cán màng, chịu nắng và lau nước dừa không ố\n• Kích thước thường làm: dài 1,0-1,2 m, rộng 0,5-0,6 m, cao tổng khoảng 2,2 m\n• Lưu ý: bán ngoài trời cả buổi nên dùng bình giữ lạnh có vòi thay cho thùng đá hở\n\nTrường Thịnh thiết kế, đóng xe tại xưởng và giao tận nơi trọn gói.","descriptionEn":"A mobile coconut water cart with a canvas roof suits coconut water and soft drink brands trading early mornings in parks, on running paths and at races, where the pitch changes daily and power is rare.\n\n• Frame: powder-coated steel box section, stainless top, larger wheels if it has to cross dirt paths\n• Body: aluminium composite with laminated UV-printed vinyl that takes the sun and wipes clean of coconut water\n• Typical size: 1.0-1.2 m long, 0.5-0.6 m deep, about 2.2 m tall overall\n• Tip: for a full morning outdoors, use insulated urns with taps rather than an open ice box\n\nTrường Thịnh designs, builds the cart in its workshop and delivers it ready to use.","altVi":"Xe bán nước dừa xanh, mái bạt, bình giữ lạnh bên đường chạy bộ","altEn":"Green coconut water cart with canvas roof and cooler urns by a jogging path","source":"/assets/content/projects/advertising/mobile-retail/xe-ban-nuoc-dua-mai-bat.webp","sha256":"dfab784205a06f119a037ccd779605780d3c2bd289ef00e1217a798405e25cc8","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:mobile-retail-16-1; original SHA256 df962a673c83ba799aae570c1ca1cb1d7d789578b4c760c854cc9bd2d7b4b22f; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-01": {"descriptionVi":"Bảng hiệu alu chữ nổi là cách làm mặt tiền phổ biến cho showroom nội thất và cửa hàng mặt phố: tấm alu che kín dầm, cột bê tông, chữ nổi giữ nét thương hiệu nhiều năm.\n\n• Chất liệu: alu ngoài trời dày 3-4 mm, khung sắt hộp mạ kẽm hoặc sơn chống gỉ\n• Chữ nổi: mica, inox hoặc alu chấn, LED module 12V hắt chân hoặc sáng mặt\n• Độ bền: alu ngoài trời phủ sơn PVDF bền màu nhiều năm dưới nắng, chữ inox không phải sơn lại\n• Lưu ý: hỏi rõ báo giá dùng alu trong nhà hay ngoài trời, loại trong nhà rẻ hơn nhưng nhanh bạc màu\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"An aluminium composite shopfront with raised letters is the standard frontage for furniture showrooms and street-front shops: the panels hide beams and columns, and the letters carry the brand for years.\n\n• Material: 3-4 mm exterior-grade aluminium composite on a galvanised or rust-proofed steel frame\n• Letters: acrylic, stainless steel or folded aluminium, with 12V LED modules for halo or face lighting\n• Durability: PVDF-coated exterior panels hold their colour for years in full sun, and stainless letters never need repainting\n• Tip: check whether the quote is for indoor or exterior-grade panels, since indoor grade is cheaper but fades quickly\n\nTrường Thịnh designs, builds in its own workshop and installs the whole frontage.","altVi":"Mặt tiền showroom góc phố ốp alu, chữ nổi và logo khối hắt sáng","altEn":"Corner showroom frontage in aluminium composite with halo-lit raised letters and block logo","source":"/assets/content/projects/advertising/signage-raised-letters/bang-hieu-alu-chu-noi-showroom.webp","sha256":"cdff362461893800d6a8cb6e6af6ff38359337554c6c48243d24aa2405163e6f","provenance":"AI-generated illustration; owner selected A237-v1 in HTML audit and confirmed in chat 2026-10-22; ChatGPT web gpt-image; original SHA256 8d2ab62e1e3100e5d9e1f94b8ce98339dcc7a8bc56620daaea75546dc63bf66d; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-02": {"descriptionVi":"Pano dự án bất động sản đặt trước công trường là cách chủ đầu tư giới thiệu dự án và số bán hàng suốt thời gian thi công, rẻ hơn nhiều so với thuê billboard.\n\n• Mặt pano: bạt hiflex hoặc bạt 3M in dầu, căng trên khung sắt hộp\n• Kết cấu: hai trụ thép ống hoặc thép hộp, móng bê tông đổ tại chỗ, có thanh chống xiên\n• Kích thước thường làm: 3x6 m, 4x8 m hoặc 5x10 m\n• Lưu ý: pano ven đường cần xin phép quảng cáo ngoài trời, móng phải tính theo tải gió\n\nTrường Thịnh thiết kế, in bạt, gia công khung tại xưởng và dựng pano trọn gói.","descriptionEn":"A property development billboard in front of the site lets the developer show the project and sales contact for the whole build, for far less than renting a roadside billboard.\n\n• Face: hiflex or 3M banner with solvent print, stretched on a steel box frame\n• Structure: two steel tube or box posts on cast-in-place concrete footings, with diagonal braces\n• Typical size: 3x6 m, 4x8 m or 5x10 m\n• Tip: a roadside panel needs an outdoor advertising permit, and the footings must be sized for wind load\n\nTrường Thịnh designs, prints and fabricates the frame in its workshop, then erects the billboard.","altVi":"Pano bạt in phối cảnh dự án, hai trụ thép trước công trường","altEn":"Printed project billboard on two steel posts beside a construction site","source":"/assets/content/projects/advertising/signage-raised-letters/pano-du-an-bat-dong-san.webp","sha256":"5b2dccfa441228ecf45d8ecdb1dd3a1b7cae3eb86b6cad5f77e99136254e71fc","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:signage-raised-letters-02-a; original SHA256 17a4b5e0a983bb2008b5682faf418a1983f180b7a0e9a2da2a30a55e4697fa2b; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-03": {"descriptionVi":"Pano tấm lớn một trụ ven quốc lộ hợp với nhà hàng tiệc cưới, trung tâm hội nghị nằm cách đường chính một đoạn, cần chỉ lối cho khách từ xa tới.\n\n• Kết cấu: trụ thép ống đường kính 500-800 mm, dàn khung thép hình, sàn thao tác và thang lên\n• Mặt pano: bạt hiflex hoặc bạt 3M in khổ lớn, thay nội dung theo mùa cưới\n• Kích thước thường làm: 5x10 m hoặc 6x12 m, cao 12-18 m\n• Lưu ý: cần hồ sơ xin phép xây dựng và tính móng theo địa chất, nên khảo sát trước khi chốt vị trí\n\nTrường Thịnh khảo sát, gia công kết cấu tại xưởng và dựng pano trọn gói.","descriptionEn":"A large single-pole billboard on a highway suits wedding venues and convention centres set back from the main road, guiding guests in from a distance.\n\n• Structure: 500-800 mm steel pole, steel section frame, service platform and ladder\n• Face: large-format hiflex or 3M banner, changed with the wedding season\n• Typical size: 5x10 m or 6x12 m, 12-18 m high\n• Tip: it needs a building permit and footings designed for the ground conditions, so survey before fixing the spot\n\nTrường Thịnh surveys the site, fabricates the structure in its workshop and erects the billboard.","altVi":"Pano tấm lớn một trụ thép ven quốc lộ, có đèn rọi","altEn":"Large single-pole billboard with floodlights beside a highway at sunset","source":"/assets/content/projects/advertising/signage-raised-letters/pano-tam-lon-tiec-cuoi.webp","sha256":"3dc4e5bfe8cf6bfa48e260caa32379731a99d023b308c95c2974b2d375a172c2","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:signage-raised-letters-03-a; original SHA256 84f36e487bcb3c3c7e7baba0d6d92c9ef92667c8ad45d0754c78e197d6994919; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-04": {"descriptionVi":"Hộp đèn bạt hiflex sáng mặt là kiểu bảng hiệu tiết kiệm cho cửa hàng đặc sản, tạp hóa, nhà thuốc mặt phố cần bảng ngang cỡ lớn với chi phí thấp hơn chữ nổi.\n\n• Cấu tạo: khung sắt hộp, viền nhôm hoặc tôn sơn tĩnh điện, LED module bên trong\n• Mặt bạt: bạt hiflex xuyên sáng in dầu, căng bằng nẹp nhôm\n• Kích thước thường làm: dài theo mặt tiền 4-8 m, cao 1-1,5 m\n• Lưu ý: bạt thường bạc màu sau 2-3 năm nắng; chọn bạt 3M hoặc in UV nếu muốn giữ màu lâu hơn\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A front-lit hiflex lightbox is the budget fascia sign for speciality food shops, grocers and pharmacies that need a large horizontal sign for less than raised letters.\n\n• Build: steel box frame, aluminium or powder-coated steel edge, LED modules inside\n• Face: translucent hiflex with solvent print, tensioned in aluminium trims\n• Typical size: 4-8 m wide to suit the frontage, 1-1.5 m high\n• Tip: standard banner fades after 2-3 years of sun; choose 3M fabric or UV print for longer-lasting colour\n\nTrường Thịnh designs, builds in its own workshop and installs the sign.","altVi":"Hộp đèn bạt hiflex nền xanh trên mặt tiền cửa hàng kẹo dừa","altEn":"Green hiflex lightbox fascia over a coconut candy shop","source":"/assets/content/projects/advertising/signage-raised-letters/hop-den-bat-hiflex-cua-hang.webp","sha256":"f8bad29dd2e74739f37deacc63ced44b318aa67ec9be6c02a833c9e2f05d19c8","provenance":"AI-generated illustration; source ID imagegen:2026-10-15:signage-raised-letters-04-a; original SHA256 10f46d4e8c6355bfa6d6ce088171c4e0e1071829b9181226c465ce5322f8e3a0; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-05": {"descriptionVi":"Bảng hiệu ngân hàng mặt dựng alu hợp với phòng giao dịch, chi nhánh ngân hàng, quỹ tín dụng, nơi màu và logo phải khớp đúng bộ nhận diện của cả hệ thống.\n\n• Chất liệu: alu ngoài trời phủ PVDF, khung sắt hộp mạ kẽm\n• Chữ và logo: mica hoặc inox mạ vàng, LED module sáng mặt hoặc hắt chân\n• Màu: pha sơn theo mã Pantone trong cẩm nang nhận diện, duyệt mẫu màu trước khi sản xuất\n• Lưu ý: nhiều ngân hàng có bản vẽ chuẩn riêng, gửi trước để báo giá đúng vật liệu yêu cầu\n\nTrường Thịnh sản xuất theo bộ nhận diện tại xưởng và lắp đặt trọn gói.","descriptionEn":"A bank fascia sign in aluminium composite suits branches, transaction offices and credit funds, where colours and logo must match the network's brand manual exactly.\n\n• Material: PVDF-coated exterior aluminium composite on a galvanised steel frame\n• Letters and logo: acrylic or gold-plated stainless, face-lit or halo-lit with LED modules\n• Colour: mixed to the Pantone codes in the brand manual, with a colour sample approved first\n• Tip: many banks have standard sign drawings, so send them early for an accurate materials quote\n\nTrường Thịnh builds to the brand guidelines in its workshop and installs the sign.","altVi":"Bảng hiệu ngân hàng nền xanh navy viền vàng trên mặt tiền kính","altEn":"Navy bank fascia sign with gold trim above a glass frontage","source":"/assets/content/projects/advertising/signage-raised-letters/bang-hieu-ngan-hang-mat-dung.webp","sha256":"0bbf8e1210de3a3f392a2b4d73a7c0984e401ea5975d9592569a73e60e212a8e","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd42a-52c4-83ec-a624-fd7c453f0fef); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-27 01:07Z; master PNG SHA256 65c8890e2455cda516b62b47795a725c61369eb571658cd06823ce0049a68fb9."},
  "signage-raised-letters-06": {"descriptionVi":"Chữ nổi hắt sáng ngoài trời gắn trên bệ đá hợp với sảnh khách sạn, resort, khu biệt thự, nơi bảng tên đặt thấp giữa sân vườn thay vì treo trên mặt tiền.\n\n• Bệ: xây gạch ốp đá travertine, granite hoặc tấm xi măng giả đá\n• Chữ: inox 304 xước, lưng mica, LED chống nước từ IP65 trở lên\n• Kích thước thường làm: bệ dài 2-4 m, cao 0,6-1 m, chữ cao 20-35 cm\n• Lưu ý: bệ nằm trong khu tưới cây nên dây điện phải đi ống ngầm và có aptomat chống giật riêng\n\nTrường Thịnh thiết kế, sản xuất chữ tại xưởng và thi công bệ trọn gói.","descriptionEn":"Outdoor halo-lit letters on a stone plinth suit hotel entrances, resorts and villa estates, where the name sits low in the landscaping rather than up on the facade.\n\n• Plinth: masonry clad in travertine, granite or stone-look cement board\n• Letters: brushed 304 stainless with acrylic backs, LEDs rated IP65 or higher\n• Typical size: plinth 2-4 m long and 0.6-1 m high, letters 20-35 cm tall\n• Tip: the plinth sits in an irrigated bed, so run cables in buried conduit with a dedicated earth-leakage breaker\n\nTrường Thịnh designs, makes the letters in its workshop and builds the plinth.","altVi":"Chữ inox hắt sáng gắn trên bệ đá travertine giữa thảm cây","altEn":"Halo-lit stainless letters on a travertine plinth set in planting","source":"/assets/content/projects/advertising/signage-raised-letters/chu-noi-hat-sang-be-da.webp","sha256":"85084e4624b8bb8636a8c2e91243ceff72cdef4b500c1c35855fea8d6fa5fedd","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 2ff5e9a436ba01c222df4bef98d1ee834b93ef33dc2bb8b72dbf588f247f7fca."},
  "signage-raised-letters-07": {"descriptionVi":"Chữ nổi mica trắng trên nền alu màu trầm là kiểu bảng hiệu gọn cho tiệm bánh, tiệm hoa, cửa hàng nhỏ mặt phố muốn nhìn sạch mà không cần nhiều chi tiết.\n\n• Chất liệu chữ: mica 3-5 mm cắt CNC, dán thành khối dày 3-5 cm\n• Nền: alu ngoài trời 3 mm trên khung sắt hộp\n• Đèn: có thể lắp LED module trong chữ nếu tiệm bán cả buổi tối\n• Lưu ý: mica trắng ngoài nắng gắt nên chọn loại chống UV, đỡ ố vàng sau vài năm\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"White acrylic raised letters on a dark aluminium fascia make a tidy sign for bakeries, florists and small street shops that want a clean look without extra detail.\n\n• Letters: 3-5 mm CNC-cut acrylic, built up to 3-5 cm deep\n• Background: 3 mm exterior aluminium composite on a steel box frame\n• Lighting: LED modules can be fitted inside the letters if the shop trades in the evening\n• Tip: in strong sun choose UV-stabilised white acrylic, which resists yellowing for years\n\nTrường Thịnh designs, builds in its own workshop and installs the sign.","altVi":"Chữ nổi mica trắng trên bảng alu nâu phía trên cửa kính tiệm bánh","altEn":"White acrylic raised letters on a brown fascia above a bakery door","source":"/assets/content/projects/advertising/signage-raised-letters/chu-noi-mica-trang-tiem-banh.webp","sha256":"f91e84e07022163d53d4f34c4965d7c0e3c27bbca8f273438482016f6ae198b2","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:signage-raised-letters-07-a; original SHA256 eb2047c65355bfc6851a8638723ddc4e98e6b43bd6ed8256370a336003aae5a8; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-08": {"descriptionVi":"Chữ nổi văn phòng công ty gắn thẳng lên tường sảnh hợp với công ty kiến trúc, thiết kế, tư vấn muốn khách bước vào là gặp tên thương hiệu mà không cần bảng nền.\n\n• Chất liệu: alu chấn hoặc inox xước, chữ nhỏ dùng lõi Formex dày 1-3 cm\n• Gia công: cắt CNC, chấn viền, sơn tĩnh điện hoặc giữ màu kim loại\n• Lắp đặt: chân ty âm hoặc keo hai mặt, căn vị trí bằng mẫu giấy in tỷ lệ thật trước khi khoan\n• Lưu ý: tường sơn nhám hoặc không thật phẳng nên chọn chữ dày từ 2 cm để giấu độ lệch\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"Company office letters fixed straight to the reception wall suit architecture, design and consulting firms that want visitors to meet the brand name without a backing panel.\n\n• Material: folded aluminium or brushed stainless, with a 1-3 cm Formex core for small letters\n• Fabrication: CNC cut, folded returns, powder-coated or left in natural metal\n• Installation: concealed studs or double-sided tape, positioned with a full-size paper template before drilling\n• Tip: on textured or uneven walls choose letters at least 2 cm deep to hide the irregularities\n\nTrường Thịnh designs, builds in its own workshop and installs the sign.","altVi":"Chữ nổi alu bạc gắn tường xám sảnh văn phòng kiến trúc","altEn":"Silver aluminium raised letters on a grey wall in an architecture office","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-08-aluminium-and-foam-dimensional-letters-v2.webp","sha256":"7be9361707f591ead8c6d40067766d66271a27f4260304c39e4924c0022cb551","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:signage-raised-letters-08-a; original SHA256 5e82aeb3b09221cd07696ac986668959b4cc432d293a787d06a0e57801b78507; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-09": {"descriptionVi":"Chữ nổi LED tòa nhà xếp dọc hợp với siêu thị, trung tâm thương mại, khách sạn có góc nhà cao mà mặt tiền ngang hẹp hoặc bị cây che.\n\n• Chữ: mặt mica xuyên sáng, viền alu hoặc inox sơn, LED module 12V\n• Kết cấu: khung xương thép bắt vào cột hoặc dầm, chừa lối kiểm tra phía sau\n• Kích thước thường làm: chữ cao 0,8-1,5 m, tổng chiều cao 6-15 m\n• Lưu ý: thi công trên cao cần xe nâng hoặc giàn giáo, làm cùng lúc hoàn thiện mặt dựng sẽ đỡ chi phí\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"Vertical LED building letters suit supermarkets, malls and hotels with a tall corner but a narrow or tree-screened frontage.\n\n• Letters: translucent acrylic faces, aluminium or painted stainless returns, 12V LED modules\n• Structure: steel subframe fixed to columns or beams, with service access behind\n• Typical size: letters 0.8-1.5 m tall, 6-15 m overall height\n• Tip: high-level work needs a lift or scaffold, so doing it alongside the facade cladding saves cost\n\nTrường Thịnh designs, builds in its own workshop and installs the sign.","altVi":"Chữ nổi LED xếp dọc trên góc tòa nhà siêu thị lúc chạng vạng","altEn":"Vertical LED-lit raised letters on the corner of a supermarket building at dusk","source":"/assets/content/projects/advertising/signage-raised-letters/chu-noi-led-toa-nha.webp","sha256":"02f9305f51f3cfe4966a5781d29eb6ab35c3f53c6c982326155fa4d784d3b26e","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 348c5b2d4aa78b1a47451aad2c5c04b387a59bbb2154653a52e24f42ce308f8b."},
  "signage-raised-letters-10": {"descriptionVi":"Biển vẫy hộp đèn tròn treo trần hợp với quán có hiên sâu hoặc mái thấp, nơi không còn mảng tường để gắn tay đỡ.\n\n• Chất liệu: viền tôn hoặc inox uốn tròn, hai mặt mica sữa 3 mm\n• In: UV trực tiếp lên mica hoặc decal cắt, bền màu dưới mái hiên\n• Kích thước thường làm: đường kính 50-70 cm, dày 12-15 cm\n• Lắp đặt: ống thép hoặc ty ren bắt vào đà trần, dây điện đi trong ống; cần kiểm tra trần chịu lực trước khi treo\n\nTrường Thịnh thiết kế, gia công tại xưởng và treo lắp trọn gói.","descriptionEn":"A ceiling-hung round lightbox sign suits cafés with deep porches or low canopies, where there is no wall left for a bracket.\n\n• Material: rolled steel or stainless rim, 3 mm opal acrylic on both faces\n• Print: UV printed directly onto the acrylic or cut vinyl, colourfast under a porch\n• Typical size: 50-70 cm diameter, 12-15 cm deep\n• Installation: steel tubes or threaded rods into the ceiling joists, cable run through the tube; check the ceiling can take the load first\n\nTrường Thịnh designs, fabricates and hangs the sign as one job.","altVi":"Hộp đèn tròn mica in logo quán cà phê, treo ty dưới trần gỗ","altEn":"Round acrylic lightbox with a café logo, hung on rods from a timber ceiling","source":"/assets/content/projects/advertising/signage-raised-letters/bien-vay-hop-den-treo-tran.webp","sha256":"3828ce0ac5984defb38456ba76499ae06a25ac61c405287788d821a3cc4bcc03","provenance":"AI-generated illustration; owner selected A246-v1 in HTML audit and confirmed in chat 2026-10-22; ChatGPT web gpt-image; original SHA256 178d39f494efcc0bc8979a195206d4e2500b6249933840fa83536443d1cc7670; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-11": {"descriptionVi":"Biển vẫy LED dùng bóng LED đúc cắm thành hình, hợp với quán cà phê, quán bar muốn có biển chạy hiệu ứng với chi phí thấp hơn nhiều so với màn hình LED.\n\n• Cấu tạo: hộp tôn hoặc inox sơn tĩnh điện, mặt alu khoan lỗ, bóng LED đúc chống nước\n• Điều khiển: mạch chạy viền, nháy hoặc sáng tĩnh, hẹn giờ bật tắt\n• Kích thước thường làm: đường kính 50-80 cm, hai mặt\n• Lưu ý: hình nên đơn giản, nét dày; chữ cao dưới 10 cm sẽ vỡ nét giữa các bóng LED\n\nTrường Thịnh thiết kế hình, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"An LED projecting sign uses moulded LED bulbs set into a pattern, suiting cafés and bars that want animated effects for far less than an LED screen.\n\n• Build: powder-coated steel or stainless case, drilled aluminium face, waterproof moulded LEDs\n• Control: chasing, blinking or steady modes on a timer\n• Typical size: 50-80 cm diameter, double-sided\n• Tip: keep the graphic simple and bold, because text under about 10 cm breaks up between the dots\n\nTrường Thịnh draws the graphic, builds the sign in its workshop and installs it.","altVi":"Biển vẫy tròn bóng LED chấm hình tách cà phê, gắn tay thép","altEn":"Round LED-dot projecting sign of a coffee cup on a steel bracket","source":"/assets/content/projects/advertising/signage-raised-letters/bien-vay-led-tron-ca-phe.webp","sha256":"161982bb4ea13083e0c3452f09d63636fc7f472da4fc182e046b010eadb9cf62","provenance":"AI-generated illustration; owner approved A247-v3 in chat 2026-10-22; ChatGPT web; model unknown; original SHA256 f5917ebae759c6a32bd96dbe074bf1d3b92077d4c20cfd6baa7b9f19a55cb1ee; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-12": {"descriptionVi":"Hộp đèn tròn inox gắn vuông góc tường hợp với tiệm cà phê rang xay, tiệm bánh, cửa hàng mặt tiền gỗ hoặc kính cần một chiếc biển nhỏ mà bền ngoài trời.\n\n• Chất liệu: viền inox 304 uốn tròn đánh bóng hoặc xước, mặt mica sữa in UV hai mặt\n• Đèn: LED module ánh trắng ấm, nguồn đặt trong hộp kín nước\n• Kích thước thường làm: đường kính 50-70 cm, dày 10-15 cm\n• Lưu ý: tay đỡ nên cùng loại inox với viền, tránh gỉ loang xuống tường sau mùa mưa\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A round stainless lightbox mounted at right angles to the wall suits coffee roasters, bakeries and timber or glass shopfronts that want a small sign built to last outdoors.\n\n• Material: rolled 304 stainless rim, polished or brushed, opal acrylic faces UV printed on both sides\n• Lighting: warm white LED modules, power supply in a sealed box\n• Typical size: 50-70 cm diameter, 10-15 cm deep\n• Tip: make the bracket from the same stainless as the rim so no rust streaks run down the wall after the rains\n\nTrường Thịnh designs, builds in its own workshop and installs the sign.","altVi":"Hộp đèn tròn viền inox in logo cà phê rang xay, tay inox","altEn":"Round stainless-rimmed lightbox with a roastery logo on a steel bracket","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-12-stainless-steel-and-hiflex-projecting-signs-audit-a248-v1.webp","sha256":"c25698b77c47c0197b93071119cb2c25ed6d4061a2fc5250aab224c758894fb4","provenance":"AI-generated illustration; owner selected A248-v1 in HTML audit and confirmed in chat 2026-10-22; ChatGPT web gpt-image; original SHA256 468af112f29132832642725ec5a705ac17ae74b4c4039c913df3697caa5c7bd4; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-13": {"descriptionVi":"Bảng hiệu bệnh viện mặt dựng alu hợp với bệnh viện tư, phòng khám đa khoa, trung tâm y tế cần mặt tiền ốp đồng bộ và tên cơ sở bền nhiều năm.\n\n• Mặt dựng: alu ngoài trời 4 mm phủ PVDF, khung sắt hộp mạ kẽm\n• Chữ: mica hoặc alu chấn, LED module sáng mặt hoặc hắt chân\n• Kích thước thường làm: mặt dựng dài 10-30 m, chữ cao 60-120 cm\n• Lưu ý: tên cơ sở y tế phải đúng như trên giấy phép hoạt động, nên kiểm lại chính tả trước khi cắt chữ\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A hospital fascia in aluminium composite suits private hospitals, polyclinics and health centres that need a uniform frontage and a name that lasts for years.\n\n• Facade: 4 mm PVDF-coated exterior aluminium composite on a galvanised steel frame\n• Letters: acrylic or folded aluminium, face-lit or halo-lit with LED modules\n• Typical size: facade 10-30 m long, letters 60-120 cm tall\n• Tip: the name must match the operating licence exactly, so proofread before the letters are cut\n\nTrường Thịnh designs, builds in its own workshop and installs the sign.","altVi":"Bảng hiệu bệnh viện mặt dựng alu xanh teal, chữ nổi trắng","altEn":"Teal aluminium composite hospital fascia with white raised letters","source":"/assets/content/projects/advertising/signage-raised-letters/bang-hieu-benh-vien-alu.webp","sha256":"a640762c830c31fc0d1bfc220c7e49cecd674af670f39d1fc1e7de62e6acebc0","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:signage-raised-letters-13-a-2; original SHA256 6195ce110e7671424f05a218cc9a16ceded15a46b0f81063ab749b0615e570ea; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-14": {"descriptionVi":"Biển quảng cáo bằng tôn sơn hợp với cửa hàng vật liệu xây dựng, đại lý phân bón, cây xăng ở đường làng, đường liên xã cần biển bền mưa nắng và rẻ hơn hộp đèn.\n\n• Mặt biển: tôn kẽm 0,4-0,6 mm, sơn lót chống gỉ, chữ sơn dầu hoặc decal\n• Kết cấu: khung sắt hộp, hai trụ thép ống trên chân đế bê tông, có thanh chống\n• Kích thước thường làm: 1,2x2,4 m đến 2,4x4,8 m\n• Lưu ý: tôn mỏng dưới 0,4 mm dễ móp và gỉ mép, hỏi rõ độ dày khi so báo giá\n\nTrường Thịnh thiết kế, gia công tại xưởng và dựng biển trọn gói.","descriptionEn":"A painted steel sign suits building-materials stores, fertiliser dealers and fuel stations on village and district roads that need a weatherproof sign for less than a lightbox.\n\n• Face: 0.4-0.6 mm galvanised sheet, anti-rust primer, enamel-painted or vinyl lettering\n• Structure: steel box frame on two tube posts with concrete bases and a brace\n• Typical size: 1.2x2.4 m to 2.4x4.8 m\n• Tip: sheet under 0.4 mm dents and rusts at the edges, so check the thickness when comparing quotes\n\nTrường Thịnh designs, fabricates in its workshop and erects the sign.","altVi":"Biển quảng cáo tôn sơn đỏ trên hai trụ thép ven đường quê","altEn":"Red painted steel sign on two posts beside a country road","source":"/assets/content/projects/advertising/signage-raised-letters/bien-quang-cao-bang-ton.webp","sha256":"84d6e10c76a9849b126c90e20450930fe97d647f81fdc3e6c025b95567995652","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:signage-raised-letters-14-a; original SHA256 2d29013d490f38abf7bee2603fe49819b52a20cbf1d0c280c9bbe9087d157d12; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-15": {"descriptionVi":"Pano ngoài trời trụ thép ở vòng xoay, cửa ngõ thị xã hợp với khu du lịch sinh thái, homestay, làng nghề cần giới thiệu điểm đến với khách đi xe qua.\n\n• Kết cấu: trụ thép ống mạ kẽm, dàn khung thép hình, sàn thao tác và thang lên\n• Mặt pano: bạt 3M hoặc bạt hiflex in dầu khổ lớn, căng tăng đơ\n• Đèn: đèn pha LED 100-200 W, hẹn giờ tắt lúc khuya để tiết kiệm điện\n• Lưu ý: vị trí vòng xoay, cửa ngõ thường do địa phương quản lý, nên làm việc với đơn vị cho thuê mặt bằng quảng cáo trước\n\nTrường Thịnh thiết kế, gia công kết cấu tại xưởng và dựng pano trọn gói.","descriptionEn":"An outdoor pole billboard at a roundabout or town gateway suits eco-tourism sites, homestays and craft villages introducing the destination to passing traffic.\n\n• Structure: galvanised steel pole, steel section frame, service platform and ladder\n• Face: large-format 3M or hiflex banner with solvent print, tensioned with turnbuckles\n• Lighting: 100-200 W LED floodlights on a timer that switches off late at night\n• Tip: roundabout and gateway sites are usually controlled by the local authority, so talk to the licensed site operator first\n\nTrường Thịnh designs, fabricates the structure in its workshop and erects the billboard.","altVi":"Pano ngoài trời một trụ thép giữa vòng xoay, đèn rọi ban đêm","altEn":"Single-pole outdoor billboard with floodlights at a roundabout at night","source":"/assets/content/projects/advertising/signage-raised-letters/pano-ngoai-troi-du-lich.webp","sha256":"4067ad8fa184512cbb4e7ac2e1fbf1ea0cebb17ff386feed1f807885b7917da5","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:signage-raised-letters-15-a; original SHA256 6978bc6bb1dc4343da9feadec38902cb1f1257845325d2361fa2c38a55ee470c; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-16": {"descriptionVi":"Hộp đèn vẫy mỏng khung nhôm hợp với quán cà phê, tiệm trà đổi món theo mùa, vì mặt tranh thay được mà không phải làm lại hộp.\n\n• Cấu tạo: khung nhôm định hình sơn đen dày 5-8 cm, tấm dẫn sáng LED viền\n• Mặt tranh: bạt hiflex xuyên sáng, bạt 3M hoặc film in UV, thay qua nẹp mở mặt trước\n• Kích thước thường làm: 60x80 cm hoặc 80x100 cm, một hoặc hai mặt\n• Lưu ý: ảnh in nên từ 3000 px cạnh dài trở lên, ảnh nhỏ phóng ra sẽ vỡ khi có đèn chiếu sau\n\nTrường Thịnh thiết kế ảnh, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A slim aluminium projecting lightbox suits cafés and tea shops with seasonal drinks, since the graphic can be swapped without rebuilding the box.\n\n• Build: 5-8 cm black extruded aluminium frame, edge-lit LED panel\n• Graphic: translucent flex, 3M flex or UV-printed film, changed through an opening front frame\n• Typical size: 60x80 cm or 80x100 cm, single or double-sided\n• Tip: supply images at least 3000 px on the long side, as small files break up once backlit\n\nTrường Thịnh designs the artwork, builds the box in its workshop and installs it.","altVi":"Hộp đèn vẫy vuông khung đen in ảnh ly cà phê đá trên cột","altEn":"Square black-framed projecting lightbox with an iced coffee print on a pillar","source":"/assets/content/projects/advertising/signage-raised-letters/hop-den-vay-quan-ca-phe.webp","sha256":"b2631725ee9ebe59169c3a9ef379642efc41aee6db7c7b1a2a50f8bbb6a60dcf","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 294670a02916f30a3f93af22040ed34ac2790b28bd51e1cbb1a96e8ac3c2d9dd."},
  "signage-raised-letters-17": {"descriptionVi":"Hộp đèn vươn tường hợp với văn phòng bảo hiểm, ngân hàng, phòng khám trong dãy nhà phố, nơi bảng ngang dễ lẫn với bảng của nhà bên cạnh.\n\n• Cấu tạo: hộp tôn hoặc nhôm sơn tĩnh điện, hai mặt mica in UV hoặc dán decal xuyên sáng, muốn rẻ hơn thì căng bạt 3M\n• Đèn: LED module chống nước, nguồn 12V\n• Kích thước thường làm: 60x60 cm đến 80x100 cm, dày 15-20 cm\n• Lưu ý: duyệt màu thương hiệu trên mẫu mica đã bật đèn, vì màu khi sáng thường khác bản in giấy\n\nTrường Thịnh sản xuất theo bộ nhận diện tại xưởng và lắp đặt trọn gói.","descriptionEn":"A wall-projecting lightbox suits insurance offices, banks and clinics in a row of shophouses, where a fascia sign easily blends into the neighbours'.\n\n• Build: powder-coated steel or aluminium case, two acrylic faces UV printed or with backlit vinyl, or 3M flex faces on a tighter budget\n• Lighting: waterproof LED modules on a 12V supply\n• Typical size: 60x60 cm to 80x100 cm, 15-20 cm deep\n• Tip: approve brand colours on a lit acrylic sample, since colours look different lit than on a paper proof\n\nTrường Thịnh builds to the brand guidelines in its workshop and installs the sign.","altVi":"Hộp đèn mica xanh dương gắn tay thép trước văn phòng bảo hiểm","altEn":"Blue acrylic lightbox on a steel bracket outside an insurance office","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-17-imagegen-20261018.webp","sha256":"a46fefa6800df9dec29a632766318e5324126ace1e22dadff173ded496d70219","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 8cf580898da3ccacbaa103568720975458dbf791c41e65624a0c82090716231c."},
  "signage-raised-letters-18": {"descriptionVi":"Chữ nổi inox hắt sáng hợp với phòng khám, nha khoa, spa muốn mặt tiền chỉn chu, ánh sáng dịu, không chói như chữ sáng mặt.\n\n• Chất liệu: inox 304 mạ vàng xước hoặc vàng gương, lưng mica để lắp LED\n• Đèn: LED module ánh vàng 3000K, chân ty giữ chữ cách tường 3-5 cm\n• Kích thước thường làm: chữ cao 15-40 cm, logo 60-120 cm\n• Lưu ý: logo nhiều mảnh nên có khung đỡ chung phía sau, căn chỉnh tại xưởng rồi mới mang đi lắp\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"Halo-lit stainless letters suit clinics, dental practices and spas that want a polished frontage with soft light, without the glare of face-lit letters.\n\n• Material: brushed or mirror gold-plated 304 stainless, acrylic backs to hold the LEDs\n• Lighting: 3000K warm LED modules, letters held 3-5 cm off the wall on studs\n• Typical size: letters 15-40 cm tall, logo 60-120 cm\n• Tip: a multi-piece logo should sit on a shared rear frame, aligned in the workshop before it goes on site\n\nTrường Thịnh designs, builds in its own workshop and installs the sign.","altVi":"Chữ nổi inox vàng hắt sáng kèm logo hoa sen trên tường đá","altEn":"Halo-lit gold stainless letters and lotus logo on a stone wall","source":"/assets/content/projects/advertising/signage-raised-letters/chu-noi-inox-hat-sang.webp","sha256":"256941ef1bea0489903fe5cce231bf535903a653761fc2ae6fc95244cffaffdc","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 94ee9310681077b7e53a7691dd88f76405c92e0076713408c5c616d352641eda."},
  "signage-raised-letters-19": {"descriptionVi":"Chữ nổi mica đèn LED gắn tường trong nhà hợp với cửa hàng mỹ phẩm, spa, tiệm thời trang muốn tên thương hiệu làm điểm nhấn ngay trên quầy kệ.\n\n• Chất liệu: mặt mica màu xuyên sáng 3 mm, viền mica hoặc alu chấn cao 3-5 cm\n• Đèn: LED module 12V bên trong, nguồn giấu sau trần hoặc trong tủ\n• Kích thước thường làm: chữ cao 15-35 cm, tổng dài 1,5-3 m\n• Lưu ý: nét chữ mảnh dưới 2 cm khó lắp đèn đều, nên chọn font nét dày cho phần chữ sáng\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"Indoor LED acrylic letters on the wall suit cosmetics shops, spas and fashion stores that want the brand name as the focal point above the shelving.\n\n• Material: 3 mm translucent coloured acrylic faces, acrylic or folded aluminium returns 3-5 cm deep\n• Lighting: 12V LED modules inside, power supply hidden in the ceiling or a cabinet\n• Typical size: letters 15-35 cm tall, 1.5-3 m overall\n• Tip: strokes under 2 cm wide are hard to light evenly, so pick a bold typeface for the lit text\n\nTrường Thịnh designs, builds in its own workshop and installs the sign.","altVi":"Chữ nổi mica xanh lá sáng đèn gắn tường trên kệ mỹ phẩm","altEn":"Green illuminated acrylic letters on a shop wall above cosmetics shelves","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-19-acrylic-dimensional-letters-v2.webp","sha256":"77988ac9dc9d94d4a984fbeb5db5c5bd987bdd66126c725ea88339cc2dfdeec3","provenance":"AI-generated illustration; source ID imagegen:2026-10-15:signage-raised-letters-19-a; original SHA256 c176243d35d66609367fbda56a1c2d3ff9cdeb1b89cfe01701bded7ca82cda5c; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-20": {"descriptionVi":"Chữ nổi mặt dựng alu hợp với nhà sách, siêu thị mini, cửa hàng mặt tiền rộng cần ốp kín tầng trên và đặt tên lớn ngay trên mái hiên.\n\n• Mặt dựng: alu ngoài trời 3-4 mm trên khung sắt hộp, che luôn ống điện và cục nóng máy lạnh\n• Chữ: mica màu hoặc alu chấn sơn, LED module sáng mặt\n• Kích thước thường làm: mặt dựng ngang 5-10 m, chữ cao 40-80 cm\n• Lưu ý: chừa ô thăm trên mặt dựng để sửa đèn, nguồn mà không phải tháo tấm alu\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"Raised letters on an aluminium composite facade suit bookshops, mini-marts and wide shopfronts that need the upper floor clad and a large name right above the awning.\n\n• Facade: 3-4 mm exterior aluminium composite on a steel box frame, also hiding cables and AC units\n• Letters: coloured acrylic or painted folded aluminium, face-lit LED modules\n• Typical size: facade 5-10 m wide, letters 40-80 cm tall\n• Tip: leave access panels in the cladding so lights and drivers can be serviced without removing panels\n\nTrường Thịnh designs, builds in its own workshop and installs the sign.","altVi":"Chữ nổi đỏ và logo sách trên mặt dựng alu trắng nhà sách","altEn":"Red raised letters and book logo on a white aluminium bookshop facade","source":"/assets/content/projects/advertising/signage-raised-letters/chu-noi-mat-dung-alu.webp","sha256":"bae6c9d42abac4112833421166c5b97619fd12d74f5fc2d9ac7f8bb2b78efe5b","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 63edc03eed79381457f664829ca4740e66b1b957476c329663fc79d4110bf41a."},
  "signage-raised-letters-21": {"descriptionVi":"Chữ nổi trên mái tòa nhà hợp với nhà máy, công ty chế biến, trụ sở trong khu công nghiệp hoặc ven quốc lộ cần tên công ty thấy được từ đường lớn.\n\n• Chữ: alu chấn hoặc tôn sơn tĩnh điện, mặt mica, cao 1,2-2,5 m\n• Kết cấu: dàn khung thép hộp mạ kẽm bắt bu lông vào sàn mái, có giằng chống gió\n• Đèn: LED module sáng mặt hoặc đèn pha rọi, nguồn đặt trong hộp kín nước\n• Lưu ý: cần kiểm tra mái chịu được tải dàn chữ và gió bão trước khi thi công\n\nTrường Thịnh khảo sát mái, gia công tại xưởng và lắp đặt trọn gói.","descriptionEn":"Rooftop letters suit factories, processing companies and head offices in industrial parks or along highways, where the company name has to register from the main road.\n\n• Letters: folded aluminium or powder-coated steel with acrylic faces, 1.2-2.5 m tall\n• Structure: galvanised steel box frame bolted to the roof slab, braced against wind\n• Lighting: face-lit LED modules or floodlights, with power supplies in sealed boxes\n• Tip: have the roof checked for the frame load and storm winds before work starts\n\nTrường Thịnh surveys the roof, fabricates in its workshop and installs the letters.","altVi":"Chữ nổi và logo khối dựng trên khung thép mái văn phòng nhà máy","altEn":"Large raised letters and logo on a steel frame atop a factory office","source":"/assets/content/projects/advertising/signage-raised-letters/chu-noi-tren-mai-nha-may.webp","sha256":"30cce69077781aac4d97fc9baa7c599f406286a3e352d5571658d414cab210ee","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 55653ea9c72c5805aeb2f13e22f08b00588bd4f943b5b7bb7f7c111dcfc66713."},
  "signage-raised-letters-22": {"descriptionVi":"Bảng vẫy mica hợp với tiệm tạp hóa, nhà thuốc, tiệm sửa xe trong dãy phố có mái hiên, nơi bảng ngang dễ bị mái che khuất.\n\n• Cấu tạo: hộp tôn hoặc nhôm, mặt mica hút nổi hoặc mica phẳng in UV, hai mặt\n• Đèn: LED module bên trong, có thể dùng chung nguồn với bảng hiệu chính\n• Kích thước thường làm: 50x70 cm đến 60x90 cm\n• Lưu ý: tay sắt nên sơn tĩnh điện và bắt bu lông nở vào cột, không bắt vào tường gạch mỏng\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"An acrylic projecting sign suits grocers, pharmacies and repair shops in a row with awnings, where a fascia sign is easily hidden.\n\n• Build: steel or aluminium case, vacuum-formed or flat UV-printed acrylic, double-sided\n• Lighting: LED modules inside, able to share the main sign's power supply\n• Typical size: 50x70 cm to 60x90 cm\n• Tip: powder-coat the steel arm and anchor it into a column, not into a thin brick wall\n\nTrường Thịnh designs, builds in its own workshop and installs the sign.","altVi":"Bảng vẫy mica cam bo góc gắn tay sắt trên mái hiên tạp hóa","altEn":"Rounded orange acrylic projecting sign on a steel arm above a grocery","source":"/assets/content/projects/advertising/signage-raised-letters/bang-vay-mica-tap-hoa.webp","sha256":"7e10d604049cc9b969aa3c37bec3e7004f01039ed81f2f84cbcdd042359e064b","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:signage-raised-letters-22-a; original SHA256 8ceafaa602592f2aaeffb1c55ea3a0b2b1e5577678d2e9b1db5c6d0380ddfe2f; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-01": {"descriptionVi":"Biển số nhà inox khắc hoa văn hợp với nhà phố, biệt thự có cổng và tường rào hiện đại, muốn biển bền ngoài trời mà vẫn có nét riêng thay vì mẫu chữ trơn.\n\n• Chất liệu: inox 304 xước dày 1-1,5 mm, không gỉ dưới mưa nắng\n• Gia công: ăn mòn hoặc khắc laser rồi đổ sơn, hoa văn vẽ theo ý chủ nhà\n• Kích thước thường làm: 30x20 cm đến 40x25 cm\n• Lưu ý: nên chọn inox 304 thay vì 201, biển gắn ngoài trời lâu năm không bị ố vàng\n\nTrường Thịnh thiết kế, gia công tại xưởng và lắp đặt trọn gói.","descriptionEn":"An etched stainless house number plate with a pattern suits townhouses and villas with modern gates and fences, for owners who want a plate that lasts outdoors and still has its own character.\n\n• Material: 1-1.5 mm brushed 304 stainless, rust-free in sun and rain\n• Fabrication: etched or laser-engraved, then paint-filled, with a pattern drawn to the owner's taste\n• Typical size: 30x20 cm to 40x25 cm\n• Tip: choose 304 rather than 201 stainless, so an outdoor plate doesn't stain yellow over the years\n\nTrường Thịnh designs, makes the plate in its workshop and installs it.","altVi":"Biển số nhà inox xước khắc đường sóng, gắn trụ cổng trắng","altEn":"Brushed stainless house number plate with etched wave line on white gate pillar","source":"/assets/content/projects/advertising/office-signs-wayfinding/bien-so-nha-inox-khac-song.webp","sha256":"d56ccd3077c07be4218325d4696b55e6978483201bea363b273241dc85317b64","provenance":"AI-generated illustration; source ID imagegen:2026-09-09:office-signs-wayfinding-01:v2; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-02": {"descriptionVi":"Biển chỉ dẫn mica trong phối inox xước hợp với văn phòng, quán cà phê, showroom phong cách tối giản, cần hệ biển rõ ràng mà không lấn nội thất.\n\n• Chất liệu: mica trong 8-10 mm, inox 304 xước 1-1,5 mm\n• Gia công: in UV mặt sau mica; inox in UV hoặc ăn mòn đổ sơn\n• Lắp đặt: chân đinh inox bắt vít nở, hoặc keo 3M cho tường không khoan được\n• Lưu ý: in mặt sau mica thì hình nằm dưới lớp mica, lau chùi lâu năm không bị trầy\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"Clear acrylic wayfinding signs paired with brushed stainless suit minimalist offices, cafés and showrooms that need clear signage without fighting the interior.\n\n• Material: 8-10 mm clear acrylic, 1-1.5 mm brushed 304 stainless\n• Fabrication: reverse UV print on the acrylic; stainless UV printed or etched and paint-filled\n• Installation: stainless stand-offs with wall plugs, or 3M tape where drilling isn't possible\n• Tip: printing on the back of the acrylic protects the graphic, so years of cleaning won't scratch it\n\nTrường Thịnh designs, makes the signs in its workshop and installs them.","altVi":"Biển chỉ dẫn mica trong và biển WC inox xước trên tường bê tông","altEn":"Clear acrylic arrow signs and brushed stainless toilet signs on a concrete wall","source":"/assets/content/projects/advertising/office-signs-wayfinding/bien-chi-dan-mica-inox.webp","sha256":"e700067d98e256dc8c25256d9f69918081c61224eb34cd3a464c9c2a20fefc2d","provenance":"AI-generated illustration; ChatGPT web image generation 2026-10-24; owner approved audit #785 in chat; original SHA256 0aa16acec728727eccfcec6c07af5f42e1edd83a3394f4b17cb321828275ef14; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-03": {"descriptionVi":"Biển chỉ dẫn văn phòng dạng thanh song ngữ hợp với tòa nhà văn phòng, coworking, trường học có nhiều khu chức năng và khách ra vào thường xuyên.\n\n• Chất liệu: alu hoặc mica 5 mm sơn đen mờ, khối màu đầu thanh in UV hoặc ghép\n• Chữ: in UV hoặc decal cắt, cao 3-4 cm cho khoảng đọc 5-6 m\n• Kích thước thường làm: 60x12 cm đến 90x15 cm\n• Lưu ý: làm dạng thanh rời thì khi đổi tên phòng chỉ cần thay một thanh, không phải làm lại cả bảng\n\nTrường Thịnh thiết kế hệ biển, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"Bilingual office wayfinding signs in bar format suit office buildings, coworking spaces and schools with many zones and steady visitor traffic.\n\n• Material: 5 mm aluminium composite or acrylic in matt black, colour tabs UV printed or inset\n• Lettering: UV print or cut vinyl, 3-4 cm high for reading at 5-6 m\n• Typical size: 60x12 cm to 90x15 cm\n• Tip: separate bars mean a renamed room needs only one new bar, not a whole new board\n\nTrường Thịnh plans the sign system, makes it in its workshop and installs it.","altVi":"Biển chỉ dẫn song ngữ dạng thanh trên cột sảnh ốp đá","altEn":"Bilingual office wayfinding bar signs on a stone-clad lobby column","source":"/assets/content/projects/advertising/office-signs-wayfinding/bien-chi-dan-van-phong.webp","sha256":"bc0db81d6601042b63d6dcc3e5733d549faf8763d5d42ae35942feec5a3e9640","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adf73c3-8098-83ec-add4-160cfdefcad6, card #857); upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-26 19:11Z; master PNG SHA256 60051dc0c7fec2e56c0d4b6bedccfa7874797518c5f063a059fd9fb03f253bdb."},
  "office-signs-wayfinding-04": {"descriptionVi":"Totem chỉ dẫn là trụ biển đứng trên bệ, hợp với khu đô thị, khu dân cư mới và khuôn viên lớn cần chỉ hướng đến công viên, trường học, trạm y tế ngay từ lối đi bộ.\n\n• Kết cấu: khung sắt hộp mạ kẽm, ốp alu ngoài trời hoặc tôn sơn tĩnh điện\n• Nội dung: chữ và biểu tượng decal phản quang hoặc in UV, song ngữ khi khu có khách nước ngoài\n• Kích thước thường làm: cao 1,8-2,5 m, rộng 0,6-0,9 m\n• Lưu ý: chân totem cần móng bê tông và bu lông neo, làm cùng lúc lát vỉa hè sẽ đỡ phải đục lại\n\nTrường Thịnh thiết kế hệ biển, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A wayfinding totem is a free-standing sign on a plinth, suited to new townships, residential estates and large campuses that need to point people to parks, schools and clinics from the footpath.\n\n• Structure: galvanised steel box frame clad in exterior aluminium composite or powder-coated steel\n• Content: reflective vinyl or UV-printed text and icons, bilingual where there are foreign visitors\n• Typical size: 1.8-2.5 m tall, 0.6-0.9 m wide\n• Tip: the totem needs a concrete footing with anchor bolts, and casting it while the pavement is laid saves breaking it up later\n\nTrường Thịnh designs the sign system, builds it in its workshop and installs it.","altVi":"Totem chỉ dẫn alu đen song ngữ trên vỉa hè khu đô thị","altEn":"Black aluminium bilingual wayfinding totem on a pavement in a new township","source":"/assets/content/projects/advertising/office-signs-wayfinding/totem-chi-dan-khu-do-thi.webp","sha256":"82eda4dc43a50b11989ec40938f3b3202cff38c17b0197bf6641743b61dc9a66","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 fb3f6f4b5ca2b0a4a14ceb18662780acc557fa394e0a529de5399c0bec1822c4."},
  "office-signs-wayfinding-05": {"descriptionVi":"Bảng chức danh để bàn bằng đồng trên đế gỗ hợp với phòng giám đốc ngân hàng, văn phòng luật, cơ quan nhà nước có bàn làm việc gỗ tối màu và nội thất cổ điển.\n\n• Chất liệu: đồng thau dày 1-1,5 mm hoặc inox mạ PVD vàng, đế gỗ hương, gõ hoặc sồi\n• Gia công: ăn mòn chữ nổi hoặc khắc laser đổ sơn, phủ lớp chống oxy hóa\n• Kích thước thường làm: 25x7 cm đến 30x10 cm\n• Lưu ý: đặt theo bộ cho cả ban giám đốc thì chốt một kiểu chữ, một màu đế để các phòng đồng bộ\n\nTrường Thịnh thiết kế, gia công tại xưởng và giao tận nơi trọn gói.","descriptionEn":"A brass desk title plate on a timber base suits bank managers' offices, law firms and government offices with dark wooden desks and a classic interior.\n\n• Material: 1-1.5 mm brass or gold-tone PVD stainless, rosewood, ironwood or oak base\n• Fabrication: raised etched lettering or laser engraving with paint fill, sealed against tarnish\n• Typical size: 25x7 cm to 30x10 cm\n• Tip: when ordering for a whole management team, fix one typeface and one base finish so every office matches\n\nTrường Thịnh designs, makes the plates in its workshop and delivers them.","altVi":"Bảng chức danh đồng chữ nổi trên đế gỗ, đặt bàn giám đốc","altEn":"Brass desk title plate with raised letters on a timber base","source":"/assets/content/projects/advertising/office-signs-wayfinding/bang-chuc-danh-de-ban-dong.webp","sha256":"f7ad2395ae89ed5df0e173728b7b86cbc73733f7ac7131edc1d5fc71bf75add6","provenance":"AI-generated illustration; source ID imagegen:2026-10-15:office-signs-wayfinding-05-a; original SHA256 81b7e76225dfe16bc68f7e190bc718dc5e903457621dd4eab6f3b20e41c848d8; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-06": {"descriptionVi":"Biển để bàn mica chữ L hợp với văn phòng bảo hiểm, ngân hàng, phòng giao dịch cần đánh dấu bàn tiếp khách, quầy tư vấn với chi phí thấp và làm được số lượng nhiều.\n\n• Chất liệu: mica trắng sữa 3-5 mm uốn nhiệt thành chữ L, đứng vững không cần đế\n• In: UV trực tiếp hoặc decal cắt, thêm logo và màu nhận diện\n• Kích thước thường làm: 20x7 cm đến 30x10 cm\n• Lưu ý: nhân sự hay đổi thì chọn kiểu có khe cài giấy, chỉ cần in lại tờ tên thay vì làm biển mới\n\nTrường Thịnh thiết kế, in và giao tận nơi trọn gói.","descriptionEn":"An L-shaped acrylic desk sign suits insurance offices, banks and service counters that need to mark reception desks and advice points cheaply and in quantity.\n\n• Material: 3-5 mm opal acrylic heat-bent into an L, standing on its own without a base\n• Print: direct UV print or cut vinyl, with logo and brand colours\n• Typical size: 20x7 cm to 30x10 cm\n• Tip: if staff change often, choose a version with a paper insert slot so only the name sheet is reprinted\n\nTrường Thịnh designs, prints and delivers to your door.","altVi":"Biển để bàn mica trắng chữ L trên bàn tiếp khách văn phòng","altEn":"White L-shaped acrylic desk sign on an office reception table","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-06-acrylic-desk-nameplates-v2.webp","sha256":"f7571a32573fa2773f4d89d82e477bf147bd57982bacc4e61fad8fd495fbb7ee","provenance":"AI-generated illustration; source ID imagegen:2026-10-15:office-signs-wayfinding-06-a; original SHA256 6b4cc87bb97380ccf6632ba9dbb7d09b7ca4cba6532af59a7a0bca39a63ab572; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-07": {"descriptionVi":"Biển chỉ dẫn inox dùng biểu tượng thay chữ hợp với tòa văn phòng, trung tâm thương mại, khách sạn đông khách nước ngoài, vì không phụ thuộc ngôn ngữ của người đọc.\n\n• Chất liệu: inox 304 xước dày 1-1,2 mm, cắt laser, mài cạnh\n• Gia công: ăn mòn đổ sơn hoặc in UV, biểu tượng theo chuẩn ISO 7001\n• Kích thước thường làm: 15x15 cm đến 30x10 cm, chia module vuông và chữ nhật\n• Lưu ý: làm module rời theo một lưới kích thước thì dễ ghép thêm biển khi tòa nhà mở rộng\n\nTrường Thịnh thiết kế hệ biển, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"Stainless pictogram wayfinding signs suit office towers, shopping malls and hotels with many international guests, because they work regardless of the reader's language.\n\n• Material: 1-1.2 mm brushed 304 stainless, laser cut, edges deburred\n• Fabrication: etched and paint-filled or UV printed, pictograms following ISO 7001\n• Typical size: 15x15 cm to 30x10 cm, in square and oblong modules\n• Tip: separate modules on one size grid make it easy to add signs when the building expands\n\nTrường Thịnh designs the sign system, makes it in its workshop and installs it.","altVi":"Bộ biển chỉ dẫn inox xước biểu tượng thang máy, cầu thang, WC","altEn":"Set of brushed stainless pictogram signs for lift, stairs and toilets","source":"/assets/content/projects/advertising/office-signs-wayfinding/bien-chi-dan-inox-bieu-tuong.webp","sha256":"815394c0c5d28b49f0fb5efc93a0c5ef0bab12d68bfdf121ff8bb6bc5d73bc23","provenance":"AI-generated illustration; ChatGPT web image generation 2026-10-24; owner approved audit #793 in chat; original SHA256 321023a8f1a5f3c34e844899f7aeaac9ac6f6c16a95e3ff8be4c7c17160324d7; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-08": {"descriptionVi":"Bộ biển chỉ dẫn ốp gỗ phối đá hợp với khách sạn boutique, resort, văn phòng thiết kế muốn hệ biển cùng chất liệu với nội thất thay vì biển mica phổ thông.\n\n• Chất liệu: nền alu hoặc MDF chống ẩm, ốp veneer óc chó hoặc sồi, tấm đá nhân tạo mỏng\n• Gia công: cắt CNC ghép mảng, biểu tượng in UV hoặc khắc lõm đổ sơn\n• Kích thước thường làm: biển vuông 20x20 cm, biển ngang 40x15 cm\n• Lưu ý: veneer gỗ chỉ nên dùng trong nhà, biển gần khu vệ sinh ẩm cần phủ PU chống nước\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A timber-and-stone wayfinding set suits boutique hotels, resorts and design studios that want signs in the same materials as the interior rather than standard acrylic.\n\n• Material: aluminium composite or moisture-resistant MDF base, walnut or oak veneer, thin engineered stone\n• Fabrication: CNC-cut inlaid panels, icons UV printed or engraved and paint-filled\n• Typical size: 20x20 cm squares, 40x15 cm oblongs\n• Tip: timber veneer is for indoor use only, and signs near damp washrooms need a waterproof PU coat\n\nTrường Thịnh designs, makes it in its own workshop and installs it.","altVi":"Bộ biển WC, thang máy, cầu thang ghép gỗ, đá và khối màu","altEn":"Washroom, lift and stair signs combining timber veneer, stone and colour blocks","source":"/assets/content/projects/advertising/office-signs-wayfinding/bien-chi-dan-op-go-da.webp","sha256":"3405f0dbdf5c6a1036f7b5fadc41621818d4f80414f5e7dafb23b3127aa2a82a","provenance":"AI-generated illustration; source ID imagegen:2026-09-01:office-signs-wayfinding:08; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-09": {"descriptionVi":"Biển chỉ dẫn phòng họp kèm mũi tên hợp với văn phòng có phòng họp nằm sâu trong hành lang hoặc sau vách kính mờ, khách cần biết hướng trước khi thấy cửa.\n\n• Chất liệu: alu hoặc MDF chống ẩm phủ sơn vân đá, dải dưới alu sơn đen mờ\n• Gia công: biểu tượng in UV, mũi tên in hoặc khắc lõm đổ sơn trắng\n• Kích thước thường làm: 20x25 cm đến 25x30 cm\n• Lưu ý: dải mũi tên làm tấm rời thì khi đổi hướng chỉ cần xoay hoặc thay một tấm\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A meeting room direction sign with an arrow suits offices where the meeting room sits down a corridor or behind frosted glass, so visitors need the direction before they see the door.\n\n• Material: aluminium composite or moisture-resistant MDF with stone-texture paint, matt black aluminium lower band\n• Fabrication: UV-printed icon, arrow printed or engraved and filled white\n• Typical size: 20x25 cm to 25x30 cm\n• Tip: make the arrow band a separate piece, so a change of direction means turning or swapping one strip\n\nTrường Thịnh designs, makes it in its own workshop and installs it.","altVi":"Biển chỉ dẫn phòng họp nền be vân đá, dải đen có mũi tên","altEn":"Stone-textured beige meeting room sign with a black arrow band","source":"/assets/content/projects/advertising/office-signs-wayfinding/bien-chi-dan-phong-hop.webp","sha256":"bccaa373bc92a2ba24c2a921abad38f47529f2b27dbb53cb13efb6892e8cecfd","provenance":"AI-generated illustration; ChatGPT web gpt-image (owner chat 6af47257-bcf0-83ec-b42c-258c8122018c, latest image chosen by the owner); owner chose it 2026-11-11; original PNG SHA256 d98cf688ffc07d1f5667f222dd1e841d48bd26f7c6cc20ac10365e44fa7b7730. Site file encoded from the 1536 px JPEG preview of that PNG until the PNG is handed over."},
  "office-signs-wayfinding-10": {"descriptionVi":"Biển chỉ dẫn tầng dạng thanh dọc hợp với sảnh thang máy tòa nhà văn phòng, nơi mảng tường cạnh cửa thang hẹp, không đủ chỗ cho biển ngang.\n\n• Chất liệu: alu hoặc tôn sơn tĩnh điện, chữ và biểu tượng in UV\n• Kích thước thường làm: rộng 30-40 cm, cao 1,4-1,8 m\n• Lắp đặt: pát âm hoặc keo 3M chuyên dụng cho tường đá\n• Lưu ý: làm cùng mẫu, cùng vị trí ở mọi tầng, chỉ thay nội dung, để khách ra thang máy ở tầng nào cũng biết chỗ nhìn\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A vertical floor directory sign suits office lift lobbies where the wall beside the lift is too narrow for a horizontal sign.\n\n• Material: powder-coated aluminium or steel sheet, UV-printed text and icons\n• Typical size: 30-40 cm wide, 1.4-1.8 m tall\n• Installation: concealed brackets or stone-rated 3M tape\n• Tip: use the same sign in the same spot on every floor and change only the content, so visitors always know where to look\n\nTrường Thịnh designs, makes the sign in its workshop and installs it.","altVi":"Biển chỉ dẫn tầng dạng thanh dọc cạnh thang máy","altEn":"Vertical floor directory sign beside a lift in an office lobby","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-10-floor-wayfinding-signs-audit-a163-v1.webp","sha256":"c825805a565f4135ee5c8bcddd12e6b0659ffd75516b58e2c53795979d00cc10","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adf73e4-34e4-83ec-bab9-43c33d4a2199, card #872); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-26 18:24Z; master PNG SHA256 07fd98e5d1033d884363e60c41bb2c2a69360dca57ff292bb9fe94b83611f590."},
  "office-signs-wayfinding-11": {"descriptionVi":"Bảng chỉ dẫn tòa nhà gom mọi khu chức năng vào một tấm lớn, hợp với sảnh văn phòng, khách sạn, tòa nhà hỗn hợp cần khách tự tìm đường ngay khi bước vào.\n\n• Chất liệu: alu hoặc mica sơn màu nền, viền ốp đá nhân tạo hoặc tôn sơn giả đồng\n• Nội dung: chữ song ngữ và biểu tượng in UV, mỗi dòng là một thanh rời\n• Kích thước thường làm: rộng 60-80 cm, cao 1,2-1,6 m\n• Lưu ý: chọn tông nền và viền theo vật liệu sảnh để bảng trông như một phần nội thất\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A building directory board gathers every area onto one large panel, suiting office, hotel and mixed-use lobbies where visitors should find their way as soon as they walk in.\n\n• Material: painted aluminium composite or acrylic, trim in engineered stone or bronze-finish steel\n• Content: bilingual text and icons UV printed, each line a separate bar\n• Typical size: 60-80 cm wide, 1.2-1.6 m tall\n• Tip: match the background and trim to the lobby finishes so the board reads as part of the interior\n\nTrường Thịnh designs, makes the board in its workshop and installs it.","altVi":"Bảng chỉ dẫn tòa nhà nền kem viền đá, gắn tường sảnh thang máy","altEn":"Cream building directory board with stone and bronze trim in a lift lobby","source":"/assets/content/projects/advertising/office-signs-wayfinding/bang-chi-dan-toa-nha-sanh.webp","sha256":"d17c5827d62ef5177e0a0ce44bda563dde5389cd06d4400991ea8172c5a59e77","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adf73e1-dacc-83ec-b661-941e3d846491, card #867); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-26 18:24Z; master PNG SHA256 ef00155491e951af7d75387974e5f9dd066bd9568832fea8b00b1124ba27aadc."},
  "office-signs-wayfinding-12": {"descriptionVi":"Biển cảnh báo alu giả đồng hợp với khách sạn, nhà hàng, tòa văn phòng cao cấp cần biển an toàn đủ quy định mà vẫn cùng tông với biển WC, biển phòng.\n\n• Chất liệu: alu mặt xước màu đồng 3 mm, phần nền trắng ghép hoặc in UV\n• Gia công: biểu tượng khắc lõm hoặc in UV đen, cạnh cắt CNC\n• Kích thước thường làm: 20x15 cm đến 30x20 cm\n• Lưu ý: alu giả đồng không oxy hóa như đồng thật, rẻ hơn và không cần đánh bóng định kỳ\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"Copper-look aluminium warning signs suit hotels, restaurants and premium offices that need compliant safety signs in the same finish as their washroom and room signs.\n\n• Material: 3 mm brushed copper-finish aluminium composite, white section inlaid or UV printed\n• Fabrication: icons engraved or UV printed in black, CNC-cut edges\n• Typical size: 20x15 cm to 30x20 cm\n• Tip: copper-look aluminium doesn't tarnish like real copper, costs less and never needs polishing\n\nTrường Thịnh designs, makes the signs in its workshop and installs them.","altVi":"Biển cảnh báo và biển WC alu giả đồng gắn tường hành lang","altEn":"Copper-tone aluminium warning and washroom signs on a dark corridor wall","source":"/assets/content/projects/advertising/office-signs-wayfinding/bien-canh-bao-alu-gia-dong.webp","sha256":"f6ff379dd4036f3208f4ec181a6bf52690154d3ac2a5b5afae246d97f7a8d5cd","provenance":"AI-generated illustration; source ID imagegen:2026-09-01:office-signs-wayfinding:12; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-13": {"descriptionVi":"Biển số nhà inox chữ nổi hợp với nhà trong hẻm, nhà phố có địa chỉ dài kèm tên hẻm, tên khóm, cần biển ghi đủ thông tin mà vẫn bền ngoài trời.\n\n• Chất liệu: inox 304 xước 1,2-1,5 mm, chữ inox hoặc mica cắt laser dán nổi\n• Gia công: chữ sơn tĩnh điện, viền chỉ ăn mòn, góc bắt ốc inox\n• Kích thước thường làm: 30x20 cm đến 45x30 cm\n• Lưu ý: địa chỉ có số phụ nên để số lớn, tên hẻm nhỏ hơn một cỡ để biển không rối\n\nTrường Thịnh thiết kế, gia công tại xưởng và lắp đặt trọn gói.","descriptionEn":"A stainless house number plate with raised characters suits homes down alleys and townhouses with long addresses that include the alley and ward, fitting all of it on a plate that lasts outdoors.\n\n• Material: 1.2-1.5 mm brushed 304 stainless, laser-cut stainless or acrylic characters applied in relief\n• Fabrication: powder-coated characters, etched border line, stainless corner fixings\n• Typical size: 30x20 cm to 45x30 cm\n• Tip: with a sub-numbered address, keep the number large and the alley name a size smaller so the plate stays clear\n\nTrường Thịnh designs, makes the plate in its workshop and installs it.","altVi":"Biển số nhà inox xước chữ nổi đen, ghi số và tên hẻm","altEn":"Brushed stainless house number plate with raised black numbers and alley name","source":"/assets/content/projects/advertising/office-signs-wayfinding/bien-so-nha-inox-chu-noi.webp","sha256":"fc4f6e2a482cdd96f234cf19dc65a8920adb9d8e27054d8adf3e6d4032b7186d","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:office-signs-wayfinding-13-a; original SHA256 323769faeabafbb255ca944213f8ba0d061566660a4e92f075d54ea5e9baee70; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-01": {"descriptionVi":"Bảng LED ma trận đỏ thay bảng hiệu ngang là cách làm tiết kiệm cho quán cơm, quán ăn bình dân: một bảng vừa ghi tên quán, vừa chạy món trong ngày kèm hình minh họa.\n\n• Module: LED P10 hoặc P5 một màu đỏ, loại bóng bền và rẻ nhất trong các màu\n• Khung: nhôm định hình đen, bắt lên khung sắt mái hiên\n• Kích thước thường làm: ngang theo mặt tiền 3-5 m, cao 70-100 cm cho chữ lớn kèm hình\n• Lưu ý: hình minh họa trên bảng một màu nên vẽ nét đơn, chi tiết nhỏ sẽ nhòe thành mảng sáng\n\nTrường Thịnh thiết kế nội dung, lắp ráp tại xưởng và lắp đặt trọn gói.","descriptionEn":"A red matrix LED sign in place of a fascia board is an economical choice for rice shops and everyday eateries: one sign carries the shop name, the day's dishes and a simple graphic.\n\n• Modules: single-colour red P10 or P5, the most durable and cheapest LED colour\n• Frame: black aluminium profile fixed to the steel awning frame\n• Typical size: 3-5 m wide to match the frontage, 70-100 cm high for large text plus a graphic\n• Tip: keep graphics on a single-colour sign to simple line drawings, as fine detail blurs into a bright patch\n\nTrường Thịnh designs the content, assembles the sign in its workshop and installs it.","altVi":"Bảng LED ma trận đỏ hình đĩa cơm trên mặt tiền quán cơm tấm","altEn":"Red matrix LED sign with a rice plate icon over a broken-rice eatery","source":"/assets/content/projects/advertising/led-displays-lightboxes/bang-led-ma-tran-do.webp","sha256":"d751ac828fab9943f52cad5d5d08578e36c028d45f3f9139802aaac0d44e2c84","provenance":"AI-generated illustration; owner selected A075-v1 in HTML audit and confirmed in chat 2026-10-22; ChatGPT web gpt-image; original SHA256 d0a89887d5a0609ebcffbedc4d5d66abec3e3fae3e60f0a1b056741f58528c40; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-02": {"descriptionVi":"Bảng LED chạy chữ ba màu hợp với siêu thị mini, cửa hàng tạp hóa hay đổi khuyến mãi, giờ mở cửa, hàng mới về mà không muốn in lại bạt mỗi tuần.\n\n• Module: LED P10 ngoài trời ba màu đỏ, xanh lá, vàng, mỗi tấm 32x16 cm\n• Khung: nhôm định hình, mặt sau kín, gioăng cao su chống nước\n• Điều khiển: card wifi, đổi nội dung ngay trên điện thoại\n• Lưu ý: chữ tiếng Việt có dấu cần ít nhất một module cho mỗi dòng, bảng hai dòng nên cao từ 35 cm\n\nTrường Thịnh thiết kế, lắp ráp bảng tại xưởng và lắp đặt trọn gói.","descriptionEn":"A three-colour scrolling LED sign suits mini-marts and grocery stores that change promotions, opening hours and new stock often and don't want to reprint a banner every week.\n\n• Modules: outdoor P10 in red, green and yellow, each tile 32x16 cm\n• Frame: aluminium profile with a sealed back and rubber weather gaskets\n• Control: Wi-Fi card, so content is changed straight from a phone\n• Tip: Vietnamese text with diacritics needs at least one module height per line, so a two-line sign should be 35 cm tall or more\n\nTrường Thịnh designs, assembles the sign in its workshop and installs it.","altVi":"Bảng LED chạy chữ ba màu dưới bảng hiệu ốp gỗ siêu thị mini","altEn":"Three-colour scrolling LED sign under a timber-clad mini-mart fascia","source":"/assets/content/projects/advertising/led-displays-lightboxes/bang-led-chay-chu-sieu-thi.webp","sha256":"5d77ec47317d175026590649bdb57da1673c7852eef6f59fb136457ad800b7b1","provenance":"AI-generated illustration; owner selected A076-v1 in HTML audit and confirmed in chat 2026-10-22; ChatGPT web gpt-image; original SHA256 d45062a089db3009b5b8f724eb782830ae3b474914d483902fb864a25e85a48e; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-03": {"descriptionVi":"Màn hình LED mặt tiền full màu hợp với quán lẩu, quán nướng, nhà hàng mặt phố muốn đổi hình món theo mùa và chạy video khuyến mãi thay cho bảng in cố định.\n\n• Module: LED ngoài trời full màu P4-P6, độ sáng từ 5.000 nit, chuẩn chống nước IP65\n• Khung: cabinet thép hoặc nhôm, khung đỡ bắt vào dầm bê tông mặt tiền\n• Kích thước thường làm: ngang 3-6 m, cao 1-2 m\n• Lưu ý: gắn cảm biến ánh sáng để màn tự giảm sáng ban đêm, đỡ chói nhà đối diện và LED bền hơn\n\nTrường Thịnh khảo sát mặt tiền, làm khung và lắp đặt màn trọn gói.","descriptionEn":"A full-colour shopfront LED screen suits hotpot, barbecue and street-front restaurants that want to change dish images with the seasons and run promotional video instead of a fixed printed sign.\n\n• Modules: full-colour outdoor LED, P4-P6, 5,000 nits or more, IP65 rated\n• Frame: steel or aluminium cabinets on a support frame fixed to the concrete beam\n• Typical size: 3-6 m wide, 1-2 m high\n• Tip: fit a light sensor so the screen dims itself at night, sparing the neighbours opposite and extending LED life\n\nTrường Thịnh surveys the frontage, builds the frame and installs the screen.","altVi":"Màn hình LED full màu trên mặt tiền quán lẩu cá linh buổi tối","altEn":"Full-colour LED screen above a hotpot restaurant frontage at night","source":"/assets/content/projects/advertising/led-displays-lightboxes/man-hinh-led-mat-tien.webp","sha256":"f9d9a58e4db8e8b181e0329a5e237798fd7b02cc259322665974eefe799cf461","provenance":"AI-generated illustration; Codex gpt-6-sol image edit of the earlier led-displays-lightboxes-03 image; source ID codex-edit:2026-11-18:led-displays-lightboxes-03; original PNG SHA256 a9ea7177cb6d6f811c4c36de9e31540859c3301dcda5dd8228fc5bfc851b77ae; 1k master, owner approved 2026-11-18."},
  "led-displays-lightboxes-04": {"descriptionVi":"Bảng LED ma trận trong nhà hợp với sảnh ngân hàng, bưu điện, bộ phận một cửa, nơi cần chạy lời chào, lãi suất, thông báo cho khách đang chờ mà không dán giấy lên tường.\n\n• Module: LED P4.75 hoặc P5 trong nhà một màu đỏ, nét chữ mịn khi nhìn gần 3-5 m\n• Khung: nhôm định hình sơn đen, viền mảnh hợp vách ốp gỗ\n• Kích thước thường làm: ngang 2-4 m, cao 40-60 cm cho hai dòng\n• Lưu ý: nên đi dây điện và dây tín hiệu âm vách trước khi ốp gỗ, lắp sau sẽ lộ dây\n\nTrường Thịnh thiết kế, lắp ráp tại xưởng và lắp đặt trọn gói.","descriptionEn":"An indoor matrix LED sign suits bank lobbies, post offices and public service counters that need to show greetings, interest rates and notices to waiting customers without paper taped to the wall.\n\n• Modules: indoor single-colour red, P4.75 or P5, with smooth lettering at 3-5 m\n• Frame: black aluminium profile with a slim edge that sits well on timber panelling\n• Typical size: 2-4 m wide, 40-60 cm high for two lines\n• Tip: run power and data cables inside the wall before the panelling goes up, or they will show\n\nTrường Thịnh designs, assembles the sign in its workshop and installs it.","altVi":"Bảng LED ma trận chữ đỏ trên vách gỗ sau quầy giao dịch","altEn":"Red matrix LED sign on a timber wall above bank teller counters","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-04-indoor-matrix-led-systems-v2.webp","sha256":"40893a8609b0d9aa59e2784530c1dbf36efe18b7ba891d05f6d02e66584741ef","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:led-displays-lightboxes-04-a; original SHA256 d9e1118e17719312606938e201ac5b118b4aa51f85ea4e081e1af930351ceb65; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-05": {"descriptionVi":"Bảng LED chữ chạy ngoài trời hợp với bến tàu, bến xe, quầy vé khu du lịch cần báo giờ chạy, giá vé, tuyến đi và đổi ngay khi lịch thay đổi.\n\n• Module: LED P10 ngoài trời chống nước, đọc rõ cả dưới nắng trưa\n• Khung: nhôm định hình hoặc sắt hộp sơn tĩnh điện, ốc vít inox chống gỉ hơi nước sông\n• Kích thước thường làm: ngang 1,5-3 m, cao 35-70 cm\n• Lưu ý: đặt bộ nguồn và card điều khiển trong hộp kín có khe thoát nhiệt, chỗ ẩm ven sông là chỗ hỏng trước tiên\n\nTrường Thịnh thiết kế, lắp ráp tại xưởng và lắp đặt trọn gói.","descriptionEn":"An outdoor scrolling LED sign suits ferry piers, bus stations and tourist ticket booths that need to post departure times, fares and routes and update them the moment the schedule changes.\n\n• Modules: waterproof outdoor P10, readable even in midday sun\n• Frame: aluminium profile or powder-coated steel, with stainless fixings against river damp\n• Typical size: 1.5-3 m wide, 35-70 cm high\n• Tip: keep the power supply and controller in a sealed, ventilated box, since damp is the first thing to kill a riverside sign\n\nTrường Thịnh designs, assembles the sign in its workshop and installs it.","altVi":"Bảng LED chữ chạy gắn dưới mái quầy bán vé bến tàu ven sông","altEn":"Scrolling LED sign under the roof of a riverside ferry ticket booth","source":"/assets/content/projects/advertising/led-displays-lightboxes/bang-led-chu-chay-ngoai-troi.webp","sha256":"6374c0072d7a31c7bb49b0f4083656339279b93e734c48fb2d1d5ff96fe78b92","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:led-displays-lightboxes-05-a; original SHA256 9841d01e079086d8d384ec7a5c634c792ed6b6784b624e0fb8cb8da0eb9bba3e; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-06": {"descriptionVi":"Màn hình LED sân khấu thay cho phông in bạt ở hội nghị, lễ ra mắt, tiệc tất niên: một màn dùng cho cả slide, video và tên khách mời, không phải in lại cho từng sự kiện.\n\n• Module: LED trong nhà full màu P2.5-P3.91, cabinet nhôm đúc ghép khít\n• Kích thước thường làm: ngang 6-12 m, cao 3-4 m\n• Lắp đặt: khung truss hoặc khung thép sau sân khấu, kèm bộ xử lý hình ảnh và kỹ thuật trực\n• Lưu ý: hội trường sâu có thể chọn bước điểm lớn hơn, từ ghế ngồi vẫn nét mà chi phí thấp hơn\n\nTrường Thịnh khảo sát hội trường, lắp đặt và vận hành màn LED trọn gói.","descriptionEn":"A stage LED screen replaces the printed backdrop at conferences, launches and year-end parties: one screen handles slides, video and guest names with nothing to reprint for each event.\n\n• Modules: full-colour indoor LED, P2.5-P3.91, tight-fitting die-cast aluminium cabinets\n• Typical size: 6-12 m wide, 3-4 m high\n• Installation: truss or steel frame behind the stage, with a video processor and an on-site technician\n• Tip: in a deep hall a larger pixel pitch still looks sharp from the seats and costs less\n\nTrường Thịnh surveys the venue, then installs and runs the screen as one package.","altVi":"Màn hình LED khổ lớn sau sân khấu hội nghị trong khách sạn","altEn":"Large LED screen behind a conference stage in a hotel ballroom","source":"/assets/content/projects/advertising/led-displays-lightboxes/man-hinh-led-san-khau.webp","sha256":"6a9c8451bbf9437be6aad979bbf252f1263f4f90298338f7850775500498d138","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd448-309c-83ec-922c-12ddc1ba739c); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-27 01:07Z; master PNG SHA256 b3821ca76a9d532a00f313d5779dc1947e9e309e62fb8540e9bffdc9671605c4."},
  "led-displays-lightboxes-07": {"descriptionVi":"Màn hình LED hội nghị lắp cố định trên sân khấu hợp với sở ngành, hiệp hội, doanh nghiệp tổ chức hội thảo, họp tổng kết nhiều lần trong năm.\n\n• Module: LED trong nhà full màu P2-P2.5, cabinet nhôm đúc ghép phẳng\n• Kích thước thường làm: ngang 5-8 m, tỷ lệ 16:9 hoặc 32:9 để chiếu slide song song video\n• Lắp đặt: khung thép bắt vào vách sau, chừa lối bảo trì hoặc dùng module tháo mặt trước\n• Lưu ý: đèn sân khấu rọi thẳng vào màn sẽ làm hình bạc màu, nên chỉnh góc đèn ngay khi lắp\n\nTrường Thịnh khảo sát, lắp đặt màn và hướng dẫn kỹ thuật viên hội trường vận hành.","descriptionEn":"A conference LED screen fixed on stage suits government departments, associations and companies that run seminars and review meetings many times a year.\n\n• Modules: full-colour indoor LED, P2-P2.5, flush die-cast aluminium cabinets\n• Typical size: 5-8 m wide in 16:9, or 32:9 to show slides next to video\n• Installation: steel frame on the back wall, with a service gap or front-serviceable modules\n• Tip: stage lights aimed straight at the screen wash out the picture, so set the lighting angles during installation\n\nTrường Thịnh surveys the hall, installs the screen and trains the venue's technician to run it.","altVi":"Màn LED full màu trên sân khấu gỗ chiếu chủ đề hội nghị","altEn":"Full-colour LED wall on a timber stage showing a coconut conference title","source":"/assets/content/projects/advertising/led-displays-lightboxes/man-hinh-led-hoi-nghi.webp","sha256":"d8b1c878dc3d5f92dc174db62ccd3b0e3690ea2cfd2f50535dd8636c78959b95","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 a7f30852f7849827b0a67063fb3321ebad024789489239ec5fe8741558a11a7a."},
  "led-displays-lightboxes-08": {"descriptionVi":"Màn hình LED trong nhà hợp với cửa hàng đồ uống, mỹ phẩm, chuỗi bán lẻ muốn chạy video sản phẩm trên cả mảng tường lớn, nơi tivi ghép sẽ lộ viền đen giữa các tấm.\n\n• Module: LED trong nhà P1.8-P2.5, nhìn gần 2-3 m vẫn mịn\n• Lắp đặt: khung thép mỏng bắt tường, module hít nam châm tháo mặt trước\n• Kích thước thường làm: ngang 2-4 m theo mảng tường trên kệ\n• Lưu ý: bước điểm càng nhỏ giá càng cao, nên chọn theo khoảng cách khách đứng xem chứ không theo thông số đẹp nhất\n\nTrường Thịnh tư vấn bước điểm, lắp đặt màn và cài phần mềm đổi nội dung trọn gói.","descriptionEn":"An indoor LED screen suits drinks, cosmetics and retail chain stores that want product video across a whole wall, where a video wall of TVs would show black bezels between panels.\n\n• Modules: indoor LED, P1.8-P2.5, still smooth from 2-3 m\n• Installation: slim steel wall frame, magnetic front-serviceable modules\n• Typical size: 2-4 m wide to fit the wall above the shelving\n• Tip: finer pixel pitch costs more, so choose it by how far customers stand, not by the best number on the spec sheet\n\nTrường Thịnh advises on pixel pitch, installs the screen and sets up the content software.","altVi":"Màn hình LED trên kệ chai sữa dừa trong cửa hàng đồ uống","altEn":"LED screen above shelves of coconut milk bottles in a drinks shop","source":"/assets/content/projects/advertising/led-displays-lightboxes/man-hinh-led-trong-nha.webp","sha256":"40ef3c6ec0c4472b9629f2a543931c149832137577ffb4749ccfb33f894dc592","provenance":"AI-generated illustration; source ID imagegen:2026-10-19:led-displays-lightboxes-08-a-2; original SHA256 9424e7b1a6fcc90a19f21e484598f360e0b21577838f4bb9d82b88a49442f7ca; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-09": {"descriptionVi":"Màn hình LED quảng cáo khổ lớn gắn mặt dựng hợp với trung tâm thương mại, tòa văn phòng, chủ nhà mặt phố muốn cho thuê chỗ quảng cáo hoặc chạy chiến dịch của chính nhãn hàng mình.\n\n• Module: LED ngoài trời full màu P5-P8, cabinet thép 960x960 mm chuẩn IP65\n• Kết cấu: khung thép mạ kẽm bắt vào dầm tòa nhà, tính tải gió trước khi thi công\n• Điều khiển: phần mềm hẹn giờ phát, đổi chiến dịch từ xa qua mạng\n• Lưu ý: màn lớn hướng ra đường có thể cần xin phép quảng cáo ở địa phương, nên hỏi trước khi đặt cọc\n\nTrường Thịnh khảo sát công trình, dựng khung và lắp đặt màn trọn gói.","descriptionEn":"A large advertising LED screen on a building facade suits shopping centres, office blocks and street-front owners who want to rent out ad space or run their own brand campaigns.\n\n• Modules: full-colour outdoor LED, P5-P8, 960x960 mm IP65 steel cabinets\n• Structure: galvanised steel frame fixed to the building beams, with wind load checked before work starts\n• Control: scheduling software, campaigns changed remotely over the network\n• Tip: a large street-facing screen may need a local advertising permit, so check before paying a deposit\n\nTrường Thịnh surveys the building, erects the frame and installs the screen.","altVi":"Màn hình LED khổ đứng trên mặt dựng kính tòa nhà chiếu nước dừa","altEn":"Portrait LED screen on a glass building facade showing a coconut drink ad","source":"/assets/content/projects/advertising/led-displays-lightboxes/man-hinh-led-quang-cao.webp","sha256":"f12b5a6e7f99227e93abcaaaf93e04bc738489db09f13dcbd2318d6f30e31eb3","provenance":"AI-generated illustration; ChatGPT web image edit with owner mask (chat 6ae5f98d-0428-83ec-9fc2-6ec405a33356); upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-27; master PNG SHA256 091b8e43c8ae14d48c706529cba357d76cadeaa1b576b850c03d76900097fc77."},
  "led-displays-lightboxes-10": {"descriptionVi":"Hộp đèn siêu mỏng treo trên quầy hợp với gian hàng food court, quán ăn nhanh, căng tin, nơi khách chọn món bằng ảnh trước khi xếp hàng gọi.\n\n• Cấu tạo: khung nhôm định hình dày 2-4 cm, tấm dẫn sáng LED viền\n• Mặt tranh: film in UV hoặc decal xuyên sáng, thay qua nẹp mở mặt trước\n• Kích thước thường làm: 60x80 cm hoặc 80x100 cm, treo bộ 3-4 tấm\n• Lưu ý: nên chụp món thật bằng máy ảnh tốt, ảnh điện thoại phóng lớn thường mờ và lệch màu\n\nTrường Thịnh thiết kế, in và lắp đặt trọn gói.","descriptionEn":"Slim lightboxes hung over the counter suit food court stalls, fast-food outlets and canteens, where customers choose from photos before they queue to order.\n\n• Build: 2-4 cm extruded aluminium frame, edge-lit LED panel\n• Graphic: UV-printed film or backlit vinyl, changed through an opening front frame\n• Typical size: 60x80 cm or 80x100 cm, hung in sets of 3-4\n• Tip: shoot the real dishes with a proper camera, as enlarged phone photos often look soft and off-colour\n\nTrường Thịnh designs, prints and installs the set.","altVi":"Ba hộp đèn siêu mỏng ảnh phở, bún, cơm gà trên quầy","altEn":"Three slim lightboxes with noodle and chicken rice photos above a counter","source":"/assets/content/projects/advertising/led-displays-lightboxes/hop-den-sieu-mong-mon-an.webp","sha256":"211767dda5390b46dc0bc851079917d17313295b81bba2a79e5a92035e1cd082","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:led-displays-lightboxes-10-a; original SHA256 81aa99e28617064af42ff5b67fadbfe241f2540b87fca6f43addccd7c4145d1f; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-11": {"descriptionVi":"Tranh hộp đèn treo hành lang hợp với khách sạn, resort, nhà hàng có lối đi dài ít cửa sổ, vừa thay đèn tường vừa kể được câu chuyện địa phương qua ảnh.\n\n• Cấu tạo: khung nhôm mỏng sơn đen dày 3-5 cm, tấm dẫn sáng LED viền\n• Mặt tranh: film in UV hoặc vải xuyên sáng, gắn nam châm để thay nhanh\n• Kích thước thường làm: 60x90 cm hoặc 80x120 cm\n• Lưu ý: chọn LED 3000-4000K có bộ giảm sáng, tránh tranh chói hơn đèn trần hành lang\n\nTrường Thịnh chọn ảnh, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"Lightbox art along a corridor suits hotels, resorts and restaurants with long, windowless passages, standing in for wall lights while telling a local story through photographs.\n\n• Build: slim 3-5 cm black aluminium frame, edge-lit LED panel\n• Graphic: UV-printed film or backlit fabric, held magnetically for quick changes\n• Typical size: 60x90 cm or 80x120 cm\n• Tip: specify 3000-4000K LEDs with a dimmer so the art never outshines the corridor lighting\n\nTrường Thịnh helps choose the images, builds the frames in its workshop and installs them.","altVi":"Tranh hộp đèn khung đen ảnh sông nước treo dọc hành lang khách sạn","altEn":"Black-framed lightbox prints of river scenes along a hotel corridor","source":"/assets/content/projects/advertising/led-displays-lightboxes/tranh-hop-den-hanh-lang.webp","sha256":"a5a767ac3321a8f44976e989cc54e3db91e2fd64bc13999471e5c07a99426146","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:led-displays-lightboxes-11-a; original SHA256 7530ee2e684f437d5115e61522f936c9a3446ebc4d0b450259780c984ad2ab06; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-12": {"descriptionVi":"Tranh điện nắp bật hợp với phòng khám, bệnh viện, trường học cần biển chỉ dẫn có đèn mà đổi nội dung thường xuyên do đổi phòng, đổi giờ khám.\n\n• Cấu tạo: viền nhôm nắp bật 25-32 mm, tấm dẫn sáng LED, dày 2-3 cm\n• Mặt tranh: film đèn in kỹ thuật số hoặc decal xuyên sáng, phủ tấm PET chống bụi\n• Kích thước thường làm: A2, A1 hoặc 60x80 cm\n• Lưu ý: đổi nội dung chỉ cần lật bốn cạnh viền và thay tờ in, nhân viên tự làm không cần thợ\n\nTrường Thịnh thiết kế, in và lắp đặt trọn gói.","descriptionEn":"A snap-frame lightbox suits clinics, hospitals and schools that need lit directional signs with content that changes often as rooms and hours change.\n\n• Build: 25-32 mm snap-open aluminium frame, LED light-guide panel, 2-3 cm deep\n• Graphic: digitally printed backlit film or vinyl, under a dust-proof PET cover\n• Typical size: A2, A1 or 60x80 cm\n• Tip: changing the poster just means flipping open the four sides, so staff can do it without a technician\n\nTrường Thịnh designs, prints and installs the sign.","altVi":"Tranh điện nắp bật viền nhôm sơ đồ lối khám bệnh trên tường","altEn":"Snap-frame aluminium lightbox with a patient route diagram on a clinic wall","source":"/assets/content/projects/advertising/led-displays-lightboxes/tranh-dien-nap-bat-phong-kham.webp","sha256":"e195b296c46142ceee7c52f16251a6b67faba9b986aa0d315ae62e7bd6e47913","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 ad23c090ea3a6deac814d1b1ee99d9cfe3fb64f605065f74643ab2b5d9df974a."},
  "led-displays-lightboxes-13": {"descriptionVi":"Bảng LED ma trận một màu gắn cổng hợp với nhà máy, xưởng chế biến, khu công nghiệp cần đăng tin tuyển dụng, chào đoàn khách, nhắc an toàn lao động ngay lối ra vào.\n\n• Module: LED P10 ngoài trời một màu xanh lá, đỏ hoặc trắng, giá thấp nhất trong các loại bảng LED\n• Khung: nhôm định hình, mặt sau tôn kín, bắt vào dầm cổng bằng bát sắt\n• Kích thước thường làm: ngang 3-5 m, cao 35-70 cm\n• Lưu ý: cổng xa nhà điều hành thì chọn card wifi hoặc 4G, đổi nội dung từ văn phòng không cần ra cổng\n\nTrường Thịnh thiết kế, lắp ráp bảng tại xưởng và lắp đặt trọn gói.","descriptionEn":"A single-colour matrix LED sign on the gate suits factories, processing plants and industrial parks that post job openings, welcome visiting groups and give safety reminders right at the entrance.\n\n• Modules: outdoor P10 in single green, red or white, the lowest-cost type of LED sign\n• Frame: aluminium profile, sealed steel back, fixed to the gate beam with steel brackets\n• Typical size: 3-5 m wide, 35-70 cm high\n• Tip: if the gate is far from the office, choose a Wi-Fi or 4G controller so content is changed without walking out\n\nTrường Thịnh designs, assembles the sign in its workshop and installs it.","altVi":"Bảng LED ma trận chữ xanh lá trên dầm cổng nhà máy","altEn":"Green matrix LED sign on the gate beam of a coconut processing plant","source":"/assets/content/projects/advertising/led-displays-lightboxes/bang-led-ma-tran-mot-mau.webp","sha256":"3bfa2e474996f2db2720ae6a6fb4bd8f53c434be3097c1718051594d6fabec25","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:led-displays-lightboxes-13-a; original SHA256 c2ca1127b6525ccfcb79fd8eadeb5e054cd5ce85a440478afb8b1e313b2fdc8b; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-14": {"descriptionVi":"Bảng LED hai màu hợp với nhà hàng, quán ăn sân vườn muốn tách tên quán và món đặc trưng thành hai dòng khác màu, đổi món theo ngày ngay trên điện thoại.\n\n• Module: LED P10 ngoài trời hai màu đỏ và xanh lá, trộn ra thêm màu vàng\n• Khung: nhôm định hình, bắt vào xà gỗ hoặc sắt của cổng bằng pát chữ L\n• Kích thước thường làm: ngang 2-3 m, cao 70 cm cho hai dòng chữ lớn\n• Lưu ý: cổng gỗ ngoài trời co ngót theo mùa, nên bắt bảng qua khung sắt phụ thay vì vít thẳng vào gỗ\n\nTrường Thịnh thiết kế, lắp ráp tại xưởng và lắp đặt trọn gói.","descriptionEn":"A two-colour LED sign suits restaurants and garden eateries that want the name and the signature dishes on two lines in different colours, with the menu changed daily from a phone.\n\n• Modules: outdoor P10 in red and green, which mix to give yellow as well\n• Frame: aluminium profile fixed to the gateway beam with L brackets\n• Typical size: 2-3 m wide, 70 cm high for two lines of large text\n• Tip: outdoor timber moves with the seasons, so mount the sign on a steel sub-frame rather than screwing straight into the wood\n\nTrường Thịnh designs, assembles the sign in its workshop and installs it.","altVi":"Bảng LED hai màu treo trên cổng gỗ nhà hàng ven sông lúc chiều","altEn":"Two-colour LED sign on the timber gateway of a riverside restaurant at dusk","source":"/assets/content/projects/advertising/led-displays-lightboxes/bang-led-hai-mau-nha-hang.webp","sha256":"f18acdc67c72c3576c47dfa9234017bb06398623b002ca25c0a886020d12f58d","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:led-displays-lightboxes-14-a; original SHA256 34474ef03d07cecf4ca608ca162e19ee8ff0066f8072a399873269d9d38f8ae1; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-15": {"descriptionVi":"Bảng vẫy màn hình LED hai mặt hợp với điểm giao dịch, ngân hàng, nhà thuốc trên phố đông, cần chạy logo, video và khuyến mãi về cả hai hướng xe chạy.\n\n• Module: LED ngoài trời full màu P4-P5, hai mặt dùng chung một bộ điều khiển\n• Khung: hộp thép sơn tĩnh điện, tay đỡ hai thanh bắt bu lông hóa chất vào cột\n• Kích thước thường làm: 0,8x1,2 m đến 1x1,6 m mỗi mặt\n• Lưu ý: màn hai mặt nặng hơn hộp đèn nhiều lần, cần kiểm tra cột hoặc tường chịu lực trước khi treo\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A double-sided LED screen projecting sign suits money transfer points, banks and pharmacies on busy streets that want logos, video and offers visible to traffic from both directions.\n\n• Modules: full-colour outdoor LED, P4-P5, both faces on one controller\n• Frame: powder-coated steel case on a twin-arm bracket with chemical anchors\n• Typical size: 0.8x1.2 m to 1x1.6 m per face\n• Tip: a double-sided screen weighs several times more than a lightbox, so check the column or wall can carry it first\n\nTrường Thịnh designs, builds in its own workshop and installs the sign.","altVi":"Bảng vẫy màn hình LED logo chuyển tiền trên tay thép cột đá","altEn":"LED screen projecting sign with a money transfer logo on a granite column","source":"/assets/content/projects/advertising/led-displays-lightboxes/bang-vay-man-hinh-led.webp","sha256":"7ce5d23ae093de1e42744ac1517bd2fdc6d51c07d60ce0ccc4b7b2d3d7c36344","provenance":"AI-generated illustration; Codex gpt-6-sol; source ID codex:2026-11-21:led-displays-lightboxes-15; brand named by the owner; original PNG SHA256 f77243a3be4852bc77a18cf945f1bd14ba9115b46bb3bd25e201570d63ae5355; 1k master, owner approved 2026-11-21."},
  "led-displays-lightboxes-16": {"descriptionVi":"Bảng LED chỉ dẫn bệnh viện treo trần hợp với hành lang khoa khám, khu cận lâm sàng, nơi hướng đi và giờ làm việc đổi theo ca mà biển in cố định không theo kịp.\n\n• Module: LED P4.75 hoặc P5 trong nhà một màu đỏ, hai dòng chữ\n• Treo: ty ren hoặc ống thép bắt vào sàn bê tông phía trên, không treo vào khung trần thạch cao\n• Kích thước thường làm: ngang 1,5-2,5 m, cao 30-40 cm\n• Lưu ý: mép dưới bảng nên cách sàn từ 2,2 m để băng ca, xe đẩy đi qua an toàn\n\nTrường Thịnh thiết kế, lắp ráp tại xưởng và lắp đặt trọn gói.","descriptionEn":"A ceiling-hung hospital LED direction sign suits outpatient corridors and diagnostic areas, where routes and opening hours change by shift faster than printed signs can keep up.\n\n• Modules: indoor single-colour red, P4.75 or P5, two lines\n• Hanging: threaded rods or steel tube fixed to the concrete slab above, never to the plasterboard ceiling grid\n• Typical size: 1.5-2.5 m wide, 30-40 cm high\n• Tip: keep the bottom edge at least 2.2 m above the floor so stretchers and trolleys pass safely\n\nTrường Thịnh designs, assembles the sign in its workshop and installs it.","altVi":"Bảng LED chữ đỏ hai dòng treo ty trần hành lang khoa khám","altEn":"Two-line red LED sign hung on rods in a hospital clinic corridor","source":"/assets/content/projects/advertising/led-displays-lightboxes/bang-led-chi-dan-benh-vien.webp","sha256":"24e1d72b07f64f27edc6244ca122b4776895a7d2d27104b0faa45ef4f04b5069","provenance":"AI-generated illustration; ChatGPT web image edit with owner mask; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 cbfbb7abafa0f6a8029937dcba203a2a087ef2a27d006a48fb179a81215dfafb."},
  "led-displays-lightboxes-17": {"descriptionVi":"Biển LED vẫy một màu hợp với cửa hàng phân bón, vật tư nông nghiệp, đại lý ven đường quê có mái hiên sâu, nơi bảng ngang trên mặt tiền gần như bị che khuất.\n\n• Module: LED P10 ngoài trời một màu, làm hai mặt nếu đường có xe từ cả hai hướng\n• Khung: nhôm định hình, tay vươn sắt hộp sơn tĩnh điện, dây điện đi trong ống ruột gà\n• Kích thước thường làm: ngang 1,2-2 m, cao 40-50 cm\n• Lưu ý: chọn card có hẹn giờ để bảng tự bật lúc chạng vạng và tắt khi đóng cửa\n\nTrường Thịnh thiết kế, lắp ráp tại xưởng và lắp đặt tận nơi.","descriptionEn":"A single-colour LED projecting sign suits fertiliser shops, farm supply stores and roadside dealers with deep awnings, where a fascia sign is almost hidden from the road.\n\n• Modules: outdoor single-colour P10, double-sided if traffic comes both ways\n• Frame: aluminium profile on a powder-coated steel arm, cable run in flexible conduit\n• Typical size: 1.2-2 m wide, 40-50 cm high\n• Tip: pick a controller with a timer so the sign switches on at dusk and off at closing\n\nTrường Thịnh designs, assembles the sign in its workshop and installs it on site.","altVi":"Biển LED vẫy chữ đỏ trên tay sắt trước cửa hàng phân bón","altEn":"Red LED projecting sign on a steel arm outside a fertiliser shop","source":"/assets/content/projects/advertising/led-displays-lightboxes/bien-led-vay-phan-bon.webp","sha256":"1661dd832e27f790ad55fd1fa51b1ddb2ceda403c0fdf08be5860232a9461af7","provenance":"AI-generated illustration; ChatGPT web image edit with owner mask; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 ca8729a77ad5b20b3370feb3dba05431dd5fcf6509b504fd183cc17be524c65f."},
  "led-displays-lightboxes-18": {"descriptionVi":"Màn hình LED ngoài trời dựng trên giàn truss hợp với lễ hội, hội chợ xúc tiến đầu tư, lễ ra mắt sản phẩm ở quảng trường hay sân bãi, dựng xong trong ngày và tháo dời đi nơi khác.\n\n• Module: LED cho thuê ngoài trời P3.9-P4.8, cabinet nhôm đúc 500x500 mm khóa nhanh\n• Kết cấu: giàn truss nhôm, chân đế dằn tải, cáp giằng chống gió\n• Kích thước thường làm: ngang 4-8 m, cao 3-4,5 m\n• Lưu ý: sân khấu ngoài trời cần phương án che mưa cho màn và tủ điện, nhất là vào mùa mưa\n\nTrường Thịnh khảo sát mặt bằng, dựng giàn, lắp màn và cử kỹ thuật trực suốt chương trình.","descriptionEn":"An outdoor LED screen on truss suits festivals, investment promotion fairs and product launches held in squares or open grounds, going up in a day and moving on to the next venue.\n\n• Modules: outdoor rental LED, P3.9-P4.8, quick-lock 500x500 mm die-cast cabinets\n• Structure: aluminium truss, ballasted bases, guy cables against wind\n• Typical size: 4-8 m wide, 3-4.5 m high\n• Tip: an outdoor stage needs a rain plan for the screen and the power cabinet, especially in the wet season\n\nTrường Thịnh surveys the site, rigs the truss, installs the screen and keeps a technician on hand throughout.","altVi":"Màn hình LED sân khấu trên giàn truss nhôm chiếu chủ đề ngành dừa","altEn":"Stage LED screen on aluminium truss showing a coconut industry theme","source":"/assets/content/projects/advertising/led-displays-lightboxes/man-hinh-led-ngoai-troi-truss.webp","sha256":"277de8ae144bd7efd8258926b4a333ef0c98da94822e54d5d1d0fc024569fffe","provenance":"AI-generated illustration; ChatGPT web image edit with owner mask (chat 6ae5fa09-eab8-83ec-bfba-c30dc31894dc); upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-27; master PNG SHA256 db2c76530facdf6974069658d8dc5a674abc64ed220f64281bfdbabadf7772b2."},
  "print-decals-01": {"descriptionVi":"In card visit trên giấy mỹ thuật hợp với studio thiết kế, công ty kiến trúc, thương hiệu nhỏ muốn tấm danh thiếp cầm lên đã thấy chất giấy, không cần nhiều chữ.\n\n• Giấy: mỹ thuật vân nhám hoặc kraft trắng, định lượng 300-350 gsm\n• In: kỹ thuật số cho vài hộp, offset khi in số lượng lớn để màu đều giữa các lô\n• Quy cách: 90x54 mm, in hai mặt, bo góc hoặc để góc vuông\n• Lưu ý: mảng màu in tràn mép cần chừa 2 mm xén, tránh hở viền trắng sau khi cắt\n\nTrường Thịnh thiết kế, in và giao tận nơi trọn gói.","descriptionEn":"Art-paper business card printing suits design studios, architecture firms and small brands that want the card to feel like quality stock before anyone reads it.\n\n• Paper: textured art paper or white kraft, 300-350 gsm\n• Print: digital for a few boxes, offset for larger runs so colour stays even\n• Format: 90x54 mm, printed both sides, rounded or square corners\n• Tip: full-bleed colour blocks need 2 mm extra for trimming, or a white edge can show\n\nTrường Thịnh designs, prints and delivers to your door.","altVi":"Chồng danh thiếp giấy mỹ thuật mảng màu đất nung trên khối bê tông","altEn":"Stack of art-paper business cards with terracotta colour blocks on concrete","source":"/assets/content/projects/advertising/print-decals/in-card-visit-giay-my-thuat.webp","sha256":"44dd7f9149f8a5b54b5f4264b9757a19f478a9c2b55edfe24bf8bebedaebe177","provenance":"AI-generated illustration; Codex gpt-6-sol; source ID codex:2026-11-22:print-decals-01; original PNG SHA256 75e35e4e4c641f6f0db3dd1c0ed799d3e23d7239bb7834e8a894ba094b810364; 1k master, owner approved 2026-11-21."},
  "print-decals-02": {"descriptionVi":"In tờ rơi giấy couché hợp với quán trà, quán nước mới mở cần phát nhanh ở quầy, ngoài phố hay bỏ kèm đơn giao hàng để giới thiệu món và khuyến mãi.\n\n• Giấy: couché 150 gsm cho tờ phát tay, 200-250 gsm nếu muốn khách giữ lại lâu\n• Khổ thường làm: A5, A6, in một hoặc hai mặt\n• In: offset từ vài nghìn tờ để giá mỗi tờ thấp, kỹ thuật số khi cần gấp số ít\n• Lưu ý: tờ bỏ kèm đơn giao hàng nên chọn khổ A6 để vừa túi, không phải gập\n\nTrường Thịnh thiết kế, in và giao tận nơi trọn gói.","descriptionEn":"Coated-paper flyer printing suits new tea and drinks shops that need something quick to hand out at the counter, on the street or inside delivery bags to introduce the menu and offers.\n\n• Paper: 150 gsm coated for handouts, 200-250 gsm if you want customers to keep it\n• Typical size: A5 or A6, single or double sided\n• Print: offset from a few thousand sheets for a low unit price, digital for small rush jobs\n• Tip: flyers that go into delivery bags work best at A6, so they fit without folding\n\nTrường Thịnh designs, prints and delivers to your door.","altVi":"Xấp tờ rơi couché in trà trái cây với hình cam, dâu, đào","altEn":"Stack of coated-paper flyers for a fruit tea shop with orange, strawberry and peach","source":"/assets/content/projects/advertising/print-decals/in-to-roi-tra-trai-cay.webp","sha256":"e81d20666349e2eb48c79fbeeb3af2dbbfc73185114b88ae1cca7112ec50affb","provenance":"AI-generated illustration; source ID imagegen:2026-09-13:print-flyers-fnb-owner-r2-v3; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "print-decals-03": {"descriptionVi":"Brochure gấp ba hợp với showroom gạch ốp lát, thiết bị vệ sinh, vật liệu nội thất cần một ấn phẩm gọn để khách mang về so mẫu và bàn với gia đình.\n\n• Giấy: couché 200-250 gsm, cán màng mờ để ảnh vân gạch không lóa\n• Khổ thường làm: A4 gấp ba thành 10x21 cm, vừa kệ brochure\n• Gia công: cấn lằn trước khi gấp để nếp gấp không nứt mực\n• Lưu ý: ảnh vân gạch nên in thử một tờ để so với mẫu thật, tránh khách thấy lệch màu\n\nTrường Thịnh thiết kế, in, gấp và giao tận nơi trọn gói.","descriptionEn":"A tri-fold brochure suits tile, sanitaryware and interior materials showrooms that need a compact piece customers can take home to compare samples and discuss with family.\n\n• Paper: 200-250 gsm coated with matt lamination, so tile photos don't glare\n• Typical size: A4 folded in three to 10x21 cm, sized for brochure racks\n• Finishing: creased before folding so the ink doesn't crack along the folds\n• Tip: proof one sheet against the real tiles, so customers don't find the colours off\n\nTrường Thịnh designs, prints, folds and delivers to your door.","altVi":"Brochure gấp ba in ảnh phòng tắm và mẫu gạch, dựng trên mặt đá","altEn":"Tri-fold brochures with bathroom and tile photos standing on travertine","source":"/assets/content/projects/advertising/print-decals/brochure-gap-ba-showroom-gach.webp","sha256":"e926f3d5cc5bd0ccf22e1f4d8bfa65d1723a59cd9436882e748a841a5c654401","provenance":"AI-generated illustration; Codex gpt-6-sol; source ID codex:2026-11-22:print-decals-03; original PNG SHA256 37598ad65b636880090b7e32c5c04192961b01329a2fc12eff0a1d9127006489; 1k master, owner approved 2026-11-21."},
  "print-decals-04": {"descriptionVi":"In catalogue bìa cứng gáy vuông hợp với xưởng nội thất, nhà sản xuất cần một cuốn giới thiệu bộ sưu tập dày trang, gửi đại lý và khách dự án dùng nhiều năm.\n\n• Bìa: carton 2-3 mm bọc giấy in, cán màng mờ chống trầy\n• Ruột: couché hoặc giấy mỹ thuật 150-200 gsm, may chỉ hoặc keo nhiệt gáy vuông\n• Khổ thường làm: A4 đứng hoặc vuông 25x25 cm, từ 40 trang trở lên\n• Lưu ý: trang vật liệu và mẫu màu nên duyệt bản in thử, màu gỗ và vải dễ lệch khi in\n\nTrường Thịnh thiết kế, in, đóng cuốn và giao tận nơi trọn gói.","descriptionEn":"Hardcover square-spine catalogue printing suits furniture workshops and manufacturers that need a substantial collection book for dealers and project clients to keep for years.\n\n• Cover: 2-3 mm board wrapped in printed paper, matt laminated against scuffs\n• Pages: 150-200 gsm coated or art paper, sewn or PUR-bound with a square spine\n• Typical size: A4 portrait or 25x25 cm square, from 40 pages up\n• Tip: approve a proof of the materials and swatch pages, as wood and fabric tones shift easily in print\n\nTrường Thịnh designs, prints, binds and delivers the catalogues.","altVi":"Catalogue nội thất bìa cứng, một cuốn mở trang vật liệu trên bàn inox","altEn":"Hardcover furniture catalogues, one open at a materials spread, on a steel bench","source":"/assets/content/projects/advertising/print-decals/in-catalogue-bia-cung-gay-vuong.webp","sha256":"46bff4331771ccd0b39fd02f3307e2a18a8f8e429860008a08b865340d3bd6f5","provenance":"AI-generated illustration; Codex gpt-6-sol; source ID codex:2026-11-22:print-decals-04; original PNG SHA256 f36919ea461857ca0850b6c9e98dc585e8224b0299d5087df02c59837a3d1779; 1k master, owner approved 2026-11-21."},
  "print-decals-05": {"descriptionVi":"In thiệp cưới giấy mỹ thuật hợp với cô dâu chú rể thích kiểu thiệp nhẹ nhàng, ít màu, cầm lên thấy được vân giấy thay vì ép kim lấp lánh.\n\n• Giấy: mỹ thuật màu kem hoặc trắng ngà 250-300 gsm, phong bì cùng loại giấy\n• Quy cách: gấp đôi hoặc một tờ phẳng, khổ 12x17 cm hoặc 13x18 cm\n• Hoàn thiện: in màu kỹ thuật số, buộc dây gai, ép kim hay dập nổi tên nếu muốn\n• Lưu ý: đặt in trước ngày phát thiệp 3-4 tuần, chừa thời gian sửa tên và in bù\n\nTrường Thịnh thiết kế, in và giao thiệp tận nơi.","descriptionEn":"Art-paper wedding invitations suit couples who prefer a quiet, low-colour card where guests feel the paper texture rather than shiny foil.\n\n• Paper: 250-300 gsm cream or ivory art paper, with envelopes in the same stock\n• Format: folded or flat card, 12x17 cm or 13x18 cm\n• Finishing: digital colour print, jute twine, optional foil or embossed names\n• Tip: order 3-4 weeks before sending, leaving time to correct names and reprint\n\nTrường Thịnh designs, prints and delivers the invitations.","altVi":"Thiệp cưới gấp đôi in hoa lá nhạt kèm phong bì màu kem","altEn":"Folded wedding invitations with soft floral print and cream envelopes","source":"/assets/content/projects/advertising/print-decals/in-thiep-cuoi-giay-my-thuat.webp","sha256":"1f16a99bf0f2162cc697eaeaef99e91c830d0e87e6dd7c118ce8ac13593f3617","provenance":"AI-generated illustration; Codex gpt-6-sol; source ID codex:2026-11-22:print-decals-05; original PNG SHA256 c753d6fe779684f8f15c7e4bdfd8cb2a8bab9e679c7c7504dae044197537ddc2; 1k master, owner approved 2026-11-21."},
  "print-decals-06": {"descriptionVi":"In giấy chứng nhận kèm bìa đựng và phong bì in logo hợp với công ty, trung tâm đào tạo, hiệp hội trao khen thưởng, chứng chỉ khóa học cần bộ giấy tờ đồng nhận diện.\n\n• Giấy: mỹ thuật hoặc couché 250-300 gsm, khổ A4 hoặc A5 ngang\n• Bìa đựng: carton bồi giấy màu, có góc gài và chân dựng\n• Phong bì: khổ 12x22 cm hoặc C5, in logo một màu hoặc in màu đủ\n• Lưu ý: để trống ô tên người nhận rồi in lẻ bằng máy văn phòng, sửa tên không phải in lại cả lô\n\nTrường Thịnh thiết kế, in và giao tận nơi trọn gói.","descriptionEn":"Printed certificates with matching folders and logo envelopes suit companies, training centres and associations handing out awards or course certificates as one branded set.\n\n• Paper: 250-300 gsm art or coated paper, A4 or A5 landscape\n• Folder: board wrapped in coloured paper, with corner slots and a stand\n• Envelopes: 12x22 cm or C5, logo in one colour or full colour\n• Tip: leave the name field blank and fill it on an office printer, so a typo never means reprinting the batch\n\nTrường Thịnh designs, prints and delivers to your door.","altVi":"Giấy chứng nhận viền xanh navy, bìa đựng đứng và phong bì in logo","altEn":"Navy-bordered certificates, a standing presentation folder and logo envelopes on a desk","source":"/assets/content/projects/advertising/print-decals/in-giay-chung-nhan-phong-bi.webp","sha256":"c2572b0d465d978181b07d42fe72c4f8cf9cf0bb107633a03744d77ccfdb5dbe","provenance":"AI-generated illustration; Codex gpt-6-sol; source ID codex:2026-11-22:print-decals-06; original PNG SHA256 3300ee6d6d59dadcb9607cc55004c65fb9277b9027d9a86cc430b517664e4510; 1k master, owner approved 2026-11-21."},
  "print-decals-07": {"descriptionVi":"Menu bìa da ép nhũ và bìa gỗ khắc laser hợp với nhà hàng Âu, khách sạn, quán bar cần cuốn menu dùng nhiều năm, chỉ thay ruột khi đổi món.\n\n• Bìa da: simili hoặc da PU bồi carton, logo ép nhũ vàng hay nhũ bạc\n• Bìa gỗ: gỗ óc chó hoặc gỗ tràm ép, khắc laser logo, phủ dầu chống ẩm\n• Gáy: ốc vít đồng, tháo ra thay ruột mà không phải làm lại bìa\n• Ruột: giấy mỹ thuật hoặc giấy chịu nước, khổ A4 hoặc A5\n\nTrường Thịnh thiết kế, gia công bìa tại xưởng và in ruột trọn gói.","descriptionEn":"Foil-stamped leather and laser-engraved timber menu covers suit restaurants, hotels and bars that want a menu lasting for years, with only the inner pages changed when dishes change.\n\n• Leather cover: faux or PU leather over board, logo foil-stamped in gold or silver\n• Timber cover: walnut or acacia board, laser-engraved logo, oiled against moisture\n• Spine: brass screw posts, so pages are swapped without remaking the cover\n• Pages: art paper or waterproof stock, A4 or A5\n\nTrường Thịnh designs, makes the covers in its own workshop and prints the pages.","altVi":"Menu bìa da xanh ép nhũ, bìa gỗ khắc laser và cuốn mở ruột","altEn":"Green foil-stamped leather menu, laser-engraved timber cover and an open menu","source":"/assets/content/projects/advertising/print-decals/menu-bia-da-bia-go.webp","sha256":"79c233aa9b8fc7f82c7325451820204986c07b92801e32734d5b270aae78fa87","provenance":"AI-generated illustration; Codex gpt-6-sol; source ID codex:2026-11-22:print-decals-07; original PNG SHA256 4134545136fda20877287d132e80a68dc4a082f32503342f35bbcdf68646474c; 1k master, owner approved 2026-11-21."},
  "print-decals-08": {"descriptionVi":"Menu nhựa chống nước hợp với quán ăn, quán phở, quán cơm đông khách, nơi thực đơn qua tay nhiều người và hay dính dầu mỡ, nước canh.\n\n• Chất liệu: giấy C300 ép plastic dày hai mặt, viền trong bo góc, hoặc nhựa PP in UV\n• In: kỹ thuật số cho số lượng ít, offset khi in từ vài trăm tờ\n• Kích thước thường làm: A4, A3, gập đôi hoặc gập ba\n• Lưu ý: quán hay đổi giá nên in số lượng vừa đủ, menu ép plastic làm lại nhanh hơn menu nhựa PP\n\nTrường Thịnh thiết kế, in và giao tận nơi trọn gói.","descriptionEn":"Waterproof plastic menus suit busy eateries, noodle and rice shops where menus pass through many hands and pick up grease and broth.\n\n• Material: 300 gsm art paper in thick two-sided laminate with a rounded clear border, or UV-printed PP plastic\n• Print: digital for short runs, offset from a few hundred sheets\n• Typical size: A4, A3, folded in half or in three\n• Tip: if your prices change often, order a modest run, since laminated sheets are quicker to redo than printed PP\n\nTrường Thịnh designs, prints and delivers to your door.","altVi":"Menu nhựa ép plastic in món Việt và đồ uống trên bàn quán","altEn":"Laminated plastic menus listing Vietnamese dishes and drinks on a café table","source":"/assets/content/projects/advertising/print-decals/menu-nhua-chong-nuoc-quan-an.webp","sha256":"60da035935650cd167b271ec6f6ec6348ee5430a3bcd8556602e7385110cf876","provenance":"AI-generated illustration; Codex gpt-6-sol; source ID codex:2026-11-22:print-decals-08; original PNG SHA256 cb335d285fee9f3dadc4331163d581dff4ac2dd12ae514e6ad1422cca9ca5bbf; 1k master, owner approved 2026-11-21."},
  "print-decals-09": {"descriptionVi":"Menu mica để bàn in UV trực tiếp hợp với quán cà phê, nhà hàng nhỏ muốn khách xem món ngay khi ngồi, không phải đợi nhân viên mang menu cuốn ra.\n\n• Chất liệu: mica trong 3-5 mm cắt CNC theo dáng, cắm khe đế gỗ sồi hoặc gỗ cao su\n• In: UV trực tiếp lên mặt sau mica, mực nằm phía trong nên lau không bong\n• Kích thước thường làm: A5, A6 đứng hoặc 10x20 cm\n• Lưu ý: giá in thẳng lên mica thì đổi giá phải in lại cả tấm, quán hay đổi giá nên chọn kiểu kẹp tờ giấy\n\nTrường Thịnh thiết kế, cắt mica, in UV và giao tận nơi.","descriptionEn":"UV-printed acrylic table menus suit cafés and small restaurants that want guests reading the menu as soon as they sit, without waiting for staff to bring a menu book.\n\n• Material: 3-5 mm clear acrylic, CNC-cut to shape, slotted into oak or rubberwood bases\n• Print: UV-printed on the back face, so the ink sits behind the acrylic and won't wipe off\n• Typical size: A5, A6 portrait or 10x20 cm\n• Tip: prices printed straight onto acrylic mean a new panel for every change, so shops that reprice often should use a sheet holder\n\nTrường Thịnh designs, cuts, UV-prints and delivers the menus.","altVi":"Hai menu mica đế gỗ in UV ghi FOOD và DRINKS cạnh menu cuốn","altEn":"Two UV-printed acrylic menus on timber bases beside an open menu book","source":"/assets/content/projects/advertising/print-decals/menu-mica-de-ban-de-go.webp","sha256":"ee2b547429a8d51394e04287349bf7df62b1976694084c511f183329cb2c2a18","provenance":"AI-generated illustration; Codex gpt-6-sol; source ID codex:2026-11-22:print-decals-09; original PNG SHA256 2f360406dccc41fbf9b81700e0e21f183bfc113d103efa479c656f0503d4b89a; 1k master, owner approved 2026-11-21."},
  "print-decals-10": {"descriptionVi":"In bạt hiflex làm banner là cách quảng cáo rẻ và nhanh cho quán cà phê, cửa hàng chạy món mới, khai trương hay khuyến mãi theo đợt, hết đợt thay tấm khác.\n\n• Chất liệu: bạt hiflex 280-340 gsm, chọn loại xuyên sáng nếu sau này lắp đèn\n• In: máy khổ lớn mực dầu, bền màu ngoài trời từ vài tháng đến hơn một năm\n• Gia công: may viền, đóng khoen inox cách 30-50 cm, căng dây lên khung sắt\n• Lưu ý: tấm căng ngoài trời khổ trên 3 m nên đục lỗ thoát gió để không rách khoen\n\nTrường Thịnh thiết kế, in, làm khung và lắp đặt trọn gói.","descriptionEn":"Hiflex banner printing is the cheapest, quickest advertising for cafés and shops running a new drink, an opening or a seasonal promotion, swapped out when the campaign ends.\n\n• Material: 280-340 gsm hiflex, or backlit grade if lighting may be added later\n• Print: large-format solvent printer, colourfast outdoors from a few months to over a year\n• Finishing: hemmed edges, stainless eyelets every 30-50 cm, laced to a steel frame\n• Tip: outdoor banners over 3 m wide need wind slits, or the eyelets tear out\n\nTrường Thịnh designs, prints, builds the frame and installs the banner.","altVi":"Banner bạt hiflex quảng cáo cà phê căng dây trên khung sắt đen","altEn":"Hiflex coffee banner tied to a black steel frame outside a café","source":"/assets/content/projects/advertising/print-decals/in-bat-hiflex-banner-ca-phe.webp","sha256":"6cdaf5f979fdc157a70b18edb786973e1eb695c1c5e5d28275b3eecd27346ced","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd2e5-d558-83ec-872f-73e40836ae7b); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-27 01:07Z; master PNG SHA256 1278e7999d4095db88216494d0773a0475266d145262ccd078c90255f37fbaa6."},
  "print-decals-11": {"descriptionVi":"Decal dán kính mặt tiền hợp với cửa hàng đặc sản, tiệm bánh kẹo, shop nhỏ mặt phố có vách kính lớn, biến mặt kính thành chỗ đặt tên và hình sản phẩm.\n\n• Chất liệu: decal PVC in màu cho mảng kín, decal lưới một chiều nếu cần nhìn từ trong ra\n• In: mực dầu hoặc UV, cán màng chống UV để không phai dưới nắng\n• Gia công: cắt bế theo đường hình bằng máy, dán ướt để không còn bọt khí\n• Lưu ý: cùng file thiết kế có thể in thêm decal dán thùng xe giao hàng cho đồng bộ\n\nTrường Thịnh thiết kế, in và dán tận nơi trọn gói.","descriptionEn":"Window decals suit specialty food shops, sweet shops and small street-front stores with large glass fronts, turning the glass into space for the name and product images.\n\n• Material: printed PVC vinyl for solid areas, one-way perforated vinyl where staff need to see out\n• Print: solvent or UV inks with UV-protective lamination, so colours don't fade in the sun\n• Finishing: machine contour-cut and applied wet, leaving no air bubbles\n• Tip: the same artwork can be printed for delivery box and vehicle decals to match\n\nTrường Thịnh designs, prints and applies the decals on site.","altVi":"Decal xanh lá in hình dừa dán kín vách kính cửa hàng kẹo dừa","altEn":"Green coconut-themed decals covering a candy shop's glass frontage","source":"/assets/content/projects/advertising/print-decals/decal-dan-kinh-keo-dua.webp","sha256":"b9ebb2de20480e8c9e7712d6c6d5bc3712f8380d2770946483883bc354644f9a","provenance":"AI-generated illustration; ChatGPT web (chat 6ae624fe-198c-83ec-8919-3c8fab92403c); upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 dcd667e0c00c12ab816a58d2f35c578e7e3b85678c873806203351f319812ebb."},
  "print-decals-12": {"descriptionVi":"Tranh canvas khung gỗ treo theo bộ hợp với quán cà phê, homestay, phòng khách cần một mảng tường điểm nhấn mà không phải sơn vẽ lại.\n\n• Chất liệu: vải canvas cotton pha, in mực gốc dầu hoặc UV, căng trên khung gỗ thông sấy\n• Khung viền: gỗ sồi kiểu khung nổi, chừa khe hở quanh tranh\n• Kích thước thường làm: 30x40, 40x60, 60x90 cm, phối lớn nhỏ trong một bộ\n• Lưu ý: treo ở phòng ẩm thì nên chọn khung gỗ đã sấy, tránh cong vênh làm chùng vải\n\nTrường Thịnh chọn ảnh, in, đóng khung và giao tận nơi trọn gói.","descriptionEn":"A set of timber-framed canvas prints suits cafés, homestays and living rooms that need a feature wall without repainting.\n\n• Material: cotton-blend canvas, solvent or UV inks, stretched over kiln-dried pine\n• Frame: oak floater frame with a small gap around the canvas\n• Typical size: 30x40, 40x60 or 60x90 cm, mixed within one set\n• Tip: for humid rooms insist on kiln-dried stretcher bars, which won't warp and let the canvas sag\n\nTrường Thịnh helps pick the images, then prints, frames and delivers the set.","altVi":"Bộ năm tranh canvas viền gỗ mảnh treo trên vách trắng","altEn":"Set of five canvas prints in slim timber frames on a white wall","source":"/assets/content/projects/advertising/print-decals/tranh-canvas-khung-go-treo-tuong.webp","sha256":"70be2d90437d244d83dc1c00c6af496f5e8ddd9785a6771c30d6efc64354ed8a","provenance":"AI-generated illustration; Codex gpt-6-sol; source ID codex:2026-11-22:print-decals-12; original PNG SHA256 29f70897dbb4bbb81331959b7fe3d3debf3c42f3c0519bf05e1f9b1276fbdbde; 1k master, owner approved 2026-11-21."},
  "print-decals-13": {"descriptionVi":"In danh thiếp giấy mỹ thuật cho kiến trúc sư, văn phòng thiết kế nhà phố thường chọn hai màu trầm, ít chữ, để tấm thẻ gọn gàng như một bản vẽ.\n\n• Giấy: mỹ thuật trắng ngà phối giấy màu xanh rêu, 300-350 gsm\n• Gia công: bo góc 3-5 mm, ép kim hoặc in nổi logo để có điểm nhấn khi chạm tay\n• Quy cách: 90x54 mm, mỗi hộp 100 tấm\n• Lưu ý: giấy màu đậm khó in chữ trắng bằng mực thường, nên dùng ép kim trắng hoặc ép nhũ\n\nTrường Thịnh thiết kế, in và giao tận nơi trọn gói.","descriptionEn":"Art-paper business cards for architects and townhouse design practices usually stay with two muted colours and little text, keeping the card as clean as a drawing.\n\n• Paper: ivory art paper paired with moss-green coloured stock, 300-350 gsm\n• Finishing: 3-5 mm rounded corners, foil or embossed logo for something to feel\n• Format: 90x54 mm, 100 cards per box\n• Tip: white text is hard to print with standard ink on dark stock, so use white foil or metallic foil instead\n\nTrường Thịnh designs, prints and delivers to your door.","altVi":"Danh thiếp kiến trúc nền kem và xanh rêu bo góc trên bàn gỗ","altEn":"Cream and moss-green rounded architect business cards on a timber desk","source":"/assets/content/projects/advertising/print-decals/print-decals-13-imagegen-20261019.webp","sha256":"164348870131619a55cb5a8c796378b5f07fd5d4ec21a805c8671e745828d80e","provenance":"AI-generated illustration; source ID imagegen:2026-10-19:print-decals-13-a-3; original SHA256 d89a35f97d44464f8e2b611ce54d7cb0cf74ac5fd8dc5f9c20cd193b5121ad20; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "print-decals-14": {"descriptionVi":"Tờ rơi khai trương hợp với quán bánh mì, quán ăn nhỏ mới mở, phát tay ở chợ, cổng trường, khu dân cư trong vài tuần đầu để kéo khách ghé thử.\n\n• Giấy: couché 120-150 gsm, đủ cứng để cầm mà không tốn kém\n• Khổ thường làm: A5 hoặc A6, in một mặt cho đợt phát lớn\n• Số lượng: 1.000-5.000 tờ, in offset rẻ hơn hẳn in kỹ thuật số\n• Lưu ý: in kèm phiếu giảm giá cắt rời để đếm được bao nhiêu khách tới nhờ tờ rơi\n\nTrường Thịnh thiết kế, in và giao tận nơi trọn gói.","descriptionEn":"Opening flyers suit new bánh mì stalls and small eateries handing them out at markets, school gates and neighbourhoods in the first few weeks to bring people in to try.\n\n• Paper: 120-150 gsm coated, stiff enough to hold without costing much\n• Typical size: A5 or A6, single-sided for large drops\n• Quantity: 1,000-5,000 sheets, where offset is far cheaper than digital\n• Tip: add a tear-off discount coupon so you can count how many customers the flyers bring\n\nTrường Thịnh designs, prints and delivers to your door.","altVi":"Tờ rơi khai trương quán bánh mì được phát tay ở chợ","altEn":"Bakery opening flyer being handed out at an outdoor market","source":"/assets/content/projects/advertising/print-decals/print-decals-14-flyers-v2.webp","sha256":"4e3aa2098ed3b755d42c1973e684c102c03e7332f07ce6993eada4b09c13fa42","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:print-decals-14-a; original SHA256 971fd76f6905ac6f9689ccb7ff77aae108ca648c335b1b3416abb9a06013f3c6; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "print-decals-15": {"descriptionVi":"Kệ mica đựng brochure hợp với quầy lễ tân khách sạn, trung tâm hội nghị, phòng khám, showroom, nơi khách tự lấy tài liệu trong lúc chờ.\n\n• Chất liệu: mica trong 2-3 mm uốn nhiệt, mép cắt CNC đánh bóng\n• Quy cách: 2-4 ngăn bậc thang, ngăn vừa A4 gấp ba hoặc A5\n• Đi kèm: brochure, tờ gấp giới thiệu sảnh tiệc, phòng hội nghị in cùng bộ màu\n• Lưu ý: ngăn nên rộng hơn ấn phẩm 5-10 mm để khách rút ra dễ, không bị kẹt\n\nTrường Thịnh gia công kệ mica tại xưởng, in ấn phẩm và giao tận nơi.","descriptionEn":"An acrylic brochure holder suits hotel reception desks, conference centres, clinics and showrooms where guests help themselves to information while they wait.\n\n• Material: 2-3 mm clear acrylic, heat-bent, with CNC-cut polished edges\n• Format: 2-4 stepped pockets sized for DL tri-folds or A5\n• Supplied with: brochures and leaflets for banquet and meeting rooms in one colour scheme\n• Tip: make pockets 5-10 mm wider than the print, so leaflets slide out without jamming\n\nTrường Thịnh makes the acrylic holder in its own workshop, prints the literature and delivers both.","altVi":"Kệ mica ba ngăn đựng brochure sảnh tiệc trên quầy lễ tân","altEn":"Three-tier acrylic brochure holder with banquet hall leaflets on a hotel reception desk","source":"/assets/content/projects/advertising/print-decals/ke-mica-dung-brochure-le-tan.webp","sha256":"2b3e949ec1cabc514655ae58010470487b1b441252651f8c99fa365e879048f1","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:print-decals-15-a; original SHA256 968242ecf9f31c95e5bf843d4cc2e90f3807746500891c8a6dc1fc3b6d331f81; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "print-decals-16": {"descriptionVi":"Catalogue nội thất bìa cứng in như sách ảnh hợp với showroom, nhà thiết kế muốn đặt trên bàn tiếp khách hoặc kệ trưng bày, vừa giới thiệu sản phẩm vừa làm vật trang trí.\n\n• Bìa: bìa cứng bọc giấy mỹ thuật, một ảnh lớn, chữ tối giản\n• In: offset 4 màu, ruột 157-200 gsm để ảnh không gian lên đủ chiều sâu\n• Đóng cuốn: may chỉ gáy vuông, mở phẳng hai trang không gãy ảnh\n• Lưu ý: làm mỗi dòng sản phẩm một màu bìa, xếp chung trên kệ vẫn đồng bộ\n\nTrường Thịnh thiết kế, dàn trang, in và giao tận nơi trọn gói.","descriptionEn":"Hardcover interior catalogues printed like photo books suit showrooms and designers who want them on the client table or display shelf, both presenting products and dressing the space.\n\n• Cover: hardcover wrapped in art paper, one large image, minimal type\n• Print: four-colour offset on 157-200 gsm pages for depth in room shots\n• Binding: sewn square spine that opens flat without breaking spreads\n• Tip: give each product line its own cover colour, so the set still matches on a shelf\n\nTrường Thịnh designs, lays out, prints and delivers the catalogues.","altVi":"Bộ catalogue nội thất bìa cứng dựng đứng, một cuốn mở trên bàn gỗ","altEn":"Hardcover interior catalogues standing upright, one open on a timber table","source":"/assets/content/projects/advertising/print-decals/catalogue-noi-that-trung-bay.webp","sha256":"e490331f23e4c24251ec73275a0ecce98d97021ef1ffdc33f71d3efbada93346","provenance":"AI-generated illustration; Codex gpt-6-sol; source ID codex:2026-11-22:print-decals-16; original PNG SHA256 c77d662d7b97a00ca6325ede3ca218576cf5935e5e8da0d15fb57459181aa1af; 1k master, owner approved 2026-11-21."},
  "kiosk-posm-44": {"descriptionVi":"Backdrop hội nghị dạng vòm hợp với hội nghị xúc tiến thương mại, hội thảo nông sản ở sảnh khách sạn, dùng làm cả phông đón khách lẫn góc check-in.\n\n• Kết cấu: khung gỗ ép hoặc formex cắt CNC theo vòm, mặt in bạt hoặc decal\n• Viền: nan gỗ uốn có LED hắt, cột chữ chủ đề in UV\n• Kích thước thường làm: ngang 5-7 m, cao 3-3,5 m\n• Lưu ý: hỏi khách sạn chiều cao trần sảnh và giờ được dựng, vòm cao thường phải dựng từ đêm trước\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và thi công trọn gói từ lúc dựng đến khi tháo.","descriptionEn":"An arched conference backdrop suits trade promotion conferences and farm produce seminars in hotel foyers, serving as both the welcome wall and the check-in photo spot.\n\n• Structure: plywood or foam PVC frame CNC cut to the arch, faced with printed banner or vinyl\n• Edging: bent timber slats with LED backlight, theme columns UV printed\n• Typical size: 5-7 m wide, 3-3.5 m high\n• Tip: ask the hotel for the foyer ceiling height and set-up hours, as tall arches usually go up the night before\n\nTrường Thịnh designs, builds and handles the backdrop from set-up to take-down.","altVi":"Backdrop vòm in cảnh sông nước, viền nan gỗ và bảng check-in tròn","altEn":"Arched backdrop with a river scene, timber slat edging and a round check-in sign","source":"/assets/content/projects/advertising/kiosk-posm/backdrop-hoi-nghi-vom.webp","sha256":"3178f921eeb7565d25880b0c143221e73a55a0866797e7c025b6907139c782a4","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd3a3-0bd0-83ec-9259-a005bd90ca4b); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-27 01:07Z; master PNG SHA256 b313ec01f8c1a28d77873f1bc49b84fde1fac781cc121e505aa26498af815ee6."},
  "kiosk-posm-45": {"descriptionVi":"Gian hàng đặc sản khung gỗ nan dọc hợp với cơ sở OCOP, hợp tác xã trái cây, kẹo dừa đi hội chợ, cần vừa bày hàng vừa có chỗ mời khách ngồi dùng thử.\n\n• Kết cấu: khung gỗ thông hoặc MDF chống ẩm, nan gỗ dọc sơn PU, bảng tên cắt CNC\n• Kệ: nhiều tầng gắn vào vách, chịu được chai lọ, hũ thủy tinh\n• Kích thước thường làm: 3x3 m, 3x6 m theo ô ban tổ chức\n• Lưu ý: quầy và kệ làm module bắt vít thì tháo gọn lên một xe tải nhỏ, mang đi được nhiều kỳ hội chợ\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và thi công gian hàng trọn gói.","descriptionEn":"A slatted timber specialty-goods booth suits regional producers, fruit cooperatives and coconut candy makers at trade fairs, giving room both to display products and to seat visitors for tastings.\n\n• Structure: pine or moisture-resistant MDF frame, vertical PU-finished slats, CNC-cut name sign\n• Shelving: multi-tier units fixed to the walls, strong enough for bottles and glass jars\n• Typical size: 3x3 m or 3x6 m to suit the organiser's plot\n• Tip: a bolted modular counter and shelving pack onto one small truck and travel to many fairs\n\nTrường Thịnh designs, builds and installs the whole booth.","altVi":"Gian hàng nan gỗ có kệ đặc sản, quầy cong và tranh sông nước","altEn":"Timber slat booth with specialty shelves, a curved counter and river-scene print","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-45-imagegen-20261018.webp","sha256":"c273d3a28c882e0238f79b489fcebad32aa76f2c77bc4232cca742555575459d","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd387-5cf4-83ec-b31c-b03f2e56c353); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-27 01:07Z; master PNG SHA256 80c1f1ee99068e33f1917a836ee770471544645e017c3ea4d58c2ac490362188."},
  "kiosk-posm-46": {"descriptionVi":"Backdrop sân khấu hội nghị ghép nhiều lớp hợp với hội nghị ngành, hội nghị khách hàng ở phòng tiệc lớn, nơi sân khấu ngang từ 10 m cần chiều sâu hơn một tấm bạt phẳng.\n\n• Kết cấu: khung sắt hộp, mặt chính in bạt hoặc vải, cánh gà formex hoặc gỗ ép cắt CNC\n• Đèn: LED dây hắt viền cánh gà, đèn par rọi mặt phông\n• Kích thước thường làm: ngang 10-16 m, cao 3,5-4,5 m\n• Lưu ý: chừa khoảng sau phông 1-1,5 m cho kỹ thuật đi dây và đứng chờ\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và thi công sân khấu trọn gói.","descriptionEn":"A layered conference stage backdrop suits industry and customer conferences in large ballrooms, where a stage 10 m or wider needs more depth than a flat banner.\n\n• Structure: steel box frame, main face in printed banner or fabric, side wings in CNC-cut foam PVC or plywood\n• Lighting: LED strip along the wing edges, par cans washing the main face\n• Typical size: 10-16 m wide, 3.5-4.5 m high\n• Tip: leave 1-1.5 m behind the backdrop for cabling and crew standing by\n\nTrường Thịnh designs, builds the set in its workshop and installs the whole stage.","altVi":"Backdrop sân khấu in vườn dừa, cánh gà cắt hình lá","altEn":"Stage backdrop printed with a coconut grove, with leaf-shaped side wings","source":"/assets/content/projects/advertising/kiosk-posm/backdrop-san-khau-hoi-nghi.webp","sha256":"b4b7e5aae8871b3a331fc6f91c4bc976d5977b00983f45a9d9e5d6148a4a49b5","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:bd-hoi-nghi-1; original SHA256 6afa6447a8fe463d30ba6121c57c00667e5b3a2caa08ff1721f12e9f7f94bd84; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-47": {"descriptionVi":"Backdrop khai trương cắt hình theo logo hợp với cửa hàng mỹ phẩm, phụ kiện, spa muốn ngày mở cửa có góc chụp ảnh riêng và giữ lại phần cổng làm mặt tiền lâu dài.\n\n• Kết cấu: gỗ ép hoặc formex nhiều lớp cắt CNC, sơn PU, viền LED dây hắt sáng\n• Chữ: mica hoặc formex dán nổi, sơn đúng màu thương hiệu\n• Kích thước thường làm: ngang 2,5-4 m, cao 2,5-3 m\n• Lưu ý: backdrop dựng trên vỉa hè cần hỏi phép phường và có chân đế nặng hoặc bao cát chống đổ\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"An opening backdrop cut to the shape of the logo suits cosmetics, accessories and spa shops that want their own photo spot on opening day, with the matching arch kept as a permanent frontage.\n\n• Build: layered plywood or foam PVC, CNC cut, PU paint, LED strip edge lighting\n• Lettering: raised acrylic or foam PVC in exact brand colours\n• Typical size: 2.5-4 m wide, 2.5-3 m high\n• Tip: a backdrop on the pavement needs local ward permission and a weighted base or sandbags against tipping\n\nTrường Thịnh designs, builds in its own workshop and installs it.","altVi":"Backdrop khai trương cánh sen hồng cạnh cổng mặt tiền cửa hàng mỹ phẩm","altEn":"Pink lotus-petal opening backdrop beside a matching cosmetics shopfront","source":"/assets/content/projects/advertising/kiosk-posm/backdrop-khai-truong-hoa-sen.webp","sha256":"53647e1a278146046e7c5584bd039a126fa35ba88c6fa2b84ddfdfd4c822b21f","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:bd-khai-truong-1; original SHA256 45ae2aada72fb7cb2f4ef319b9141e54d8f0319580515abf96d7a17517a4bbee; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-48": {"descriptionVi":"Bảng hiệu gỗ khắc kết hợp tranh phù điêu hợp với nhà hàng đồng quê, quán ăn miệt vườn muốn tên quán nằm ngay trên mảng tường chính thay vì một tấm biển riêng.\n\n• Chất liệu: gỗ ép hoặc MDF chống ẩm cắt CNC nhiều lớp, sơn PU chống ẩm\n• Chữ: gỗ hoặc mica dày 10-20 mm, LED hắt chân sau chữ\n• Kích thước thường làm: ngang 3-6 m, cao 1,8-2,5 m\n• Lưu ý: quán mái mở ven sông độ ẩm cao, nên phủ PU hai mặt và chừa khe thoáng sau tấm để gỗ không phồng\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A carved timber sign built into a relief mural suits countryside restaurants and riverside eateries that want the name on the main wall rather than on a separate board.\n\n• Material: layered CNC-cut plywood or moisture-resistant MDF, moisture-proof PU finish\n• Lettering: 10-20 mm timber or acrylic with halo LED behind each letter\n• Typical size: 3-6 m wide, 1.8-2.5 m high\n• Tip: open-sided riverside venues are humid, so seal both faces in PU and leave an air gap behind the panels so the wood doesn't swell\n\nTrường Thịnh designs, builds in its own workshop and installs it.","altVi":"Vách gỗ khắc cảnh sông nước, chữ tên quán hắt đèn trong nhà hàng","altEn":"Carved timber wall of a river scene with backlit name lettering in a restaurant","source":"/assets/content/projects/advertising/kiosk-posm/bang-hieu-go-khac-nha-hang.webp","sha256":"e7cf1b44c3a2f376b0ba36b949c012cff021b49ef09efe17a01a65011b8000f3","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:bd-nha-hang-1; original SHA256 c15b3214f07c019e12d42e10e7163a23ba718fe5ff23082a638fcbb4150e5833; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-49": {"descriptionVi":"Vách logo phù điêu sau quầy thu ngân hợp với cửa hàng đặc sản, mỹ phẩm thiên nhiên, showroom sản phẩm dừa, nơi mảng tường chính cần kể câu chuyện thương hiệu.\n\n• Chất liệu: gỗ ép hoặc formex cắt CNC xếp lớp, sơn nước hoặc PU màu kem\n• Logo: chữ gỗ hoặc mica nổi 10-15 mm, LED hắt viền khung vòm\n• Kích thước thường làm: rộng 2-3 m, cao 2,2-2,8 m\n• Lưu ý: phù điêu nhiều lớp dễ bám bụi, nên phủ sơn bóng mờ để lau bằng chổi lông hay khăn khô\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A relief logo wall behind the till suits specialty food shops, natural cosmetics stores and coconut product showrooms, where the main wall should tell the brand's story.\n\n• Material: layered CNC-cut plywood or foam PVC, cream emulsion or PU paint\n• Logo: 10-15 mm raised timber or acrylic letters, LED edge light around the arch\n• Typical size: 2-3 m wide, 2.2-2.8 m high\n• Tip: layered relief collects dust, so a satin finish lets you clean it with a soft brush or dry cloth\n\nTrường Thịnh designs, builds in its own workshop and installs it.","altVi":"Vách phù điêu sóng, cây dừa màu kem, logo nổi giữa kệ vòm","altEn":"Cream relief wall of waves and palms with a raised logo between arched shelves","source":"/assets/content/projects/advertising/kiosk-posm/vach-logo-phu-dieu-cua-hang.webp","sha256":"edc0c8d9d9872fd91f1482f98eb34defd810daec8958c2f7ae34b2e82279f68b","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:bd-showroom-1; original SHA256 c0940bdb6e2902e67bb76fc283bc1a748fc090dd3192f6fd05a136ab01c66dc3; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-50": {"descriptionVi":"Cổng cưới hoa dạng vòm ghép nhiều lớp hợp với đám cưới tại gia, rạp sân vườn, nhà hàng ngoài trời, thay cho cổng kẽm kết hoa truyền thống.\n\n• Kết cấu: khung gỗ ép hoặc formex cắt CNC, sơn PU, chân đế sắt chống đổ\n• Hoa: hoa tươi hoặc hoa lụa phối vải voan; hoa lụa giữ lại dùng được cho nhiều tiệc\n• Kích thước thường làm: cao 2,6-3,2 m, lòng cổng rộng 1,8-2,4 m\n• Lưu ý: cổng ngoài trời cần dây chằng hoặc bao cát, mùa mưa nên tính sẵn phương án mái che\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và dựng cổng tận nơi.","descriptionEn":"A layered floral wedding arch suits home weddings, garden marquees and outdoor restaurants, replacing the traditional wire-frame flower gate.\n\n• Build: CNC-cut plywood or foam PVC, PU paint, steel base against tipping\n• Flowers: fresh or silk with chiffon drapes; silk flowers can be reused for many weddings\n• Typical size: 2.6-3.2 m high, 1.8-2.4 m clear opening\n• Tip: outdoor arches need guy lines or sandbags, and in the rainy season plan for a canopy\n\nTrường Thịnh designs, builds the arch in its workshop and sets it up on site.","altVi":"Cổng vòm Lễ Vu Quy cắm hoa cam hồng dẫn vào rạp cưới","altEn":"Lễ Vu Quy wedding arch with orange and pink flowers leading into a marquee","source":"/assets/content/projects/advertising/kiosk-posm/cong-cuoi-hoa-ngoai-troi.webp","sha256":"c525b04769e6df50d02fcea0f1405298c3cf39c9eec0eac5735a1522b998ff73","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd365-4208-83ec-af8f-57fa7fa79f6b); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-27 01:07Z; master PNG SHA256 28ca2e759527185848ba965764644815f28c293df40d051ad5b624c595398761."},
  "kiosk-posm-51": {"descriptionVi":"Backdrop khai giảng in bạt khung sắt hợp với trường học, phòng giáo dục cần sân khấu ngoài sân trường dựng xong trong một buổi và tháo gọn sau lễ.\n\n• Kết cấu: khung sắt hộp hoặc giàn ống, căng bạt hiflex in kỹ thuật số\n• Cánh gà: formex hoặc bạt căng khung, in khẩu hiệu năm học\n• Kích thước thường làm: ngang 8-12 m, cao 3-4 m\n• Lưu ý: dựng ngoài sân nên đục lỗ thoát gió trên bạt và neo chân khung, tránh lật khi có gió lớn\n\nTrường Thịnh thiết kế, in và dựng sân khấu trọn gói.","descriptionEn":"A printed school opening ceremony backdrop on a steel frame suits schools and education offices that need an outdoor stage set up in one session and packed away after the ceremony.\n\n• Structure: steel box or pipe frame with stretched digitally printed hiflex\n• Side wings: foam PVC or framed banner printed with the school year's slogans\n• Typical size: 8-12 m wide, 3-4 m high\n• Tip: outdoors, punch wind vents in the banner and anchor the frame feet so it won't topple in a gust\n\nTrường Thịnh designs, prints and builds the whole stage.","altVi":"Sân khấu lễ khai giảng phông bạt in sen, cánh gà khẩu hiệu đỏ","altEn":"School opening ceremony stage with a lotus-printed backdrop and red slogan wings","source":"/assets/content/projects/advertising/kiosk-posm/backdrop-khai-giang-truong-hoc.webp","sha256":"12f12c62818ddf2244ca56bdf9f0b44b83a7252c00672365e91ba5fe50c864ec","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd346-7cd4-83ec-add9-8f74b7e7b0cc); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-27 01:07Z; master PNG SHA256 043dd9ad8fa723029b450e0185ce51101fe73cb61a4be5470ada6ee728c9aac3."},
  "kiosk-posm-52": {"descriptionVi":"Vách logo lễ tân ốp lam gỗ hợp với văn phòng giao dịch, ngân hàng, công ty dịch vụ muốn quầy và vách nhận diện làm đồng bộ một lần theo cùng đường cong.\n\n• Vách: MDF chống ẩm sơn bả mịn, lam gỗ hoặc lam nhựa giả gỗ chạy theo đường cong\n• Logo: mica hoặc alu chấn dày 3-5 cm, LED hắt chân\n• Quầy: mặt đá nhân tạo, thân ốp lam đồng bộ với vách\n• Lưu ý: lam nhựa giả gỗ không cong vênh và rẻ hơn gỗ thật, hợp sảnh có cửa kính nắng chiếu\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A slatted reception logo wall suits service offices, bank branches and service companies that want the desk and brand wall built together on the same curve.\n\n• Wall: moisture-resistant MDF with a smooth painted finish, timber or wood-look composite slats following the curve\n• Logo: 3-5 cm deep acrylic or folded aluminium, halo LED\n• Desk: solid surface top, body clad in slats to match the wall\n• Tip: wood-look composite slats don't warp and cost less than real timber, a good fit for sunny lobbies with glass fronts\n\nTrường Thịnh designs, builds in its own workshop and installs it.","altVi":"Logo chữ nổi hắt sáng trên vách cong ốp lam gỗ sảnh giao dịch","altEn":"Halo-lit raised logo on a curved slatted timber wall behind a service desk","source":"/assets/content/projects/advertising/kiosk-posm/vach-logo-le-tan-van-phong.webp","sha256":"9ea63a0c964982a6d782cba15ff65b6d6db0a2b858fcec02eb8731699078e483","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 959311363bb9e3cd8c2c96c7534c1da59443e8ab44fd8920d3bae97517e2a718."},
  "kiosk-posm-53": {"descriptionVi":"Gian hàng tre lá hợp với cơ sở đặc sản, OCOP, làng nghề miền Tây muốn nổi bật giữa dãy gian khung nhôm tiêu chuẩn mà chi phí vật liệu vẫn thấp.\n\n• Kết cấu: khung tre già xử lý chống mọt, mái lá dừa hoặc lá giả chống cháy\n• Bảng tên: gỗ khắc CNC, biển tròn đan tre hoặc mây\n• Kích thước thường làm: 3x3 m, 3x6 m\n• Lưu ý: nhiều hội chợ trong nhà cấm lá thật vì dễ cháy, nên hỏi ban tổ chức trước và dùng lá giả khi cần\n\nTrường Thịnh thiết kế, dựng gian tại hội chợ và tháo dỡ trọn gói.","descriptionEn":"A bamboo and thatch booth suits specialty producers, regional brands and craft villages that want to stand out from rows of standard aluminium shells at a low material cost.\n\n• Structure: seasoned bamboo treated against borers, coconut-leaf or fire-retardant artificial thatch\n• Signs: CNC-engraved timber board, round woven bamboo or rattan plaques\n• Typical size: 3x3 m or 3x6 m\n• Tip: many indoor fairs ban real thatch as a fire risk, so check with the organiser and switch to artificial leaves if needed\n\nTrường Thịnh designs, builds the booth on site and takes it down after the fair.","altVi":"Gian tre mái lá dừa, kệ đặc sản và biển tròn đan treo cột","altEn":"Bamboo booth with a coconut-leaf roof, specialty shelves and woven round signs","source":"/assets/content/projects/advertising/kiosk-posm/gian-hang-tre-la-hoi-cho.webp","sha256":"fc0e72323cbac961eacfbb6e8365e73bafadabaddc840a0874e06ba532c4405f","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:gian-trien-lam-bu-01-1; original SHA256 df88cc879b0cc89120eabebef315e47b80d0bdf9dd2d740c577adb37cc1696da; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-54": {"descriptionVi":"Kiosk bán hàng khung gỗ hợp với thương hiệu đặc sản, bánh kẹo thuê ô sảnh trung tâm thương mại, cần quầy, kệ và bảng hiệu gói gọn trong một khối.\n\n• Kết cấu: khung gỗ hoặc sắt hộp ốp MDF chống ẩm, quầy ốp nan có LED hắt\n• Bảng hiệu: hộp đèn bạt hiflex xuyên sáng hoặc bạt 3M trên mái và hai trụ, bản cao cấp dùng mica in UV\n• Kích thước thường làm: 2x3 m hoặc 3x3 m, cao 2,4-2,8 m\n• Lưu ý: mỗi trung tâm có quy định riêng về chiều cao, vật liệu chống cháy và giờ thi công, cần gửi bản vẽ duyệt trước\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt kiosk trọn gói.","descriptionEn":"A timber retail kiosk suits specialty food and confectionery brands renting a mall concourse plot, packing counter, shelving and signage into one unit.\n\n• Structure: timber or steel box frame clad in moisture-resistant MDF, slatted counter with LED backlight\n• Signage: translucent or 3M flex lightboxes on the canopy and both posts, or UV-printed acrylic for a premium finish\n• Typical size: 2x3 m or 3x3 m, 2.4-2.8 m high\n• Tip: every mall has its own rules on height, fire-rated materials and working hours, so get drawings approved first\n\nTrường Thịnh designs, builds and installs the kiosk.","altVi":"Kiosk gỗ bán kẹo dừa, bánh dừa ở sảnh trung tâm thương mại","altEn":"Timber kiosk selling coconut candy and cakes in a shopping mall concourse","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-ban-hang-dac-san-dua.webp","sha256":"432e5db0939aecd4ce7aaecfaba44b92fafc9a2194eb44020a0b36fce4d90a16","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd327-9610-83ec-b5ac-394880730cd9); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-27 01:07Z; master PNG SHA256 1d91b52830370f0e14bd48d0ffa6a831c90e8d2f316804c264bb1ed738789e31."},
  "kiosk-posm-55": {"descriptionVi":"Xe bán nước dừa bằng gỗ hợp với điểm bán ở bờ kè, công viên, khu du lịch, nơi xe đứng cố định ban ngày và đẩy vào cất lúc tối.\n\n• Khung xe: sắt hộp sơn tĩnh điện, ốp gỗ thông hoặc nhựa giả gỗ, bánh căm lớn dễ đẩy\n• Mặt quầy: inox hoặc gỗ phủ PU, chừa chỗ đặt thùng đá\n• Kích thước thường làm: dài 1,6-2 m, cao tổng 2,3-2,5 m\n• Lưu ý: dừa và đá rất nặng, nên làm trục bánh và khung đáy chịu tải 150-200 kg\n\nTrường Thịnh thiết kế, đóng xe tại xưởng và giao tận nơi trọn gói.","descriptionEn":"A timber coconut water cart suits pitches on riverside promenades, parks and tourist spots, where the cart stands in one place by day and is wheeled away at night.\n\n• Frame: powder-coated steel box section clad in pine or wood-look composite, large spoked wheels that push easily\n• Counter: stainless or PU-sealed timber, with room for an ice box\n• Typical size: 1.6-2 m long, 2.3-2.5 m tall overall\n• Tip: coconuts and ice are heavy, so the axle and base frame should be rated for 150-200 kg\n\nTrường Thịnh designs, builds the cart in its workshop and delivers it to your door.","altVi":"Xe đẩy gỗ bán nước dừa có mái che và bảng menu bên hông","altEn":"Timber coconut water cart with a canopy and a side menu board","source":"/assets/content/projects/advertising/kiosk-posm/xe-ban-nuoc-dua-go.webp","sha256":"684acec3f1f69da4e6617d9228d226f5a23badaac9de662f60161668cded5c71","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd309-47a8-83ec-9acd-5021dc477af9); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-27 01:07Z; master PNG SHA256 4ea1e4619e289a52ba5d33029064ed7aa04d468f5d4636a67e093c4721bcbf11."},
  "led-displays-lightboxes-31": {"descriptionVi":"LED neon trang trí cắt theo hình hợp với nhà hàng chay, quán ăn gia đình muốn một mảng tường mang tên quán, thay cho tranh treo hay hộp đèn trong nhà.\n\n• Chất liệu: mica 5 mm in UV, cắt CNC theo viền hình, dây LED neon silicon chạy dọc mép và nét chữ\n• Đèn: nguồn 12V giấu sau tấm, ánh vàng 3000K\n• Kích thước thường làm: ngang 1,2-2,5 m\n• Lưu ý: tường lam gỗ cần pát cách tường 2-3 cm để ánh sáng hắt đều ra viền\n\nTrường Thịnh thiết kế hình, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"Shaped decorative LED neon suits vegetarian and family restaurants that want a feature wall carrying the name, in place of framed art or an indoor lightbox.\n\n• Material: 5 mm UV-printed acrylic, CNC-cut to the outline, silicone LED neon along the edge and lettering\n• Lighting: 12V supply hidden behind the panel, 3000K warm white\n• Typical size: 1.2-2.5 m wide\n• Tip: on a slatted timber wall, stand the panel 2-3 cm off the wall so the edge glow spreads evenly\n\nTrường Thịnh designs the artwork, builds it in its workshop and installs it.","altVi":"Bảng LED neon cắt hình hoa sen trên vách lam gỗ nhà hàng chay","altEn":"Lotus-shaped LED neon panel on a timber-slat wall in a vegetarian restaurant","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-neon-trang-tri-quan-chay.webp","sha256":"8ec5b8a16c398f83c2d00f03af79e8d340149d15fd4304fbf4d221b00ed88947","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:led-decor-bu-01-1; original SHA256 470b3dd795e65f747463be1585933dd1adfd6e362530d2012bb647b81a38791a; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-32": {"descriptionVi":"Biển vẫy hộp đèn viền gỗ hợp với quán trà, cà phê, tiệm bánh nhỏ theo phong cách mộc, đi cùng bảng gỗ chữ khắc ở cửa cho đồng bộ.\n\n• Cấu tạo: viền gỗ hoặc alu vân gỗ uốn theo dáng, mặt mica sữa in UV\n• Đèn: LED module ánh vàng, nguồn 12V\n• Kích thước thường làm: 50x60 cm đến 60x80 cm, hai mặt\n• Lưu ý: viền gỗ thật ngoài trời cần sơn PU ngoài trời và có mái che, nếu không nên chọn alu vân gỗ\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A timber-rimmed lightbox projecting sign suits small tea, coffee and cake shops with a rustic style, matched with a carved timber board by the door.\n\n• Build: timber or woodgrain aluminium rim shaped to the outline, UV-printed opal acrylic face\n• Lighting: warm white LED modules on a 12V supply\n• Typical size: 50x60 cm to 60x80 cm, double-sided\n• Tip: real timber outdoors needs exterior PU and some shelter, otherwise choose woodgrain aluminium\n\nTrường Thịnh designs, builds in its own workshop and installs the sign.","altVi":"Biển vẫy hộp đèn viền gỗ trên tay sắt trước quán trà cà phê","altEn":"Timber-rimmed lightbox projecting sign on a steel arm outside a tea café","source":"/assets/content/projects/advertising/led-displays-lightboxes/bien-vay-hop-den-vien-go.webp","sha256":"32c22fa8199af974aa6354bf109b858d8b1edee1d04d1e23d13d57c8f2efb2d2","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:led-decor-bu-01-2; original SHA256 1f54b5a1e2463fdd33c83e50455ef353206b6e6e0316311da412cbcf91dfd569; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-33": {"descriptionVi":"Cổng chào LED hoa sen hợp với quán ăn sân vườn, khu ẩm thực, lễ hội đêm muốn lối vào thành điểm chụp ảnh, kéo khách đi dạo ghé vào.\n\n• Kết cấu: khung sắt uốn vòm sơn tĩnh điện, ốp nan tre hoặc nhựa giả tre chịu nắng mưa\n• Hoa sen: mica hoặc composite tạo hình, LED dây và LED neon bên trong\n• Kích thước thường làm: rộng 3-4 m, cao 3-3,5 m\n• Lưu ý: cổng ngoài trời cần đế bê tông hoặc bu lông neo xuống nền, dây điện chôn ngầm có CB chống giật\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và thi công lắp dựng trọn gói.","descriptionEn":"A lotus LED gateway suits garden restaurants, food courts and night festivals that want the entrance to become a photo spot that draws passers-by in.\n\n• Structure: bent steel arch with powder coat, clad in bamboo slats or weatherproof faux bamboo\n• Lotus: shaped acrylic or composite with LED strip and LED neon inside\n• Typical size: 3-4 m wide, 3-3.5 m high\n• Tip: an outdoor arch needs concrete footings or anchor bolts, with buried cabling on an earth-leakage breaker\n\nTrường Thịnh designs, fabricates in its workshop and erects the gateway on site.","altVi":"Cổng vòm nan tre với hoa sen phát sáng trước quán ăn ven sông","altEn":"Bamboo-clad arch with illuminated lotus flowers at a riverside eatery","source":"/assets/content/projects/advertising/led-displays-lightboxes/cong-chao-led-hoa-sen.webp","sha256":"ec47da2ae3b6b5e5bff423fb69137fa4e05ac8953f30cf93b772aaa938c1ee31","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:led-decor-bu-02-1; original SHA256 9fb7761425e6b9d59e076cbd83686cdef3e3c6f3082f2a04e5226bf0c5d279fc; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-34": {"descriptionVi":"Bảng vẫy LED quán ăn hợp với quán cơm, bún, hủ tiếu bình dân cần liệt kê nhiều món trên một bảng mà chi phí thấp hơn màn hình LED.\n\n• Cấu tạo: hộp nhôm định hình, mặt alu khoan lỗ CNC, LED ruồi kèm LED neon cho hình món\n• Điều khiển: mạch chạy viền, nháy từng dòng, hẹn giờ bật tắt\n• Kích thước thường làm: 60x80 cm đến 80x120 cm, hai mặt\n• Lưu ý: tên món nên ngắn, mỗi dòng tối đa 10-12 ký tự để chữ còn đủ lớn\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"An eatery LED projecting sign suits everyday rice and noodle shops that want to list several dishes on one board for far less than an LED screen.\n\n• Build: aluminium profile case, CNC-drilled aluminium composite face, LED dots plus LED neon for the dish graphic\n• Control: chasing border, line-by-line flashing, on/off timer\n• Typical size: 60x80 cm to 80x120 cm, double-sided\n• Tip: keep dish names short, 10-12 characters per line at most, so the letters stay large\n\nTrường Thịnh designs, builds in its own workshop and installs the sign.","altVi":"Bảng vẫy LED ruồi nhiều màu hình tô bún trước quán ăn","altEn":"Multi-colour LED-dot projecting sign with a noodle bowl outside an eatery","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-34-owner-20261019.webp","sha256":"96cd35f9c675185dba692a31c01eb63e96eb4f9b263d3902f87dba08214acad8","provenance":"AI-generated illustration edited by the owner; source ID owner-edit:2026-10-19:led-sign-02-2; original SHA256 1ef91a76c0ff47d6e282b02b199a4c43e21ed4e6b73db3ba4eb9fd3e313200b1; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-35": {"descriptionVi":"Bảng LED điểm gửi hàng hợp với đại lý chuyển phát, tiệm tạp hóa kiêm nhận gửi hàng, cần khách lạ tìm đúng điểm nhận mà không phải hỏi đường.\n\n• Cấu tạo: hộp nhôm bo góc, mặt khoan lỗ, LED ruồi chống nước, hai mặt\n• Lắp đặt: khung sắt vuông góc mặt tiền, đặt dưới mái hiên tránh mưa tạt trực tiếp\n• Kích thước thường làm: 60x90 cm đến 80x120 cm\n• Lưu ý: nếu làm đại lý cho hãng chuyển phát, nên hỏi hãng quy định màu và logo trước khi làm bảng\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt tận nơi.","descriptionEn":"A parcel point LED sign suits courier agents and grocery stores that also take parcels, helping first-time customers find the right drop-off without asking.\n\n• Build: round-cornered aluminium case, drilled face, waterproof LED dots, double-sided\n• Installation: steel bracket at right angles to the frontage, under the awning out of driving rain\n• Typical size: 60x90 cm to 80x120 cm\n• Tip: if you are an agent for a courier brand, check its colour and logo rules before the sign is made\n\nTrường Thịnh designs, builds the sign in its workshop and installs it on site.","altVi":"Bảng LED ruồi hình thùng hàng treo dưới mái hiên điểm gửi hàng","altEn":"LED-dot sign with a parcel icon under the awning of a parcel drop-off point","source":"/assets/content/projects/advertising/led-displays-lightboxes/bang-led-diem-gui-hang.webp","sha256":"d1a6aca0e0f127466d6dc285e69a955fe38e6e77f9aecc1ec891d344300e3fe9","provenance":"AI-generated illustration edited by the owner; source ID owner-edit:2026-10-19:led-sign-03-1; original SHA256 ff146b57259bc04f9e5cfb86757c979eacd4f6039e92e13239699850b572449f; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-36": {"descriptionVi":"Bảng LED ruồi khổ đứng hợp với tiệm chụp ảnh thẻ, photocopy, dịch vụ giấy tờ có nhiều dịch vụ nhỏ cần liệt kê thành danh sách.\n\n• Cấu tạo: hộp nhôm, mặt alu hoặc mica đen khoan lỗ, cắm LED ruồi 5 mm chống nước\n• Màu: ba màu chính, dòng tiêu đề và danh sách dịch vụ để khác màu\n• Kích thước thường làm: 80x100 cm đến 100x120 cm\n• Lưu ý: danh sách trên 4 dòng thì chữ dòng dưới vẫn nên cao từ 10 cm, nhỏ hơn đứng xa khó đọc\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt tận nơi.","descriptionEn":"A portrait LED-dot sign suits ID photo studios, copy shops and paperwork services with many small services to set out as a list.\n\n• Build: aluminium case, drilled aluminium composite or black acrylic face, waterproof 5 mm LED dots\n• Colour: three main colours, with the heading and the service list in different colours\n• Typical size: 80x100 cm to 100x120 cm\n• Tip: with more than four lines, keep the lower lines at least 10 cm tall or they are hard to read from a distance\n\nTrường Thịnh designs, builds the sign in its workshop and installs it on site.","altVi":"Bảng LED ruồi viền xanh dương treo trước tiệm chụp ảnh thẻ, photocopy","altEn":"Blue-bordered LED-dot sign hung outside a photo and copy shop","source":"/assets/content/projects/advertising/led-displays-lightboxes/bang-led-ruoi-tiem-chup-anh.webp","sha256":"d0337bf4a5008f4485417f513c2969bf2e0a0820e9c17004696c5ccb37364118","provenance":"AI-generated illustration edited by the owner; source ID owner-edit:2026-10-19:led-sign-04-1; original SHA256 256c99a55c1f50aa42f81b058a5ff612ba69966032dbc33aebbaa78a4a923711; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-37": {"descriptionVi":"Tranh đèn LED treo tường hợp với tiệm áo cưới, studio cưới, tiệm hoa muốn mảng tường khu thử đồ có điểm nhấn mềm, sáng nhẹ, hợp ảnh chụp kỷ niệm.\n\n• Chất liệu: mica in UV, in thêm lớp lót trắng để màu dày và không lộ đèn phía sau\n• Đèn: LED neon ánh vàng ấm dọc nét hình và viền khung\n• Kích thước thường làm: 60x80 cm đến 90x120 cm\n• Lưu ý: có thể dùng hình vẽ riêng của tiệm, gửi bản vẽ nét để xưởng đặt đường LED theo nét\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"An LED wall picture suits bridal shops, wedding studios and florists that want a soft, gently lit feature in the fitting area that also works as a backdrop for keepsake photos.\n\n• Material: UV-printed acrylic with a white underlayer so colours stay dense and the lights don't show through\n• Lighting: warm white LED neon along the figure's lines and the frame edge\n• Typical size: 60x80 cm to 90x120 cm\n• Tip: the shop's own illustration can be used; send line artwork so the workshop can follow it with the LED\n\nTrường Thịnh designs, builds in its own workshop and installs the piece.","altVi":"Tranh đèn LED hình cô dâu viền sáng vàng trên tường tiệm áo cưới","altEn":"LED-outlined bridal portrait artwork on a bridal shop wall","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-37-imagegen-20261018.webp","sha256":"832c8ad546b9924a0fd72df76f5bdd28513ccb4ebdb2823ea205de5cdc68c313","provenance":"AI-generated illustration; ChatGPT web image edit with owner mask (chat 6ae5fa39-91a4-83ec-bde4-16e7b02be8fb); upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-27; master PNG SHA256 f5e2af7d5ab3d374cd6d6301f46d505613c6ffbc63f82bd2028840976807d5f9."},
  "led-displays-lightboxes-38": {"descriptionVi":"Bảng LED sửa xe dạng LED ruồi hợp với tiệm sửa xe máy, thay nhớt, vá vỏ ven đường, cần biển chạy cả ngày lẫn tối mà tốn ít điện hơn hộp đèn huỳnh quang.\n\n• Cấu tạo: hộp nhôm định hình, mặt khoan lỗ CNC, LED ruồi chân keo chống nước\n• Hiệu ứng: mũi tên chạy hướng vào tiệm, chỉnh tốc độ trên mạch\n• Kích thước thường làm: 80x100 cm hoặc 1x1,2 m\n• Lưu ý: treo dưới mái tôn nên chừa khe thoát nhiệt sau bảng, mùa nắng hộp kín dễ nóng làm hỏng nguồn\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"An LED-dot repair shop sign suits roadside motorbike repair, oil change and tyre shops that need a sign running day and night while using less power than a fluorescent lightbox.\n\n• Build: aluminium profile case, CNC-drilled face, resin-sealed waterproof LED dots\n• Effects: arrows chasing towards the shop, speed set on the controller\n• Typical size: 80x100 cm or 1x1.2 m\n• Tip: under a metal roof leave a vent gap behind the sign, as a sealed box overheats in the dry season and kills the power supply\n\nTrường Thịnh designs, builds in its own workshop and installs the sign.","altVi":"Bảng LED ruồi hình xe máy, cờ lê trước tiệm sửa xe ven kênh","altEn":"LED-dot sign with a scooter and spanner outside a canal-side repair shop","source":"/assets/content/projects/advertising/led-displays-lightboxes/bang-led-sua-xe-may.webp","sha256":"5617ea29959dfee8441d4f734cacfc478673da74a00b40f1dc509889f95a37d5","provenance":"AI-generated illustration edited by the owner; source ID owner-edit:2026-10-19:led-sign-06-1; original SHA256 1c58fa2a27231f1470812f686420009f61dbdc3be2f98bcf9bd86fc055bafe22; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-39": {"descriptionVi":"Biển neon trang trí hình xe mô tô hợp với cửa hàng mũ bảo hiểm, phụ tùng, đồ chơi xe, gara độ xe muốn góc trưng bày mang chất thể thao.\n\n• Chất liệu: mica đen bóng 5 mm, dây LED neon silicon uốn theo nét, bắt chân đinh inox\n• Đèn: nguồn 12V giấu sau tấm, mạch nháy hoặc sáng tĩnh\n• Kích thước thường làm: ngang 80-150 cm\n• Lưu ý: nền mica đen làm LED neon nổi rõ nhất nhưng dễ bám bụi, nên lau bằng khăn mềm khô\n\nTrường Thịnh thiết kế hình, uốn LED tại xưởng và lắp đặt tận nơi.","descriptionEn":"A decorative motorbike neon sign suits helmet, parts and accessories shops and custom bike garages that want a display corner with a racing feel.\n\n• Material: 5 mm gloss black acrylic, silicone LED neon bent to the drawing, stainless stand-offs\n• Lighting: 12V supply hidden behind the panel, flashing or steady\n• Typical size: 80-150 cm wide\n• Tip: black acrylic makes LED neon stand out most but shows dust, so wipe it with a soft dry cloth\n\nTrường Thịnh draws the design, bends the LED in its workshop and installs it on site.","altVi":"Biển neon hình xe mô tô trên mica đen cạnh tủ mũ bảo hiểm","altEn":"Neon motorbike sign on black acrylic beside a helmet display","source":"/assets/content/projects/advertising/led-displays-lightboxes/bien-neon-trang-tri-xe-may.webp","sha256":"cf17222985a09417104325c29037ec971bd4c80659e92b59c02c9d4002da1864","provenance":"AI-generated illustration; ChatGPT web image edit with owner mask (chat 6ae5fa7b-ffa0-83ec-8e39-8c4607ab4943); upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-27; master PNG SHA256 fa61d7c9b9573fde58cf65b75596040e2a8747003b6b5e9b932cd5d198b61035."},
  "led-displays-lightboxes-40": {"descriptionVi":"Bảng neon di động có bánh xe hợp với quán trà trái cây, nước ép, quầy đồ uống trong trung tâm thương mại, đẩy ra lối đi lúc mở cửa và cất gọn khi đóng.\n\n• Chất liệu: mica in UV, LED neon nhiều màu gắn theo nét hình, khung sắt hộp sơn tĩnh điện\n• Chân: bánh xe xoay có khóa, đế rộng chống lật\n• Kích thước thường làm: mặt 80x100 cm đến 100x140 cm, hai mặt\n• Lưu ý: đi dây nguồn theo chân khung và có ổ cắm riêng gần chỗ đặt, tránh dây vắt ngang lối khách đi\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và giao tận nơi.","descriptionEn":"A mobile neon sign on wheels suits fruit tea, juice and drinks counters in shopping centres, rolled into the walkway at opening and tucked away at closing.\n\n• Material: UV-printed acrylic with multi-colour LED neon on the artwork, powder-coated steel frame\n• Base: lockable swivel casters on a wide anti-tip base\n• Typical size: 80x100 cm to 100x140 cm face, double-sided\n• Tip: run the power lead down the frame leg to a dedicated socket nearby, so no cable crosses the customer walkway\n\nTrường Thịnh designs, builds the sign in its workshop and delivers it.","altVi":"Bảng neon ly trà trái cây trên khung bánh xe cạnh quầy","altEn":"Neon fruit tea sign on a wheeled frame beside a drinks counter","source":"/assets/content/projects/advertising/led-displays-lightboxes/bang-neon-di-dong-quan-tra.webp","sha256":"5d51651fe81b757605f83f731919e86d085a442643b84102000e7073d6e46ca6","provenance":"AI-generated illustration; ChatGPT web image edit with owner mask (chat 6ae5faae-8684-83ec-8e5e-ec153c9eb928); upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-27; master PNG SHA256 86d9d70da7f1497781a2b248e2a86c3ffd3eaeb0dac55130f05030ae900dc56c."},
  "led-displays-lightboxes-41": {"descriptionVi":"Bảng vẫy LED nhà nghỉ hợp với nhà nghỉ, homestay, khách sạn nhỏ cần một biển mang dáng riêng, khác các hộp đèn chữ nhật quen thuộc trên cùng tuyến đường.\n\n• Cấu tạo: mặt mica in UV cắt dáng khiên, LED ruồi đi nét chữ, hình cây và viền\n• Tay treo: sắt uốn hoa văn sơn tĩnh điện, treo bằng móc xích\n• Kích thước thường làm: 60x80 cm đến 80x110 cm\n• Lưu ý: nền in UV trên mica giúp bảng vẫn đẹp ban ngày khi chưa bật LED\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A guesthouse LED projecting sign suits guesthouses, homestays and small hotels that want a sign with its own shape, unlike the familiar rectangular lightboxes along the same street.\n\n• Build: UV-printed acrylic face cut to a shield shape, LED dots tracing the lettering, palm and border\n• Bracket: powder-coated scrolled steel, hung on chains\n• Typical size: 60x80 cm to 80x110 cm\n• Tip: a UV-printed background keeps the sign attractive by day before the LEDs come on\n\nTrường Thịnh designs, builds in its own workshop and installs the sign.","altVi":"Bảng vẫy LED dáng khiên hình cây dừa, nhà nhỏ trên tay sắt uốn","altEn":"Shield-shaped LED projecting sign with a palm and cottage on a scroll bracket","source":"/assets/content/projects/advertising/led-displays-lightboxes/bang-vay-led-nha-nghi.webp","sha256":"f1935dcbeeacb7caf87cf32558d6aff07908b96facf26e670612509acbec5112","provenance":"AI-generated illustration; ChatGPT web image edit with owner mask (chat 6ae5fd2a-a46c-83ec-bfd6-479ea0232a4a); upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-27; master PNG SHA256 5b2c0fe3147985871363b6325a646e0ad1e2e5451614e32f8851eb5b6b39f623."},
  "led-displays-lightboxes-42": {"descriptionVi":"Bảng LED quán cà phê ca nhạc dùng LED ruồi nhiều màu hợp với phòng trà, quán acoustic, karaoke sân vườn muốn báo khách có nhạc sống ngay từ ngoài đường.\n\n• Cấu tạo: hộp nhôm, mặt mica đen khoan lỗ, LED ruồi đi theo chữ viết tay và hình\n• Hiệu ứng: hình nháy theo nhịp, chỉnh trên mạch điều khiển\n• Kích thước thường làm: ngang 1,2-1,6 m, cao 60-80 cm\n• Lưu ý: chữ viết tay nên giữ nét to và liền, LED ruồi đi nét mảnh sẽ rời rạc\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A multi-colour LED-dot sign for a music café suits tea rooms, acoustic bars and garden karaoke venues that want to tell people on the street there is live music tonight.\n\n• Build: aluminium case, drilled black acrylic face, LED dots following the script lettering and graphics\n• Effects: graphics flash in rhythm, set on the controller\n• Typical size: 1.2-1.6 m wide, 60-80 cm high\n• Tip: keep script lettering bold and joined, since LED dots on thin strokes look broken\n\nTrường Thịnh designs, builds in its own workshop and installs the sign.","altVi":"Bảng LED ruồi hình micro, nốt nhạc treo hiên quán cà phê ca nhạc","altEn":"LED-dot sign with a microphone and music notes at a live-music café","source":"/assets/content/projects/advertising/led-displays-lightboxes/bang-led-quan-ca-phe.webp","sha256":"da02fabb599e02b1d9f8a69c7b8c6d4577c8c8e5974d2024ee1e4dcb679eff2c","provenance":"AI-generated illustration edited by the owner; source ID owner-edit:2026-10-19:led-sign-09-1; original SHA256 5fb9bf9dffdd9de77754efcf44632b3676193ae7de9e2f973854ae6c190091c5; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-43": {"descriptionVi":"Tranh LED neon hình ly cà phê hợp với quán cà phê, trà sữa có mảng tường trống sau dãy sofa, cần một điểm nhấn nói rõ quán bán gì mà không phải sơn vẽ tường.\n\n• Chất liệu: mica in UV độ phân giải cao, cắt CNC theo viền, LED neon chạy mép và chữ\n• Đèn: nguồn 12V, có dimmer để giảm sáng vào buổi tối\n• Kích thước thường làm: ngang 1,5-2,5 m\n• Lưu ý: hình in nên là file vector hoặc ảnh gốc lớn, ảnh mạng phóng to sẽ vỡ hạt khi in khổ lớn\n\nTrường Thịnh lên mẫu, sản xuất tại xưởng và lắp đặt tận nơi.","descriptionEn":"LED neon artwork of a coffee glass suits cafés and bubble tea shops with a blank wall above the seating that needs a focal point saying what they sell, without a painted mural.\n\n• Material: high-resolution UV print on acrylic, CNC-cut to shape, LED neon along the edge and lettering\n• Lighting: 12V supply with a dimmer to soften it in the evening\n• Typical size: 1.5-2.5 m wide\n• Tip: supply vector artwork or a large original image, since enlarged web pictures pixelate at this size\n\nTrường Thịnh drafts the design, builds it in its workshop and installs it on site.","altVi":"Tranh LED neon ly cà phê đá trên tường sau dãy ghế sofa","altEn":"LED neon artwork of an iced coffee on the wall above a banquette","source":"/assets/content/projects/advertising/led-displays-lightboxes/tranh-led-neon-ca-phe-da.webp","sha256":"378d0b85c8f1d5d11dfb63564748af8202a23d2ee5917f46113b399c8704894b","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:led-neon-uv-ca-phe-2; original SHA256 e71c3b21f53bf6255f27ab2d2bdffb1790cfde2874dbe529dc4aec5349b21db1; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-44": {"descriptionVi":"LED neon góc check in là mảng tường in hình kèm viền sáng, hợp với quán cà phê, nhà hàng, khu du lịch muốn khách chụp ảnh đăng mạng xã hội và nhớ tên quán.\n\n• Chất liệu: mica in UV cắt CNC, có thể ghép nhiều lớp mica tạo chiều sâu\n• Đèn: LED neon nhiều màu, mạch đổi màu hoặc sáng tĩnh\n• Kích thước thường làm: ngang 2-3 m, đặt cao ngang tầm đầu người ngồi\n• Lưu ý: chừa khoảng trống trước tường cho ghế hoặc chỗ đứng, góc chụp hẹp quá khách không lấy được cả hình\n\nTrường Thịnh lên ý tưởng, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"An LED neon photo spot is a printed wall piece with a glowing outline, suiting cafés, restaurants and tourist sites that want guests to take photos for social media and remember the name.\n\n• Material: UV-printed, CNC-cut acrylic, optionally layered for depth\n• Lighting: multi-colour LED neon, colour-changing or steady\n• Typical size: 2-3 m wide, hung at seated head height\n• Tip: leave clear space in front for a bench or standing spot, or guests can't fit the whole piece in frame\n\nTrường Thịnh develops the idea, builds it in its workshop and installs it.","altVi":"Mảng LED neon cảnh xuồng, hoa sen trên băng ghế gỗ quán cà phê","altEn":"LED neon wall piece of a boat and lotus above a timber bench","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-neon-goc-check-in.webp","sha256":"2e93e12830f2c81d124f623529e23b2eb26bfd84bc979a9c66bcb12719ad2018","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:led-neon-uv-goc-chup-2; original SHA256 80e71303646ac0a389664f2c0060bf7dc8afe87db59dd6dc0a62f25a8d215bc6; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-45": {"descriptionVi":"Đèn neon shop phụ kiện làm logo kèm hình sản phẩm hợp với cửa hàng túi xách, kính mắt, thời trang nữ, vì tường sau quầy thu ngân là chỗ khách nhìn lâu nhất.\n\n• Chất liệu: mica in UV cắt CNC, chữ LED neon hồng hoặc trắng ấm\n• Đèn: nguồn 12V, công tắc riêng hoặc hẹn giờ theo giờ mở cửa\n• Kích thước thường làm: ngang 1,5-2,5 m\n• Lưu ý: shop trong trung tâm thương mại cần gửi thông số điện và vật liệu cho ban quản lý duyệt trước khi lắp\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A neon logo with product artwork suits handbag, eyewear and women's fashion boutiques, because the wall behind the cash desk is where customers look longest.\n\n• Material: UV-printed, CNC-cut acrylic with pink or warm white LED neon lettering\n• Lighting: 12V supply on its own switch or a timer matched to opening hours\n• Typical size: 1.5-2.5 m wide\n• Tip: mall units must send power and material specs to management for approval before installation\n\nTrường Thịnh designs, builds in its own workshop and installs the sign.","altVi":"Đèn neon hình túi xách, kính mát sau quầy thu ngân shop phụ kiện","altEn":"Neon handbag and sunglasses artwork behind a boutique cash desk","source":"/assets/content/projects/advertising/led-displays-lightboxes/den-neon-shop-phu-kien.webp","sha256":"2e00302698d6c2d181c51b0ef58259d2c35ca3cffa08f361de1cea4e47d00565","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:led-neon-uv-quay-shop-2; original SHA256 276fece7f0ce6850c9f64fd0e4b1f98fbfdd26778e356153ddd05fac5959c2ac; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-46": {"descriptionVi":"Đèn neon spa hình hoa sen hợp với phòng trị liệu, thẩm mỹ viện, spa dưỡng sinh cần ánh sáng nền dịu thay đèn trần, để khách nằm ngửa thư giãn mà không bị chói.\n\n• Chất liệu: mica in UV cắt CNC, LED neon hắt viền và chữ\n• Đèn: ánh vàng 2700K, dimmer giảm còn 20-30% độ sáng trong lúc trị liệu\n• Kích thước thường làm: ngang 1-1,8 m\n• Lưu ý: phòng spa có hơi nước nên dùng nguồn chống ẩm và đặt ổ cắm xa khu xông\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A lotus neon sign suits treatment rooms, beauty clinics and wellness spas that need soft background light instead of ceiling lights, so guests lying face up aren't dazzled.\n\n• Material: UV-printed, CNC-cut acrylic with LED neon on the outline and lettering\n• Lighting: 2700K warm white, dimmable to 20-30% during treatments\n• Typical size: 1-1.8 m wide\n• Tip: spa rooms are steamy, so use a moisture-resistant power supply and keep sockets away from the steam area\n\nTrường Thịnh designs, builds in its own workshop and installs the piece.","altVi":"Đèn neon hoa sen chữ Thư giãn phía trên giường spa","altEn":"Lotus neon artwork reading Thư giãn above a spa massage bed","source":"/assets/content/projects/advertising/led-displays-lightboxes/den-neon-spa-hoa-sen.webp","sha256":"b230e85f70fdf09dea72106140df0a8cdbbfee40fe43ddb0910566b1bede6b1b","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:led-neon-uv-spa-2; original SHA256 44b06ebc9519baaa323860165241ff488c29861de0584a5bad34bbda65c72fbf; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-41": {"descriptionVi":"Biển gỗ homestay hợp với homestay, nhà vườn, resort nhỏ theo phong cách mộc, nơi biển tên cần hòa vào cổng và cây xanh hơn là nổi bật như bảng hiệu cửa hàng.\n\n• Chất liệu: gỗ căm xe, gỗ teak hoặc gỗ nhựa composite ngoài trời\n• Chữ: đồng hoặc inox mạ màu đồng cắt laser, gắn nổi bằng chân ẩn\n• Kích thước thường làm: 60x30 cm đến 90x45 cm\n• Lưu ý: gỗ tự nhiên ngoài trời cần lau dầu lại mỗi 1-2 năm; ít thời gian bảo trì thì chọn gỗ nhựa\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A timber homestay sign suits homestays, garden guesthouses and small rustic resorts where the name should blend with the gate and greenery rather than shout like a shop sign.\n\n• Material: hardwood such as teak, or exterior-grade wood-plastic composite\n• Letters: laser-cut brass or bronze-tone stainless, stood off on hidden pins\n• Typical size: 60x30 cm to 90x45 cm\n• Tip: solid timber outdoors needs re-oiling every 1-2 years; if upkeep is a concern, choose composite\n\nTrường Thịnh designs, makes the sign in its workshop and installs it.","altVi":"Biển gỗ homestay chữ đồng nổi gắn trên trụ cổng trắng ven sông","altEn":"Timber homestay sign with raised brass letters on a riverside gate pillar","source":"/assets/content/projects/advertising/office-signs-wayfinding/bien-go-homestay-tru-cong.webp","sha256":"079dcdc945689eaed0f16e3081cb97548767cd4b8f178e744824de3958532169","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:bang-ten-bu-01-1; original SHA256 0389b2dcdfcb0eea340f3e5b1ee3f6bbc8f263e6b8e8e24b4e96a28b32c86bfd; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-42": {"descriptionVi":"Biển số nhà inox xước hợp với nhà phố, biệt thự có trụ cổng ốp đá hoặc sơn tông xám, cần biển bền ngoài trời và gần như không phải bảo trì.\n\n• Chất liệu: inox 304 xước dày 1-1,5 mm\n• Gia công: ăn mòn đổ sơn hoặc in UV, số có thể cắt mica đen dán nổi\n• Kích thước thường làm: 30x20 cm, 40x30 cm, gắn chân cách inox\n• Lưu ý: inox 201 rẻ hơn nhưng dễ ố vàng sau mùa mưa, nên hỏi rõ loại inox trong báo giá\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A brushed stainless house number plate suits townhouses and villas with stone-clad or grey gate pillars, where the sign has to last outdoors with almost no upkeep.\n\n• Material: 1-1.5 mm brushed 304 stainless\n• Fabrication: etched and paint-filled or UV printed, with optional raised black acrylic numerals\n• Typical size: 30x20 cm or 40x30 cm, on stainless stand-offs\n• Tip: 201-grade stainless is cheaper but stains after a rainy season, so ask which grade is quoted\n\nTrường Thịnh designs, makes the plate in its workshop and installs it.","altVi":"Biển số nhà inox xước số đen gắn chân cách trên trụ đá","altEn":"Brushed stainless house number plate with black numerals on a marble-clad pillar","source":"/assets/content/projects/advertising/office-signs-wayfinding/bien-so-nha-inox-xuoc.webp","sha256":"0cbff5fe56fee05ee98cb63e9f4bebf628d1e7b370ba7916017e661fe5b9c3d4","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:bang-ten-bu-02-1; original SHA256 68515cc8fd26363db59fe117664a1c311971047b3cd4c60033141173dee1a37a; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-43": {"descriptionVi":"Bảng tên công ty đèn hắt đặt sau quầy lễ tân hợp với trung tâm ngoại ngữ, công ty tư vấn du học, văn phòng tuyển dụng, nơi khách bước vào cần nhận ra đơn vị ngay.\n\n• Chất liệu: alu hoặc inox xước dày 2-3 mm, gấp hộp sâu 3-4 cm\n• Chữ: in UV, ăn mòn đổ sơn hoặc chữ nổi mica dán mặt\n• Đèn: LED dây hoặc module ánh vàng ấm hắt ra sau, chân cách tường 3-5 cm\n• Lưu ý: chân cách quá sát tường thì quầng sáng bị gắt, quá xa thì loang; 3-5 cm là vừa\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A backlit company name sign behind reception suits language centres, study-abroad consultancies and recruitment offices, where visitors should recognise the business the moment they walk in.\n\n• Material: 2-3 mm brushed aluminium or stainless, folded into a tray 3-4 cm deep\n• Lettering: UV print, etched and paint-filled, or applied acrylic letters\n• Lighting: warm white LED strip or modules shining back onto the wall, 3-5 cm stand-off\n• Tip: too close to the wall and the halo looks harsh, too far and it spreads out; 3-5 cm is right\n\nTrường Thịnh designs, makes the sign in its workshop and installs it.","altVi":"Bảng tên kim loại xước đèn hắt sau quầy lễ tân, vách lam gỗ","altEn":"Backlit brushed metal name sign behind a reception desk on a timber slat wall","source":"/assets/content/projects/advertising/office-signs-wayfinding/bang-ten-cong-ty-den-hat.webp","sha256":"59fa6afbd124a66704eb15b21d98fc47be066705e809524b539ca87f6118a4f2","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:bang-ten-bu-03-1; original SHA256 9a7a39b4d5a51c5df888afc4fb90c1a1ec4895b45bedf3fc8eaa2ebaa3339409; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-44": {"descriptionVi":"Biển số nhà vân gỗ phối vàng hợp với nhà vườn, biệt thự, nhà phố có cổng tông ấm, muốn biển trông như gỗ mà không lo mục, cong vênh ngoài trời.\n\n• Chất liệu: alu vân gỗ ngoài trời hoặc gỗ nhựa composite\n• Số và viền: inox mạ PVD vàng hoặc mica gương vàng cắt laser, dán nổi\n• Kích thước thường làm: 40x30 cm, 50x35 cm\n• Lưu ý: chỗ nắng gắt nên chọn inox mạ PVD, mica gương vàng để ngoài trời lâu dễ mờ lớp tráng gương\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A wood-grain house number plate with gold detailing suits garden homes, villas and townhouses with warm-toned gates, giving the look of timber without rot or warping outdoors.\n\n• Material: exterior wood-grain aluminium composite or wood-plastic composite\n• Numerals and border: gold PVD stainless or laser-cut gold mirror acrylic, applied in relief\n• Typical size: 40x30 cm or 50x35 cm\n• Tip: in strong sun choose PVD stainless, since gold mirror acrylic loses its mirror finish after long outdoor exposure\n\nTrường Thịnh designs, makes the plate in its workshop and installs it.","altVi":"Biển số nhà vân gỗ nâu viền và số vàng trên trụ cổng","altEn":"Wood-grain house number plate with gold border and numerals on a gate pillar","source":"/assets/content/projects/advertising/office-signs-wayfinding/bien-so-nha-van-go.webp","sha256":"11740b751e95b99e35d5fb025d0d4d57013561f6e8d149d885cdcf3ee80ea4fe","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:bang-ten-bu-04-1; original SHA256 7e11e7f1a9af308550c0aa65fedd760c64f3ed9cc17811e333d834802d6c2cde; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-45": {"descriptionVi":"Biển phòng khám đông y bằng gỗ hợp với phòng chẩn trị y học cổ truyền, nhà thuốc nam, phòng châm cứu muốn mặt tiền trang nhã, đúng tinh thần nghề thuốc.\n\n• Chất liệu: gỗ tự nhiên sơn PU ngoài trời hoặc alu vân gỗ\n• Chữ: mica gương đồng hoặc inox mạ đồng cắt laser, dán nổi\n• Kích thước thường làm: 60x40 cm đến 80x50 cm\n• Lưu ý: nội dung biển phòng khám phải khớp giấy phép hoạt động, nên gửi bản giấy phép để đối chiếu trước khi làm\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A timber clinic sign suits traditional medicine clinics, herbal pharmacies and acupuncture practices that want a quiet, dignified frontage in keeping with the trade.\n\n• Material: solid timber with exterior PU, or wood-grain aluminium composite\n• Lettering: laser-cut bronze mirror acrylic or bronze-tone stainless, applied in relief\n• Typical size: 60x40 cm to 80x50 cm\n• Tip: clinic sign wording must match the operating licence, so send a copy of the licence to check against before production\n\nTrường Thịnh designs, makes the sign in its workshop and installs it.","altVi":"Biển gỗ phòng khám đông y chữ nổi màu đồng gắn trụ cổng","altEn":"Timber traditional medicine clinic sign with bronze-tone letters on a gate pillar","source":"/assets/content/projects/advertising/office-signs-wayfinding/bien-phong-kham-dong-y.webp","sha256":"c9f8d9b943746c42e78add707d8f33552bace5f6fceecf79ccb2c1ec2030ddb5","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:bang-ten-bu-05-1; original SHA256 392b7e18191bd0faa215c50fb40de3b6dc52954f5ee99425351ea9e017f3d2e3; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-46": {"descriptionVi":"Bảng chức danh để bàn đế gỗ mặt đồng là mẫu quen thuộc ở phòng kế toán, phòng giám đốc, quầy ngân hàng, hợp với bàn gỗ và nội thất tông ấm.\n\n• Chất liệu: đế gỗ tự nhiên hoặc MDF sơn PU, mặt đồng hoặc alu mạ vàng xước\n• Gia công: khắc laser hoặc ăn mòn đổ sơn đen\n• Kích thước thường làm: 25x8 cm, 30x10 cm\n• Lưu ý: chọn mặt cài rời thì khi đổi người chỉ thay tấm mặt, giữ lại đế gỗ\n\nTrường Thịnh thiết kế, gia công tại xưởng và giao tận nơi trọn gói.","descriptionEn":"A timber desk nameplate with a brass face is the familiar choice for accounts departments, directors' offices and bank counters, matching timber desks and warm interiors.\n\n• Material: solid timber or PU-lacquered MDF base, brushed brass or gold-tone aluminium face\n• Fabrication: laser-engraved or etched and filled in black\n• Typical size: 25x8 cm or 30x10 cm\n• Tip: choose a slot-in face so that when staff change, only the plate is replaced and the base is kept\n\nTrường Thịnh designs, makes the nameplates in its workshop and delivers them.","altVi":"Bảng chức danh đế gỗ mặt đồng vàng xước trên bàn làm việc","altEn":"Timber desk nameplate with a brushed brass face on an office desk","source":"/assets/content/projects/advertising/office-signs-wayfinding/bang-chuc-danh-go-mat-dong.webp","sha256":"ccc99f155806a96be517d31fd9c30ee63967f44fdb169ed9c33c2af622c831d8","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:chuc-danh-bu-01-1; original SHA256 87825f9c00e94c121d3ea3a2dc8be80932731e80401cd8f050fa2abab725e397; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-47": {"descriptionVi":"Bảng chức danh gỗ khắc laser hợp với văn phòng công ty nhỏ, hợp tác xã, nhà hàng có phòng tiếp khách, cần một bộ bảng mộc, ấm và đồng bộ cho cả phòng họp.\n\n• Chất liệu: mặt gỗ sồi hoặc gỗ thông ghép, đế gỗ sẫm màu\n• Gia công: khắc laser chữ cháy nâu, không dùng mực nên không phai\n• Kích thước thường làm: 25x8 cm đến 30x10 cm\n• Lưu ý: đặt cả bộ một lần để vân gỗ và màu khắc đều nhau, làm bổ sung sau dễ lệch tông\n\nTrường Thịnh thiết kế, gia công tại xưởng và giao tận nơi trọn gói.","descriptionEn":"Laser-engraved timber title plates suit small company offices, cooperatives and restaurants with a meeting room, giving a warm, natural set that matches across the table.\n\n• Material: oak or finger-jointed pine face on a dark timber base\n• Fabrication: laser-burned brown lettering, with no ink to fade\n• Typical size: 25x8 cm to 30x10 cm\n• Tip: order the whole set at once so grain and engraving tone match, as later additions often differ\n\nTrường Thịnh designs, makes the plates in its workshop and delivers them.","altVi":"Bốn bảng chức danh gỗ khắc chữ xếp trên bàn họp gỗ","altEn":"Four engraved timber title plates set along a wooden meeting table","source":"/assets/content/projects/advertising/office-signs-wayfinding/bang-chuc-danh-go-khac-laser.webp","sha256":"23ddec0d5573384c2d9b1adafc0460431d61a67b73222e0b65c1c450a84ddce3","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:chuc-danh-bu-02-1; original SHA256 87ae8007b9efde6f7083064c93680c269e5d54b825ed003235aefd4eb0540d23; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-48": {"descriptionVi":"Bảng chức danh để bàn gỗ mặt sáng hợp với văn phòng công ty, phòng kế toán, cơ quan có nội thất gỗ, muốn bảng mộc hơn mặt đồng nhưng vẫn rõ chữ.\n\n• Chất liệu: đế gỗ tự nhiên sẫm màu, mặt gỗ phong hoặc mica vân gỗ kem\n• Gia công: khắc laser chữ cháy nâu, mặt bo góc tròn\n• Kích thước thường làm: 30x10 cm, 35x12 cm\n• Lưu ý: mặt gỗ thật nên phủ lớp sơn mờ chống bám tay, giữ màu sáng lâu hơn\n\nTrường Thịnh thiết kế, gia công tại xưởng và giao tận nơi trọn gói.","descriptionEn":"A timber desk nameplate with a light face suits company offices, accounts departments and public offices with timber furniture, for a more natural look than brass while staying easy to read.\n\n• Material: dark solid timber base, maple face or cream wood-grain acrylic\n• Fabrication: laser-burned lettering, face with rounded corners\n• Typical size: 30x10 cm or 35x12 cm\n• Tip: have a real wood face sealed in matt lacquer so it resists fingerprints and stays pale longer\n\nTrường Thịnh designs, makes the nameplate in its workshop and delivers it.","altVi":"Bảng chức danh đế gỗ sẫm mặt gỗ sáng khắc chữ trên bàn","altEn":"Dark timber desk nameplate with an engraved light wood face on an office desk","source":"/assets/content/projects/advertising/office-signs-wayfinding/bang-chuc-danh-go-van-phong.webp","sha256":"5bf917de1a8128592648e74081596c2fae2a1700d0b60f60dd008f75c38cb520","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd1f3-a3cc-83ec-9332-edaa7cb6f322); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-27 01:07Z; master PNG SHA256 ae14df539f3845c10adb67112b20b03ef79ff6a50ca70734120e1bfbdcb93b3a."},
  "office-signs-wayfinding-49": {"descriptionVi":"Bảng chức danh mica kẹp đế gỗ hợp với ngân hàng, quầy giao dịch, lễ tân khách sạn, nơi nhân viên đổi ca thường xuyên và cần thay nội dung nhanh.\n\n• Cấu tạo: hai tấm mica trong 3-5 mm kẹp lá in, ốc inox bốn góc\n• In: UV hoặc in giấy ảnh, đổi chức danh chỉ cần in lại lá giữa\n• Đế: gỗ óc chó hoặc gỗ cao su phủ dầu, xẻ rãnh cắm mica\n• Lưu ý: in họa tiết theo màu nhận diện ngân hàng để cả dãy quầy đồng bộ\n\nTrường Thịnh thiết kế, gia công tại xưởng và giao tận nơi trọn gói.","descriptionEn":"Acrylic title signs on timber bases suit banks, transaction counters and hotel front desks where shifts change often and the wording needs swapping quickly.\n\n• Build: two 3-5 mm clear acrylic sheets clamping a printed insert, stainless screws at each corner\n• Print: UV or photo paper, so a new title means reprinting only the insert\n• Base: oiled walnut or rubberwood with a slot for the acrylic\n• Tip: print the artwork in your brand colours so the whole row of counters matches\n\nTrường Thịnh designs, makes the signs in its workshop and delivers them.","altVi":"Ba bảng chức danh mica kẹp ốc trên đế gỗ, đặt quầy đá","altEn":"Three screw-clamped acrylic title signs on timber bases at a granite counter","source":"/assets/content/projects/advertising/office-signs-wayfinding/bang-chuc-danh-mica-de-go.webp","sha256":"e91714dc49f5939e7a9ab6786dd74034583cb80d06e0f4ee9e968a1d807cc256","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:chuc-danh-bu-04-1; original SHA256 bbe3586e092b7f53ae63c75cef4b88e4bbac03502524d6c4fb5ed12fa4c94f56; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-50": {"descriptionVi":"Bảng chức danh quầy giao dịch dạng dài hợp với ngân hàng, quỹ tín dụng, phòng chăm sóc khách hàng có nhiều quầy xếp liền, cần khách đọc được từ hàng ghế chờ.\n\n• Chất liệu: mica trong 8-10 mm in UV mặt sau, cắm trên đế gỗ\n• Kích thước thường làm: 40x12 cm cho quầy chính, 30x10 cm cho bàn phụ\n• Gia công: cạnh mica đánh bóng, đế xẻ rãnh vừa khít không lung lay\n• Lưu ý: in mặt sau thì lớp màu nằm dưới mica, lau cồn hằng ngày vẫn không trầy\n\nTrường Thịnh thiết kế, gia công tại xưởng và giao tận nơi trọn gói.","descriptionEn":"Long-format counter title signs suit banks, credit funds and customer service centres with rows of counters, where customers need to read them from the waiting seats.\n\n• Material: 8-10 mm clear acrylic with reverse UV print, set into a timber base\n• Typical size: 40x12 cm for main counters, 30x10 cm for side desks\n• Fabrication: polished acrylic edges, a snug routed slot that doesn't wobble\n• Tip: with reverse printing the colour sits behind the acrylic, so daily alcohol wipes won't scratch it\n\nTrường Thịnh designs, makes the signs in its workshop and delivers them.","altVi":"Bảng chức danh mica sóng xanh đế gỗ trên quầy đá giao dịch","altEn":"Blue wave acrylic title signs on timber bases at a stone counter","source":"/assets/content/projects/advertising/office-signs-wayfinding/bang-chuc-danh-quay-giao-dich.webp","sha256":"ba61133dc19da6b0ae30f78c59357ff66c1758f9ecef28810af52f82c8f9f4d9","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:chuc-danh-bu-04-2; original SHA256 c3fe801e4825745c6c429e8f85315aef508d2a1c32b5de6dad3ed3a9caf1283c; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-51": {"descriptionVi":"Biển chức danh mạ vàng cài đế gỗ hợp với phòng kế toán, phòng hành chính, văn phòng doanh nghiệp gia đình muốn bảng tên bàn chỉn chu mà giá vừa phải.\n\n• Chất liệu: inox mạ vàng xước hoặc alu giả đồng, đế gỗ tự nhiên xẻ rãnh\n• Gia công: khắc laser hoặc in UV chữ, bo cạnh để không cấn tay\n• Kích thước thường làm: 25x8 cm đến 30x10 cm\n• Lưu ý: tấm biển cài rời khỏi đế, khi đổi người hay đổi chức danh chỉ thay tấm biển, giữ nguyên đế\n\nTrường Thịnh thiết kế, gia công tại xưởng và giao tận nơi trọn gói.","descriptionEn":"A gold-tone title plate in a timber base suits accounts and admin offices and family businesses that want a smart desk sign at a moderate price.\n\n• Material: brushed gold-plated stainless or brass-look aluminium, slotted solid timber base\n• Fabrication: laser-engraved or UV-printed lettering, edges rounded so they don't catch\n• Typical size: 25x8 cm to 30x10 cm\n• Tip: the plate lifts out of the base, so a new person or title needs only a new plate\n\nTrường Thịnh designs, makes the plates in its workshop and delivers them.","altVi":"Biển chức danh mạ vàng cài khe đế gỗ trên bàn kế toán","altEn":"Gold-tone title plate slotted into a timber base on an accountant's desk","source":"/assets/content/projects/advertising/office-signs-wayfinding/bien-chuc-danh-ma-vang.webp","sha256":"cc849483a3a8d55ec48cbad9ddde7e542a70b30d61635d137affe1b70a586755","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:chuc-danh-bu-05-1; original SHA256 7cd8783b907569fb47bb0196ab2709bca64a5ee85e32ea8fefb81277f408258b; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-52": {"descriptionVi":"Bảng chức danh hội nghị bằng gỗ hợp với cơ quan, đoàn thể, hợp tác xã tổ chức đại hội, hội nghị định kỳ, cần một bộ bảng dùng lại được qua nhiều kỳ.\n\n• Chất liệu: gỗ ghép hoặc MDF phủ veneer sáng màu, đế gỗ sẫm\n• Gia công: khắc laser hoặc in UV, chữ chân phương dễ đọc ở bàn đại biểu\n• Kích thước thường làm: 30x10 cm cho đại biểu, 40x12 cm cho chủ tọa\n• Lưu ý: nên làm thêm vài bảng trống để in decal tên khách mời đột xuất\n\nTrường Thịnh thiết kế, gia công tại xưởng và giao tận nơi trọn gói.","descriptionEn":"Timber conference title plates suit public bodies, associations and cooperatives holding regular congresses and meetings, as one set can be reused year after year.\n\n• Material: finger-jointed timber or light veneered MDF, dark timber base\n• Fabrication: laser-engraved or UV printed in a plain, legible typeface\n• Typical size: 30x10 cm for delegates, 40x12 cm for the chair\n• Tip: order a few blank plates for vinyl names when unexpected guests turn up\n\nTrường Thịnh designs, makes the plates in its workshop and delivers them.","altVi":"Bảng chức danh gỗ sáng cho chủ tọa, đại biểu trên bàn hội nghị","altEn":"Light timber title plates for chair, secretary and delegates on a conference table","source":"/assets/content/projects/advertising/office-signs-wayfinding/bang-chuc-danh-hoi-nghi.webp","sha256":"6dd1a2200bd5d324686afce091333c53549649373489a8939f6c11ee9d106aff","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:chuc-danh-bu-06-1; original SHA256 0f0fdb7f50ec1f4a6047cd98909ed78bf09c36cefd911d700a8bcb22a8ab4f86; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-53": {"descriptionVi":"Kỷ niệm chương thành lập công ty làm theo bộ, mỗi hạng mục một kiểu, hợp với doanh nghiệp vừa tổ chức lễ kỷ niệm vừa tri ân nhân viên, đối tác trong cùng chương trình.\n\n• Chất liệu: gỗ óc chó hoặc gỗ sồi, phối pha lê K9, inox xước, mica gương vàng\n• Gia công: cắt CNC, khắc laser họa tiết lúa, sen, sông nước theo chủ đề\n• Kích thước thường làm: cao 18-25 cm, đế rộng 12-18 cm\n• Lưu ý: chốt danh sách hạng mục trước rồi mới chọn kiểu, để giải cao nhất có mẫu nổi bật nhất\n\nTrường Thịnh thiết kế trọn bộ, gia công tại xưởng và giao tận nơi.","descriptionEn":"Company anniversary awards made as a set, with a different design for each category, suit businesses that celebrate the milestone and thank staff and partners in the same programme.\n\n• Material: walnut or oak, combined with K9 crystal, brushed stainless or gold mirror acrylic\n• Fabrication: CNC-cut, with laser-engraved rice, lotus or river motifs to suit the theme\n• Typical size: 18-25 cm tall, bases 12-18 cm wide\n• Tip: settle the list of categories first, then pick the designs, so the top award gets the standout piece\n\nTrường Thịnh designs the full set, makes it in its workshop and delivers it.","altVi":"Bộ kỷ niệm chương gỗ phối pha lê và inox trên bàn văn phòng","altEn":"Set of timber awards combined with crystal and stainless steel on an office desk","source":"/assets/content/projects/advertising/office-signs-wayfinding/ky-niem-chuong-thanh-lap.webp","sha256":"b8ecaac26b7ad65e39ea9ee0fe8dded769b5f20535170b17e8cb1c33dc78fc96","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:ky-niem-chuong-bu-01-1; original SHA256 63ad9eda00cec1f7807d6bdb729a753280f79a7454b592e15352483f5c41045e; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "print-decals-25": {"descriptionVi":"In hộp giấy kraft đựng bánh hợp với tiệm bánh nhà làm, cơ sở đặc sản bán quà du lịch cần bộ hộp quai xách và túi cùng một tranh in cho từng loại bánh.\n\n• Chất liệu: kraft 300-400 gsm, bồi sóng E cho hộp đựng bánh nặng\n• In: offset 4 màu trên kraft, màu lên trầm hơn in trên giấy trắng\n• Kiểu hộp: hộp quai xách, hộp nắp gài, hộp âm dương cho bánh làm quà\n• Lưu ý: dùng chung một tranh nền, chỉ đổi tên bánh, một khuôn bế dùng được cho nhiều loại\n\nTrường Thịnh thiết kế, in, bế hộp và giao tận nơi trọn gói.","descriptionEn":"Printed kraft cake boxes suit home bakeries and specialty-food makers selling to tourists who need carry boxes and bags sharing one illustration across every product.\n\n• Material: 300-400 gsm kraft, E-flute laminated for heavier cakes\n• Print: four-colour offset on kraft, which prints more muted than white board\n• Box styles: handled carry boxes, tuck-flap boxes, two-piece lid boxes for gifts\n• Tip: keep one background artwork and change only the product name, so one cutting die serves many lines\n\nTrường Thịnh designs, prints, die-cuts and delivers the boxes.","altVi":"Hộp quai xách và túi kraft in tranh dừa cho bánh nhà làm","altEn":"Kraft carry boxes and a bag with palm-tree artwork for homemade cakes","source":"/assets/content/projects/advertising/print-decals/in-hop-giay-kraft-dung-banh.webp","sha256":"0268a1375a34b4b6f5d56d20cb3e9140a5f3107cc637dfe29c5a29fe75e092e0","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile, edited by owner; owner approved to site 2026-10-26 23:04Z; master PNG SHA256 44662baf7f89b2dbafd544d1faac4ac14915d947c3456488dab99f550b9e7dfd."},
  "print-decals-26": {"descriptionVi":"Hộp quà giấy kraft có cửa sổ hợp với cơ sở đặc sản dừa, sản phẩm OCOP, cửa hàng quà du lịch cần bộ quà biếu gồm túi, hộp và nhãn hũ cùng một mẫu.\n\n• Hộp: kraft 350-400 gsm, cửa sổ màng PET trong, quai dây gai\n• Nhãn: decal giấy kraft dán hũ thủy tinh, chai dầu, in theo từng sản phẩm\n• Lót: rơm giấy hoặc khay bế giữ hũ không va nhau khi xách\n• Lưu ý: đo hũ, chai thật trước khi làm khuôn bế, lệch vài mm là hộp lỏng hoặc không vừa\n\nTrường Thịnh thiết kế, in, bế hộp và giao tận nơi trọn gói.","descriptionEn":"Windowed kraft gift boxes suit coconut specialty producers, OCOP brands and tourist gift shops that need a gift set of bag, box and jar labels in one design.\n\n• Box: 350-400 gsm kraft, clear PET window, jute handle\n• Labels: kraft paper stickers for glass jars and oil bottles, printed per product\n• Insert: shredded paper or a die-cut tray to stop jars knocking together\n• Tip: measure the real jars and bottles before making the die, as a few millimetres off leaves the box loose or too tight\n\nTrường Thịnh designs, prints, die-cuts and delivers the gift sets.","altVi":"Hộp quà kraft có cửa sổ, túi và nhãn hũ đặc sản dừa","altEn":"Windowed kraft gift box, bag and jar labels for coconut products","source":"/assets/content/projects/advertising/print-decals/hop-qua-giay-kraft-dua.webp","sha256":"77f683fd6aa0a65fd61760d44664f8d38486008b28dcfcbfd4dd818df9e7a97f","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile, edited by owner; owner approved to site 2026-10-26 23:04Z; master PNG SHA256 370b2a49928b837fd6cbaa9a57bcdc9172f64bdfc6180233793cb86c6f033836."},
  "print-decals-27": {"descriptionVi":"In vé sự kiện kèm vòng tay giấy hợp với lễ hội, hội chợ, sự kiện ngoài trời nhiều khu, cần soát vé ở cổng và phân biệt khách mời, ban tổ chức bằng màu.\n\n• Vé: couché 250-300 gsm, cán màng, cấn răng cưa xé cuống\n• Vòng tay: giấy Tyvek không rách, không thấm nước, khóa keo dán một lần\n• Phân loại: mỗi nhóm khách một màu vòng, in thêm số nếu cần đếm\n• Lưu ý: sự kiện ngoài trời dễ gặp mưa, nên cán màng vé và chọn Tyvek thay giấy thường\n\nTrường Thịnh thiết kế theo chủ đề sự kiện, in và giao tận nơi.","descriptionEn":"Event tickets with paper wristbands suit festivals, fairs and outdoor events with several zones, where the gate checks tickets and colour tells guests and organisers apart.\n\n• Tickets: 250-300 gsm coated, laminated, with a perforated stub\n• Wristbands: tear-proof, water-resistant Tyvek with single-use adhesive closure\n• Grouping: one wristband colour per guest type, numbered if you need a count\n• Tip: outdoor events risk rain, so laminate tickets and use Tyvek rather than plain paper\n\nTrường Thịnh designs to the event theme, prints and delivers.","altVi":"Vé tham dự in tranh sông nước và vòng tay giấy phân loại khách","altEn":"Riverside-themed event tickets and colour-coded paper wristbands on a wooden deck","source":"/assets/content/projects/advertising/print-decals/in-ve-su-kien-vong-tay.webp","sha256":"22292357d0b181ace3cffdab23b4304d03729175affcecb1a02c030cab090900","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:bao-bi-bu-03-1; original SHA256 ed4319f5a3f1f25a006445093f893483caa4876ec98b6a2d4e0db70bdea676f1; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "print-decals-28": {"descriptionVi":"In thẻ tích điểm và thẻ thành viên hợp với quán cà phê, quán nước muốn giữ khách quen bằng ưu đãi mua đủ ly tặng một ly, không cần cài phần mềm.\n\n• Chất liệu: giấy mỹ thuật 300-350 gsm cán màng, hoặc nhựa PVC dùng lâu\n• Quy cách: 86x54 mm hoặc 9x6 cm, bo góc, mặt sau in ô đóng dấu\n• Giá để thẻ: gỗ thông hoặc gỗ cao su khắc laser, chia hai ngăn\n• Lưu ý: in ô tích điểm trên nền mờ để đóng mộc hay ghi bút không lem\n\nTrường Thịnh thiết kế, in thẻ, làm giá gỗ tại xưởng và giao tận nơi.","descriptionEn":"Loyalty and member card printing suits cafés and drinks shops that want to keep regulars with a buy-ten-get-one offer, with no app to install.\n\n• Material: 300-350 gsm laminated art paper, or longer-lasting PVC\n• Format: 86x54 mm or 9x6 cm, rounded corners, stamp boxes on the back\n• Card stand: laser-engraved pine or rubberwood with two compartments\n• Tip: print the stamp boxes on a matt surface so stamps and pens don't smudge\n\nTrường Thịnh designs and prints the cards, makes the timber stand in its workshop and delivers both.","altVi":"Giá gỗ khắc hoa sen đựng thẻ thành viên, thẻ tích điểm trên bàn","altEn":"Lotus-engraved timber stand holding café member and loyalty cards on a table","source":"/assets/content/projects/advertising/print-decals/in-the-tich-diem.webp","sha256":"11c14d331b223a8a27d82e059e4e4c47dce280835971fcd0846254480713dd55","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:bao-bi-bu-04-1; original SHA256 6322ea0c523ab4ba2c24f3133bae286cb852e02d70576009fbfd980ced8b306b; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "print-decals-29": {"descriptionVi":"In bao bì đồng bộ gồm túi giấy, ly giấy và thẻ treo hợp với shop thời trang có góc đồ uống, cửa hàng quà tặng muốn mọi thứ khách mang về cùng một họa tiết.\n\n• Túi: kraft 150-200 gsm, quai dây thừng luồn lỗ, miệng túi gia cố bìa\n• Ly: ly giấy hai lớp in offset, đi kèm nắp nhựa\n• Thẻ treo: giấy mỹ thuật 300-350 gsm, đục lỗ xỏ dây gai, mỗi dòng hàng một màu\n• Lưu ý: ly giấy thường in theo lô lớn, nên chốt mẫu ly trước rồi in túi và thẻ số ít\n\nTrường Thịnh thiết kế trọn bộ, in và giao tận nơi.","descriptionEn":"Matching packaging of paper bags, cups and hang tags suits fashion boutiques with a drinks corner and gift shops that want everything customers carry home to share one motif.\n\n• Bags: 150-200 gsm kraft, rope handles through reinforced tops\n• Cups: double-wall paper cups, offset printed, with plastic lids\n• Hang tags: 300-350 gsm art paper, punched for jute string, one colour per product line\n• Tip: paper cups are printed in large runs, so fix the cup design first, then print bags and tags in smaller lots\n\nTrường Thịnh designs the full set, prints it and delivers to your door.","altVi":"Túi kraft, ly giấy, thẻ treo in họa tiết sen cho shop thời trang","altEn":"Kraft bags, paper cups and hang tags with lotus artwork for a boutique","source":"/assets/content/projects/advertising/print-decals/in-bao-bi-shop-thoi-trang.webp","sha256":"9f3552e4e8ac9f5e63a97bd278e52ba3558b78db4b3d24e541ef6b191ed31394","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd25c-4a40-83ec-9cc3-a5b59140d3f6); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-27 01:07Z; master PNG SHA256 7dd932275bd836db2cfeccb9016a3ba903f37cfd397056fc7abb3e90f7214f17."},
  "print-decals-30": {"descriptionVi":"Thực đơn để bàn khung gỗ có khoen lật hợp với quán cà phê sân vườn, quán ăn vặt, đặt sẵn trên từng bàn để khách tự xem và thêm trang khi quán có món mới.\n\n• Khung: gỗ tràm hoặc gỗ cao su, đế dày, phủ PU chống ẩm\n• Ruột: couché 250-300 gsm cán màng, in hai mặt, lật trang bằng khoen kim loại\n• Khổ thường làm: A5 hoặc A4 đứng\n• Lưu ý: quán ngoài trời nên cán màng mờ dày, tránh lóa nắng và nước đá đọng làm ướt trang\n\nTrường Thịnh thiết kế, in ruột, làm khung gỗ và giao tận nơi.","descriptionEn":"A timber-framed flip table menu suits garden cafés and snack shops, left on each table so guests browse on their own and pages can be added when new dishes arrive.\n\n• Frame: acacia or rubberwood with a heavy base, PU-sealed against moisture\n• Pages: 250-300 gsm laminated coated paper, printed both sides, flipping on metal rings\n• Typical size: A5 or A4 portrait\n• Tip: for outdoor seating use thick matt lamination, which avoids glare and survives drips from iced drinks\n\nTrường Thịnh designs, prints the pages, makes the timber frame and delivers.","altVi":"Thực đơn khung gỗ có khoen kim loại, in món quê và cà phê","altEn":"Timber-framed table menu on metal rings listing coffee and local snacks","source":"/assets/content/projects/advertising/print-decals/thuc-don-de-ban-khung-go.webp","sha256":"8f8bca3e2b66736489c05c9e72d968f78eb1db0c196c2a9bfa1a110585d4a620","provenance":"AI-generated illustration; ChatGPT web image edit with owner mask (chat 6ae5c743-2164-83ec-977b-b0ac7c6c55a3); upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-27; master PNG SHA256 939deddf1606efdc56aa68b1ac12a86f7457804a2d845cb04f25eb5e53320fb6."},
  "print-decals-31": {"descriptionVi":"Bảng menu gỗ treo hợp với quán nước trái cây, quầy sinh tố, cà phê đông khách mua mang đi, nơi khách chọn món trong lúc xếp hàng.\n\n• Khung: gỗ thông hoặc MDF dán veneer, chia ô, treo ty sắt hoặc cáp\n• Mặt menu: decal in cán màng dán lên tấm alu hoặc formex\n• Kích thước thường làm: mỗi ô 50x80 cm, ghép 2-4 ô theo chiều dài quầy\n• Lưu ý: giá dán bằng decal rời từng dòng, đổi giá không phải in lại cả tấm\n\nTrường Thịnh thiết kế, làm khung tại xưởng, in decal và lắp đặt trọn gói.","descriptionEn":"A hanging timber menu board suits juice bars, smoothie counters and busy takeaway cafés, where customers choose while they queue.\n\n• Frame: pine or veneered MDF in panels, hung from steel rods or cable\n• Face: laminated printed vinyl on aluminium composite or foam PVC board\n• Typical size: 50x80 cm per panel, 2-4 panels to match the counter length\n• Tip: put prices on separate vinyl strips, so a price change never means reprinting the whole panel\n\nTrường Thịnh designs, builds the frame in its workshop, prints the graphics and installs.","altVi":"Bảng menu gỗ ba ô treo ty phía trên quầy nước trái cây","altEn":"Three-panel timber drinks menu hung on rods above a juice bar","source":"/assets/content/projects/advertising/print-decals/bang-menu-go-treo-quay-nuoc.webp","sha256":"44a9f105dd6c3d5f62ad477304c2ec60873d3496d15f123866741b3664b925fc","provenance":"AI-generated illustration; owner hand-edited 2026-10-31; owner approved to site 2026-10-31; master PNG SHA256 c36760cb02d431e82f46271fecfea2d9de73e8a8c5341f8457bed046a116fa78."},
  "print-decals-32": {"descriptionVi":"Menu bìa mây đan kèm ruột khung gỗ hợp với quán ăn ven sông, nhà hàng đặc sản, nhà vườn muốn thực đơn hợp không gian mộc và dùng ngoài trời nhiều năm.\n\n• Bìa: tấm mây hoặc tre đan ép, in UV hay khắc laser tên quán, nẹp gỗ ở gáy\n• Ruột: giấy chịu nước hoặc giấy in cán màng, kẹp khoen trên ván gỗ\n• Khổ thường làm: A4 đứng, 2-6 trang\n• Lưu ý: mây tre ở nơi ẩm dễ mốc, nên phủ PU mờ và lau khô sau giờ đóng quán\n\nTrường Thịnh thiết kế, làm bìa, in ruột và giao tận nơi.","descriptionEn":"Woven cane menus with timber-backed pages suit riverside eateries, specialty restaurants and garden venues that want menus matching a rustic setting and lasting outdoors for years.\n\n• Cover: pressed woven cane or bamboo, UV-printed or laser-engraved name, timber spine strip\n• Pages: waterproof stock or laminated prints, ring-bound on timber boards\n• Typical size: A4 portrait, 2-6 pages\n• Tip: cane goes mouldy in damp air, so seal it with matt PU and wipe it dry after closing\n\nTrường Thịnh designs, makes the covers, prints the pages and delivers.","altVi":"Menu bìa mây đan in tên quán và hai trang menu khung gỗ","altEn":"Woven cane menu cover and two timber-backed menu pages on a riverside table","source":"/assets/content/projects/advertising/print-decals/menu-bia-may-khung-go.webp","sha256":"d71181403bc3e503c9b7df1befc5e2553072eee621ecc2dd770aeef3aa86548a","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd21b-8e1c-83ec-914f-743c5dbb4ed0); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-27 01:07Z; master PNG SHA256 89dcdb48aa6d5feacd9b67bbf9d41e66364b8a3dd9605a6d92814c27771061e7."},
  "print-decals-33": {"descriptionVi":"Bảng menu chữ A khung gỗ hợp với quán bún, quán ăn, quán nước đặt trước cửa hay lối vào, sáng mang ra, tối gấp lại cất.\n\n• Khung: gỗ thông hoặc gỗ tràm, bản lề và xích giữ chân hai bên\n• Mặt bảng: decal in cán màng dán trên formex hoặc alu, làm hai mặt\n• Kích thước thường làm: 60x90 cm hoặc 60x120 cm\n• Lưu ý: đặt ngoài trời nên chọn mặt alu, formex phơi nắng lâu dễ cong\n\nTrường Thịnh thiết kế, làm khung, in decal và giao tận nơi.","descriptionEn":"A timber A-frame menu board suits noodle shops, eateries and drinks stalls that stand it by the door or entrance, out in the morning and folded away at night.\n\n• Frame: pine or acacia with hinges and a safety chain between the legs\n• Face: laminated printed vinyl on foam PVC or aluminium composite, both sides\n• Typical size: 60x90 cm or 60x120 cm\n• Tip: for outdoor use pick aluminium composite, as foam board warps after long sun exposure\n\nTrường Thịnh designs, builds the frame, prints the graphics and delivers.","altVi":"Bảng menu chữ A gỗ in bún riêu, bún mắm, hủ tiếu","altEn":"Timber A-frame menu board for noodle soups at a riverside eatery","source":"/assets/content/projects/advertising/print-decals/bang-menu-chu-a-quan-bun.webp","sha256":"13d6ed5827eb3da148e6d2cb693ac7676ed3a0fcf4d5b4907c227cd7448f2b89","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 991f80b179f65a394a0aab4fdc3cb8ff54863e487f732e0ad83576153f443ddd."},
  "print-decals-34": {"descriptionVi":"Hộp đèn menu treo trần hợp với tiệm bánh, quán cà phê bánh mì có quầy dài, gom tên tiệm và danh mục món vào một hộp sáng duy nhất.\n\n• Khung: nhôm định hình hoặc gỗ uốn bo góc, sâu 8-12 cm\n• Mặt: bạt xuyên sáng (bạt 3M, bạt Hàn Quốc) hoặc mica sữa dán decal in, LED module hoặc LED dây bên trong\n• Lắp đặt: treo ty ren xuống trần, cấp điện 12V qua nguồn tổ ong\n• Lưu ý: hay đổi món thì chọn mặt bạt căng, thay tấm in nhanh và rẻ hơn mặt mica\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A ceiling-hung menu lightbox suits bakeries and bánh mì cafés with a long counter, combining the shop name and menu in a single lit box.\n\n• Frame: aluminium extrusion or bent timber with rounded corners, 8-12 cm deep\n• Face: translucent flex (3M or Korean grade) or opal acrylic with printed vinyl, LED modules or strip inside\n• Installation: hung on threaded rods from the ceiling, 12V power supply\n• Tip: if the menu changes often choose a tensioned flex face, which is quicker and cheaper to swap than acrylic\n\nTrường Thịnh designs, builds in its own workshop and installs the whole lightbox.","altVi":"Hộp đèn menu dài viền gỗ treo ty trên tủ bánh","altEn":"Long timber-rimmed menu lightbox hung on rods above a bakery counter","source":"/assets/content/projects/advertising/print-decals/hop-den-menu-treo-tran.webp","sha256":"bc202ab32decd47d5a2e6705c520db929445dd78d4087b67761bdfa5247fb4fd","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:menu-bu-05-1; original SHA256 69d5cf66d1629f84567f886539e5c1fcf092567570f336b9d0acbc3fec84b457; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "print-decals-35": {"descriptionVi":"Hộp đèn menu chia ô theo nhóm món hợp với tiệm bánh, quầy đồ ăn sáng bán nhiều loại, mỗi nhóm một ô để thay riêng khi thêm món hay đổi giá.\n\n• Cấu tạo: khung nhôm hoặc gỗ, mỗi ô một tấm mặt riêng, chung nguồn LED\n• Mặt: bạt 3M hoặc bạt Hàn Quốc xuyên sáng in ảnh món độ phân giải cao, bản cao cấp dùng decal xuyên sáng dán mica sữa 3 mm\n• Kích thước thường làm: dài 2-3 m, cao 60-80 cm, chia 3-4 ô\n• Lưu ý: nên dùng ảnh chụp món thật của tiệm, ảnh mẫu trên mạng dễ khác món khách nhận\n\nTrường Thịnh thiết kế, sản xuất hộp đèn tại xưởng và lắp đặt trọn gói.","descriptionEn":"A sectioned menu lightbox suits bakeries and breakfast counters with many items, giving each product group its own panel to change when items or prices change.\n\n• Build: aluminium or timber frame, a separate face per panel, one shared LED supply\n• Face: 3M or Korean translucent flex printed with high-resolution food photos, or backlit vinyl on 3 mm opal acrylic for a premium finish\n• Typical size: 2-3 m long, 60-80 cm high, in 3-4 panels\n• Tip: use photos of your own food, since stock images rarely match what customers receive\n\nTrường Thịnh designs, builds the lightbox in its own workshop and installs it.","altVi":"Hộp đèn menu ba ô viền gỗ treo trên tủ bánh ngọt","altEn":"Three-panel timber-framed menu lightbox above a pastry display case","source":"/assets/content/projects/advertising/print-decals/hop-den-menu-chia-o.webp","sha256":"8f0cbd396a65f9c10b30dbd4ef7c687e5a1b560d05969650c26f130cc3eaead6","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:menu-bu-05-2; original SHA256 d24aa5e2d1b07d7f4229c3b308b6e787855ec2553dc5f02fc32ed2c663f40fe3; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "print-decals-36": {"descriptionVi":"Bảng hiệu cửa hàng đặc sản làm trọn bộ gồm bảng alu chữ nổi, biển vẫy và decal dán kính, hợp với cửa hàng dừa, trái cây sấy, quà quê muốn mặt tiền đồng bộ một tông màu.\n\n• Bảng chính: alu ngoài trời trên khung sắt, chữ mica hoặc alu chấn sáng mặt\n• Biển vẫy: hộp đèn tròn mica hai mặt, đường kính 50-70 cm\n• Decal kính: decal in UV cán màng hoặc decal cắt, chừa khoảng trong để nhìn được vào cửa hàng\n• Lưu ý: làm cả bộ cùng một nơi thì màu in và màu mica khớp nhau hơn đặt rải rác nhiều chỗ\n\nTrường Thịnh thiết kế trọn bộ mặt tiền, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A complete speciality shop sign set, with an aluminium fascia, raised letters, a projecting sign and window decals, suits coconut, dried fruit and local gift shops that want one consistent colour scheme.\n\n• Main sign: exterior aluminium composite on a steel frame, face-lit acrylic or folded aluminium letters\n• Projecting sign: round double-sided acrylic lightbox, 50-70 cm diameter\n• Window decals: laminated UV-printed or cut vinyl, leaving clear areas to see into the shop\n• Tip: ordering the whole set from one maker keeps print and acrylic colours matched, unlike buying piece by piece\n\nTrường Thịnh designs the full frontage, builds it in its workshop and installs it.","altVi":"Mặt tiền cửa hàng dừa: bảng alu chữ nổi, biển vẫy, decal kính","altEn":"Coconut shop frontage with aluminium fascia, raised letters, projecting sign and window decals","source":"/assets/content/projects/advertising/print-decals/bang-hieu-cua-hang-dac-san.webp","sha256":"216c346eeca640fb0f77c4110676254ef48b4351112eabdf56517b48696ee46b","provenance":"AI-generated illustration; ChatGPT web (chat 6ae63347-1410-83ec-876b-bd196831f728); upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 b9dac4e6741b65c6d39d1de39c74c4bdb8f72a070f048526d2bfa02c1d635ac5."},
  "print-decals-37": {"descriptionVi":"In ly nhựa trà sữa kèm ly giấy và túi quai hợp với quán trà sữa bán mang đi, giao hàng, cần ly và túi cùng một màu nhận diện.\n\n• Ly nhựa: PP hoặc PET 500-700 ml, nắp cầu hoặc ép màng miệng ly\n• Ly giấy: giấy hai lớp cho đồ nóng, nắp nhựa đi kèm\n• Túi: kraft trắng hoặc nâu 120-150 gsm, quai giấy xoắn\n• Lưu ý: ly in theo lô tối thiểu của nhà máy, nên tính lượng bán 2-3 tháng rồi mới đặt\n\nTrường Thịnh thiết kế, in và giao tận nơi trọn gói.","descriptionEn":"Printed milk tea cups with matching paper cups and handle bags suit bubble tea shops selling takeaway and delivery, keeping cups and bags in one brand colour.\n\n• Plastic cups: PP or PET, 500-700 ml, dome lids or heat-sealed film\n• Paper cups: double-wall for hot drinks, with plastic lids\n• Bags: 120-150 gsm white or brown kraft, twisted paper handles\n• Tip: printed cups come in factory minimum runs, so estimate two to three months of sales before ordering\n\nTrường Thịnh designs, prints and delivers to your door.","altVi":"Ly nhựa, ly giấy và túi quai in trà sữa trên quầy gỗ","altEn":"Printed milk tea plastic cups, a paper cup and handle bag on a counter","source":"/assets/content/projects/advertising/print-decals/in-ly-nhua-tra-sua.webp","sha256":"27252c6542417b8d810c765c859efcd851317165bb3a59e7263e769ebcc60ff8","provenance":"AI-generated illustration; ChatGPT web gpt-image (owner chat 6af42a94-9144-83ec-a4e4-c3bfd37776ad); owner approved 2026-11-11; original PNG SHA256 79e4e9458c7fac40bfb8c65f5149e48b8dc6507f9777530a7ef9c4897819e1a6."},
  "print-decals-39": {"descriptionVi":"Khay giấy đựng ly in cùng ly giấy, ly nhựa hợp với quán cà phê bán đơn nhiều ly cho văn phòng và giao hàng.\n\n• Khay: kraft bồi sóng E, 2 hoặc 4 lỗ, quai bế liền thân\n• Ly giấy: hai lớp cho đồ nóng, in quanh thân 1-2 màu\n• Ly nhựa: PET trong, quấn đai giấy kraft in logo\n• Lưu ý: đo đường kính đáy ly trước khi làm khay, lệch cỡ thì ly lắc và dễ đổ khi xách\n\nTrường Thịnh thiết kế, in và giao tận nơi trọn gói.","descriptionEn":"Printed paper cup carriers with matching paper and plastic cups suit cafés selling multi-cup orders to offices and delivery riders.\n\n• Carrier: E-flute kraft, 2 or 4 holes, die-cut integral handle\n• Paper cups: double-wall for hot drinks, printed around the body in 1-2 colours\n• Plastic cups: clear PET wrapped in a printed kraft sleeve\n• Tip: measure the cup base before making the carrier, as a loose fit lets cups wobble and spill\n\nTrường Thịnh designs, prints and delivers to your door.","altVi":"Khay giấy bốn ly, ly giấy và ly nhựa in cà phê muối","altEn":"Four-cup kraft carrier, paper cup and plastic cup printed for salted coffee","source":"/assets/content/projects/advertising/print-decals/khay-giay-dung-ly-ca-phe.webp","sha256":"5547b65766cb3259c9d35583729d47e3fa915e7215a87895f9ec421115e8dfb7","provenance":"AI-generated illustration; ChatGPT web gpt-image (owner chat 6af4474f-0d90-83ec-a193-6730c480be89); owner approved 2026-11-11; original PNG SHA256 7b86ddea9d056096dc3982415df6ae2041fde5f53e47dbadf6bd1c9f7785dc69."},
  "print-decals-38": {"descriptionVi":"Hộp giấy đựng cơm, tô giấy có nắp và túi kraft in cùng mẫu hợp với quán cơm, bếp ăn văn phòng bán mang đi và giao hàng mỗi ngày.\n\n• Hộp: kraft tráng PE chống thấm dầu, nắp gài hoặc quấn đai giấy in logo\n• Tô giấy: 750-1.000 ml, nắp giấy, đựng canh hoặc cơm trộn\n• Túi: kraft nâu quai xoắn, đáy rộng để hộp nằm ngang\n• Lưu ý: món nhiều nước nên dùng tô tráng PE hai mặt, loại tráng một mặt dễ mềm đáy\n\nTrường Thịnh thiết kế, in và giao tận nơi trọn gói.","descriptionEn":"Printed paper meal boxes, lidded bowls and kraft bags suit rice eateries and office canteens selling takeaway and delivery every day.\n\n• Box: PE-lined kraft that resists grease, tuck lid or printed paper band\n• Bowl: 750-1,000 ml with a paper lid, for soup or mixed rice\n• Bag: brown kraft with twisted handles and a wide base so boxes lie flat\n• Tip: soupy dishes need bowls lined on both sides, as single-lined bowls soften at the base\n\nTrường Thịnh designs, prints and delivers to your door.","altVi":"Túi kraft, hộp giấy và tô giấy in logo quán cơm","altEn":"Kraft bag, paper meal box and lidded bowl printed for a rice eatery","source":"/assets/content/projects/advertising/print-decals/hop-giay-dung-com-tui-kraft.webp","sha256":"695bae28ba3cae20c16f90153961f85da622f30a8f71fbb4d96292e8704be547","provenance":"AI-generated illustration; ChatGPT web gpt-image (owner chat 6af4580c-ced8-83ec-883e-8a5bfb8c380c); owner approved 2026-11-11; original PNG SHA256 64a8eb39418654ac06758b7d7ea6ac13463c1047dcdbc6dc9b90d9634b28b170."},
  "signage-raised-letters-37": {"descriptionVi":"Bảng hiệu mắt kính dùng chữ nổi hắt sáng trên nền trơn hợp với tiệm kính mắt, phòng đo khúc xạ muốn mặt tiền sáng sủa, gọn như nội thất bên trong.\n\n• Nền: alu hoặc tấm xi măng sơn trắng mờ, che dầm và máy lạnh\n• Chữ: mica hoặc inox sơn đen, lưng mica, LED hắt sáng 3000-4000K\n• Kích thước thường làm: chữ chính cao 30-50 cm, dòng phụ 15-20 cm\n• Lưu ý: chữ hắt sáng cần nền màu sáng, đặt trên kính hoặc nền tối sẽ mất hiệu ứng\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"An optical shop sign with halo-lit letters on a plain background suits eyewear stores and eye-testing rooms that want a bright, tidy frontage to match the interior.\n\n• Background: matt white aluminium composite or cement board, hiding beams and AC units\n• Letters: black acrylic or painted stainless, acrylic backs, 3000-4000K halo LEDs\n• Typical size: main letters 30-50 cm tall, secondary line 15-20 cm\n• Tip: halo lighting needs a light background; on glass or a dark wall the effect disappears\n\nTrường Thịnh designs, builds in its own workshop and installs the sign.","altVi":"Chữ nổi hắt sáng trên mặt dựng trắng tiệm mắt kính lúc chiều","altEn":"Halo-lit raised letters on the white facade of an optical shop at dusk","source":"/assets/content/projects/advertising/signage-raised-letters/bang-hieu-mat-kinh-chu-noi.webp","sha256":"719eabb1844d874541dff4cfc7029dcf797b5b4bbe4acede394953d21b6a028a","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:signage-dusk-a-3; original SHA256 82de0bd8de935eb5f78697166f3f9b02fc584f1d70242b6025388a2aeb6528fb; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-47": {"descriptionVi":"Biển LED cửa hàng điện thoại dạng vẫy hai mặt hợp với tiệm sửa điện thoại, phụ kiện, điện máy nhỏ trên phố có nhiều cửa hàng cùng ngành san sát.\n\n• Cấu tạo: hộp nhôm định hình, mặt khoan lỗ, LED ruồi chống nước, viền đổi màu\n• Lắp đặt: tay đỡ hai thanh bắt bu lông nở vào cột hoặc tường\n• Kích thước thường làm: ngang 1-1,4 m, cao 50-60 cm\n• Lưu ý: phố có nhiều biển cùng loại thì chọn biểu tượng riêng và màu viền khác hàng xóm để khách dễ nhớ\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A double-sided LED phone shop sign suits phone repair, accessories and small electronics shops on streets lined with competitors in the same trade.\n\n• Build: aluminium profile case, drilled face, waterproof LED dots, colour-changing border\n• Installation: twin-arm bracket fixed with expansion bolts to a column or wall\n• Typical size: 1-1.4 m wide, 50-60 cm high\n• Tip: on a street full of similar signs, choose your own icon and a border colour unlike the neighbours so customers remember you\n\nTrường Thịnh designs, builds in its own workshop and installs the sign.","altVi":"Biển LED ruồi vẫy hai mặt trước cửa hàng sửa điện thoại, phụ kiện","altEn":"Double-sided LED-dot projecting sign outside a phone repair and accessories shop","source":"/assets/content/projects/advertising/led-displays-lightboxes/bien-led-cua-hang-dien-thoai.webp","sha256":"f57a1d10fa1a82d0f846111d9bb4ed6d50481f4f8020028ddacebbc9acae3f67","provenance":"AI-generated illustration edited by the owner; source ID owner-edit:2026-10-19:led-sign-01-3; original SHA256 91aeb91dac2e9f31f751271d18e996b2fe84d825c73f2854c17dd55d82af5352; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-48": {"descriptionVi":"Đèn neon quán cafe làm bằng LED neon trên mica cắt hình hợp với quán sân vườn, quán mở thoáng, vì LED neon chịu ẩm và không nóng như đèn neon thủy tinh.\n\n• Chất liệu: mica in UV phủ lớp chống trầy, dây LED neon silicon chuẩn chống nước IP65\n• Đèn: ánh vàng 3000K, nguồn 12V đặt trong hộp kín\n• Kích thước thường làm: ngang 1,2-2 m\n• Lưu ý: tường sát sông hay ẩm, nên bắt tấm bằng pát inox và đi dây trong ống\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A café neon sign made from LED neon on shaped acrylic suits garden and open-air cafés, because LED neon copes with damp and runs cool, unlike glass neon.\n\n• Material: UV-printed acrylic with an anti-scratch coat, IP65 silicone LED neon\n• Lighting: 3000K warm white, 12V supply in a sealed box\n• Typical size: 1.2-2 m wide\n• Tip: walls near a river stay damp, so fix the panel with stainless brackets and run cables in conduit\n\nTrường Thịnh designs, builds in its own workshop and installs the piece.","altVi":"Đèn neon hình ly cà phê, hạt cà phê trên tường quán ven sông","altEn":"Neon-style coffee glass and beans artwork on a riverside café wall","source":"/assets/content/projects/advertising/led-displays-lightboxes/den-neon-quan-cafe.webp","sha256":"e6aab108422653cfc6fe2b40ce177761a59624be4b13dd083d8ca1c9acd26ff8","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:led-neon-uv-ca-phe-1; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-31; master PNG SHA256 d9ccfd18bb91272d1f00aa209dbf1b085255658edecc54c75ff3f54b748b8024."},
  "led-displays-lightboxes-49": {"descriptionVi":"LED trang trí góc chụp ảnh tông ấm hợp với nhà hàng sân vườn, homestay, quán ven sông kiến trúc mộc, cần điểm sáng hắt nhẹ theo viền thay cho đèn nhiều màu.\n\n• Chất liệu: mica in UV cắt theo viền hoa lá, chữ LED neon gắn nổi trên nền tường\n• Đèn: LED neon ánh vàng 2700-3000K, nguồn 12V có dimmer\n• Kích thước thường làm: ngang 2,5-3,5 m, chia nhiều mảnh ghép\n• Lưu ý: tấm lớn nên chia mảnh dưới 1,2 m để dễ chở và lắp, mối ghép giấu theo đường hoa lá\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"Warm-toned LED decor for a photo corner suits garden restaurants, homestays and riverside venues with rustic architecture that want a soft edge glow rather than multi-colour lighting.\n\n• Material: UV-printed acrylic cut around the foliage, LED neon lettering mounted proud of the wall\n• Lighting: 2700-3000K warm LED neon, 12V supply with a dimmer\n• Typical size: 2.5-3.5 m wide, made in several sections\n• Tip: split large pieces into sections under 1.2 m for transport and fitting, with joints hidden along the leaf lines\n\nTrường Thịnh designs, builds in its own workshop and installs the piece.","altVi":"Mảng LED trang trí hoa nhiệt đới và xuồng trên băng ghế gỗ","altEn":"Warm LED wall art of tropical flowers and a boat above a wooden bench","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-trang-tri-goc-chup-anh.webp","sha256":"080402ebc0718adac909a88ae3fa376b0f77f5c63dcc2c7d19a94bb6fde1acea","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:led-neon-uv-goc-chup-1; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-31; master PNG SHA256 8729711505f6f0a2a5ffd7c60b43529816d1c293e08f6d2a1d453a6e7b684ab5."},
  "led-displays-lightboxes-50": {"descriptionVi":"LED neon quầy thu ngân cỡ vừa hợp với shop nhỏ, mặt bằng hẹp, nơi tường sau quầy chỉ rộng 2-3 m nhưng vẫn cần logo đủ nổi khi khách bước vào.\n\n• Chất liệu: mica in UV cắt theo hình, chữ LED neon nét đơn, gắn pát inox cách tường\n• Điện năng: LED neon chỉ khoảng 8-12 W mỗi mét, bật cả ngày tiền điện không đáng kể\n• Kích thước thường làm: ngang 1-1,5 m\n• Lưu ý: tường đã có đèn hắt thì chọn tông LED neon khác màu đèn hắt để logo không bị chìm\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt tận nơi.","descriptionEn":"A mid-sized LED neon sign behind the cash desk suits small shops on narrow plots, where the wall is only 2-3 m wide but the logo still has to stand out from the door.\n\n• Material: shaped UV-printed acrylic, single-line LED neon lettering on stainless stand-offs\n• Power: LED neon draws only about 8-12 W per metre, so running it all day costs very little\n• Typical size: 1-1.5 m wide\n• Tip: if the wall already has wash lighting, pick an LED neon colour that contrasts with it so the logo doesn't disappear\n\nTrường Thịnh designs, builds the sign in its workshop and installs it on site.","altVi":"Logo LED neon túi xách cỡ vừa trên tường sau quầy cửa hàng","altEn":"Mid-sized LED neon handbag logo on the wall behind a shop counter","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-50-imagegen-20261018.webp","sha256":"6267888ed29909383daa43fab1aa8123b806b07bc4a2485378392c0e228a823c","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:led-neon-uv-quay-shop-1; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-31; master PNG SHA256 47176b0458ba4320bafc6f899e70828b018ce112bef2990937af3bba8a56701c."},
  "led-displays-lightboxes-51": {"descriptionVi":"LED neon phòng spa dạng hình đơn hợp với spa resort, spa ven sông theo phong cách tối giản, nơi chỉ cần một điểm sáng nhẹ trên mảng tường lớn.\n\n• Chất liệu: mica in UV cắt theo viền hoa, chữ LED neon gắn trực tiếp lên tường\n• Đèn: nguồn 12V đặt sau tủ, dây đi âm tường\n• Kích thước thường làm: ngang 80-120 cm\n• Lưu ý: dùng cùng một mẫu cho mọi phòng trị liệu giúp chuỗi spa giữ nhận diện đồng bộ, đặt nhiều bộ cũng rẻ hơn\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A single-motif LED neon piece for spa rooms suits resort and riverside spas with a minimalist style, where one soft point of light on a large wall is enough.\n\n• Material: UV-printed acrylic cut around the flower, LED neon lettering fixed straight to the wall\n• Lighting: 12V supply behind the cabinet, cables concealed in the wall\n• Typical size: 80-120 cm wide\n• Tip: the same design in every treatment room keeps a spa chain consistent, and ordering several sets lowers the unit cost\n\nTrường Thịnh designs, builds in its own workshop and installs the pieces.","altVi":"LED neon hoa sen gắn tường phòng spa nhìn ra sông","altEn":"LED neon lotus on the wall of a riverside spa treatment room","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-neon-phong-spa.webp","sha256":"f10df9292dd4cf9d4748e80892bd711eb9a5044682e5757bb422f6bc7c89f799","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:led-neon-uv-spa-1; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-31; master PNG SHA256 603a725fff92c8ed9ecab14856851f140cb0e7f0a881fae8f181cbb10f02e688."},
  "led-displays-lightboxes-52": {"descriptionVi":"LED neon quán ăn cắt theo dáng chữ hợp với quán cơm, bún, hủ tiếu muốn biển tên trong nhà vừa liệt kê món chính vừa làm mảng trang trí cho tường quán.\n\n• Chất liệu: mica đen 5 mm cắt CNC theo viền chữ, hình tô món in UV\n• Đèn: LED neon silicon nhiều màu, nguồn 12V giấu sau tấm\n• Kích thước thường làm: cao 1-1,5 m, ngang 0,8-1,2 m\n• Lưu ý: bếp gần tường thì chọn LED neon vỏ silicon, chịu dầu mỡ và lau được bằng khăn ẩm\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A cut-out LED neon sign for an eatery suits rice and noodle shops that want an indoor name sign listing the main dishes while also decorating the dining room wall.\n\n• Material: 5 mm black acrylic CNC-cut around the lettering, UV-printed dish graphic\n• Lighting: multi-colour silicone LED neon, 12V supply hidden behind the panel\n• Typical size: 1-1.5 m tall, 0.8-1.2 m wide\n• Tip: near a kitchen, insist on silicone-jacketed LED neon, which resists grease and wipes clean with a damp cloth\n\nTrường Thịnh designs, builds in its own workshop and installs the sign.","altVi":"Biển LED neon cắt dáng chữ cơm bún hủ tiếu trên tường quán","altEn":"Cut-out LED neon sign for rice and noodle dishes on an eatery wall","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-neon-quan-an-com-bun.webp","sha256":"8a2e709d7edc6c8ca3e4da3266cf01c479fdf6c626d3b71b63d3f0c2c79b7e3e","provenance":"AI-generated illustration; ChatGPT web (chat 6ae6252b-8174-83ec-b438-3d76b4ce5be0); upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 5870fbd6b5892360a49265d7a8d0a5b3b9c89ca3eabd8e521346a4983ce6e26f."},
  "kiosk-posm-56": {"descriptionVi":"Kệ trưng bày đồ mỹ nghệ dạng quầy đảo hợp với thương hiệu thủ công thuê mặt bằng trong trung tâm thương mại, bày được nhiều nhóm hàng trên một ô diện tích nhỏ.\n\n• Chất liệu: MDF chống ẩm phủ veneer hoặc laminate, ốp mây đan, chi tiết cắt CNC\n• Đèn: LED dây âm dưới từng tầng kệ, dây điện đi trong khung\n• Kích thước thường làm: theo ô thuê 3x3 m hoặc 3x6 m\n• Lưu ý: gửi bản vẽ cho ban quản lý duyệt trước, vì nhiều trung tâm giới hạn chiều cao và chỉ cho lắp ban đêm\n\nTrường Thịnh thiết kế theo mặt bằng, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"Island-style display shelving for handicrafts suits craft brands renting a mall plot, fitting several product groups into a small footprint.\n\n• Material: moisture-resistant MDF with veneer or laminate, rattan panels, CNC-cut details\n• Lighting: LED strip recessed under each shelf, wiring run inside the frame\n• Typical size: built to the rented plot, 3x3 m or 3x6 m\n• Tip: send drawings to mall management for approval first, as many cap the height and only allow installation at night\n\nTrường Thịnh designs to the floor plan, builds in its workshop and installs it.","altVi":"Quầy đảo kệ gỗ bày đồ mỹ nghệ dừa trong trung tâm thương mại","altEn":"Timber island display of coconut handicrafts in a shopping mall","source":"/assets/content/projects/advertising/kiosk-posm/ke-trung-bay-my-nghe-dua.webp","sha256":"c1dc4018acaed904cba682f198e5e13c08b25d00f803ee944a9871a84dc497e2","provenance":"AI-generated illustration; owner selected A033-v1 in HTML audit and confirmed in chat 2026-10-22; ChatGPT web gpt-image; original SHA256 2e4cc2b879b18df0289535eba04719f19da75d2b92ea7d380a83f071282294c0; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-57": {"descriptionVi":"Standee hai mặt ngoài trời hợp với quán sữa hạt, tiệm bánh, quán ăn sáng cần một mặt giới thiệu món chủ lực, mặt kia chạy khuyến mãi theo tuần.\n\n• Khung: ống thép sơn tĩnh điện trắng, nẹp bo góc chống va\n• Đế: đối trọng đổ nước 10-15 lít, đủ vững khi gió lùa\n• In: PP hoặc bạt hiflex cán màng, thay riêng từng mặt\n• Lưu ý: tối nên kéo standee vào trong, đế nhựa phơi nắng mưa lâu sẽ giòn và nứt\n\nTrường Thịnh thiết kế, in và giao standee tận nơi trọn gói.","descriptionEn":"A double-sided outdoor standee suits nut milk bars, bakeries and breakfast spots that want one face for the signature item and the other for the week's offer.\n\n• Frame: white powder-coated steel tube with rounded bumper corners\n• Base: 10-15 litre water-filled weight, steady in a draught\n• Print: PP or laminated hiflex banner, each face replaceable on its own\n• Tip: bring it in at night, as a plastic base left out in sun and rain turns brittle and cracks\n\nTrường Thịnh designs, prints and delivers the standee.","altVi":"Standee khung trắng poster sữa hạt đặt trước cửa kính quán","altEn":"White-frame standee with a nut milk poster outside a café's glass door","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-33-owner-20260924-audit-a052-v1.webp","sha256":"b46f0aeee9270c9f0ef3f8a2cc199c2e3ff4e6e772e10b53bfbd05ff22a4ef43","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile, edited by owner; owner approved to site 2026-10-26 23:04Z; master PNG SHA256 a522cda25d8eada99240098b43128b8e57d3270966708161b9e2616c32c92230."},
  "kiosk-posm-58": {"descriptionVi":"Standee khung sắt cho tiệm bánh dùng để giới thiệu dòng bánh chủ lực, combo buổi sáng, gọn và đứng vững hơn bảng gỗ chân chữ A.\n\n• Khung: sắt hộp sơn tĩnh điện đen mờ, đế vuông thấp chống lật\n• Mặt: poster in PP hoặc mica in UV lồng sau nẹp, lau sạch bụi bột dễ dàng\n• Kích thước thường làm: 60x160 cm hoặc 70x170 cm\n• Lưu ý: ảnh bánh nên chụp thật tại tiệm, in đúng màu vỏ bánh thì khách mới tin\n\nTrường Thịnh thiết kế, in và giao standee tận nơi trọn gói.","descriptionEn":"A steel-frame standee for a bakery presents signature breads and breakfast combos, neater and steadier than a timber A-board.\n\n• Frame: matt black powder-coated steel box section, low square base that resists tipping\n• Face: PP poster or UV-printed acrylic behind a trim, easy to wipe free of flour dust\n• Typical size: 60x160 cm or 70x170 cm\n• Tip: use real photos of your own bakes with true crust colours, which customers trust more\n\nTrường Thịnh designs, prints and delivers the standee.","altVi":"Standee khung sắt đen poster bánh mì, bánh ngọt trước tiệm bánh","altEn":"Black steel standee with a bread and pastry poster outside a bakery","source":"/assets/content/projects/advertising/kiosk-posm/standee-khung-sat-tiem-banh.webp","sha256":"45666b79f1ea4e1b88850f59fdd23bfd1b77e7dbfbe24d5542d9fc65429c571b","provenance":"AI-generated illustration; edited by owner in ChatGPT web; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-27; master PNG SHA256 336b28354683ffb670f951baac15bba3019e61635f3709e95ace913e4528a09f."},
  "kiosk-posm-59": {"descriptionVi":"Standee khung ống chân trắng hợp với cửa hàng đồ dùng xanh, quà tặng, quán cà phê kiêm bán lẻ, cần nói nhanh cửa hàng bán gì với khách mới.\n\n• Khung: ống thép sơn tĩnh điện, ráp bằng khớp nối không cần dụng cụ\n• Mặt in: vải canvas hoặc bạt in UV, ít mùi, dùng được trong nhà\n• Kích thước thường làm: 80x180 cm\n• Lưu ý: cửa hàng theo hướng thân thiện môi trường có thể in trên vải bố mộc cho hợp thông điệp\n\nTrường Thịnh thiết kế, in và giao standee tận nơi.","descriptionEn":"A tube-frame standee suits eco-goods shops, gift stores and cafés with a retail corner that need to tell new customers what they sell at a glance.\n\n• Frame: powder-coated steel tube, tool-free push-fit joints\n• Print: UV-printed canvas or banner, low odour and fine indoors\n• Typical size: 80x180 cm\n• Tip: eco-minded shops can print on natural unbleached cotton to match the message\n\nTrường Thịnh designs, prints and delivers the standee.","altVi":"Standee bạt khung trắng giới thiệu đồ dùng tre gỗ trước quán","altEn":"White-frame fabric standee for bamboo and wooden goods outside a café","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-35-owner-20260924-audit-a054-v1.webp","sha256":"5691bda92bbba4c99cc3a5bbde69dd4a1d53f8ea802f75065cd49c910bc0d153","provenance":"AI-generated illustration; ChatGPT web image edit by owner (chat 6ae0088d-3700-83ec-8579-dd0779f3588b); upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-27; master PNG SHA256 c1b7b51ad34eee178275801e6c0def5052a05f9d1fa62c68622aa054caaea941."},
  "kiosk-posm-60": {"descriptionVi":"Standee vải in hợp với cửa hàng lụa, áo dài, đồ thiết kế khi thương hiệu cần mặt in mềm, màu nhạt đúng chất liệu sản phẩm thay vì bạt bóng.\n\n• Khung: ống thép sơn trắng, chân đế ngang, tháo lắp trong vài phút\n• Mặt in: vải polyester hoặc canvas in chuyển nhiệt, giữ được gam màu pastel\n• Kích thước thường làm: 80x200 cm hoặc 100x200 cm\n• Lưu ý: gam màu nhạt dễ in lệch, nên duyệt bản in thử trên đúng loại vải\n\nTrường Thịnh thiết kế, in và giao standee tận nơi trọn gói.","descriptionEn":"A printed fabric standee suits silk, áo dài and designer boutiques that want a soft, pale print true to the product instead of glossy banner.\n\n• Frame: white-painted steel tube with crossbar feet, up in a few minutes\n• Print: dye-sublimated polyester or canvas that holds pastel tones\n• Typical size: 80x200 cm or 100x200 cm\n• Tip: pale colours drift easily in print, so approve a proof on the exact fabric\n\nTrường Thịnh designs, prints and delivers the standee.","altVi":"Standee bạt chân trắng in hoa sen đặt trước cửa hàng lụa","altEn":"White-footed fabric standee printed with lotus flowers outside a silk shop","source":"/assets/content/projects/advertising/kiosk-posm/standee-vai-in-thoi-trang-lua.webp","sha256":"ce2d1927b05137a7f75caf3a053889450f5e0f1f2f675594cf6263627bba18a2","provenance":"AI-generated illustration; owner hand-edited 2026-10-31; master PNG SHA256 d44eca8db24e7bc3d16cf95c425d3b23229c75fde9b7feef088f6afba49b1dd5."},
  "kiosk-posm-61": {"descriptionVi":"Standee quảng cáo đặt trước cửa hàng cây cảnh, shop decor, quán cà phê sân vườn giúp báo chương trình mới hay khuyến mãi theo mùa mà không phải làm lại bảng hiệu.\n\n• In: bạt PP hoặc silk mờ in UV, ít lóa nắng hơn bạt hiflex bóng\n• Kích thước thường làm: 60x160 cm, 80x180 cm\n• Thay mẫu: chỉ in lại tấm bạt, chân X dùng lại được nhiều đợt\n• Lưu ý: hình cây lá nhiều chi tiết nên gửi file gốc độ phân giải cao, ảnh tải từ mạng in khổ lớn sẽ vỡ hạt\n\nTrường Thịnh thiết kế, in và giao standee tận nơi.","descriptionEn":"A promotional banner stand outside a plant shop, decor store or garden café announces a new range or seasonal offer without touching the main sign.\n\n• Print: matt PP or silk with UV inks, less glare in sunlight than glossy hiflex\n• Typical size: 60x160 cm or 80x180 cm\n• Changing designs: reprint only the banner, the X frame lasts for many campaigns\n• Tip: detailed foliage needs high-resolution original files, since images taken from the web break up at large sizes\n\nTrường Thịnh designs, prints and delivers the stand to your door.","altVi":"Standee in chậu cây lá xanh đặt trên bậc thềm cửa hàng cây cảnh","altEn":"Banner stand printed with potted foliage on the step of a plant shop","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-37-owner-20260924-audit-a056-v1.webp","sha256":"26f4915a800bf417840633fc5395861d692b4795d065ad4eb55abdef43afe057","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile, edited by owner; owner approved to site 2026-10-26 23:04Z; master PNG SHA256 c25da08e75d56ba113cb2a6b2eb1026d5043f9a972818ae4bd404350e6d43bf5."},
  "kiosk-posm-62": {"descriptionVi":"Gian hàng triển lãm khung gỗ bo cong hợp với thương hiệu mỹ phẩm, thực phẩm từ dừa tham gia hội chợ quốc tế, cần gian mở nhiều phía có khu tiếp khách riêng.\n\n• Kết cấu: khung gỗ hoặc sắt hộp ốp MDF uốn cong, lam gỗ dọc\n• Hộp đèn: vải căng in UV trên khung nhôm, LED tán sáng đều, thay hình nhanh\n• Kích thước thường làm: 6x6 m đến 9x9 m, dạng gian đảo\n• Lưu ý: gian đảo lớn thường phải nộp bản vẽ kết cấu và chứng nhận vật liệu chống cháy cho ban tổ chức\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và thi công trọn gói từ lúc dựng đến khi tháo.","descriptionEn":"A curved timber exhibition stand suits coconut cosmetics and food brands at international trade fairs that need an open-sided stand with its own meeting area.\n\n• Structure: timber or steel box frame clad in bent MDF, vertical timber slats\n• Lightboxes: UV-printed tension fabric on aluminium frames, even LED light, quick graphic changes\n• Typical size: 6x6 m to 9x9 m island stands\n• Tip: large island stands often require structural drawings and fire-rating certificates for the organiser\n\nTrường Thịnh designs, builds and handles the stand from set-up to take-down.","altVi":"Gian triển lãm gỗ cong, hộp đèn hình dừa, kệ mỹ phẩm hắt sáng","altEn":"Curved timber exhibition stand with coconut lightboxes and lit cosmetics shelves","source":"/assets/content/projects/advertising/kiosk-posm/gian-hang-trien-lam-go-cong.webp","sha256":"4a3f898d6110429a49de791727614b9b95323eba38e1340246e3a08320ed4297","provenance":"AI-generated illustration; owner approved 2026-10-23; moved from the Commercial hero pool; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-63": {"descriptionVi":"Gian hàng thủ công mỹ nghệ dạng mở hợp với làng nghề gốm, mây tre, đồ dừa đi hội chợ, khi món hàng cần bày rời từng món để khách cầm lên xem.\n\n• Bục trưng bày: MDF phủ veneer, nhiều chiều cao, rỗng ruột để chứa hàng dự phòng\n• Hộp đèn: vải căng in tranh, kệ hốc có LED dây âm\n• Kích thước thường làm: 6x6 m, 6x9 m\n• Lưu ý: bục làm theo bội số kích thước thì xếp lồng gọn khi chở và đổi được bố cục mỗi kỳ hội chợ\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và thi công trọn gói.","descriptionEn":"An open handicraft booth suits pottery, rattan and coconut-craft villages at trade fairs, where pieces are displayed one by one for visitors to pick up and handle.\n\n• Plinths: veneered MDF in several heights, hollow to store spare stock\n• Lightboxes: printed tension fabric, niche shelves with recessed LED strip\n• Typical size: 6x6 m or 6x9 m\n• Tip: plinths built in modular sizes nest together for transport and can be rearranged at every fair\n\nTrường Thịnh designs, builds and installs the whole booth.","altVi":"Gian hội chợ gỗ bày đồ gốm, giỏ mây trên bục cao thấp","altEn":"Timber fair stand showing pottery and rattan baskets on plinths of varied height","source":"/assets/content/projects/advertising/kiosk-posm/gian-hang-thu-cong-my-nghe.webp","sha256":"53b7abfd69bde6d99b3bd220982efe90c75b0c91a36869935c94452c0a5cabf4","provenance":"AI-generated illustration; owner approved 2026-10-23; moved from the Commercial hero pool; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-38": {"descriptionVi":"Chữ nổi LED sáng mặt gắn trên tường đá hợp với quán cà phê sân vườn, khu ẩm thực ngoài trời, nơi cổng quán là bức tường rào thay vì mặt tiền nhà.\n\n• Chữ: mặt mica sữa, viền inox hoặc alu sơn màu đồng, LED module chống nước\n• Lắp đặt: chân ty inox cấy keo vào đá, nguồn đặt trong hộp kín nước sau tường\n• Kích thước thường làm: chữ cao 50-90 cm\n• Lưu ý: chừa lỗ thoát nước dưới mỗi chữ, chữ ngoài vườn đọng nước sau mưa lâu ngày sẽ hỏng LED\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"Face-lit LED letters on a stone wall suit garden cafés and outdoor food courts, where the entrance is a boundary wall rather than a building front.\n\n• Letters: opal acrylic faces, stainless or bronze-painted aluminium returns, waterproof LED modules\n• Installation: stainless studs resin-anchored into the stone, power supply in a sealed box behind the wall\n• Typical size: letters 50-90 cm tall\n• Tip: leave drain holes under every letter, since garden signs collect rainwater that eventually kills the LEDs\n\nTrường Thịnh designs, builds in its own workshop and installs the sign.","altVi":"Chữ nổi LED sáng mặt gắn tường đá quán cà phê sân vườn","altEn":"Face-lit LED letters on a stone wall at a garden café","source":"/assets/content/projects/advertising/signage-raised-letters/chu-noi-led-sang-mat.webp","sha256":"06b14e45678052721990aa2d415d3c637ffcef12f757019e13e39e0194f23004","provenance":"AI-generated illustration; owner selected A242-v5 in HTML audit and confirmed in chat 2026-10-22; ChatGPT web gpt-image; original SHA256 b210bdd1781709bbabf6e4918479b190b86eb91202ad0f3aa673ebf550fa1522; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-39": {"descriptionVi":"Chữ nổi khung sắt lồng đèn neon hợp với quán nướng, quán nhậu, beer garden muốn bảng tên mang chất công nghiệp, mộc, khác hẳn chữ mica thường gặp.\n\n• Khung chữ: sắt tấm cắt laser, hàn lưới ô vuông mặt trước, sơn tĩnh điện màu gỉ hoặc đen\n• Đèn: LED neon flex 12V uốn theo nét chữ, chống nước IP65\n• Kích thước thường làm: chữ cao 60-100 cm, sâu 10-15 cm\n• Lưu ý: sắt ngoài trời nên sơn tĩnh điện hoặc dùng thép corten, sơn dầu thường gỉ chảy xuống tường sau một mùa mưa\n\nTrường Thịnh thiết kế, gia công tại xưởng và lắp đặt trọn gói.","descriptionEn":"Steel-framed letters with neon inside suit grill houses, beer bars and beer gardens that want a raw, industrial name sign quite unlike the usual acrylic letters.\n\n• Frame: laser-cut steel plate with a welded square grid on the face, powder-coated rust-tone or black\n• Lighting: 12V LED neon flex bent to each stroke, rated IP65\n• Typical size: letters 60-100 cm tall, 10-15 cm deep\n• Tip: outdoor steel should be powder-coated or Corten, as ordinary enamel rusts and streaks the wall within one rainy season\n\nTrường Thịnh designs, fabricates in its workshop and installs the letters.","altVi":"Chữ nổi khung sắt lưới lồng đèn neon trên tường đá nhà hàng nướng","altEn":"Steel grid-faced letters with neon inside on a stone wall at a grill restaurant","source":"/assets/content/projects/advertising/signage-raised-letters/chu-noi-khung-sat-den-neon.webp","sha256":"e1f0776537a338b87fb035746d1ee3c7cf619d42a23d111297d725fb7d163db9","provenance":"AI-generated illustration; owner-selected ChatGPT web image; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-27; master PNG SHA256 2e2ed2fb5178407a365cacf1a4e7bcd0d42904ed1b1a8b39655df4347d400a88."},
  "signage-raised-letters-40": {"descriptionVi":"Chữ nổi đặt đứng trên bồn cây hợp với nhà hàng sân vườn, quán ăn có khoảng lùi trước cửa, nơi không có tường mặt tiền để gắn chữ.\n\n• Chữ: mặt mica sữa, viền alu sơn màu gỗ hoặc đồng, LED module chống nước\n• Chân đế: khung sắt hộp giấu trong lòng chữ, bắt bu lông xuống bệ bê tông\n• Kích thước thường làm: chữ cao 70-120 cm, dày 15-20 cm\n• Lưu ý: chữ đứng cao trên 1 m cần tính lực gió, nên có thanh giằng phía sau nối các chữ với nhau\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"Freestanding letters on a planter suit garden restaurants and eateries with a forecourt, where there is no front wall to mount letters on.\n\n• Letters: opal acrylic faces, aluminium returns painted wood-tone or bronze, waterproof LED modules\n• Base: steel box frame hidden inside each letter, bolted down to a concrete plinth\n• Typical size: letters 70-120 cm tall, 15-20 cm deep\n• Tip: freestanding letters over 1 m must be designed for wind, ideally with a rear brace tying them together\n\nTrường Thịnh designs, builds in its own workshop and installs the sign.","altVi":"Chữ nổi sáng mặt và logo lá đặt đứng trên bồn cây nhà hàng","altEn":"Face-lit letters and leaf logo standing on a planter outside a restaurant","source":"/assets/content/projects/advertising/signage-raised-letters/chu-noi-dat-dung-nha-hang.webp","sha256":"aef9b301ff0fd7bcc1824c8df40427c25fdf5846dd379ffa3bb78ca2a45ad163","provenance":"AI-generated illustration; owner selected A242-v1 in HTML audit and confirmed in chat 2026-10-22; ChatGPT web gpt-image; original SHA256 f9ef054454738bd5164ae0743d49a5b6f31b76e3622ce657a197d63682160a6b; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-54": {"descriptionVi":"Biển chỉ dẫn tiếng Anh hợp với trung tâm thương mại, khu nghỉ dưỡng, khách sạn đông khách quốc tế, khi một ngôn ngữ kèm biểu tượng chuẩn là đủ cho mọi người.\n\n• Chất liệu: alu hoặc mica sơn đen mờ, chữ in UV\n• Kích thước thường làm: 70x15 cm đến 100x20 cm, chữ cao 5-6 cm cho sảnh rộng\n• Lắp đặt: gắn ở nút giao lối đi, cao 1,6-2 m\n• Lưu ý: mỗi nhóm tiện ích giữ một màu ở mọi tầng, khách nhớ màu nhanh hơn đọc chữ\n\nTrường Thịnh thiết kế hệ biển, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"English wayfinding signs suit shopping malls, resorts and hotels with many international visitors, where one language plus standard icons serves everyone.\n\n• Material: matt black aluminium composite or acrylic, UV-printed lettering\n• Typical size: 70x15 cm to 100x20 cm, with 5-6 cm lettering for large concourses\n• Installation: at walkway junctions, 1.6-2 m high\n• Tip: keep one colour per facility group on every floor, because visitors learn colours faster than words\n\nTrường Thịnh designs the sign system, makes it in its workshop and installs it.","altVi":"Biển chỉ dẫn tiếng Anh dạng thanh trên cột trung tâm thương mại","altEn":"English-only wayfinding bar signs on a shopping mall column","source":"/assets/content/projects/advertising/office-signs-wayfinding/bien-chi-dan-tieng-anh.webp","sha256":"18d5e2fe124c0bef60d8fb32f550740f2278ca0c161f6b6f2d9501baea7363b7","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd1e3-5f04-83ec-992a-69601e4ffe58); upscaled RunningHub SeedVR2 tile to 3072; owner approved incl. design system 2026-10-27 01:54Z; master PNG SHA256 f17c1ae02b9b32b33f0834bd39ebe28a5b4f88283c1e1a8eb0f0c8e9024f7e02."},
  "office-signs-wayfinding-55": {"descriptionVi":"Bảng chức danh inox xước hợp với văn phòng giám đốc, phòng họp, công ty có khách nước ngoài và nội thất hiện đại, cần bảng mảnh, bền và không bao giờ phai chữ.\n\n• Chất liệu: inox 304 xước dày 1-1,2 mm, chấn gấp chữ L\n• Gia công: ăn mòn đổ sơn hoặc in UV, làm được song ngữ\n• Kích thước thường làm: 25x8 cm, 30x10 cm\n• Lưu ý: dán đệm cao su dưới chân để bảng không trượt và không xước mặt bàn gỗ\n\nTrường Thịnh thiết kế, gia công tại xưởng và giao tận nơi trọn gói.","descriptionEn":"A brushed stainless desk nameplate suits directors' offices, meeting rooms and companies with foreign visitors and modern interiors, giving a slim, durable plate whose lettering never fades.\n\n• Material: 1-1.2 mm brushed 304 stainless, folded into an L\n• Fabrication: etched and paint-filled or UV printed, bilingual if needed\n• Typical size: 25x8 cm or 30x10 cm\n• Tip: add rubber pads underneath so the plate doesn't slide or scratch a timber desk\n\nTrường Thịnh designs, makes the nameplate in its workshop and delivers it.","altVi":"Bảng chức danh inox xước song ngữ gấp chữ L trên bàn giám đốc","altEn":"Bilingual brushed stainless desk nameplate folded in an L on a director's desk","source":"/assets/content/projects/advertising/office-signs-wayfinding/bang-chuc-danh-inox-xuoc.webp","sha256":"0f291a704fb3e029c47f2775e19e7db6a2f3356893435865a64cff3af85b4836","provenance":"AI-generated illustration; ChatGPT web image generation 2026-10-24; owner approved audit #798 in chat; original SHA256 f3a7eb77275da937c90209235c9cc06c6faafbe7f244aee7330b3427c40ae5cb; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-56": {"descriptionVi":"Cúp pha lê dáng cánh buồm hợp với doanh nghiệp tri ân đối tác, nhà phân phối, khách hàng thân thiết trong lễ tổng kết hoặc hội nghị khách hàng.\n\n• Chất liệu: pha lê K9 dày 15-20 mm, cạnh vát đánh bóng\n• Gia công: khắc laser hoặc phun cát mặt sau, chữ trắng mờ\n• Đế: pha lê đen hoặc gỗ, kèm hộp nhung lót mút\n• Lưu ý: làm cho nhiều đối tác thì giữ một mẫu chung, chỉ đổi tên đơn vị, vừa đồng bộ vừa nhanh\n\nTrường Thịnh thiết kế, khắc tại xưởng và giao tận nơi trọn gói.","descriptionEn":"A sail-shaped crystal trophy suits companies thanking partners, distributors and loyal customers at year-end events or customer conferences.\n\n• Material: 15-20 mm K9 crystal with polished bevelled edges\n• Fabrication: laser-engraved or sandblasted from the back, leaving frosted white text\n• Base: black crystal or timber, supplied in a foam-lined velvet box\n• Tip: for many partners keep one shared design and change only the company name, which is consistent and quicker\n\nTrường Thịnh designs, engraves in its workshop and delivers the trophies.","altVi":"Cúp pha lê dáng cánh buồm khắc chữ trên đế đen, bàn họp","altEn":"Sail-shaped crystal trophy with engraved text on a black base in a boardroom","source":"/assets/content/projects/advertising/office-signs-wayfinding/cup-pha-le-doi-tac.webp","sha256":"87b2e44f5f6dea6c2e74f016cd839e3f7c3b2cafab0baa5605a443b3bb445807","provenance":"AI-generated illustration; ChatGPT web gpt-image (owner chat 6af42b8d-a07c-83ec-8ae5-e6f4c8656812); owner approved 2026-11-11; original PNG SHA256 7cb48adf816655eaa87db5aab89cdf8e62d3b420d2ee5503376a253edd36a569."},
  "office-signs-wayfinding-58": {"descriptionVi":"Cúp gỗ khắc laser hợp với doanh nghiệp, hợp tác xã, trường học trao cho người gắn bó lâu năm, muốn phần thưởng ấm, mộc và khác cúp kim loại quen thuộc.\n\n• Chất liệu: gỗ beech hoặc gỗ sồi, ghép gỗ óc chó và mica gương vàng\n• Gia công: cắt CNC theo dáng, khắc laser chữ cháy nâu\n• Kích thước thường làm: cao 22-28 cm\n• Lưu ý: khắc laser trên gỗ sáng lên nét rõ nhất, gỗ sẫm nên dùng chữ ghép mica hoặc nhũ\n\nTrường Thịnh thiết kế, gia công tại xưởng và giao tận nơi trọn gói.","descriptionEn":"A laser-engraved timber trophy suits companies, cooperatives and schools honouring long service, for a warm, natural award that stands apart from the usual metal cups.\n\n• Material: beech or oak, layered with walnut and gold mirror acrylic\n• Fabrication: CNC-cut to shape, laser-burned lettering\n• Typical size: 22-28 cm tall\n• Tip: laser engraving reads best on pale timber; on dark wood use inlaid acrylic or foil lettering instead\n\nTrường Thịnh designs, makes the trophy in its workshop and delivers it.","altVi":"Cúp gỗ khắc chữ ghép lớp gỗ sẫm và mica vàng phía sau","altEn":"Engraved timber trophy layered with dark wood and gold acrylic behind","source":"/assets/content/projects/advertising/office-signs-wayfinding/cup-go-khac-laser.webp","sha256":"b818bd6cd5798bc9ce1a5bd41bfe489f1a1b8bffd843e1e73db2d8ed4ad0ced0","provenance":"AI-generated illustration; ChatGPT web gpt-image (owner chat 6af43840-9024-83ec-adaf-e21b5ad680d7); owner approved 2026-11-11; original PNG SHA256 4ba9d1d231bca588c8116a3af1891b213c2c19f506b74a2fb338727d26604872."},
  "office-signs-wayfinding-57": {"descriptionVi":"Cúp mica ghép màu hợp với giải doanh số, đại lý xuất sắc trao trong lễ tổng kết, khi cần nhiều cúp rực màu, nhẹ và giá dễ chịu hơn pha lê.\n\n• Chất liệu: mica trong và mica màu dày 8-10 mm, đế mica 15-20 mm\n• Gia công: cắt laser, ghép lớp bằng keo chuyên dụng, in UV chữ\n• Kích thước thường làm: cao 20-25 cm\n• Lưu ý: mica màu cam, đỏ lên màu đẹp dưới đèn sân khấu, nên chọn màu hợp nhận diện thương hiệu\n\nTrường Thịnh thiết kế, gia công tại xưởng và giao tận nơi trọn gói.","descriptionEn":"A layered colour acrylic trophy suits sales and top-dealer awards at year-end events, when you need many bright, light trophies at a friendlier price than crystal.\n\n• Material: 8-10 mm clear and coloured acrylic, 15-20 mm acrylic base\n• Fabrication: laser-cut, bonded with acrylic cement, UV-printed text\n• Typical size: 20-25 cm tall\n• Tip: orange and red acrylic glow under stage lighting, so pick a colour that fits your brand\n\nTrường Thịnh designs, makes the trophies in its workshop and delivers them.","altVi":"Cúp mica trong ghép lớp mica cam hình ngọn lửa, đế mica","altEn":"Clear acrylic trophy with an orange acrylic flame layer on an acrylic base","source":"/assets/content/projects/advertising/office-signs-wayfinding/cup-mica-ghep-mau.webp","sha256":"431871f3868a4d3b6d2964d084692c76d60163011e297cce4d77bc0667c03577","provenance":"AI-generated illustration; ChatGPT web gpt-image (owner chat 6af437e0-c9d0-83ec-b6eb-6f5c7062f285); owner approved 2026-11-11; original PNG SHA256 1b16c3fe62117d16ee6a545f9ee4958bdcdcdfa4dd3a1e7bf1229a73e2f97b31."},
  "office-signs-wayfinding-59": {"descriptionVi":"Biển chỉ dẫn bệnh viện hợp với bệnh viện, phòng khám đa khoa, trung tâm y tế, nơi hệ biển phải đồng bộ màu phân khu từ cổng vào đến từng khoa.\n\n• Chất liệu: alu sơn đen mờ chống lóa, chữ song ngữ in UV\n• Vệ sinh: bề mặt chịu lau dung dịch sát khuẩn hằng ngày\n• Kích thước thường làm: 80x18 cm đến 100x20 cm\n• Lưu ý: lập sơ đồ luồng đi của người bệnh trước khi đặt biển, tránh mỗi khoa tự làm một kiểu\n\nTrường Thịnh thiết kế hệ biển, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"Hospital wayfinding signs suit hospitals, polyclinics and health centres, where one consistent colour-coded system has to run from the entrance to every department.\n\n• Material: anti-glare matt black aluminium composite, bilingual UV print\n• Cleaning: a surface that stands up to daily wiping with disinfectant\n• Typical size: 80x18 cm to 100x20 cm\n• Tip: map patient routes before placing signs, rather than letting each department order its own style\n\nTrường Thịnh designs the sign system, makes it in its workshop and installs it.","altVi":"Biển chỉ dẫn bệnh viện song ngữ trên cột sảnh chờ","altEn":"Bilingual hospital wayfinding signs on a column in the waiting hall","source":"/assets/content/projects/advertising/office-signs-wayfinding/bien-chi-dan-benh-vien.webp","sha256":"33f278e4535e71cfeddecca2cf0142dafd98208f2d4084900b9e2ce153021edc","provenance":"AI-generated illustration; ChatGPT web gpt-image (owner approved 2026-11-11, round 2 of G9-2); original PNG SHA256 97de74910e150184fdd6dd41b8a7035edee5ebeaf7cc19dec0370d2c506c20d4. Site file encoded from the 1536 px JPEG preview of that PNG until the PNG is handed over."},
  "signage-raised-letters-41": {"descriptionVi":"Biển vẫy phòng khám dạng oval hợp với phòng khám tư, nha khoa, nhà thuốc trong dãy phố có mái hiên, cần biển vuông góc gọn và nhẹ nhàng đúng tính chất y tế.\n\n• Cấu tạo: viền tôn hoặc nhôm uốn oval sơn trắng, hai mặt mica sữa\n• Chữ: mica màu dán nổi hoặc in UV, LED module bên trong\n• Kích thước thường làm: 60x100 cm đến 70x120 cm, dày 12-15 cm\n• Lưu ý: biển oval ngang trên 1 m nên dùng tay đỡ hai thanh trên dưới để không xoay khi gió lớn\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"An oval projecting sign suits private clinics, dental practices and pharmacies in a row with awnings, giving a neat, calm sign at right angles that fits a medical setting.\n\n• Build: rolled steel or aluminium oval rim painted white, opal acrylic on both faces\n• Lettering: raised coloured acrylic or UV print, LED modules inside\n• Typical size: 60x100 cm to 70x120 cm, 12-15 cm deep\n• Tip: oval signs over 1 m wide need a twin-arm bracket, top and bottom, so they don't twist in strong wind\n\nTrường Thịnh designs, builds in its own workshop and installs the sign.","altVi":"Biển vẫy oval mica trắng gắn tay thép trên mái hiên phòng khám","altEn":"White oval acrylic projecting sign on a steel bracket outside a clinic","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-41-imagegen-20261019.webp","sha256":"7561436834b46da8194bba877553198069016a344da12cea92cafaedb94dff5b","provenance":"AI-generated illustration; source ID imagegen:2026-10-19:signage-raised-letters-10-a-1; original SHA256 f79cba3d871e8cacd85149151e59b156f237453bac7b9aca9f978c98cf7009ad; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-42": {"descriptionVi":"Hộp đèn quán cà phê viền inox xước hợp với quán phin, quán vỉa hè muốn một chiếc biển ngoài trời bền và ít phải bảo trì.\n\n• Chất liệu: viền inox 304 xước, mặt mica sữa in UV\n• Đèn: LED module chống nước, nguồn 12V tách riêng\n• Kích thước thường làm: đường kính 50-70 cm, hai mặt\n• Lưu ý: inox 201 rẻ hơn nhưng dễ ố sau một mùa mưa, nên hỏi rõ loại inox trong báo giá\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A café lightbox with a brushed stainless rim suits drip-coffee shops and pavement cafés that want an outdoor sign needing little upkeep.\n\n• Material: brushed 304 stainless rim, opal acrylic face with UV print\n• Lighting: waterproof LED modules on a separate 12V supply\n• Typical size: 50-70 cm diameter, double-sided\n• Tip: 201-grade stainless is cheaper but stains within a rainy season, so ask which grade is quoted\n\nTrường Thịnh designs, builds in its own workshop and installs the sign.","altVi":"Hộp đèn tròn viền inox ghi CÀ PHÊ PHỐ CŨ trên phố tối","altEn":"Round stainless-rimmed lightbox reading CÀ PHÊ PHỐ CŨ on a street at dusk","source":"/assets/content/projects/advertising/signage-raised-letters/hop-den-quan-ca-phe-phin.webp","sha256":"be672d25ed49cb3480c1d405ab59a4594bf51c4e120ae8583184f68c49ded38e","provenance":"AI-generated illustration; source ID imagegen:2026-10-19:signage-detail-x3-1; original SHA256 91650ee1e1bbcff4f7bd08047743c5c20183d207663b75048086b064600eb1ae; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-64": {"descriptionVi":"Kiosk bánh ngọt khung sắt hợp với tiệm bánh mở điểm bán trong siêu thị, sảnh chung cư, chỉ cần vài mét vuông mà vẫn đủ tủ kính, quầy thu và bảng tên.\n\n• Khung: sắt hộp sơn tĩnh điện, mái phẳng có đèn rọi\n• Quầy: MDF chống ẩm ốp nan, mặt đá nhân tạo, bảng tên mica hắt sáng\n• Tủ bánh: kính cường lực, loại thường hoặc có làm lạnh tùy loại bánh\n• Lưu ý: bánh kem cần tủ mát 2-8°C, nên chừa ổ điện riêng và khe thoát nhiệt dưới quầy\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A steel-framed cake kiosk suits bakeries opening a pitch in a supermarket or apartment lobby, fitting a display case, till and name sign into a few square metres.\n\n• Frame: powder-coated steel box section, flat roof with downlights\n• Counter: moisture-resistant MDF with slats, solid surface top, backlit acrylic name panel\n• Cake case: toughened glass, ambient or chilled depending on the products\n• Tip: cream cakes need a 2-8°C chiller, so plan a dedicated socket and a vent under the counter\n\nTrường Thịnh designs, builds in its own workshop and installs it.","altVi":"Kiosk khung sắt xanh rêu, tủ kính bánh và bảng đèn tên tiệm","altEn":"Sage steel-frame kiosk with a pastry case and lit name panel in a supermarket","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-64-imagegen-20261024.webp","sha256":"724969b3bb97545f7dbec686a9d8c9ca3bd93f1ba41777f334cf9fb5c19d18d2","provenance":"AI-generated illustration; source ID imagegen:2026-10-24:hero-kiosk-a-banh-mien-tay-4; original SHA256 f8742671bb2fa851752e521ddb412ae6f31f0177dd1986c5fb47aded9211f667; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-65": {"descriptionVi":"Tủ trưng bày nước hoa dạng đứng hợp với cửa hàng nước hoa, mỹ phẩm cao cấp, quầy trong trung tâm thương mại cần bày nhiều mẫu mà vẫn có tủ khóa chứa hàng bên dưới.\n\n• Khung tủ: nhôm định hình bo góc hoặc MDF sơn PU, kệ kính cường lực 8 mm\n• Đèn: LED thanh dưới từng tầng, ánh 4000K giữ màu nước hoa trong\n• Kích thước thường làm: ngang 1-1,2 m, cao 2,2-2,4 m\n• Lưu ý: tránh đặt tủ chỗ nắng chiếu, nhiệt và tia UV làm nước hoa nhanh biến mùi\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A freestanding perfume display cabinet suits perfume and premium cosmetics shops and mall counters that need to show many testers with lockable stock storage below.\n\n• Frame: rounded aluminium profiles or PU-painted MDF, 8 mm toughened glass shelves\n• Lighting: LED bars under each shelf at 4000K so the liquid colours look clear\n• Typical size: 1-1.2 m wide, 2.2-2.4 m tall\n• Tip: keep cabinets out of direct sun, as heat and UV quickly spoil fragrance\n\nTrường Thịnh designs, builds in its own workshop and installs it.","altVi":"Hai tủ nước hoa đứng, kệ kính hắt đèn, hộp đèn trên đỉnh","altEn":"Two freestanding perfume cabinets with lit glass shelves and lightbox headers","source":"/assets/content/projects/advertising/kiosk-posm/tu-trung-bay-nuoc-hoa.webp","sha256":"d0141405fc92fad9b8db0072019ea66c61f363149d71ff3bf507e0db898ba965","provenance":"AI-generated illustration; ChatGPT web gpt-image (owner chat 6adf0fe8-7f04-83ec-932d-ee1162b64f97, card #810); upscaled RunningHub SeedVR2 tile x2 to 3072; owner approved 2026-10-26; upscaled PNG SHA256 b58795010e88f4bda781066e456c9ff627b880714bf86b8396b1a286cb402d76."},
  "kiosk-posm-66": {"descriptionVi":"Đảo trưng bày mỹ phẩm nhiều tầng hợp với cửa hàng mỹ phẩm thiên nhiên, mỹ phẩm từ dừa đặt giữa lối đi, dành cho sản phẩm mới, hàng khuyến mãi hoặc bộ quà tặng.\n\n• Kết cấu: MDF uốn cong sơn PU, mỗi tầng cao 15-20 cm, chân hắt LED\n• Mặt: sơn bóng mờ hoặc laminate, lau sạch được dầu, kem dính\n• Kích thước thường làm: dài 1,6-2,2 m, sâu 0,8-1 m\n• Lưu ý: tầng trên cùng không nên cao quá 1,2 m để không che vách kệ phía sau\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A tiered cosmetics display island suits natural and coconut skincare shops, set in the aisle for new launches, promotions or gift sets.\n\n• Build: bent MDF in PU paint, each tier 15-20 cm high, LED light at the base\n• Surface: satin paint or laminate that wipes clean of oils and creams\n• Typical size: 1.6-2.2 m long, 0.8-1 m deep\n• Tip: keep the top tier under 1.2 m so it doesn't hide the wall shelving behind\n\nTrường Thịnh designs, builds in its own workshop and installs it.","altVi":"Đảo mỹ phẩm oval nhiều tầng trước vách kệ hốc tông kem","altEn":"Tiered oval cosmetics island in front of cream niche shelving","source":"/assets/content/projects/advertising/kiosk-posm/dao-trung-bay-my-pham.webp","sha256":"bfd6183730f932eb2088c17697fb1695eb5e4cad45458b83c32bdc8d5b713b46","provenance":"AI-generated illustration; ChatGPT web image edit with owner mask; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 3b3be8b34ebf3be31ddd77cc54d76540389f9c875bf9f7ada415c0144ca089a8."},
  "kiosk-posm-67": {"descriptionVi":"Kệ trưng bày quần áo âm tường có thanh treo hắt đèn hợp với shop thời trang nữ, boutique, showroom váy cưới muốn mỗi ô treo vừa một nhóm mẫu theo màu hoặc bộ sưu tập.\n\n• Chất liệu: MDF chống ẩm sơn PU hoặc phủ melamine, thanh treo inox mạ vàng mờ\n• Đèn: LED thanh âm trên đỉnh ô, chiếu xuống vai áo\n• Kích thước thường làm: mỗi ô rộng 1-1,2 m, cao 2,4-2,6 m\n• Lưu ý: thanh treo đặt cách sàn 1,6-1,7 m cho váy dài, ô treo đồ ngắn có thể chia hai tầng\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"Built-in clothing display units with lit hanging rails suit women's fashion shops, boutiques and bridal showrooms that want each bay to hold one colour group or collection.\n\n• Material: moisture-resistant MDF in PU paint or melamine, matt gold-plated stainless rails\n• Lighting: LED bars recessed in the top of each bay, shining down onto the shoulders\n• Typical size: bays 1-1.2 m wide, 2.4-2.6 m tall\n• Tip: set rails 1.6-1.7 m from the floor for long dresses, and split short-garment bays into two levels\n\nTrường Thịnh designs, builds in its own workshop and installs it.","altVi":"Thanh treo quần áo hắt đèn, ô túi xách và bàn đảo gấp đồ","altEn":"Lit hanging rails, handbag niches and a folding table in a cream fashion shop","source":"/assets/content/projects/advertising/kiosk-posm/ke-trung-bay-quan-ao.webp","sha256":"686ea1f0034d9ee08b440a52e12d7cc44405cbb15dd413e8e79721c29862d3b8","provenance":"AI-generated illustration; ChatGPT web gpt-image (owner chat 6adf2ab8-464c-83ec-b540-764c553cfac0, card #847); upscaled RunningHub SeedVR2 tile x2 to 3072; owner approved 2026-10-26; upscaled PNG SHA256 08dabe3b28bcc8732f36acdcab0f492e6fd22acfc9d2c297b2fe228f6abe276c."},
  "kiosk-posm-68": {"descriptionVi":"Kệ trưng bày túi xách dạng hốc vòm hợp với cửa hàng túi xách, giày dép, phụ kiện thời trang, nơi mỗi món cần khoảng trống riêng để giữ cảm giác hàng chọn lọc.\n\n• Chất liệu: MDF chống ẩm, lòng hốc sơn hiệu ứng vữa, kệ kính cường lực 8-10 mm\n• Đèn: LED thanh âm dưới mỗi tầng kính, ánh 3000K cho da thuộc lên màu ấm\n• Kích thước thường làm: hốc rộng 60-70 cm, các tầng cách nhau 35-40 cm\n• Lưu ý: giày nên bày từ tầm hông đến ngang tầm mắt, đôi chủ lực đưa ra bục thấp giữa shop\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"Arched niche display shelving for handbags suits bag, shoe and fashion accessory stores, where each piece needs its own space to keep a curated feel.\n\n• Material: moisture-resistant MDF, textured plaster-effect niche backs, 8-10 mm toughened glass shelves\n• Lighting: LED bars recessed under each glass shelf at 3000K to warm up leather tones\n• Typical size: niches 60-70 cm wide, shelves 35-40 cm apart\n• Tip: show shoes between hip and eye level, and bring hero pairs out onto a low plinth mid-store\n\nTrường Thịnh designs, builds in its own workshop and installs it.","altVi":"Vách hốc vòm kệ kính bày túi xách, giày và mũ cói","altEn":"Arched niche wall with glass shelves for handbags, shoes and straw hats","source":"/assets/content/projects/advertising/kiosk-posm/ke-trung-bay-tui-xach.webp","sha256":"15e611cb705eb9a3f6f489f8404b4bf78bdd72c49afd272b3110530ed510f698","provenance":"AI-generated illustration; ChatGPT web gpt-image (owner chat 6adf2ac2-81a8-83ec-b28e-ba88057a38e5, card #848); upscaled RunningHub SeedVR2 tile x2 to 3072; owner approved 2026-10-26; upscaled PNG SHA256 24364f83ccc1176f9c7e0f61c7e38314e37275d692be03457e348bee56aec0a8."},
  "kiosk-posm-69": {"descriptionVi":"Kệ trưng bày nước hoa dạng ô so le hợp với cửa hàng nước hoa chiết, nước hoa chính hãng có nhiều mẫu nhỏ, mỗi chai một ô để khách so mùi theo dòng.\n\n• Chất liệu: MDF chống ẩm sơn PU, viền inox hoặc nhôm mạ vàng\n• Đèn: LED dây âm trong từng ô, ánh 3000-4000K\n• Kích thước thường làm: ô 25-40 cm, cả vách ngang 2-3 m\n• Lưu ý: ô nhỏ nhiều đèn nên đi dây và đặt nguồn trong hộp kỹ thuật riêng, hỏng một đoạn LED không phải tháo cả vách\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A staggered-niche perfume display suits decant and authentic perfume shops with many small bottles, one per niche so customers can compare scents by line.\n\n• Material: moisture-resistant MDF in PU paint, stainless or gold-anodised aluminium trim\n• Lighting: LED strip recessed in every niche, 3000-4000K\n• Typical size: niches 25-40 cm, whole wall 2-3 m wide\n• Tip: with many small lit niches, route cables and drivers to a separate service box so one failed LED run doesn't mean dismantling the wall\n\nTrường Thịnh designs, builds in its own workshop and installs it.","altVi":"Vách ô so le hắt đèn bày nước hoa, hộp đèn hoa phía trên","altEn":"Staggered lit niche wall of perfume bottles under a floral lightbox","source":"/assets/content/projects/advertising/kiosk-posm/ke-trung-bay-nuoc-hoa.webp","sha256":"feb7c764a5bf5e5409cb67260b1e13254bade2a3c3c9c2de39343062f5292b83","provenance":"AI-generated illustration; ChatGPT web gpt-image (owner chat 6adf2b24-fc84-83ec-b6c3-ef8d065a3ed0, card #849); upscaled RunningHub SeedVR2 tile x2 to 3072; owner approved 2026-10-26; upscaled PNG SHA256 fe5fc78940cfffa897baae0611ee822ac23987ba554a747eb795022c56d6e0dc."},
  "kiosk-posm-70": {"descriptionVi":"Kệ trưng bày mỹ phẩm treo tường hợp với cửa hàng skincare, spa bán lẻ có mặt bằng sâu, khi tường chính phải chứa phần lớn mẫu và lối giữa để trống cho đảo tư vấn.\n\n• Kệ: thép sơn tĩnh điện hoặc MDF phủ melamine, gắn ray âm tường chỉnh được cao độ\n• Đèn: LED dây âm mép kệ và hắt vách sau\n• Tủ dưới: MDF chống ẩm, cánh mở hoặc ngăn kéo chứa hàng\n• Lưu ý: chừa khoảng 30-40 cm giữa các tầng cho chai cao, kệ chỉnh cao độ thì đổi mẫu theo mùa dễ hơn\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"Wall-mounted cosmetics display shelving suits skincare shops and retail spas with deep floor plans, where the main wall holds most of the range and the centre stays free for a consultation island.\n\n• Shelves: powder-coated steel or melamine-faced MDF on adjustable recessed rails\n• Lighting: LED strip recessed in shelf edges plus a wash on the back wall\n• Base units: moisture-resistant MDF with doors or drawers for stock\n• Tip: allow 30-40 cm between shelves for tall bottles, and adjustable heights make seasonal changes easier\n\nTrường Thịnh designs, builds in its own workshop and installs it.","altVi":"Kệ mỹ phẩm treo tường hắt đèn, tủ dưới và đảo mặt đá vân","altEn":"Lit wall-hung cosmetics shelves with base cabinets and a marble-top island","source":"/assets/content/projects/advertising/kiosk-posm/ke-trung-bay-my-pham-treo-tuong.webp","sha256":"828e23e137835f260cdd214d71b8e3d4a46e08827ae691113642e8b2127ad94f","provenance":"AI-generated illustration; ChatGPT web gpt-image (owner chat 6adf2b96-11dc-83ec-a8d6-f1bfae810064, card #850); upscaled RunningHub SeedVR2 tile x2 to 3072; owner approved 2026-10-26; upscaled PNG SHA256 c6228cfcc3d433e95d583608c7bdf3ce3615673642e90b07ff0c4afe0acb429c."},
  "kiosk-posm-71": {"descriptionVi":"Kiosk mỹ phẩm giữa sảnh trung tâm thương mại hợp với thương hiệu mỹ phẩm thiên nhiên muốn thử thị trường trước khi thuê cửa hàng, hoặc mở điểm bán theo mùa lễ.\n\n• Kết cấu: MDF chống ẩm sơn PU, quầy bo tròn ốp gỗ, chân hắt LED\n• Trưng bày: kệ hốc vòm phía sau, hộp đèn vải căng thay hình theo chiến dịch\n• Kích thước thường làm: 2x3 m đến 3x4 m, cao không quá 2,4 m\n• Lưu ý: kiosk giữa sảnh nên có tủ khóa dưới quầy và đèn hẹn giờ theo giờ mở cửa của trung tâm\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt kiosk trọn gói.","descriptionEn":"A cosmetics kiosk in a mall atrium suits natural skincare brands testing the market before leasing a shop, or running a seasonal pop-up.\n\n• Build: moisture-resistant MDF in PU paint, rounded timber-clad counter with LED base light\n• Display: arched niche shelving behind, tension-fabric lightbox changed for each campaign\n• Typical size: 2x3 m to 3x4 m, no more than 2.4 m high\n• Tip: an atrium kiosk needs lockable storage under the counter and lighting on a timer matched to mall hours\n\nTrường Thịnh designs, builds and installs the kiosk.","altVi":"Quầy kiosk bo tròn bày mỹ phẩm dừa, ba hốc vòm và hộp đèn","altEn":"Rounded kiosk counter with coconut skincare, three arched niches and a lightbox","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-my-pham-thien-nhien.webp","sha256":"ca79265ec83e001629006e4ed138ac51d75d060196891f962a4a093c7d261f56","provenance":"AI-generated illustration; ChatGPT web gpt-image (owner chat 6adf2d98-dbd0-83ec-8ea0-fd1bda1eef3a, card #851); upscaled RunningHub SeedVR2 tile x2 to 3072; owner approved 2026-10-26; upscaled PNG SHA256 77316cf985a6998e3f642762a970bce93cf4ff27c9e71055aea720fccc72b36e."},
  "kiosk-posm-72": {"descriptionVi":"Kệ mỹ phẩm hốc vòm hợp với showroom mỹ phẩm, nước hoa theo phong cách ấm, khi chủ tiệm muốn mỗi hốc là một dòng sản phẩm riêng và dễ sắp theo bộ.\n\n• Chất liệu: MDF chống ẩm cắt CNC theo vòm, sơn PU màu theo nhận diện\n• Đèn: LED dây âm dọc viền vòm và dưới từng tầng kệ\n• Kích thước thường làm: mỗi hốc rộng 60-80 cm, cao 2,2-2,4 m\n• Lưu ý: tường màu đậm làm chai lọ sáng màu nổi hơn, nhưng cần đèn 3000-3500K để cả gian không bị tối\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"Arched alcove cosmetics shelving suits warm-toned beauty and perfume showrooms, where each alcove holds one product line and sets are easy to arrange.\n\n• Material: moisture-resistant MDF, CNC cut to the arch, PU paint in brand colours\n• Lighting: LED strip recessed around each arch and under every shelf\n• Typical size: alcoves 60-80 cm wide, 2.2-2.4 m tall\n• Tip: a dark wall makes pale bottles stand out, but use 3000-3500K lighting so the room doesn't feel dim\n\nTrường Thịnh designs, builds in its own workshop and installs it.","altVi":"Tủ hốc vòm màu đất nung bày mỹ phẩm, đảo ốp sóng giữa phòng","altEn":"Terracotta arched alcove cabinets of cosmetics with a fluted central island","source":"/assets/content/projects/advertising/kiosk-posm/ke-my-pham-hoc-vom.webp","sha256":"d68501cb44edd56d0897c1ace311eb9bcef85ac1ce295cd6b92f3748a3afd784","provenance":"AI-generated illustration; ChatGPT web gpt-image (owner chat 6adf2bb9-b598-83ec-9f35-430736b1648d, card #852); upscaled RunningHub SeedVR2 tile x2 to 3072; owner approved 2026-10-26; upscaled PNG SHA256 590a440a792524b1574d7ff8be95fac5a37c2b461b43c6fd7ed6372f69a6f15c."},
  "kiosk-posm-73": {"descriptionVi":"Kệ trưng bày mỹ phẩm spa dạng ô tròn hắt sáng hợp với spa có góc bán lẻ, cửa hàng mỹ phẩm thiên nhiên ít mẫu, mỗi ô bày trọn một bộ sản phẩm.\n\n• Cấu tạo: vách MDF khoét tròn, sau mỗi ô là hộp đèn mica sữa, kệ mica trong\n• Đèn: LED module trong hộp, ánh trắng ấm, tán đều không lộ bóng\n• Kích thước thường làm: ô đường kính 50-70 cm, vách ngang 2,4-3,6 m\n• Lưu ý: kệ mica trong chỉ chịu hàng nhẹ, chai thủy tinh lớn nên đặt trên bục trụ bên dưới\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"Round backlit spa cosmetics shelving suits spas with a retail corner and natural skincare shops with a small range, each circle holding one complete set.\n\n• Build: MDF wall with circular cut-outs, an opal acrylic lightbox behind each, clear acrylic shelves\n• Lighting: warm white LED modules in each box, evenly diffused with no hot spots\n• Typical size: circles 50-70 cm across, wall 2.4-3.6 m wide\n• Tip: clear acrylic shelves take only light items, so put large glass bottles on the plinth below\n\nTrường Thịnh designs, builds in its own workshop and installs it.","altVi":"Vách kệ tròn hắt sáng bày mỹ phẩm dừa, bục trụ ốp sóng","altEn":"Wall of round backlit shelves with coconut skincare and a fluted pillar plinth","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-73-ke-trung-bay-20261026.webp","sha256":"a0a405cd2b92a71b749913e4cd8da0eb91ee29334306b37fbdf8510179288136","provenance":"AI-generated illustration; ChatGPT web gpt-image (owner chat 6adf10b0-1edc-83ec-be4b-13f67a4b5d68, card #853); upscaled RunningHub SeedVR2 tile x2 to 3072; owner approved 2026-10-26; upscaled PNG SHA256 519eaf667e6a5aff9bb5b871e5211190da30b7d29d5b67777f23267a667c09f9."},
  "kiosk-posm-74": {"descriptionVi":"Backdrop kỷ niệm thành lập công ty dạng ghép lớp hợp với lễ kỷ niệm 10, 15, 20 năm tổ chức ở phòng tiệc, cần một phông dùng chung cho phần lễ, phần tiệc và chụp ảnh tập thể.\n\n• Kết cấu: khung sắt hộp, mặt gỗ ép hoặc formex cắt CNC xếp nhiều lớp\n• Số nổi: formex dày 3-5 cm, viền sơn nhũ vàng hoặc mica gương vàng\n• Kích thước thường làm: ngang 6-10 m, cao 3-4 m\n• Lưu ý: giữ lại số nổi và logo sau lễ để trưng ở sảnh công ty, chỉ phần phông là đồ dùng một lần\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và thi công backdrop trọn gói.","descriptionEn":"A layered company anniversary backdrop suits 10, 15 or 20-year celebrations in banquet halls, giving one backdrop for the ceremony, the dinner and the group photo.\n\n• Structure: steel box frame faced with layered CNC-cut plywood or foam PVC\n• Numerals: 3-5 cm foam PVC with gold-painted edges or gold mirror acrylic\n• Typical size: 6-10 m wide, 3-4 m high\n• Tip: keep the raised numerals and logo after the event for the company lobby, since only the backdrop face is single-use\n\nTrường Thịnh designs, builds and installs the backdrop.","altVi":"Backdrop xanh trắng chữ Kỷ Niệm 15 Năm, số nổi viền nhũ vàng","altEn":"Blue and white anniversary backdrop with raised gold-edged numerals","source":"/assets/content/projects/advertising/kiosk-posm/backdrop-ky-niem-thanh-lap.webp","sha256":"15ef5bb82c680b0e96ab2278dfb9095442a2ebddeafb0b5ff816d05ab7ce6155","provenance":"AI-generated illustration; ChatGPT web gpt-image (owner chat 6af44824-6320-83ec-93b9-9fc870d77c12); owner approved 2026-11-11; original PNG SHA256 80b792301183557332a96181620812b5c56cf1aa7a9f5eb2afb80b2f6f75540a."},
  "kiosk-posm-76": {"descriptionVi":"Backdrop kim sa phối vòm formex hợp với tiệc tất niên, gala doanh nghiệp tổ chức ở khách sạn, khi muốn phông bắt đèn sân khấu và lên ảnh lấp lánh.\n\n• Mặt kim sa: tấm sequin gắn lưới, cuộn lại được, thuê hoặc mua tùy số lần dùng\n• Hai bên: formex hoặc gỗ ép cắt cung, sơn PU, viền LED dây\n• Kích thước thường làm: ngang 6-8 m, cao 3-3,5 m\n• Lưu ý: kim sa phản sáng mạnh, nên rọi đèn chếch từ hai bên thay vì chiếu thẳng để ảnh không bị cháy sáng\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và thi công trọn gói.","descriptionEn":"A sequin backdrop framed with foam PVC arches suits year-end parties and corporate galas in hotels, catching the stage lights and sparkling in photos.\n\n• Sequin wall: shimmer panels on mesh that roll up, rented or bought depending on use\n• Sides: CNC-cut foam PVC or plywood arcs, PU paint, LED strip edging\n• Typical size: 6-8 m wide, 3-3.5 m high\n• Tip: sequins reflect strongly, so light them at an angle from both sides rather than head-on to avoid blown-out photos\n\nTrường Thịnh designs, builds and installs the whole set.","altVi":"Tường kim sa vàng chữ Year End Party, hai bên vòm xanh navy","altEn":"Gold sequin wall reading Year End Party between navy and cream arches","source":"/assets/content/projects/advertising/kiosk-posm/backdrop-kim-sa-tiec-cuoi-nam.webp","sha256":"fe0d6a83c2a8861a38a9ae78d2aab63bf8fcd8f39f4f674b04fffb6e2f65a7c0","provenance":"AI-generated illustration; ChatGPT web gpt-image (owner chat 6af450a2-aa00-83ec-8a13-79fd6b608213); owner approved 2026-11-11; original PNG SHA256 c301db7587dd17be8b9d1e883491173d6575be8762e8d0863f68c8b747c8e05c."},
  "kiosk-posm-75": {"descriptionVi":"Backdrop khai trương spa dạng vòm ghép lớp hợp với spa, thẩm mỹ viện, tiệm nail ngày mở cửa, cần góc chụp ảnh đặt trên vỉa hè hoặc ngay sảnh.\n\n• Kết cấu: gỗ ép hoặc formex cắt CNC, sơn PU, viền LED dây\n• Chữ: mica gương vàng hoặc formex sơn nhũ, dán nổi 1-2 cm\n• Kích thước thường làm: ngang 3-4 m, cao 2,2-2,8 m\n• Lưu ý: cắt backdrop thành 2-3 mảng bắt vít thì sau khai trương chuyển vào làm vách check-in trong spa\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A layered arched spa opening backdrop suits spas, beauty clinics and nail salons on opening day, as a photo spot on the pavement or in the lobby.\n\n• Build: CNC-cut plywood or foam PVC, PU paint, LED strip edging\n• Lettering: gold mirror acrylic or metallic-painted foam PVC, raised 1-2 cm\n• Typical size: 3-4 m wide, 2.2-2.8 m high\n• Tip: build it in 2-3 bolted sections so it can move inside as a check-in wall after the opening\n\nTrường Thịnh designs, builds in its own workshop and installs it.","altVi":"Backdrop Grand Opening hồng trắng chữ nổi vàng, hoa hồng và đèn viền","altEn":"Pink and white Grand Opening backdrop with gold letters, roses and edge lighting","source":"/assets/content/projects/advertising/kiosk-posm/backdrop-khai-truong-spa.webp","sha256":"95b9d8deb51cbeca46fca37ef27dcc8560ca84b8d643f948f834bdb18fc47390","provenance":"AI-generated illustration; ChatGPT web gpt-image (owner chat 6af46231-5064-83ec-a0be-ed613a7aee85, latest image chosen by the owner); owner approved 2026-11-11; original PNG SHA256 d2318c6d35bb5a1b6849a015b828d98d510f652a5de4a66baf87479709358ca3."},
  "kiosk-posm-77": {"descriptionVi":"Quầy trưng bày gỗ veneer uốn cong hợp với showroom đồ mỹ nghệ, nội thất, cửa hàng quà tặng cao cấp, dùng được làm quầy đón khách lẫn bàn bày sản phẩm chủ lực.\n\n• Chất liệu: khung gỗ uốn, ốp veneer óc chó dán nhiều lớp, sơn PU bóng mờ\n• Viền: nẹp inox mạ vàng hoặc đồng thau ôm mép mặt quầy và chân quầy\n• Đèn: LED dây âm dưới mặt quầy và trong rãnh kệ nổi\n• Lưu ý: veneer vân lớn nên lấy cùng một lô tấm để vân chạy liền quanh đoạn cong\n\nTrường Thịnh thiết kế, đóng quầy tại xưởng và lắp đặt trọn gói.","descriptionEn":"A curved veneer display counter suits handicraft and furniture showrooms and premium gift shops, working both as a reception desk and as a table for hero products.\n\n• Material: bent timber frame, laminated walnut veneer, satin PU finish\n• Trim: gold-tone stainless or brass edging around the top and plinth\n• Lighting: LED strip recessed under the top and in the floating shelf channels\n• Tip: order bold-grain veneer from a single batch of sheets so the figure runs unbroken around the curve\n\nTrường Thịnh designs, builds the counter in its workshop and installs it.","altVi":"Quầy cong veneer óc chó viền vàng, sau là kệ nổi hắt đèn","altEn":"Curved walnut-veneer counter with brass trim and lit floating shelves behind","source":"/assets/content/projects/advertising/kiosk-posm/quay-trung-bay-veneer-cong.webp","sha256":"22ef0a37e6e910a3c0215b32bbb92050d37d7a7e269e0d79f0cca83df09ac213","provenance":"AI-generated illustration; ChatGPT web gpt-image (owner approved 2026-11-11, round 3 of G8-1, ceiling changed to a flat plaster ceiling); original PNG SHA256 d8477346 (full hash in the owner PC record.json). Site file encoded from the 1536 px JPEG preview of that PNG until the PNG is handed over."},
  "kiosk-posm-79": {"descriptionVi":"Gian hàng trưng bày dụng cụ dạng vách lỗ hợp với thương hiệu dụng cụ cầm tay, đồ nghề thợ mộc, phụ kiện máy đi triển lãm, khi cần treo hàng trăm món nhỏ trên một mặt vách.\n\n• Khung: sắt hộp sơn tĩnh điện đen, bảng tên gỗ ép khắc chữ\n• Vách: ván ép hoặc MDF khoan lỗ đều, móc treo đổi vị trí tùy mẫu\n• Kích thước thường làm: 3x3 m, 3x6 m\n• Lưu ý: hàng giá trị như máy khoan, máy phay nên đặt trên quầy giữa có dây khóa, chỉ treo dụng cụ cầm tay lên vách\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và thi công gian hàng trọn gói.","descriptionEn":"A pegboard tool display booth suits hand tool, woodworking and machine accessory brands at exhibitions, where hundreds of small items need to hang on one wall.\n\n• Frame: black powder-coated steel box section, engraved plywood name board\n• Wall: evenly drilled plywood or MDF pegboard, hooks moved to suit each product\n• Typical size: 3x3 m or 3x6 m\n• Tip: keep valuable items such as drills and routers on the centre counter with security cables, and hang only hand tools on the wall\n\nTrường Thịnh designs, builds and installs the whole booth.","altVi":"Vách lỗ treo bào, đục, kẹp và lưỡi cưa trong gian khung đen","altEn":"Pegboard wall of planes, chisels, clamps and saw blades in a black-framed stand","source":"/assets/content/projects/advertising/kiosk-posm/gian-hang-trung-bay-dung-cu.webp","sha256":"8ef0f08a21cc33c0a7c2608adc09ce9d81ab6847802b41d41ada8d004a12054f","provenance":"AI-generated illustration; ChatGPT web gpt-image (chat 6af6300f-6274-83ec-acec-7691218782b7); owner approved 2026-11-13; original PNG SHA256 49e67b72115b14a5e66b55935741938ec0485f6458e29326e201f1af65e02ad3."},
  "kiosk-posm-80": {"descriptionVi":"Backdrop hội nghị khách hàng in bạt hợp với doanh nghiệp tổ chức tri ân đại lý, hội nghị nhà phân phối trong phòng tiệc khách sạn, cần phông lớn mà chi phí vừa phải.\n\n• Kết cấu: khung gỗ hoặc sắt hộp, cánh gà formex cắt chéo tạo chiều sâu\n• In: bạt hiflex, hoặc vải in UV nếu muốn ít lóa dưới đèn sân khấu\n• Kích thước thường làm: ngang 6-10 m, cao 3-4 m\n• Lưu ý: chốt file trước sự kiện 2-3 ngày để kịp in, căng bạt và chỉnh màu khi dựng thử\n\nTrường Thịnh thiết kế, in và thi công backdrop trọn gói.","descriptionEn":"A printed customer conference backdrop suits companies holding dealer appreciation nights or distributor meetings in hotel ballrooms, giving a large backdrop at a sensible cost.\n\n• Structure: timber or steel box frame, angled foam PVC wings for depth\n• Print: hiflex banner, or UV-printed fabric for less glare under stage lights\n• Typical size: 6-10 m wide, 3-4 m high\n• Tip: sign off the artwork 2-3 days ahead to leave time for printing, stretching and colour checks at a test set-up\n\nTrường Thịnh designs, prints and installs the backdrop.","altVi":"Phông bạt in cảnh sông nước trên sân khấu hội nghị khách hàng","altEn":"River-scene printed backdrop on a customer conference stage in a ballroom","source":"/assets/content/projects/advertising/kiosk-posm/backdrop-hoi-nghi-khach-hang.webp","sha256":"08611aff800abbb12074b16db7960f0ab42cbea260ed75cc751b081f7535e62c","provenance":"AI-generated illustration; ChatGPT web gpt-image (chat 6af6197b-f13c-83ec-875c-bf769550caa9); owner approved 2026-11-13; original PNG SHA256 7d3dc2c872f9140e164a506663694ac0ecac7b64109c293deac46285666e95ce."},
  "kiosk-posm-81": {"descriptionVi":"Backdrop khai trương khung giàn là cách làm phổ biến cho phòng khám, cửa hàng, văn phòng mới mở: dựng trước cửa trong vài giờ, xong lễ tháo trả khung và chỉ giữ lại tấm bạt.\n\n• Khung: giàn thép ống mạ kẽm tiết diện 30x30 cm, thuê hoặc mua tùy số lần dùng\n• In: bạt hiflex in kỹ thuật số, đóng khoen buộc dây rút\n• Kích thước thường làm: 3x2 m, 4x2,5 m\n• Lưu ý: khung giàn thuê theo ngày rẻ hơn mua, chỉ nên mua khi doanh nghiệp làm sự kiện thường xuyên\n\nTrường Thịnh thiết kế, in và dựng khung trọn gói.","descriptionEn":"A truss-mounted opening backdrop is the usual choice for new clinics, shops and offices: it goes up outside the door in a few hours, and after the ceremony the frame goes back and only the banner is kept.\n\n• Frame: galvanised steel truss, 30x30 cm section, rented or bought depending on how often it's used\n• Print: digitally printed hiflex with eyelets and cable ties\n• Typical size: 3x2 m or 4x2.5 m\n• Tip: renting truss by the day is cheaper than buying, so only buy if the business runs events regularly\n\nTrường Thịnh designs, prints and sets up the frame.","altVi":"Phông bạt khai trương phòng khám căng trên khung giàn trước cửa","altEn":"Clinic opening banner stretched on a steel truss outside the entrance","source":"/assets/content/projects/advertising/kiosk-posm/backdrop-khai-truong-khung-gian.webp","sha256":"397a4b28ee48f9575ad2988dad374d45ddf66142d58868ea68d2db38f5be58a3","provenance":"AI-generated illustration; ChatGPT web gpt-image (chat 6af61980-baf0-83ec-af4b-79e04d4642ae); owner approved 2026-11-13; original PNG SHA256 21765622dc74e75bd624ce3362a87e0ad498c0012628e895188186fb5a4f64e2."},
  "kiosk-posm-82": {"descriptionVi":"Backdrop tất niên dạng cuộn thư hợp với doanh nghiệp, cơ quan tổ chức tiệc cuối năm ở nhà hàng, sảnh khách sạn, khi cần một phông vừa trang trọng vừa có không khí Tết.\n\n• Kết cấu: gỗ ép hoặc formex cắt CNC theo đường lượn, sơn PU, viền LED dây\n• Trang trí: hoa giấy khổ lớn, quạt giấy, chữ in UV hoặc decal cắt\n• Kích thước thường làm: ngang 4-6 m, cao 2,5-3 m\n• Lưu ý: in chữ chương trình lên tấm rời gắn vào khung, năm sau đổi khẩu hiệu mà vẫn dùng lại khung và hoa\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và thi công trọn gói.","descriptionEn":"A scroll-shaped year-end party backdrop suits companies and agencies holding end-of-year dinners in restaurants or hotel foyers, when they want something formal with a Tết feel.\n\n• Build: CNC-cut plywood or foam PVC in a flowing outline, PU paint, LED strip edging\n• Decoration: giant paper flowers, paper fans, UV-printed or cut-vinyl lettering\n• Typical size: 4-6 m wide, 2.5-3 m high\n• Tip: put the event slogan on a separate panel fixed to the frame, so next year only the slogan changes and the frame and flowers are reused\n\nTrường Thịnh designs, builds and installs the whole set.","altVi":"Phông tất niên đỏ trắng viền LED, hoa giấy lớn và quạt giấy","altEn":"Red and white year-end backdrop with LED edging, giant paper flowers and fans","source":"/assets/content/projects/advertising/kiosk-posm/backdrop-tat-nien-cuon-thu.webp","sha256":"2186bfd90841ee3e81a6f98a433a6a34e2a02504033d54d037892cccebe7db06","provenance":"AI-generated illustration; ChatGPT web gpt-image (chat 6af6199e-3224-83ec-815d-3ad591b6e292); owner approved 2026-11-13; original PNG SHA256 695566b7e6a6a36d7a39adf17f9de606d7d6f0d6b3f126645e00cb1e6c97db7b."},
  "print-decals-40": {"descriptionVi":"In menu bìa cứng gấp đôi hợp với quán chè, quán tráng miệng ít món, cần thực đơn dựng đứng được trên bàn và lau sạch sau mỗi lượt khách.\n\n• Bìa: carton 2 mm bồi giấy in, cán màng mờ chống nước, viền dán vải hoặc giấy màu\n• Khổ thường làm: A4 hoặc A5 gấp đôi, mở ra đứng chữ V\n• In: offset hoặc kỹ thuật số, vài chục cuốn vẫn làm được\n• Lưu ý: món theo mùa nên in tờ dán rời, đổi món không phải bồi lại cả cuốn\n\nTrường Thịnh thiết kế, in, bồi bìa và giao tận nơi.","descriptionEn":"Folded hardcover menu printing suits dessert and chè shops with a short menu that needs to stand on the table and wipe clean between guests.\n\n• Cover: 2 mm board wrapped in printed paper, waterproof matt lamination, cloth or paper edging\n• Typical size: A4 or A5 folded, standing open in a V\n• Print: offset or digital, with runs of a few dozen still possible\n• Tip: print seasonal items as stick-on inserts, so changing them never means rebinding the menu\n\nTrường Thịnh designs, prints, binds and delivers the menus.","altVi":"Menu bìa cứng gấp đôi in tranh sông nước và các món chè","altEn":"Folded hardcover dessert menu with riverside artwork standing on a table","source":"/assets/content/projects/advertising/print-decals/in-menu-bia-cung-quan-che.webp","sha256":"03c3691ee1d585eddc931ba5c23d4e596a923e5f45ede46a45d7a1edbea3ae1a","provenance":"AI-generated illustration; ChatGPT web gpt-image (chat 6af618b3-740c-83ec-b112-ea02407fa1c1); owner approved 2026-11-13; original PNG SHA256 8568d6da828cdb1be367d5158db752374773b210f1f7c2a6cdf1ed6a69d86a9c."},
  "print-decals-41": {"descriptionVi":"In túi giấy trà sữa cùng đai giấy quấn ly hợp với quán trà sữa mới mở, chưa đủ số lượng in thẳng lên ly nhưng vẫn muốn ly mang đi có nhận diện riêng.\n\n• Túi: kraft trắng 120-150 gsm, quai giấy xoắn, in 2-4 màu\n• Đai ly: couché 250-300 gsm, bế cong ôm thân ly 500-700 ml\n• Ly: ly nhựa PP trơn mua sẵn, chỉ thêm đai in\n• Lưu ý: đai giấy in từ vài trăm cái, đổi màu theo mùa hay theo món mới không tốn khuôn\n\nTrường Thịnh thiết kế, in và giao tận nơi trọn gói.","descriptionEn":"Printed milk tea paper bags with cup sleeves suit newly opened bubble tea shops not yet selling enough for printed cups but still wanting branded takeaway drinks.\n\n• Bags: 120-150 gsm white kraft, twisted paper handles, printed in 2-4 colours\n• Sleeves: 250-300 gsm coated card, die-cut in a curve to wrap 500-700 ml cups\n• Cups: plain stock PP cups, branded only by the sleeve\n• Tip: sleeves print from a few hundred, so seasonal colours or new-drink versions cost no new tooling\n\nTrường Thịnh designs, prints and delivers to your door.","altVi":"Túi giấy quai và ly nhựa có đai giấy in trà sữa","altEn":"Milk tea paper bag and plastic cups wrapped in printed paper sleeves","source":"/assets/content/projects/advertising/print-decals/in-tui-giay-tra-sua.webp","sha256":"4a82712300f7322c05f68b5c2273429e613a8ff3c3f9323978870d47cb75a4bf","provenance":"AI-generated illustration; ChatGPT web gpt-image (chat 6af618ec-662c-83ec-9500-9f52effcc614); owner approved 2026-11-13; original PNG SHA256 518aa32c3b3351be07170308b752f7baa2d3abdb4e8c511c6a6ee2727e946e36."},
  "office-signs-wayfinding-61": {"descriptionVi":"Decal dán kính phòng khám vừa làm biển tên phòng vừa che tầm nhìn vào trong, hợp với phòng khám, nha khoa, spa dùng cửa kính khung nhôm.\n\n• Chất liệu: decal mờ nhập khẩu, chữ decal màu cắt hoặc in UV\n• Gia công: cắt plotter theo khổ kính, dải mờ thường cao từ 0,9 đến 1,6 m\n• Độ bền: trong nhà dùng nhiều năm, lau bằng khăn ẩm hoặc nước lau kính\n• Lưu ý: dải mờ đủ cao để che giường khám nhưng chừa phần trên cho ánh sáng đi qua\n\nTrường Thịnh thiết kế, cắt decal tại xưởng và dán tận nơi trọn gói.","descriptionEn":"A clinic glass decal works as the room sign and as a privacy screen, suiting clinics, dental practices and spas with aluminium-framed glass doors.\n\n• Material: imported frosted vinyl, coloured cut vinyl or UV-printed lettering\n• Fabrication: plotter cut to the glass size, with the frosted band usually from 0.9 to 1.6 m\n• Durability: lasts for years indoors, cleaned with a damp cloth or glass cleaner\n• Tip: set the band high enough to screen the examination bed but leave the top clear for daylight\n\nTrường Thịnh designs, cuts the vinyl in its workshop and applies it on site.","altVi":"Decal mờ dán kính ghi tên phòng khám song ngữ trên cửa nhôm","altEn":"Frosted bilingual clinic decal on an aluminium-framed glass door","source":"/assets/content/projects/advertising/office-signs-wayfinding/decal-dan-kinh-phong-kham.webp","sha256":"0a1d03a911646d6220e31c33911e5efeeb96ad73279d7c49117408eb03109242","provenance":"AI-generated illustration; ChatGPT web gpt-image (chat 6af6240d-0c14-83ec-b98a-83940513ad3b); owner approved 2026-11-13; original PNG SHA256 e2d4e821f6fa7cc9aa14c3262dce4bddb6effec6eb17359525ae55393328d1ce."},
  "office-signs-wayfinding-62": {"descriptionVi":"Biển số phòng khách sạn mica đen chữ vàng hợp với khách sạn, resort, homestay có cửa gỗ tông trầm, cần một mẫu biển chung cho mọi tầng.\n\n• Chất liệu: mica đen bóng hoặc mờ dày 3-5 mm, bo cạnh\n• Gia công: khắc laser đổ nhũ vàng hoặc dán chữ mica gương vàng\n• Kích thước thường làm: 20x8 cm, 25x10 cm\n• Lắp đặt: keo 3M VHB không khoan cửa, hoặc vít che đầu cho cửa hay va chạm\n\nTrường Thịnh thiết kế, gia công tại xưởng và lắp đặt trọn gói.","descriptionEn":"Black acrylic hotel room number signs with gold lettering suit hotels, resorts and homestays with dark timber doors that need one design for every floor.\n\n• Material: 3-5 mm gloss or matt black acrylic with rounded edges\n• Fabrication: laser-engraved and gold-filled, or applied gold mirror acrylic lettering\n• Typical size: 20x8 cm or 25x10 cm\n• Installation: 3M VHB tape with no drilling, or capped screws for doors that take knocks\n\nTrường Thịnh designs, makes the signs in its workshop and installs them.","altVi":"Biển số phòng mica đen chữ vàng trên cửa gỗ hành lang","altEn":"Black acrylic room number sign with gold lettering on a timber door","source":"/assets/content/projects/advertising/office-signs-wayfinding/bien-so-phong-khach-san.webp","sha256":"9ba9020f51ab96a5843fc76cfe7e201ac0f1102d78b1b693216fc1f1330fe9ab","provenance":"AI-generated illustration; ChatGPT web gpt-image (chat 6af623d1-b6a8-83ec-ae8e-b3d13e1a4dcf); owner approved 2026-11-13; original PNG SHA256 ffcbeecac5a65b7b16c83de7f092a9576dde59efa97e7f0a2c6151b848fca4bc."},
  "office-signs-wayfinding-63": {"descriptionVi":"Biển phòng giám đốc bằng kính cường lực đen hợp với văn phòng doanh nghiệp, ngân hàng, khách sạn muốn biển phòng lãnh đạo khác hẳn biển các phòng ban.\n\n• Chất liệu: kính cường lực sơn đen 8-10 mm, chân đinh inox mạ vàng\n• Gia công: chữ in UV nhũ vàng hoặc decal ánh kim, cạnh kính mài bóng\n• Kích thước thường làm: 40x20 cm đến 60x30 cm\n• Lưu ý: kính cường lực phải khoan lỗ trước khi tôi, nên chốt kích thước và vị trí lỗ trước khi đặt\n\nTrường Thịnh thiết kế, gia công tại xưởng và lắp đặt trọn gói.","descriptionEn":"A black toughened-glass director's office sign suits companies, banks and hotels that want the management office sign to stand apart from department signs.\n\n• Material: 8-10 mm back-painted black toughened glass, gold-plated stainless stand-offs\n• Fabrication: gold UV print or metallic vinyl lettering, polished glass edges\n• Typical size: 40x20 cm to 60x30 cm\n• Tip: toughened glass must be drilled before tempering, so confirm the size and hole positions before ordering\n\nTrường Thịnh designs, makes the sign in its workshop and installs it.","altVi":"Biển phòng giám đốc kính đen chữ vàng, chân đinh trên tường","altEn":"Black glass director's office sign with gold lettering on stand-offs","source":"/assets/content/projects/advertising/office-signs-wayfinding/bien-phong-giam-doc-kinh-den.webp","sha256":"429bd0173df52a58ffb5b93561f6d1115c54269ee1158b4b7d394ebf7fe3cd42","provenance":"AI-generated illustration; ChatGPT web gpt-image (chat 6af6303c-dd24-83ec-8de8-a6c28e33fb48); owner approved 2026-11-13; original PNG SHA256 8558d3ffe9914677fd87747416dec4f75ee420fb326a26c9de60acda8bc1973e."},
  "office-signs-wayfinding-64": {"descriptionVi":"Bảng mica để bàn chữ L hợp với bàn hướng dẫn, quầy tiếp nhận ở bệnh viện, phòng khám, bộ phận một cửa, nơi nội dung đổi theo ca trực hoặc theo khu.\n\n• Chất liệu: mica trong 3-5 mm chấn nhiệt chữ L, có khe cài giấy\n• In: lá in giấy hoặc decal, đổi nội dung không cần làm lại bảng\n• Kích thước thường làm: 30x10 cm, 30x15 cm, A4 ngang\n• Lưu ý: mica chịu được lau cồn sát khuẩn, nhưng không dùng dung môi mạnh vì mặt sẽ bị nứt chân chim\n\nTrường Thịnh thiết kế, gia công tại xưởng và giao tận nơi trọn gói.","descriptionEn":"An L-shaped acrylic desk sign suits information desks and reception counters in hospitals, clinics and one-stop public service offices, where the wording changes by shift or area.\n\n• Material: 3-5 mm clear acrylic heat-bent into an L, with a slot for the insert\n• Print: paper or vinyl insert, so changing the text needs no new sign\n• Typical size: 30x10 cm, 30x15 cm or landscape A4\n• Tip: acrylic handles alcohol disinfectant wipes, but avoid strong solvents, which cause fine surface cracking\n\nTrường Thịnh designs, makes the signs in its workshop and delivers them.","altVi":"Bảng mica để bàn chữ xanh đặt trên quầy hướng dẫn bệnh viện","altEn":"Acrylic desk sign with blue lettering on a hospital information counter","source":"/assets/content/projects/advertising/office-signs-wayfinding/bang-mica-de-ban-benh-vien.webp","sha256":"1768df998c21b3699f35b518216eeed695867faf84bc63e72802578db79a560e","provenance":"AI-generated illustration; ChatGPT web gpt-image (chat 6af62446-e0a8-83ec-9973-68ecf1db8cf4); owner approved 2026-11-13; original PNG SHA256 293e0061fae264dad84a11d49bfd1b534a01df687ee975715d09c6f16bd0ea43."},
  "office-signs-wayfinding-65": {"descriptionVi":"Bảng chức danh mặt đồng hợp với cơ quan, trường học, đại hội cổ đông, nơi dãy bàn hội đồng cần một bộ bảng trang trọng, đặt cố định nhiều năm.\n\n• Chất liệu: đế gỗ tự nhiên sơn PU màu gỗ đỏ, mặt đồng hoặc alu mạ vàng xước\n• Gia công: khắc laser hoặc ăn mòn đổ sơn, chữ có chân cho không khí trang trọng\n• Kích thước thường làm: 30x10 cm, 35x12 cm\n• Lưu ý: làm mặt cài rời có rãnh trượt, đổi thành viên hội đồng không phải bỏ cả bảng\n\nTrường Thịnh thiết kế, gia công tại xưởng và giao tận nơi trọn gói.","descriptionEn":"Brass-faced title plates suit public offices, schools and shareholder meetings, where a council table needs a formal set that stays in use for years.\n\n• Material: solid timber base in a red-wood PU finish, brushed brass or gold-tone aluminium face\n• Fabrication: laser-engraved or etched and filled, in a serif typeface for a formal feel\n• Typical size: 30x10 cm or 35x12 cm\n• Tip: choose sliding slot-in faces so a change of council member doesn't mean replacing the whole plate\n\nTrường Thịnh designs, makes the plates in its workshop and delivers them.","altVi":"Dãy bảng chức danh mặt đồng vàng trên bàn họp phủ khăn trắng","altEn":"Row of brass-faced title plates on a meeting table with a white cloth","source":"/assets/content/projects/advertising/office-signs-wayfinding/bang-chuc-danh-mat-dong.webp","sha256":"d8ea4e31c61103671d8a1a7e77cf1ae5ebd544b91b6e09c544c6da3c3d868908","provenance":"AI-generated illustration; ChatGPT web gpt-image (chat 6af6187d-e4cc-83ec-a4b1-2c31f73249c6); owner approved 2026-11-13; original PNG SHA256 39f2ba5ca083d5b5c752fccc1a4d7c9b0dbbbb7a50f3fc6e9f4a521bc47bf422."},
  "office-signs-wayfinding-66": {"descriptionVi":"Bảng tên để bàn mica hợp với văn phòng tư vấn, phòng giao dịch, đại lý bảo hiểm có nhiều nhân viên ngồi bàn riêng, cần bảng gọn, nhẹ và dễ in đồng loạt.\n\n• Chất liệu: mica trong 5-8 mm, đế gỗ sồi hoặc gỗ cao su\n• In: UV mặt sau, theo màu nhận diện của đơn vị\n• Kích thước thường làm: 25x8 cm, 30x10 cm\n• Lưu ý: nên chọn mẫu thiết kế chung rồi chỉ đổi chữ, in số lượng lớn sẽ rẻ và đồng đều hơn\n\nTrường Thịnh thiết kế, in tại xưởng và giao tận nơi trọn gói.","descriptionEn":"An acrylic desk name sign suits consultancies, branch offices and insurance agencies with many staff at their own desks, giving a neat, light sign that is easy to print in bulk.\n\n• Material: 5-8 mm clear acrylic on an oak or rubberwood base\n• Print: reverse UV print in the organisation's brand colours\n• Typical size: 25x8 cm or 30x10 cm\n• Tip: settle one shared design and change only the wording, so a bulk run is cheaper and more consistent\n\nTrường Thịnh designs, prints in its workshop and delivers to your door.","altVi":"Bảng tên để bàn mica trong in sóng xanh trên đế gỗ sáng","altEn":"Clear acrylic desk name sign with blue wave print on a timber base","source":"/assets/content/projects/advertising/office-signs-wayfinding/bang-ten-de-ban-mica.webp","sha256":"d04c5b9e9ed6bf711324939f1b7456b6ea59b3ce270954ad018fab6eee9e615b","provenance":"AI-generated illustration; ChatGPT web gpt-image (chat 6af61882-7eb4-83ec-ade8-a8f616e04a74); owner approved 2026-11-13; original PNG SHA256 40231e296151e4a8297a20243123534e817e136d168029d9595bfce66ad27706."},
  "office-signs-wayfinding-67": {"descriptionVi":"Bảng lễ tân để bàn gỗ chữ vàng hợp với khách sạn, resort, nhà hàng có quầy đá hoặc quầy gỗ, đón khách trong nước lẫn nước ngoài.\n\n• Chất liệu: gỗ tự nhiên sơn PU màu óc chó hoặc gỗ đỏ\n• Chữ: inox mạ PVD vàng gương hoặc mica gương vàng cắt laser, dán nổi\n• Kích thước thường làm: 30x12 cm, 40x15 cm\n• Lưu ý: chữ inox mạ PVD giữ màu vàng lâu và chịu lau hằng ngày tốt hơn mica gương\n\nTrường Thịnh thiết kế, gia công tại xưởng và giao tận nơi trọn gói.","descriptionEn":"A timber reception desk sign with gold lettering suits hotels, resorts and restaurants with stone or timber front desks that welcome both local and foreign guests.\n\n• Material: solid timber in a walnut or red-wood PU finish\n• Lettering: laser-cut gold mirror PVD stainless or gold mirror acrylic, applied in relief\n• Typical size: 30x12 cm or 40x15 cm\n• Tip: PVD stainless letters keep their gold longer and stand up to daily wiping better than mirror acrylic\n\nTrường Thịnh designs, makes the sign in its workshop and delivers it.","altVi":"Bảng lễ tân gỗ sẫm chữ vàng song ngữ trên quầy đá","altEn":"Dark timber reception desk sign with bilingual gold lettering on a marble counter","source":"/assets/content/projects/advertising/office-signs-wayfinding/bang-le-tan-go-chu-vang.webp","sha256":"0e12140490f531fed98e59ff5222b5aef5d9b4759ab9e5b6b8a86c22e9fad6b9","provenance":"AI-generated illustration; ChatGPT web gpt-image (chat 6af6244e-3350-83ec-8fdd-009e4fe48a65); owner approved 2026-11-13; original PNG SHA256 f76805ba3cd78851d4b34d7b5889e89dcd9127d056045d37f40333ae9459acb2."},
  "office-signs-wayfinding-68": {"descriptionVi":"Cúp pha lê tri ân hợp với bệnh viện, phòng khám, trung tâm y tế trao cho y bác sĩ, điều dưỡng nhân ngày Thầy thuốc Việt Nam hay lễ tổng kết năm.\n\n• Chất liệu: pha lê K9 dày 15-20 mm, mài giác viền\n• Gia công: khắc laser chữ và họa tiết, có thể in UV logo màu của đơn vị\n• Đế: pha lê đen, cao 4-5 cm\n• Lưu ý: chốt danh sách người nhận sớm, mỗi cúp khắc tên riêng cần thêm 1-2 ngày\n\nTrường Thịnh thiết kế, khắc tại xưởng và giao tận nơi trọn gói.","descriptionEn":"A crystal appreciation award suits hospitals, clinics and health centres honouring doctors and nurses on Vietnamese Doctors' Day or at the year-end review.\n\n• Material: 15-20 mm K9 crystal with a faceted edge\n• Fabrication: laser-engraved text and motif, with optional UV-printed colour logo\n• Base: black crystal, 4-5 cm high\n• Tip: confirm the list of recipients early, as each individually named award adds 1-2 days\n\nTrường Thịnh designs, engraves in its workshop and delivers the awards.","altVi":"Cúp pha lê dáng giọt nước khắc chữ và hoa sen, đế đen","altEn":"Teardrop crystal award engraved with text and a lotus on a black base","source":"/assets/content/projects/advertising/office-signs-wayfinding/cup-pha-le-tri-an.webp","sha256":"1d1d7b61286fd5377228cb163a056426457078d584f99ac3253712e24a996ee7","provenance":"AI-generated illustration; ChatGPT web gpt-image (chat 6af61911-53e4-83ec-8a2d-29d74ac7a038); owner approved 2026-11-13; original PNG SHA256 b95c9166f6025d8e42a253e971bb6d80b96b26141b23cdecb2502ca868e4ce1d."},
  "office-signs-wayfinding-69": {"descriptionVi":"Bảng kỷ niệm gỗ mặt đồng hợp với doanh nghiệp, cơ quan tặng đối tác, nhân viên dịp kỷ niệm thành lập, vừa đặt bàn được vừa treo tường được.\n\n• Chất liệu: khung gỗ tự nhiên hoặc MDF sơn PU, mặt đồng hoặc alu mạ vàng xước\n• Gia công: khắc laser hoặc ăn mòn đổ sơn nâu\n• Kích thước thường làm: 15x20 cm, 20x25 cm, kèm chân dựng tháo rời\n• Lưu ý: mặt đồng thật nên phủ lớp chống oxy hóa, không thì sau vài tháng sẽ xỉn màu\n\nTrường Thịnh thiết kế, gia công tại xưởng và giao tận nơi trọn gói.","descriptionEn":"A timber anniversary plaque with a brass face suits companies and public bodies presenting partners and staff with a keepsake on a founding anniversary, for the desk or the wall.\n\n• Material: solid timber or PU-lacquered MDF frame, brushed brass or gold-tone aluminium face\n• Fabrication: laser-engraved or etched and filled in brown\n• Typical size: 15x20 cm or 20x25 cm, with a removable stand\n• Tip: real brass needs an anti-tarnish coat, or it dulls within a few months\n\nTrường Thịnh designs, makes the plaques in its workshop and delivers them.","altVi":"Bảng kỷ niệm khung gỗ mặt đồng vàng xước dựng trên chân gỗ","altEn":"Timber-framed anniversary plaque with a brushed brass face on a wooden stand","source":"/assets/content/projects/advertising/office-signs-wayfinding/bang-ky-niem-go-mat-dong.webp","sha256":"50cdc01a3bf88061431bf2615514e2fa9649852c84623201c8de737402f2a24e","provenance":"AI-generated illustration; ChatGPT web gpt-image (chat 6af63042-3308-83ec-9d59-040ab5191ae5); owner approved 2026-11-13; original PNG SHA256 27a700069c56559ccb40f97d6f35ea898c4f3f5a497181ca310ff06a72a2f9bf."},
  "office-signs-wayfinding-70": {"descriptionVi":"Cúp mica vinh danh in màu hợp với doanh nghiệp, trường học trao cho nhân viên, học sinh xuất sắc khi số lượng nhiều và mỗi cúp in một tên riêng.\n\n• Chất liệu: mica trong dày 10-15 mm, cắt vát cạnh, đế mica 20 mm\n• In: UV màu trực tiếp, in được logo và tên từng người trong cùng lượt\n• Kích thước thường làm: cao 18-22 cm\n• Lưu ý: dán màng bảo vệ đến lúc trao, mica trong dễ xước khi để chung thùng\n\nTrường Thịnh thiết kế, in tại xưởng và giao tận nơi trọn gói.","descriptionEn":"Colour-printed acrylic recognition awards suit companies and schools honouring top staff or students in large numbers, with each award printed with its own name.\n\n• Material: 10-15 mm clear acrylic with bevelled edges, 20 mm acrylic base\n• Print: direct UV colour, with logo and individual names in one run\n• Typical size: 18-22 cm tall\n• Tip: keep the protective film on until presentation, as clear acrylic scratches easily when packed together\n\nTrường Thịnh designs, prints in its workshop and delivers the awards.","altVi":"Ba cúp mica trong in màu xanh vàng trên bàn lễ tổng kết","altEn":"Three clear acrylic awards with blue and gold print on a ceremony table","source":"/assets/content/projects/advertising/office-signs-wayfinding/cup-mica-vinh-danh-nhan-vien.webp","sha256":"3e77151887d30eb4d31c38afa03b217a406b3bd94734435e727f7e9012183527","provenance":"AI-generated illustration; ChatGPT web gpt-image (chat 6af6194c-6ab4-83ec-9b44-e76f9a9ecd6a); owner approved 2026-11-13; original PNG SHA256 fc8a4603106c88090d40b2bdb489a6557a4423751ecd7d8fa0f4ecac4ac9d7a3."},
  "led-displays-lightboxes-53": {"descriptionVi":"Bảng LED giờ mở cửa gắn dưới bảng hiệu chính hợp với phòng khám thú y, tiệm thú cưng, nhà thuốc mặt phố, giúp khách biết giờ làm việc ngay cả khi cửa đã đóng.\n\n• Module: LED P10 một màu đỏ, bảng một dòng cao 16-20 cm\n• Khung: nhôm định hình, gắn vào khung sắt sẵn có của bảng hiệu\n• Điều khiển: hẹn giờ, chạy thêm số điện thoại cấp cứu ngoài giờ\n• Lưu ý: làm cùng lúc với bảng hiệu thì đi chung nguồn điện, đỡ khoan thêm lỗ trên mặt tiền\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"An opening-hours LED strip under the main sign suits vet clinics, pet shops and street-front pharmacies, telling customers the hours even when the shutters are down.\n\n• Modules: single-colour red P10, one line 16-20 cm high\n• Frame: aluminium profile fixed to the sign's existing steel frame\n• Control: timer, plus an out-of-hours emergency number on rotation\n• Tip: fitting it together with the main sign lets both share one power feed and saves drilling the frontage twice\n\nTrường Thịnh designs, builds in its own workshop and installs the sign.","altVi":"Bảng LED chữ đỏ báo giờ mở cửa dưới hộp đèn vòm thú y","altEn":"Red LED opening-hours strip under an arched vet clinic lightbox","source":"/assets/content/projects/advertising/led-displays-lightboxes/bang-led-gio-mo-cua.webp","sha256":"4cd6b58e72202c6502cbedbeca0faeee2e9b4a839c8ac7e416c18d54af0956ed","provenance":"AI-generated illustration; ChatGPT web gpt-image (chat 6af8c431-414c-83ec-b68d-595445666f11), edited by owner in ChatGPT from the 2026-11-13 image; owner approved 2026-11-14; original PNG SHA256 c593d31ecff4d40f831ea642935f0a4907d1f5a49117bbd6407f13acc030ca00."},
  "office-signs-wayfinding-60": {"descriptionVi":"Biển công ty inox xước hợp với công ty tư vấn, văn phòng luật, kiến trúc, doanh nghiệp đặt văn phòng ở nhà phố, cần biển gọn, bền ngoài trời và đúng thông tin đăng ký.\n\n• Chất liệu: inox 304 xước dày 1,2-2 mm, chân cách inox\n• Gia công: ăn mòn đổ sơn hoặc in UV, logo có thể cắt chữ nổi\n• Kích thước thường làm: 60x40 cm, 80x50 cm\n• Lưu ý: tên trên biển nên ghi đúng như giấy phép kinh doanh, kể cả tên viết tắt và loại hình công ty\n\nTrường Thịnh thiết kế, sản xuất tại xưởng và lắp đặt trọn gói.","descriptionEn":"A brushed stainless company sign suits consultancies, law and architecture practices and other businesses in townhouse offices that need a neat, weatherproof sign with the correct registered details.\n\n• Material: 1.2-2 mm brushed 304 stainless on stainless stand-offs\n• Fabrication: etched and paint-filled or UV printed, with an optional raised logo\n• Typical size: 60x40 cm or 80x50 cm\n• Tip: show the name exactly as on the business licence, including any short name and company type\n\nTrường Thịnh designs, makes the sign in its workshop and installs it.","altVi":"Biển công ty inox xước chân cách gắn trụ cổng văn phòng","altEn":"Brushed stainless company sign on stand-offs at an office gate pillar","source":"/assets/content/projects/advertising/office-signs-wayfinding/bien-cong-ty-inox-xuoc.webp","sha256":"299cb749f4bf10c52b09eaae0777cde2d151a5a090e46e9c6aff4a6ba4ad6dea","provenance":"AI-generated illustration; ChatGPT web gpt-image (chat 6af63037-6ca0-83ec-9c3d-e66550dca4b3); owner approved 2026-11-13; original PNG SHA256 c68bbf3fb7a9256b04203440388ca5e7ee7abfeb148429b7177d8790324b7c3c."},
  "office-signs-wayfinding-71": {"descriptionVi":"Cúp gỗ hình lá hợp với trường học, câu lạc bộ, cuộc thi môi trường hoặc nông nghiệp, khi ban tổ chức muốn giải nhất mang nét riêng và gần gũi thiên nhiên.\n\n• Chất liệu: gỗ phong hoặc gỗ beech, gân lá khảm hoặc khắc sâu tông sẫm, đế gỗ óc chó\n• Gia công: cắt CNC theo dáng, khắc laser danh hiệu\n• Kích thước thường làm: cao 25-35 cm\n• Lưu ý: chọn dáng lá đặc trưng của địa phương hoặc ngành hàng để giải thưởng dễ nhớ hơn\n\nTrường Thịnh thiết kế, gia công tại xưởng và giao tận nơi trọn gói.","descriptionEn":"A leaf-shaped timber trophy suits schools, clubs and environmental or farming competitions where organisers want a first prize with its own character and a natural feel.\n\n• Material: maple or beech, with darker inlaid or deep-cut veins, walnut base\n• Fabrication: CNC-cut to shape, laser-engraved title\n• Typical size: 25-35 cm tall\n• Tip: base the leaf on a plant tied to the region or the trade, so the award is easier to remember\n\nTrường Thịnh designs, makes the trophy in its workshop and delivers it.","altVi":"Cúp gỗ hình lá vân hai màu khắc chữ trên đế óc chó","altEn":"Two-tone leaf-shaped timber trophy with engraved text on a walnut base","source":"/assets/content/projects/advertising/office-signs-wayfinding/cup-go-hinh-la.webp","sha256":"5eb1acc3f97587b264b74347b38ebb9b09ec7bbc271699a4e04fb9f1fb598d21","provenance":"AI-generated illustration; ChatGPT web gpt-image (chat 6af63047-a58c-83ec-93d2-507fdd20cfd6); owner approved 2026-11-13; original PNG SHA256 dad96a0d987e161c21493ea1505724981dc50b3b706c6ae19ecc781de9f33136."},
  "print-decals-42": {"descriptionVi":"Hộp giấy kẹo dừa in cùng túi quai hợp với cơ sở sản xuất kẹo, đặc sản OCOP bán ở cửa hàng, quầy du lịch, cần bao bì đủ chỉn chu để khách mua làm quà.\n\n• Hộp: giấy ivory hoặc duplex 300-350 gsm, in offset 4 màu, cán màng mờ\n• Túi: cùng loại giấy, quai dây dù hoặc dây gai, vừa 2-4 hộp\n• Ruột: kẹo đóng túi nhựa hàn kín, hộp chỉ lo phần trình bày\n• Lưu ý: in đủ thông tin nhãn hàng hóa (thành phần, hạn dùng, nơi sản xuất) để bày được ở siêu thị và điểm bán OCOP\n\nTrường Thịnh thiết kế, in, bế hộp và giao tận nơi trọn gói.","descriptionEn":"Printed coconut candy boxes with matching carrier bags suit candy makers and OCOP specialty brands selling in shops and tourist stalls, where packaging must look good enough to give as a gift.\n\n• Box: 300-350 gsm ivory or duplex board, four-colour offset, matt laminated\n• Bag: same board, nylon or jute rope handles, holding 2-4 boxes\n• Inner: candy sealed in plastic, so the box only handles presentation\n• Tip: include full product label details (ingredients, expiry, origin) so the boxes qualify for supermarkets and OCOP outlets\n\nTrường Thịnh designs, prints, die-cuts and delivers the packaging.","altVi":"Túi quai và hộp giấy kẹo dừa in tranh dừa, sông nước","altEn":"Coconut candy gift bag and boxes with coconut and river artwork","source":"/assets/content/projects/advertising/print-decals/hop-giay-keo-dua-tui-quai.webp","sha256":"ccc862b2360b7c5d657073224b7e08376fbb47f31e564fe02da5099f20d5f952","provenance":"AI-generated illustration; ChatGPT web gpt-image, edited by owner in ChatGPT and handed over from his Downloads; owner approved 2026-11-13; original PNG SHA256 5ba0415a9bf016939d99ac6dbd6453b6e90e189415b97cbb27c4c953785bdb73."},
  "print-decals-43": {"descriptionVi":"Thẻ khách thân thiết và vé mời tiệc in giấy mỹ thuật hợp với resort, khách sạn, nhà hàng muốn gửi khách quen ưu đãi riêng hoặc mời dự tiệc tối.\n\n• Giấy: mỹ thuật 300-350 gsm, vân nhám hoặc vân lụa\n• Gia công: viền nhũ vàng, ép kim hoa văn, bo góc nhẹ\n• Quy cách: thẻ 9x6 cm hoặc 10x7 cm, vé mời 10x15 cm\n• Lưu ý: vé mời có ngày giờ nên in số ít theo từng sự kiện, thẻ khách thân thiết in một lần dùng cả năm\n\nTrường Thịnh thiết kế, in và giao tận nơi trọn gói.","descriptionEn":"Art-paper loyalty cards and dinner invitations suit resorts, hotels and restaurants that want to offer regulars private perks or invite them to an evening event.\n\n• Paper: 300-350 gsm art paper, felt or silk texture\n• Finishing: gold foil edging, foil-stamped motifs, softly rounded corners\n• Format: cards 9x6 cm or 10x7 cm, invitations 10x15 cm\n• Tip: invitations carry a date, so print small runs per event, while loyalty cards can be printed once for the year\n\nTrường Thịnh designs, prints and delivers to your door.","altVi":"Thẻ khách thân thiết và vé mời tiệc tối xếp trên khay cói","altEn":"Loyalty cards and dinner party invitations fanned on a woven tray","source":"/assets/content/projects/advertising/print-decals/the-khach-than-thiet-ve-moi.webp","sha256":"014653eb23ce3ffbffcbcee504c455117d3aea36ef91c03f1f2cafd031c64028","provenance":"AI-generated illustration; ChatGPT web gpt-image, edited by owner in ChatGPT and handed over from his Downloads; owner approved 2026-11-13; original PNG SHA256 3a5ff391a13d9c00f7432e5b1d381aeb1f419adc0de79c40a04637e44456bec2."},
});

